window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["民法商法"] = {"zhuanlifa":[{"i":1,"n":"第一条","txt":"为了保护专利权人的合法权益，鼓励发明创造，推动发明创造的应用，提高创新能力，促进科学技术进步和经济社会发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称的发明创造是指发明、实用新型和外观设计。"},{"i":3,"n":"第三条","txt":"国务院专利行政部门负责管理全国的专利工作；统一受理和审查专利申请，依法授予专利权。"},{"i":4,"n":"第四条","txt":"申请专利的发明创造涉及国家安全或者重大利益需要保密的，按照国家有关规定办理。"},{"i":5,"n":"第五条","txt":"对违反法律、社会公德或者妨害公共利益的发明创造，不授予专利权。"},{"i":6,"n":"第六条","txt":"执行本单位的任务或者主要是利用本单位的物质技术条件所完成的发明创造为职务发明创造。职务发明创造申请专利的权利属于该单位，申请被批准后，该单位为专利权人。该单位可以依法处置其职务发明创造申请专利的权利和专利权，促进相关发明创造的实施和运用。"},{"i":7,"n":"第七条","txt":"对发明人或者设计人的非职务发明创造专利申请，任何单位或者个人不得压制。"},{"i":8,"n":"第八条","txt":"两个以上单位或者个人合作完成的发明创造、一个单位或者个人接受其他单位或者个人委托所完成的发明创造，除另有协议的以外，申请专利的权利属于完成或者共同完成的单位或者个人；申请被批准后，申请的单位或者个人为专利权人。"},{"i":9,"n":"第九条","txt":"同样的发明创造只能授予一项专利权。但是，同一申请人同日对同样的发明创造既申请实用新型专利又申请发明专利，先获得的实用新型专利权尚未终止，且申请人声明放弃该实用新型专利权的，可以授予发明专利权。"},{"i":10,"n":"第十条","txt":"专利申请权和专利权可以转让。"},{"i":11,"n":"第十一条","txt":"发明和实用新型专利权被授予后，除本法另有规定的以外，任何单位或者个人未经专利权人许可，都不得实施其专利，即不得为生产经营目的制造、使用、许诺销售、销售、进口其专利产品，或者使用其专利方法以及使用、许诺销售、销售、进口依照该专利方法直接获得的产品。"},{"i":12,"n":"第十二条","txt":"任何单位或者个人实施他人专利的，应当与专利权人订立实施许可合同，向专利权人支付专利使用费。被许可人无权允许合同规定以外的任何单位或者个人实施该专利。"},{"i":13,"n":"第十三条","txt":"发明专利申请公布后，申请人可以要求实施其发明的单位或者个人支付适当的费用。"},{"i":14,"n":"第十四条","txt":"专利申请权或者专利权的共有人对权利的行使有约定的，从其约定。没有约定的，共有人可以单独实施或者以普通许可方式许可他人实施该专利；许可他人实施该专利的，收取的使用费应当在共有人之间分配。"},{"i":15,"n":"第十五条","txt":"被授予专利权的单位应当对职务发明创造的发明人或者设计人给予奖励；发明创造专利实施后，根据其推广应用的范围和取得的经济效益，对发明人或者设计人给予合理的报酬。"},{"i":16,"n":"第十六条","txt":"发明人或者设计人有权在专利文件中写明自己是发明人或者设计人。"},{"i":17,"n":"第十七条","txt":"在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织在中国申请专利的，依照其所属国同中国签订的协议或者共同参加的国际条约，或者依照互惠原则，根据本法办理。"},{"i":18,"n":"第十八条","txt":"在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织在中国申请专利和办理其他专利事务的，应当委托依法设立的专利代理机构办理。"},{"i":19,"n":"第十九条","txt":"任何单位或者个人将在中国完成的发明或者实用新型向外国申请专利的，应当事先报经国务院专利行政部门进行保密审查。保密审查的程序、期限等按照国务院的规定执行。"},{"i":20,"n":"第二十条","txt":"申请专利和行使专利权应当遵循诚实信用原则。不得滥用专利权损害公共利益或者他人合法权益。"},{"i":21,"n":"第二十一条","txt":"国务院专利行政部门应当按照客观、公正、准确、及时的要求，依法处理有关专利的申请和请求。"},{"i":22,"n":"第二十二条","txt":"授予专利权的发明和实用新型，应当具备新颖性、创造性和实用性。"},{"i":23,"n":"第二十三条","txt":"授予专利权的外观设计，应当不属于现有设计；也没有任何单位或者个人就同样的外观设计在申请日以前向国务院专利行政部门提出过申请，并记载在申请日以后公告的专利文件中。"},{"i":24,"n":"第二十四条","txt":"申请专利的发明创造在申请日以前六个月内，有下列情形之一的，不丧失新颖性："},{"i":25,"n":"第二十五条","txt":"对下列各项，不授予专利权："},{"i":26,"n":"第二十六条","txt":"申请发明或者实用新型专利的，应当提交请求书、说明书及其摘要和权利要求书等文件。"},{"i":27,"n":"第二十七条","txt":"申请外观设计专利的，应当提交请求书、该外观设计的图片或者照片以及对该外观设计的简要说明等文件。"},{"i":28,"n":"第二十八条","txt":"国务院专利行政部门收到专利申请文件之日为申请日。如果申请文件是邮寄的，以寄出的邮戳日为申请日。"},{"i":29,"n":"第二十九条","txt":"申请人自发明或者实用新型在外国第一次提出专利申请之日起十二个月内，或者自外观设计在外国第一次提出专利申请之日起六个月内，又在中国就相同主题提出专利申请的，依照该外国同中国签订的协议或者共同参加的国际条约，或者依照相互承认优先权的原则，可以享有优先权。"},{"i":30,"n":"第三十条","txt":"申请人要求发明、实用新型专利优先权的，应当在申请的时候提出书面声明，并且在第一次提出申请之日起十六个月内，提交第一次提出的专利申请文件的副本。"},{"i":31,"n":"第三十一条","txt":"一件发明或者实用新型专利申请应当限于一项发明或者实用新型。属于一个总的发明构思的两项以上的发明或者实用新型，可以作为一件申请提出。"},{"i":32,"n":"第三十二条","txt":"申请人可以在被授予专利权之前随时撤回其专利申请。"},{"i":33,"n":"第三十三条","txt":"申请人可以对其专利申请文件进行修改，但是，对发明和实用新型专利申请文件的修改不得超出原说明书和权利要求书记载的范围，对外观设计专利申请文件的修改不得超出原图片或者照片表示的范围。"},{"i":34,"n":"第三十四条","txt":"国务院专利行政部门收到发明专利申请后，经初步审查认为符合本法要求的，自申请日起满十八个月，即行公布。国务院专利行政部门可以根据申请人的请求早日公布其申请。"},{"i":35,"n":"第三十五条","txt":"发明专利申请自申请日起三年内，国务院专利行政部门可以根据申请人随时提出的请求，对其申请进行实质审查；申请人无正当理由逾期不请求实质审查的，该申请即被视为撤回。"},{"i":36,"n":"第三十六条","txt":"发明专利的申请人请求实质审查的时候，应当提交在申请日前与其发明有关的参考资料。"},{"i":37,"n":"第三十七条","txt":"国务院专利行政部门对发明专利申请进行实质审查后，认为不符合本法规定的，应当通知申请人，要求其在指定的期限内陈述意见，或者对其申请进行修改；无正当理由逾期不答复的，该申请即被视为撤回。"},{"i":38,"n":"第三十八条","txt":"发明专利申请经申请人陈述意见或者进行修改后，国务院专利行政部门仍然认为不符合本法规定的，应当予以驳回。"},{"i":39,"n":"第三十九条","txt":"发明专利申请经实质审查没有发现驳回理由的，由国务院专利行政部门作出授予发明专利权的决定，发给发明专利证书，同时予以登记和公告。发明专利权自公告之日起生效。"},{"i":40,"n":"第四十条","txt":"实用新型和外观设计专利申请经初步审查没有发现驳回理由的，由国务院专利行政部门作出授予实用新型专利权或者外观设计专利权的决定，发给相应的专利证书，同时予以登记和公告。实用新型专利权和外观设计专利权自公告之日起生效。"},{"i":41,"n":"第四十一条","txt":"专利申请人对国务院专利行政部门驳回申请的决定不服的，可以自收到通知之日起三个月内向国务院专利行政部门请求复审。国务院专利行政部门复审后，作出决定，并通知专利申请人。"},{"i":42,"n":"第四十二条","txt":"发明专利权的期限为二十年，实用新型专利权的期限为十年，外观设计专利权的期限为十五年，均自申请日起计算。"},{"i":43,"n":"第四十三条","txt":"专利权人应当自被授予专利权的当年开始缴纳年费。"},{"i":44,"n":"第四十四条","txt":"有下列情形之一的，专利权在期限届满前终止："},{"i":45,"n":"第四十五条","txt":"自国务院专利行政部门公告授予专利权之日起，任何单位或者个人认为该专利权的授予不符合本法有关规定的，可以请求国务院专利行政部门宣告该专利权无效。"},{"i":46,"n":"第四十六条","txt":"国务院专利行政部门对宣告专利权无效的请求应当及时审查和作出决定，并通知请求人和专利权人。宣告专利权无效的决定，由国务院专利行政部门登记和公告。"},{"i":47,"n":"第四十七条","txt":"宣告无效的专利权视为自始即不存在。"},{"i":48,"n":"第四十八条","txt":"国务院专利行政部门、地方人民政府管理专利工作的部门应当会同同级相关部门采取措施，加强专利公共服务，促进专利实施和运用。"},{"i":49,"n":"第四十九条","txt":"国有企业事业单位的发明专利，对国家利益或者公共利益具有重大意义的，国务院有关主管部门和省、自治区、直辖市人民政府报经国务院批准，可以决定在批准的范围内推广应用，允许指定的单位实施，由实施单位按照国家规定向专利权人支付使用费。"},{"i":50,"n":"第五十条","txt":"专利权人自愿以书面方式向国务院专利行政部门声明愿意许可任何单位或者个人实施其专利，并明确许可使用费支付方式、标准的，由国务院专利行政部门予以公告，实行开放许可。就实用新型、外观设计专利提出开放许可声明的，应当提供专利权评价报告。"},{"i":51,"n":"第五十一条","txt":"任何单位或者个人有意愿实施开放许可的专利的，以书面方式通知专利权人，并依照公告的许可使用费支付方式、标准支付许可使用费后，即获得专利实施许可。"},{"i":52,"n":"第五十二条","txt":"当事人就实施开放许可发生纠纷的，由当事人协商解决；不愿协商或者协商不成的，可以请求国务院专利行政部门进行调解，也可以向人民法院起诉。"},{"i":53,"n":"第五十三条","txt":"有下列情形之一的，国务院专利行政部门根据具备实施条件的单位或者个人的申请，可以给予实施发明专利或者实用新型专利的强制许可："},{"i":54,"n":"第五十四条","txt":"在国家出现紧急状态或者非常情况时，或者为了公共利益的目的，国务院专利行政部门可以给予实施发明专利或者实用新型专利的强制许可。"},{"i":55,"n":"第五十五条","txt":"为了公共健康目的，对取得专利权的药品，国务院专利行政部门可以给予制造并将其出口到符合中华人民共和国参加的有关国际条约规定的国家或者地区的强制许可。"},{"i":56,"n":"第五十六条","txt":"一项取得专利权的发明或者实用新型比前已经取得专利权的发明或者实用新型具有显著经济意义的重大技术进步，其实施又有赖于前一发明或者实用新型的实施的，国务院专利行政部门根据后一专利权人的申请，可以给予实施前一发明或者实用新型的强制许可。"},{"i":57,"n":"第五十七条","txt":"强制许可涉及的发明创造为半导体技术的，其实施限于公共利益的目的和本法第五十三条第（二）项规定的情形。"},{"i":58,"n":"第五十八条","txt":"除依照本法第五十三条第（二）项、第五十五条规定给予的强制许可外，强制许可的实施应当主要为了供应国内市场。"},{"i":59,"n":"第五十九条","txt":"依照本法第五十三条第（一）项、第五十六条规定申请强制许可的单位或者个人应当提供证据，证明其以合理的条件请求专利权人许可其实施专利，但未能在合理的时间内获得许可。"},{"i":60,"n":"第六十条","txt":"国务院专利行政部门作出的给予实施强制许可的决定，应当及时通知专利权人，并予以登记和公告。"},{"i":61,"n":"第六十一条","txt":"取得实施强制许可的单位或者个人不享有独占的实施权，并且无权允许他人实施。"},{"i":62,"n":"第六十二条","txt":"取得实施强制许可的单位或者个人应当付给专利权人合理的使用费，或者依照中华人民共和国参加的有关国际条约的规定处理使用费问题。付给使用费的，其数额由双方协商；双方不能达成协议的，由国务院专利行政部门裁决。"},{"i":63,"n":"第六十三条","txt":"专利权人对国务院专利行政部门关于实施强制许可的决定不服的，专利权人和取得实施强制许可的单位或者个人对国务院专利行政部门关于实施强制许可的使用费的裁决不服的，可以自收到通知之日起三个月内向人民法院起诉。"},{"i":64,"n":"第六十四条","txt":"发明或者实用新型专利权的保护范围以其权利要求的内容为准，说明书及附图可以用于解释权利要求的内容。"},{"i":65,"n":"第六十五条","txt":"未经专利权人许可，实施其专利，即侵犯其专利权，引起纠纷的，由当事人协商解决；不愿协商或者协商不成的，专利权人或者利害关系人可以向人民法院起诉，也可以请求管理专利工作的部门处理。管理专利工作的部门处理时，认定侵权行为成立的，可以责令侵权人立即停止侵权行为，当事人不服的，可以自收到处理通知之日起十五日内依照《中华人民共和国行政诉讼法》向人民法院起诉；侵权人期满不起诉又不停止侵权行为的，管理专利工作的部门可以申请人民法院强制执行。进行处理的管理专利工作的部门应当事人的请求，可以就侵犯专利权的赔偿数额进行调解；调解不成的，当事人可以依照《中华人民共和国民事诉讼法》向人民法院起诉。"},{"i":66,"n":"第六十六条","txt":"专利侵权纠纷涉及新产品制造方法的发明专利的，制造同样产品的单位或者个人应当提供其产品制造方法不同于专利方法的证明。"},{"i":67,"n":"第六十七条","txt":"在专利侵权纠纷中，被控侵权人有证据证明其实施的技术或者设计属于现有技术或者现有设计的，不构成侵犯专利权。"},{"i":68,"n":"第六十八条","txt":"假冒专利的，除依法承担民事责任外，由负责专利执法的部门责令改正并予公告，没收违法所得，可以处违法所得五倍以下的罚款；没有违法所得或者违法所得在五万元以下的，可以处二十五万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":69,"n":"第六十九条","txt":"负责专利执法的部门根据已经取得的证据，对涉嫌假冒专利行为进行查处时，有权采取下列措施："},{"i":70,"n":"第七十条","txt":"国务院专利行政部门可以应专利权人或者利害关系人的请求处理在全国有重大影响的专利侵权纠纷。"},{"i":71,"n":"第七十一条","txt":"侵犯专利权的赔偿数额按照权利人因被侵权所受到的实际损失或者侵权人因侵权所获得的利益确定；权利人的损失或者侵权人获得的利益难以确定的，参照该专利许可使用费的倍数合理确定。对故意侵犯专利权，情节严重的，可以在按照上述方法确定数额的一倍以上五倍以下确定赔偿数额。"},{"i":72,"n":"第七十二条","txt":"专利权人或者利害关系人有证据证明他人正在实施或者即将实施侵犯专利权、妨碍其实现权利的行为，如不及时制止将会使其合法权益受到难以弥补的损害的，可以在起诉前依法向人民法院申请采取财产保全、责令作出一定行为或者禁止作出一定行为的措施。"},{"i":73,"n":"第七十三条","txt":"为了制止专利侵权行为，在证据可能灭失或者以后难以取得的情况下，专利权人或者利害关系人可以在起诉前依法向人民法院申请保全证据。"},{"i":74,"n":"第七十四条","txt":"侵犯专利权的诉讼时效为三年，自专利权人或者利害关系人知道或者应当知道侵权行为以及侵权人之日起计算。"},{"i":75,"n":"第七十五条","txt":"有下列情形之一的，不视为侵犯专利权："},{"i":76,"n":"第七十六条","txt":"药品上市审评审批过程中，药品上市许可申请人与有关专利权人或者利害关系人，因申请注册的药品相关的专利权产生纠纷的，相关当事人可以向人民法院起诉，请求就申请注册的药品相关技术方案是否落入他人药品专利权保护范围作出判决。国务院药品监督管理部门在规定的期限内，可以根据人民法院生效裁判作出是否暂停批准相关药品上市的决定。"},{"i":77,"n":"第七十七条","txt":"为生产经营目的使用、许诺销售或者销售不知道是未经专利权人许可而制造并售出的专利侵权产品，能证明该产品合法来源的，不承担赔偿责任。"},{"i":78,"n":"第七十八条","txt":"违反本法第十九条规定向外国申请专利，泄露国家秘密的，由所在单位或者上级主管机关给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":79,"n":"第七十九条","txt":"管理专利工作的部门不得参与向社会推荐专利产品等经营活动。"},{"i":80,"n":"第八十条","txt":"从事专利管理工作的国家机关工作人员以及其他有关国家机关工作人员玩忽职守、滥用职权、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":81,"n":"第八十一条","txt":"向国务院专利行政部门申请专利和办理其他手续，应当按照规定缴纳费用。"},{"i":82,"n":"第八十二条","txt":"本法自1985年4月1日起施行。"}],"gerenduziqiyefa":[{"i":1,"n":"第一条","txt":"为了规范个人独资企业的行为，保护个人独资企业投资人和债权人的合法权益，维护社会经济秩序，促进社会主义市场经济的发展，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称个人独资企业，是指依照本法在中国境内设立，由一个自然人投资，财产为投资人个人所有，投资人以其个人财产对企业债务承担无限责任的经营实体。"},{"i":3,"n":"第三条","txt":"个人独资企业以其主要办事机构所在地为住所。"},{"i":4,"n":"第四条","txt":"个人独资企业从事经营活动必须遵守法律、行政法规，遵守诚实信用原则，不得损害社会公共利益。"},{"i":5,"n":"第五条","txt":"国家依法保护个人独资企业的财产和其他合法权益。"},{"i":6,"n":"第六条","txt":"个人独资企业应当依法招用职工。职工的合法权益受法律保护。"},{"i":7,"n":"第七条","txt":"在个人独资企业中的中国共产党党员依照中国共产党章程进行活动。"},{"i":8,"n":"第八条","txt":"设立个人独资企业应当具备下列条件："},{"i":9,"n":"第九条","txt":"申请设立个人独资企业，应当由投资人或者其委托的代理人向个人独资企业所在地的登记机关提交设立申请书、投资人身份证明、生产经营场所使用证明等文件。委托代理人申请设立登记时，应当出具投资人的委托书和代理人的合法证明。"},{"i":10,"n":"第十条","txt":"个人独资企业设立申请书应当载明下列事项："},{"i":11,"n":"第十一条","txt":"个人独资企业的名称应当与其责任形式及从事的营业相符合。"},{"i":12,"n":"第十二条","txt":"登记机关应当在收到设立申请文件之日起十五日内，对符合本法规定条件的，予以登记，发给营业执照；对不符合本法规定条件的，不予登记，并应当给予书面答复，说明理由。"},{"i":13,"n":"第十三条","txt":"个人独资企业的营业执照的签发日期，为个人独资企业成立日期。"},{"i":14,"n":"第十四条","txt":"个人独资企业设立分支机构，应当由投资人或者其委托的代理人向分支机构所在地的登记机关申请登记，领取营业执照。"},{"i":15,"n":"第十五条","txt":"个人独资企业存续期间登记事项发生变更的，应当在作出变更决定之日起的十五日内依法向登记机关申请办理变更登记。"},{"i":16,"n":"第十六条","txt":"法律、行政法规禁止从事营利性活动的人，不得作为投资人申请设立个人独资企业。"},{"i":17,"n":"第十七条","txt":"个人独资企业投资人对本企业的财产依法享有所有权，其有关权利可以依法进行转让或继承。"},{"i":18,"n":"第十八条","txt":"个人独资企业投资人在申请企业设立登记时明确以其家庭共有财产作为个人出资的，应当依法以家庭共有财产对企业债务承担无限责任。"},{"i":19,"n":"第十九条","txt":"个人独资企业投资人可以自行管理企业事务，也可以委托或者聘用其他具有民事行为能力的人负责企业的事务管理。"},{"i":20,"n":"第二十条","txt":"投资人委托或者聘用的管理个人独资企业事务的人员不得有下列行为："},{"i":21,"n":"第二十一条","txt":"个人独资企业应当依法设置会计帐簿，进行会计核算。"},{"i":22,"n":"第二十二条","txt":"个人独资企业招用职工的，应当依法与职工签订劳动合同，保障职工的劳动安全，按时、足额发放职工工资。"},{"i":23,"n":"第二十三条","txt":"个人独资企业应当按照国家规定参加社会保险，为职工缴纳社会保险费。"},{"i":24,"n":"第二十四条","txt":"个人独资企业可以依法申请贷款、取得土地使用权，并享有法律、行政法规规定的其他权利。"},{"i":25,"n":"第二十五条","txt":"任何单位和个人不得违反法律、行政法规的规定，以任何方式强制个人独资企业提供财力、物力、人力；对于违法强制提供财力、物力、人力的行为，个人独资企业有权拒绝。"},{"i":26,"n":"第二十六条","txt":"个人独资企业有下列情形之一时，应当解散："},{"i":27,"n":"第二十七条","txt":"个人独资企业解散，由投资人自行清算或者由债权人申请人民法院指定清算人进行清算。"},{"i":28,"n":"第二十八条","txt":"个人独资企业解散后，原投资人对个人独资企业存续期间的债务仍应承担偿还责任，但债权人在五年内未向债务人提出偿债请求的，该责任消灭。"},{"i":29,"n":"第二十九条","txt":"个人独资企业解散的，财产应当按照下列顺序清偿："},{"i":30,"n":"第三十条","txt":"清算期间，个人独资企业不得开展与清算目的无关的经营活动。在按前条规定清偿债务前，投资人不得转移、隐匿财产。"},{"i":31,"n":"第三十一条","txt":"个人独资企业财产不足以清偿债务的，投资人应当以其个人的其他财产予以清偿。"},{"i":32,"n":"第三十二条","txt":"个人独资企业清算结束后，投资人或者人民法院指定的清算人应当编制清算报告，并于十五日内到登记机关办理注销登记。"},{"i":33,"n":"第三十三条","txt":"违反本法规定，提交虚假文件或采取其他欺骗手段，取得企业登记的，责令改正，处以五千元以下的罚款；情节严重的，并处吊销营业执照。"},{"i":34,"n":"第三十四条","txt":"违反本法规定，个人独资企业使用的名称与其在登记机关登记的名称不相符合的，责令限期改正，处以二千元以下的罚款。"},{"i":35,"n":"第三十五条","txt":"涂改、出租、转让营业执照的，责令改正，没收违法所得，处以三千元以下的罚款；情节严重的，吊销营业执照。"},{"i":36,"n":"第三十六条","txt":"个人独资企业成立后无正当理由超过六个月未开业的，或者开业后自行停业连续六个月以上的，吊销营业执照。"},{"i":37,"n":"第三十七条","txt":"违反本法规定，未领取营业执照，以个人独资企业名义从事经营活动的，责令停止经营活动，处以三千元以下的罚款。"},{"i":38,"n":"第三十八条","txt":"投资人委托或者聘用的人员管理个人独资企业事务时违反双方订立的合同，给投资人造成损害的，承担民事赔偿责任。"},{"i":39,"n":"第三十九条","txt":"个人独资企业违反本法规定，侵犯职工合法权益，未保障职工劳动安全，不缴纳社会保险费用的，按照有关法律、行政法规予以处罚，并追究有关责任人员的责任。"},{"i":40,"n":"第四十条","txt":"投资人委托或者聘用的人员违反本法第二十条规定，侵犯个人独资企业财产权益的，责令退还侵占的财产；给企业造成损失的，依法承担赔偿责任；有违法所得的，没收违法所得；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"违反法律、行政法规的规定强制个人独资企业提供财力、物力、人力的，按照有关法律、行政法规予以处罚，并追究有关责任人员的责任。"},{"i":42,"n":"第四十二条","txt":"个人独资企业及其投资人在清算前或清算期间隐匿或转移财产，逃避债务的，依法追回其财产，并按照有关规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"投资人违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金，其财产不足以支付的，或者被判处没收财产的，应当先承担民事赔偿责任。"},{"i":44,"n":"第四十四条","txt":"登记机关对不符合本法规定条件的个人独资企业予以登记，或者对符合本法规定条件的企业不予登记的，对直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"登记机关的上级部门的有关主管人员强令登记机关对不符合本法规定条件的企业予以登记，或者对符合本法规定条件的企业不予登记的，或者对登记机关的违法登记行为进行包庇的，对直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"登记机关对符合法定条件的申请不予登记或者超过法定时限不予答复的，当事人可依法申请行政复议或提起行政诉讼。"},{"i":47,"n":"第四十七条","txt":"外商独资企业不适用本法。"},{"i":48,"n":"第四十八条","txt":"本法自2000年1月1日起施行。"}],"qiyepochanfa":[{"i":1,"n":"第一条","txt":"为规范企业破产程序，公平清理债权债务，保护债权人和债务人的合法权益，维护社会主义市场经济秩序，制定本法。"},{"i":2,"n":"第二条","txt":"企业法人不能清偿到期债务，并且资产不足以清偿全部债务或者明显缺乏清偿能力的，依照本法规定清理债务。"},{"i":3,"n":"第三条","txt":"破产案件由债务人住所地人民法院管辖。"},{"i":4,"n":"第四条","txt":"破产案件审理程序，本法没有规定的，适用民事诉讼法的有关规定。"},{"i":5,"n":"第五条","txt":"依照本法开始的破产程序，对债务人在中华人民共和国领域外的财产发生效力。"},{"i":6,"n":"第六条","txt":"人民法院审理破产案件，应当依法保障企业职工的合法权益，依法追究破产企业经营管理人员的法律责任。"},{"i":7,"n":"第七条","txt":"债务人有本法第二条规定的情形，可以向人民法院提出重整、和解或者破产清算申请。"},{"i":8,"n":"第八条","txt":"向人民法院提出破产申请，应当提交破产申请书和有关证据。"},{"i":9,"n":"第九条","txt":"人民法院受理破产申请前，申请人可以请求撤回申请。"},{"i":10,"n":"第十条","txt":"债权人提出破产申请的，人民法院应当自收到申请之日起五日内通知债务人。债务人对申请有异议的，应当自收到人民法院的通知之日起七日内向人民法院提出。人民法院应当自异议期满之日起十日内裁定是否受理。"},{"i":11,"n":"第十一条","txt":"人民法院受理破产申请的，应当自裁定作出之日起五日内送达申请人。"},{"i":12,"n":"第十二条","txt":"人民法院裁定不受理破产申请的，应当自裁定作出之日起五日内送达申请人并说明理由。申请人对裁定不服的，可以自裁定送达之日起十日内向上一级人民法院提起上诉。"},{"i":13,"n":"第十三条","txt":"人民法院裁定受理破产申请的，应当同时指定管理人。"},{"i":14,"n":"第十四条","txt":"人民法院应当自裁定受理破产申请之日起二十五日内通知已知债权人，并予以公告。"},{"i":15,"n":"第十五条","txt":"自人民法院受理破产申请的裁定送达债务人之日起至破产程序终结之日，债务人的有关人员承担下列义务："},{"i":16,"n":"第十六条","txt":"人民法院受理破产申请后，债务人对个别债权人的债务清偿无效。"},{"i":17,"n":"第十七条","txt":"人民法院受理破产申请后，债务人的债务人或者财产持有人应当向管理人清偿债务或者交付财产。"},{"i":18,"n":"第十八条","txt":"人民法院受理破产申请后，管理人对破产申请受理前成立而债务人和对方当事人均未履行完毕的合同有权决定解除或者继续履行，并通知对方当事人。管理人自破产申请受理之日起二个月内未通知对方当事人，或者自收到对方当事人催告之日起三十日内未答复的，视为解除合同。"},{"i":19,"n":"第十九条","txt":"人民法院受理破产申请后，有关债务人财产的保全措施应当解除，执行程序应当中止。"},{"i":20,"n":"第二十条","txt":"人民法院受理破产申请后，已经开始而尚未终结的有关债务人的民事诉讼或者仲裁应当中止；在管理人接管债务人的财产后，该诉讼或者仲裁继续进行。"},{"i":21,"n":"第二十一条","txt":"人民法院受理破产申请后，有关债务人的民事诉讼，只能向受理破产申请的人民法院提起。"},{"i":22,"n":"第二十二条","txt":"管理人由人民法院指定。"},{"i":23,"n":"第二十三条","txt":"管理人依照本法规定执行职务，向人民法院报告工作，并接受债权人会议和债权人委员会的监督。"},{"i":24,"n":"第二十四条","txt":"管理人可以由有关部门、机构的人员组成的清算组或者依法设立的律师事务所、会计师事务所、破产清算事务所等社会中介机构担任。"},{"i":25,"n":"第二十五条","txt":"管理人履行下列职责："},{"i":26,"n":"第二十六条","txt":"在第一次债权人会议召开之前，管理人决定继续或者停止债务人的营业或者有本法第六十九条规定行为之一的，应当经人民法院许可。"},{"i":27,"n":"第二十七条","txt":"管理人应当勤勉尽责，忠实执行职务。"},{"i":28,"n":"第二十八条","txt":"管理人经人民法院许可，可以聘用必要的工作人员。"},{"i":29,"n":"第二十九条","txt":"管理人没有正当理由不得辞去职务。管理人辞去职务应当经人民法院许可。"},{"i":30,"n":"第三十条","txt":"破产申请受理时属于债务人的全部财产，以及破产申请受理后至破产程序终结前债务人取得的财产，为债务人财产。"},{"i":31,"n":"第三十一条","txt":"人民法院受理破产申请前一年内，涉及债务人财产的下列行为，管理人有权请求人民法院予以撤销："},{"i":32,"n":"第三十二条","txt":"人民法院受理破产申请前六个月内，债务人有本法第二条第一款规定的情形，仍对个别债权人进行清偿的，管理人有权请求人民法院予以撤销。但是，个别清偿使债务人财产受益的除外。"},{"i":33,"n":"第三十三条","txt":"涉及债务人财产的下列行为无效："},{"i":34,"n":"第三十四条","txt":"因本法第三十一条、第三十二条或者第三十三条规定的行为而取得的债务人的财产，管理人有权追回。"},{"i":35,"n":"第三十五条","txt":"人民法院受理破产申请后，债务人的出资人尚未完全履行出资义务的，管理人应当要求该出资人缴纳所认缴的出资，而不受出资期限的限制。"},{"i":36,"n":"第三十六条","txt":"债务人的董事、监事和高级管理人员利用职权从企业获取的非正常收入和侵占的企业财产，管理人应当追回。"},{"i":37,"n":"第三十七条","txt":"人民法院受理破产申请后，管理人可以通过清偿债务或者提供为债权人接受的担保，取回质物、留置物。"},{"i":38,"n":"第三十八条","txt":"人民法院受理破产申请后，债务人占有的不属于债务人的财产，该财产的权利人可以通过管理人取回。但是，本法另有规定的除外。"},{"i":39,"n":"第三十九条","txt":"人民法院受理破产申请时，出卖人已将买卖标的物向作为买受人的债务人发运，债务人尚未收到且未付清全部价款的，出卖人可以取回在运途中的标的物。但是，管理人可以支付全部价款，请求出卖人交付标的物。"},{"i":40,"n":"第四十条","txt":"债权人在破产申请受理前对债务人负有债务的，可以向管理人主张抵销。但是，有下列情形之一的，不得抵销："},{"i":41,"n":"第四十一条","txt":"人民法院受理破产申请后发生的下列费用，为破产费用："},{"i":42,"n":"第四十二条","txt":"人民法院受理破产申请后发生的下列债务，为共益债务："},{"i":43,"n":"第四十三条","txt":"破产费用和共益债务由债务人财产随时清偿。"},{"i":44,"n":"第四十四条","txt":"人民法院受理破产申请时对债务人享有债权的债权人，依照本法规定的程序行使权利。"},{"i":45,"n":"第四十五条","txt":"人民法院受理破产申请后，应当确定债权人申报债权的期限。债权申报期限自人民法院发布受理破产申请公告之日起计算，最短不得少于三十日，最长不得超过三个月。"},{"i":46,"n":"第四十六条","txt":"未到期的债权，在破产申请受理时视为到期。"},{"i":47,"n":"第四十七条","txt":"附条件、附期限的债权和诉讼、仲裁未决的债权，债权人可以申报。"},{"i":48,"n":"第四十八条","txt":"债权人应当在人民法院确定的债权申报期限内向管理人申报债权。"},{"i":49,"n":"第四十九条","txt":"债权人申报债权时，应当书面说明债权的数额和有无财产担保，并提交有关证据。申报的债权是连带债权的，应当说明。"},{"i":50,"n":"第五十条","txt":"连带债权人可以由其中一人代表全体连带债权人申报债权，也可以共同申报债权。"},{"i":51,"n":"第五十一条","txt":"债务人的保证人或者其他连带债务人已经代替债务人清偿债务的，以其对债务人的求偿权申报债权。"},{"i":52,"n":"第五十二条","txt":"连带债务人数人被裁定适用本法规定的程序的，其债权人有权就全部债权分别在各破产案件中申报债权。"},{"i":53,"n":"第五十三条","txt":"管理人或者债务人依照本法规定解除合同的，对方当事人以因合同解除所产生的损害赔偿请求权申报债权。"},{"i":54,"n":"第五十四条","txt":"债务人是委托合同的委托人，被裁定适用本法规定的程序，受托人不知该事实，继续处理委托事务的，受托人以由此产生的请求权申报债权。"},{"i":55,"n":"第五十五条","txt":"债务人是票据的出票人，被裁定适用本法规定的程序，该票据的付款人继续付款或者承兑的，付款人以由此产生的请求权申报债权。"},{"i":56,"n":"第五十六条","txt":"在人民法院确定的债权申报期限内，债权人未申报债权的，可以在破产财产最后分配前补充申报；但是，此前已进行的分配，不再对其补充分配。为审查和确认补充申报债权的费用，由补充申报人承担。"},{"i":57,"n":"第五十七条","txt":"管理人收到债权申报材料后，应当登记造册，对申报的债权进行审查，并编制债权表。"},{"i":58,"n":"第五十八条","txt":"依照本法第五十七条规定编制的债权表，应当提交第一次债权人会议核查。"},{"i":59,"n":"第五十九条","txt":"依法申报债权的债权人为债权人会议的成员，有权参加债权人会议，享有表决权。"},{"i":60,"n":"第六十条","txt":"债权人会议设主席一人，由人民法院从有表决权的债权人中指定。"},{"i":61,"n":"第六十一条","txt":"债权人会议行使下列职权："},{"i":62,"n":"第六十二条","txt":"第一次债权人会议由人民法院召集，自债权申报期限届满之日起十五日内召开。"},{"i":63,"n":"第六十三条","txt":"召开债权人会议，管理人应当提前十五日通知已知的债权人。"},{"i":64,"n":"第六十四条","txt":"债权人会议的决议，由出席会议的有表决权的债权人过半数通过，并且其所代表的债权额占无财产担保债权总额的二分之一以上。但是，本法另有规定的除外。"},{"i":65,"n":"第六十五条","txt":"本法第六十一条第一款第八项、第九项所列事项，经债权人会议表决未通过的，由人民法院裁定。"},{"i":66,"n":"第六十六条","txt":"债权人对人民法院依照本法第六十五条第一款作出的裁定不服的，债权额占无财产担保债权总额二分之一以上的债权人对人民法院依照本法第六十五条第二款作出的裁定不服的，可以自裁定宣布之日或者收到通知之日起十五日内向该人民法院申请复议。复议期间不停止裁定的执行。"},{"i":67,"n":"第六十七条","txt":"债权人会议可以决定设立债权人委员会。债权人委员会由债权人会议选任的债权人代表和一名债务人的职工代表或者工会代表组成。债权人委员会成员不得超过九人。"},{"i":68,"n":"第六十八条","txt":"债权人委员会行使下列职权："},{"i":69,"n":"第六十九条","txt":"管理人实施下列行为，应当及时报告债权人委员会："},{"i":70,"n":"第七十条","txt":"债务人或者债权人可以依照本法规定，直接向人民法院申请对债务人进行重整。"},{"i":71,"n":"第七十一条","txt":"人民法院经审查认为重整申请符合本法规定的，应当裁定债务人重整，并予以公告。"},{"i":72,"n":"第七十二条","txt":"自人民法院裁定债务人重整之日起至重整程序终止，为重整期间。"},{"i":73,"n":"第七十三条","txt":"在重整期间，经债务人申请，人民法院批准，债务人可以在管理人的监督下自行管理财产和营业事务。"},{"i":74,"n":"第七十四条","txt":"管理人负责管理财产和营业事务的，可以聘任债务人的经营管理人员负责营业事务。"},{"i":75,"n":"第七十五条","txt":"在重整期间，对债务人的特定财产享有的担保权暂停行使。但是，担保物有损坏或者价值明显减少的可能，足以危害担保权人权利的，担保权人可以向人民法院请求恢复行使担保权。"},{"i":76,"n":"第七十六条","txt":"债务人合法占有的他人财产，该财产的权利人在重整期间要求取回的，应当符合事先约定的条件。"},{"i":77,"n":"第七十七条","txt":"在重整期间，债务人的出资人不得请求投资收益分配。"},{"i":78,"n":"第七十八条","txt":"在重整期间，有下列情形之一的，经管理人或者利害关系人请求，人民法院应当裁定终止重整程序，并宣告债务人破产："},{"i":79,"n":"第七十九条","txt":"债务人或者管理人应当自人民法院裁定债务人重整之日起六个月内，同时向人民法院和债权人会议提交重整计划草案。"},{"i":80,"n":"第八十条","txt":"债务人自行管理财产和营业事务的，由债务人制作重整计划草案。"},{"i":81,"n":"第八十一条","txt":"重整计划草案应当包括下列内容："},{"i":82,"n":"第八十二条","txt":"下列各类债权的债权人参加讨论重整计划草案的债权人会议，依照下列债权分类，分组对重整计划草案进行表决："},{"i":83,"n":"第八十三条","txt":"重整计划不得规定减免债务人欠缴的本法第八十二条第一款第二项规定以外的社会保险费用；该项费用的债权人不参加重整计划草案的表决。"},{"i":84,"n":"第八十四条","txt":"人民法院应当自收到重整计划草案之日起三十日内召开债权人会议，对重整计划草案进行表决。"},{"i":85,"n":"第八十五条","txt":"债务人的出资人代表可以列席讨论重整计划草案的债权人会议。"},{"i":86,"n":"第八十六条","txt":"各表决组均通过重整计划草案时，重整计划即为通过。"},{"i":87,"n":"第八十七条","txt":"部分表决组未通过重整计划草案的，债务人或者管理人可以同未通过重整计划草案的表决组协商。该表决组可以在协商后再表决一次。双方协商的结果不得损害其他表决组的利益。"},{"i":88,"n":"第八十八条","txt":"重整计划草案未获得通过且未依照本法第八十七条的规定获得批准，或者已通过的重整计划未获得批准的，人民法院应当裁定终止重整程序，并宣告债务人破产。"},{"i":89,"n":"第八十九条","txt":"重整计划由债务人负责执行。"},{"i":90,"n":"第九十条","txt":"自人民法院裁定批准重整计划之日起，在重整计划规定的监督期内，由管理人监督重整计划的执行。"},{"i":91,"n":"第九十一条","txt":"监督期届满时，管理人应当向人民法院提交监督报告。自监督报告提交之日起，管理人的监督职责终止。"},{"i":92,"n":"第九十二条","txt":"经人民法院裁定批准的重整计划，对债务人和全体债权人均有约束力。"},{"i":93,"n":"第九十三条","txt":"债务人不能执行或者不执行重整计划的，人民法院经管理人或者利害关系人请求，应当裁定终止重整计划的执行，并宣告债务人破产。"},{"i":94,"n":"第九十四条","txt":"按照重整计划减免的债务，自重整计划执行完毕时起，债务人不再承担清偿责任。"},{"i":95,"n":"第九十五条","txt":"债务人可以依照本法规定，直接向人民法院申请和解；也可以在人民法院受理破产申请后、宣告债务人破产前，向人民法院申请和解。"},{"i":96,"n":"第九十六条","txt":"人民法院经审查认为和解申请符合本法规定的，应当裁定和解，予以公告，并召集债权人会议讨论和解协议草案。"},{"i":97,"n":"第九十七条","txt":"债权人会议通过和解协议的决议，由出席会议的有表决权的债权人过半数同意，并且其所代表的债权额占无财产担保债权总额的三分之二以上。"},{"i":98,"n":"第九十八条","txt":"债权人会议通过和解协议的，由人民法院裁定认可，终止和解程序，并予以公告。管理人应当向债务人移交财产和营业事务，并向人民法院提交执行职务的报告。"},{"i":99,"n":"第九十九条","txt":"和解协议草案经债权人会议表决未获得通过，或者已经债权人会议通过的和解协议未获得人民法院认可的，人民法院应当裁定终止和解程序，并宣告债务人破产。"},{"i":100,"n":"第一百条","txt":"经人民法院裁定认可的和解协议，对债务人和全体和解债权人均有约束力。"},{"i":101,"n":"第一百零一条","txt":"和解债权人对债务人的保证人和其他连带债务人所享有的权利，不受和解协议的影响。"},{"i":102,"n":"第一百零二条","txt":"债务人应当按照和解协议规定的条件清偿债务。"},{"i":103,"n":"第一百零三条","txt":"因债务人的欺诈或者其他违法行为而成立的和解协议，人民法院应当裁定无效，并宣告债务人破产。"},{"i":104,"n":"第一百零四条","txt":"债务人不能执行或者不执行和解协议的，人民法院经和解债权人请求，应当裁定终止和解协议的执行，并宣告债务人破产。"},{"i":105,"n":"第一百零五条","txt":"人民法院受理破产申请后，债务人与全体债权人就债权债务的处理自行达成协议的，可以请求人民法院裁定认可，并终结破产程序。"},{"i":106,"n":"第一百零六条","txt":"按照和解协议减免的债务，自和解协议执行完毕时起，债务人不再承担清偿责任。"},{"i":107,"n":"第一百零七条","txt":"人民法院依照本法规定宣告债务人破产的，应当自裁定作出之日起五日内送达债务人和管理人，自裁定作出之日起十日内通知已知债权人，并予以公告。"},{"i":108,"n":"第一百零八条","txt":"破产宣告前，有下列情形之一的，人民法院应当裁定终结破产程序，并予以公告："},{"i":109,"n":"第一百零九条","txt":"对破产人的特定财产享有担保权的权利人，对该特定财产享有优先受偿的权利。"},{"i":110,"n":"第一百一十条","txt":"享有本法第一百零九条规定权利的债权人行使优先受偿权利未能完全受偿的，其未受偿的债权作为普通债权；放弃优先受偿权利的，其债权作为普通债权。"},{"i":111,"n":"第一百一十一条","txt":"管理人应当及时拟订破产财产变价方案，提交债权人会议讨论。"},{"i":112,"n":"第一百一十二条","txt":"变价出售破产财产应当通过拍卖进行。但是，债权人会议另有决议的除外。"},{"i":113,"n":"第一百一十三条","txt":"破产财产在优先清偿破产费用和共益债务后，依照下列顺序清偿："},{"i":114,"n":"第一百一十四条","txt":"破产财产的分配应当以货币分配方式进行。但是，债权人会议另有决议的除外。"},{"i":115,"n":"第一百一十五条","txt":"管理人应当及时拟订破产财产分配方案，提交债权人会议讨论。"},{"i":116,"n":"第一百一十六条","txt":"破产财产分配方案经人民法院裁定认可后，由管理人执行。"},{"i":117,"n":"第一百一十七条","txt":"对于附生效条件或者解除条件的债权，管理人应当将其分配额提存。"},{"i":118,"n":"第一百一十八条","txt":"债权人未受领的破产财产分配额，管理人应当提存。债权人自最后分配公告之日起满二个月仍不领取的，视为放弃受领分配的权利，管理人或者人民法院应当将提存的分配额分配给其他债权人。"},{"i":119,"n":"第一百一十九条","txt":"破产财产分配时，对于诉讼或者仲裁未决的债权，管理人应当将其分配额提存。自破产程序终结之日起满二年仍不能受领分配的，人民法院应当将提存的分配额分配给其他债权人。"},{"i":120,"n":"第一百二十条","txt":"破产人无财产可供分配的，管理人应当请求人民法院裁定终结破产程序。"},{"i":121,"n":"第一百二十一条","txt":"管理人应当自破产程序终结之日起十日内，持人民法院终结破产程序的裁定，向破产人的原登记机关办理注销登记。"},{"i":122,"n":"第一百二十二条","txt":"管理人于办理注销登记完毕的次日终止执行职务。但是，存在诉讼或者仲裁未决情况的除外。"},{"i":123,"n":"第一百二十三条","txt":"自破产程序依照本法第四十三条第四款或者第一百二十条的规定终结之日起二年内，有下列情形之一的，债权人可以请求人民法院按照破产财产分配方案进行追加分配："},{"i":124,"n":"第一百二十四条","txt":"破产人的保证人和其他连带债务人，在破产程序终结后，对债权人依照破产清算程序未受清偿的债权，依法继续承担清偿责任。"},{"i":125,"n":"第一百二十五条","txt":"企业董事、监事或者高级管理人员违反忠实义务、勤勉义务，致使所在企业破产的，依法承担民事责任。"},{"i":126,"n":"第一百二十六条","txt":"有义务列席债权人会议的债务人的有关人员，经人民法院传唤，无正当理由拒不列席债权人会议的，人民法院可以拘传，并依法处以罚款。债务人的有关人员违反本法规定，拒不陈述、回答，或者作虚假陈述、回答的，人民法院可以依法处以罚款。"},{"i":127,"n":"第一百二十七条","txt":"债务人违反本法规定，拒不向人民法院提交或者提交不真实的财产状况说明、债务清册、债权清册、有关财务会计报告以及职工工资的支付情况和社会保险费用的缴纳情况的，人民法院可以对直接责任人员依法处以罚款。"},{"i":128,"n":"第一百二十八条","txt":"债务人有本法第三十一条、第三十二条、第三十三条规定的行为，损害债权人利益的，债务人的法定代表人和其他直接责任人员依法承担赔偿责任。"},{"i":129,"n":"第一百二十九条","txt":"债务人的有关人员违反本法规定，擅自离开住所地的，人民法院可以予以训诫、拘留，可以依法并处罚款。"},{"i":130,"n":"第一百三十条","txt":"管理人未依照本法规定勤勉尽责，忠实执行职务的，人民法院可以依法处以罚款；给债权人、债务人或者第三人造成损失的，依法承担赔偿责任。"},{"i":131,"n":"第一百三十一条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":132,"n":"第一百三十二条","txt":"本法施行后，破产人在本法公布之日前所欠职工的工资和医疗、伤残补助、抚恤费用，所欠的应当划入职工个人账户的基本养老保险、基本医疗保险费用，以及法律、行政法规规定应当支付给职工的补偿金，依照本法第一百一十三条的规定清偿后不足以清偿的部分，以本法第一百零九条规定的特定财产优先于对该特定财产享有担保权的权利人受偿。"},{"i":133,"n":"第一百三十三条","txt":"在本法施行前国务院规定的期限和范围内的国有企业实施破产的特殊事宜，按照国务院有关规定办理。"},{"i":134,"n":"第一百三十四条","txt":"商业银行、证券公司、保险公司等金融机构有本法第二条规定情形的，国务院金融监督管理机构可以向人民法院提出对该金融机构进行重整或者破产清算的申请。国务院金融监督管理机构依法对出现重大经营风险的金融机构采取接管、托管等措施的，可以向人民法院申请中止以该金融机构为被告或者被执行人的民事诉讼程序或者执行程序。"},{"i":135,"n":"第一百三十五条","txt":"其他法律规定企业法人以外的组织的清算，属于破产清算的，参照适用本法规定的程序。"},{"i":136,"n":"第一百三十六条","txt":"本法自2007年6月1日起施行，《中华人民共和国企业破产法（试行）》同时废止。"}],"baoxianfa":[{"i":1,"n":"第一条","txt":"为了规范保险活动，保护保险活动当事人的合法权益，加强对保险业的监督管理，维护社会经济秩序和社会公共利益，促进保险事业的健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称保险，是指投保人根据合同约定，向保险人支付保险费，保险人对于合同约定的可能发生的事故因其发生所造成的财产损失承担赔偿保险金责任，或者当被保险人死亡、伤残、疾病或者达到合同约定的年龄、期限等条件时承担给付保险金责任的商业保险行为。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事保险活动，适用本法。"},{"i":4,"n":"第四条","txt":"从事保险活动必须遵守法律、行政法规，尊重社会公德，不得损害社会公共利益。"},{"i":5,"n":"第五条","txt":"保险活动当事人行使权利、履行义务应当遵循诚实信用原则。"},{"i":6,"n":"第六条","txt":"保险业务由依照本法设立的保险公司以及法律、行政法规规定的其他保险组织经营，其他单位和个人不得经营保险业务。"},{"i":7,"n":"第七条","txt":"在中华人民共和国境内的法人和其他组织需要办理境内保险的，应当向中华人民共和国境内的保险公司投保。"},{"i":8,"n":"第八条","txt":"保险业和银行业、证券业、信托业实行分业经营、分业管理，保险公司与银行、证券、信托业务机构分别设立。国家另有规定的除外。"},{"i":9,"n":"第九条","txt":"国务院保险监督管理机构依法对保险业实施监督管理。"},{"i":10,"n":"第十条","txt":"保险合同是投保人与保险人约定保险权利义务关系的协议。"},{"i":11,"n":"第十一条","txt":"订立保险合同，应当协商一致，遵循公平原则确定各方的权利和义务。"},{"i":12,"n":"第十二条","txt":"人身保险的投保人在保险合同订立时，对被保险人应当具有保险利益。"},{"i":13,"n":"第十三条","txt":"投保人提出保险要求，经保险人同意承保，保险合同成立。保险人应当及时向投保人签发保险单或者其他保险凭证。"},{"i":14,"n":"第十四条","txt":"保险合同成立后，投保人按照约定交付保险费，保险人按照约定的时间开始承担保险责任。"},{"i":15,"n":"第十五条","txt":"除本法另有规定或者保险合同另有约定外，保险合同成立后，投保人可以解除合同，保险人不得解除合同。"},{"i":16,"n":"第十六条","txt":"订立保险合同，保险人就保险标的或者被保险人的有关情况提出询问的，投保人应当如实告知。"},{"i":17,"n":"第十七条","txt":"订立保险合同，采用保险人提供的格式条款的，保险人向投保人提供的投保单应当附格式条款，保险人应当向投保人说明合同的内容。"},{"i":18,"n":"第十八条","txt":"保险合同应当包括下列事项："},{"i":19,"n":"第十九条","txt":"采用保险人提供的格式条款订立的保险合同中的下列条款无效："},{"i":20,"n":"第二十条","txt":"投保人和保险人可以协商变更合同内容。"},{"i":21,"n":"第二十一条","txt":"投保人、被保险人或者受益人知道保险事故发生后，应当及时通知保险人。故意或者因重大过失未及时通知，致使保险事故的性质、原因、损失程度等难以确定的，保险人对无法确定的部分，不承担赔偿或者给付保险金的责任，但保险人通过其他途径已经及时知道或者应当及时知道保险事故发生的除外。"},{"i":22,"n":"第二十二条","txt":"保险事故发生后，按照保险合同请求保险人赔偿或者给付保险金时，投保人、被保险人或者受益人应当向保险人提供其所能提供的与确认保险事故的性质、原因、损失程度等有关的证明和资料。"},{"i":23,"n":"第二十三条","txt":"保险人收到被保险人或者受益人的赔偿或者给付保险金的请求后，应当及时作出核定；情形复杂的，应当在三十日内作出核定，但合同另有约定的除外。保险人应当将核定结果通知被保险人或者受益人；对属于保险责任的，在与被保险人或者受益人达成赔偿或者给付保险金的协议后十日内，履行赔偿或者给付保险金义务。保险合同对赔偿或者给付保险金的期限有约定的，保险人应当按照约定履行赔偿或者给付保险金义务。"},{"i":24,"n":"第二十四条","txt":"保险人依照本法第二十三条的规定作出核定后，对不属于保险责任的，应当自作出核定之日起三日内向被保险人或者受益人发出拒绝赔偿或者拒绝给付保险金通知书，并说明理由。"},{"i":25,"n":"第二十五条","txt":"保险人自收到赔偿或者给付保险金的请求和有关证明、资料之日起六十日内，对其赔偿或者给付保险金的数额不能确定的，应当根据已有证明和资料可以确定的数额先予支付；保险人最终确定赔偿或者给付保险金的数额后，应当支付相应的差额。"},{"i":26,"n":"第二十六条","txt":"人寿保险以外的其他保险的被保险人或者受益人，向保险人请求赔偿或者给付保险金的诉讼时效期间为二年，自其知道或者应当知道保险事故发生之日起计算。"},{"i":27,"n":"第二十七条","txt":"未发生保险事故，被保险人或者受益人谎称发生了保险事故，向保险人提出赔偿或者给付保险金请求的，保险人有权解除合同，并不退还保险费。"},{"i":28,"n":"第二十八条","txt":"保险人将其承担的保险业务，以分保形式部分转移给其他保险人的，为再保险。"},{"i":29,"n":"第二十九条","txt":"再保险接受人不得向原保险的投保人要求支付保险费。"},{"i":30,"n":"第三十条","txt":"采用保险人提供的格式条款订立的保险合同，保险人与投保人、被保险人或者受益人对合同条款有争议的，应当按照通常理解予以解释。对合同条款有两种以上解释的，人民法院或者仲裁机构应当作出有利于被保险人和受益人的解释。"},{"i":31,"n":"第三十一条","txt":"投保人对下列人员具有保险利益："},{"i":32,"n":"第三十二条","txt":"投保人申报的被保险人年龄不真实，并且其真实年龄不符合合同约定的年龄限制的，保险人可以解除合同，并按照合同约定退还保险单的现金价值。保险人行使合同解除权，适用本法第十六条第三款、第六款的规定。"},{"i":33,"n":"第三十三条","txt":"投保人不得为无民事行为能力人投保以死亡为给付保险金条件的人身保险，保险人也不得承保。"},{"i":34,"n":"第三十四条","txt":"以死亡为给付保险金条件的合同，未经被保险人同意并认可保险金额的，合同无效。"},{"i":35,"n":"第三十五条","txt":"投保人可以按照合同约定向保险人一次支付全部保险费或者分期支付保险费。"},{"i":36,"n":"第三十六条","txt":"合同约定分期支付保险费，投保人支付首期保险费后，除合同另有约定外，投保人自保险人催告之日起超过三十日未支付当期保险费，或者超过约定的期限六十日未支付当期保险费的，合同效力中止，或者由保险人按照合同约定的条件减少保险金额。"},{"i":37,"n":"第三十七条","txt":"合同效力依照本法第三十六条规定中止的，经保险人与投保人协商并达成协议，在投保人补交保险费后，合同效力恢复。但是，自合同效力中止之日起满二年双方未达成协议的，保险人有权解除合同。"},{"i":38,"n":"第三十八条","txt":"保险人对人寿保险的保险费，不得用诉讼方式要求投保人支付。"},{"i":39,"n":"第三十九条","txt":"人身保险的受益人由被保险人或者投保人指定。"},{"i":40,"n":"第四十条","txt":"被保险人或者投保人可以指定一人或者数人为受益人。"},{"i":41,"n":"第四十一条","txt":"被保险人或者投保人可以变更受益人并书面通知保险人。保险人收到变更受益人的书面通知后，应当在保险单或者其他保险凭证上批注或者附贴批单。"},{"i":42,"n":"第四十二条","txt":"被保险人死亡后，有下列情形之一的，保险金作为被保险人的遗产，由保险人依照《中华人民共和国继承法》的规定履行给付保险金的义务："},{"i":43,"n":"第四十三条","txt":"投保人故意造成被保险人死亡、伤残或者疾病的，保险人不承担给付保险金的责任。投保人已交足二年以上保险费的，保险人应当按照合同约定向其他权利人退还保险单的现金价值。"},{"i":44,"n":"第四十四条","txt":"以被保险人死亡为给付保险金条件的合同，自合同成立或者合同效力恢复之日起二年内，被保险人自杀的，保险人不承担给付保险金的责任，但被保险人自杀时为无民事行为能力人的除外。"},{"i":45,"n":"第四十五条","txt":"因被保险人故意犯罪或者抗拒依法采取的刑事强制措施导致其伤残或者死亡的，保险人不承担给付保险金的责任。投保人已交足二年以上保险费的，保险人应当按照合同约定退还保险单的现金价值。"},{"i":46,"n":"第四十六条","txt":"被保险人因第三者的行为而发生死亡、伤残或者疾病等保险事故的，保险人向被保险人或者受益人给付保险金后，不享有向第三者追偿的权利，但被保险人或者受益人仍有权向第三者请求赔偿。"},{"i":47,"n":"第四十七条","txt":"投保人解除合同的，保险人应当自收到解除合同通知之日起三十日内，按照合同约定退还保险单的现金价值。"},{"i":48,"n":"第四十八条","txt":"保险事故发生时，被保险人对保险标的不具有保险利益的，不得向保险人请求赔偿保险金。"},{"i":49,"n":"第四十九条","txt":"保险标的转让的，保险标的的受让人承继被保险人的权利和义务。"},{"i":50,"n":"第五十条","txt":"货物运输保险合同和运输工具航程保险合同，保险责任开始后，合同当事人不得解除合同。"},{"i":51,"n":"第五十一条","txt":"被保险人应当遵守国家有关消防、安全、生产操作、劳动保护等方面的规定，维护保险标的的安全。"},{"i":52,"n":"第五十二条","txt":"在合同有效期内，保险标的的危险程度显著增加的，被保险人应当按照合同约定及时通知保险人，保险人可以按照合同约定增加保险费或者解除合同。保险人解除合同的，应当将已收取的保险费，按照合同约定扣除自保险责任开始之日起至合同解除之日止应收的部分后，退还投保人。"},{"i":53,"n":"第五十三条","txt":"有下列情形之一的，除合同另有约定外，保险人应当降低保险费，并按日计算退还相应的保险费："},{"i":54,"n":"第五十四条","txt":"保险责任开始前，投保人要求解除合同的，应当按照合同约定向保险人支付手续费，保险人应当退还保险费。保险责任开始后，投保人要求解除合同的，保险人应当将已收取的保险费，按照合同约定扣除自保险责任开始之日起至合同解除之日止应收的部分后，退还投保人。"},{"i":55,"n":"第五十五条","txt":"投保人和保险人约定保险标的的保险价值并在合同中载明的，保险标的发生损失时，以约定的保险价值为赔偿计算标准。"},{"i":56,"n":"第五十六条","txt":"重复保险的投保人应当将重复保险的有关情况通知各保险人。"},{"i":57,"n":"第五十七条","txt":"保险事故发生时，被保险人应当尽力采取必要的措施，防止或者减少损失。"},{"i":58,"n":"第五十八条","txt":"保险标的发生部分损失的，自保险人赔偿之日起三十日内，投保人可以解除合同；除合同另有约定外，保险人也可以解除合同，但应当提前十五日通知投保人。"},{"i":59,"n":"第五十九条","txt":"保险事故发生后，保险人已支付了全部保险金额，并且保险金额等于保险价值的，受损保险标的的全部权利归于保险人；保险金额低于保险价值的，保险人按照保险金额与保险价值的比例取得受损保险标的的部分权利。"},{"i":60,"n":"第六十条","txt":"因第三者对保险标的的损害而造成保险事故的，保险人自向被保险人赔偿保险金之日起，在赔偿金额范围内代位行使被保险人对第三者请求赔偿的权利。"},{"i":61,"n":"第六十一条","txt":"保险事故发生后，保险人未赔偿保险金之前，被保险人放弃对第三者请求赔偿的权利的，保险人不承担赔偿保险金的责任。"},{"i":62,"n":"第六十二条","txt":"除被保险人的家庭成员或者其组成人员故意造成本法第六十条第一款规定的保险事故外，保险人不得对被保险人的家庭成员或者其组成人员行使代位请求赔偿的权利。"},{"i":63,"n":"第六十三条","txt":"保险人向第三者行使代位请求赔偿的权利时，被保险人应当向保险人提供必要的文件和所知道的有关情况。"},{"i":64,"n":"第六十四条","txt":"保险人、被保险人为查明和确定保险事故的性质、原因和保险标的的损失程度所支付的必要的、合理的费用，由保险人承担。"},{"i":65,"n":"第六十五条","txt":"保险人对责任保险的被保险人给第三者造成的损害，可以依照法律的规定或者合同的约定，直接向该第三者赔偿保险金。"},{"i":66,"n":"第六十六条","txt":"责任保险的被保险人因给第三者造成损害的保险事故而被提起仲裁或者诉讼的，被保险人支付的仲裁或者诉讼费用以及其他必要的、合理的费用，除合同另有约定外，由保险人承担。"},{"i":67,"n":"第六十七条","txt":"设立保险公司应当经国务院保险监督管理机构批准。"},{"i":68,"n":"第六十八条","txt":"设立保险公司应当具备下列条件："},{"i":69,"n":"第六十九条","txt":"设立保险公司，其注册资本的最低限额为人民币二亿元。"},{"i":70,"n":"第七十条","txt":"申请设立保险公司，应当向国务院保险监督管理机构提出书面申请，并提交下列材料："},{"i":71,"n":"第七十一条","txt":"国务院保险监督管理机构应当对设立保险公司的申请进行审查，自受理之日起六个月内作出批准或者不批准筹建的决定，并书面通知申请人。决定不批准的，应当书面说明理由。"},{"i":72,"n":"第七十二条","txt":"申请人应当自收到批准筹建通知之日起一年内完成筹建工作；筹建期间不得从事保险经营活动。"},{"i":73,"n":"第七十三条","txt":"筹建工作完成后，申请人具备本法第六十八条规定的设立条件的，可以向国务院保险监督管理机构提出开业申请。"},{"i":74,"n":"第七十四条","txt":"保险公司在中华人民共和国境内设立分支机构，应当经保险监督管理机构批准。"},{"i":75,"n":"第七十五条","txt":"保险公司申请设立分支机构，应当向保险监督管理机构提出书面申请，并提交下列材料："},{"i":76,"n":"第七十六条","txt":"保险监督管理机构应当对保险公司设立分支机构的申请进行审查，自受理之日起六十日内作出批准或者不批准的决定。决定批准的，颁发分支机构经营保险业务许可证；决定不批准的，应当书面通知申请人并说明理由。"},{"i":77,"n":"第七十七条","txt":"经批准设立的保险公司及其分支机构，凭经营保险业务许可证向工商行政管理机关办理登记，领取营业执照。"},{"i":78,"n":"第七十八条","txt":"保险公司及其分支机构自取得经营保险业务许可证之日起六个月内，无正当理由未向工商行政管理机关办理登记的，其经营保险业务许可证失效。"},{"i":79,"n":"第七十九条","txt":"保险公司在中华人民共和国境外设立子公司、分支机构，应当经国务院保险监督管理机构批准。"},{"i":80,"n":"第八十条","txt":"外国保险机构在中华人民共和国境内设立代表机构，应当经国务院保险监督管理机构批准。代表机构不得从事保险经营活动。"},{"i":81,"n":"第八十一条","txt":"保险公司的董事、监事和高级管理人员，应当品行良好，熟悉与保险相关的法律、行政法规，具有履行职责所需的经营管理能力，并在任职前取得保险监督管理机构核准的任职资格。"},{"i":82,"n":"第八十二条","txt":"有《中华人民共和国公司法》第一百四十六条规定的情形或者下列情形之一的，不得担任保险公司的董事、监事、高级管理人员："},{"i":83,"n":"第八十三条","txt":"保险公司的董事、监事、高级管理人员执行公司职务时违反法律、行政法规或者公司章程的规定，给公司造成损失的，应当承担赔偿责任。"},{"i":84,"n":"第八十四条","txt":"保险公司有下列情形之一的，应当经保险监督管理机构批准："},{"i":85,"n":"第八十五条","txt":"保险公司应当聘用专业人员，建立精算报告制度和合规报告制度。"},{"i":86,"n":"第八十六条","txt":"保险公司应当按照保险监督管理机构的规定，报送有关报告、报表、文件和资料。"},{"i":87,"n":"第八十七条","txt":"保险公司应当按照国务院保险监督管理机构的规定妥善保管业务经营活动的完整账簿、原始凭证和有关资料。"},{"i":88,"n":"第八十八条","txt":"保险公司聘请或者解聘会计师事务所、资产评估机构、资信评级机构等中介服务机构，应当向保险监督管理机构报告；解聘会计师事务所、资产评估机构、资信评级机构等中介服务机构，应当说明理由。"},{"i":89,"n":"第八十九条","txt":"保险公司因分立、合并需要解散，或者股东会、股东大会决议解散，或者公司章程规定的解散事由出现，经国务院保险监督管理机构批准后解散。"},{"i":90,"n":"第九十条","txt":"保险公司有《中华人民共和国企业破产法》第二条规定情形的，经国务院保险监督管理机构同意，保险公司或者其债权人可以依法向人民法院申请重整、和解或者破产清算；国务院保险监督管理机构也可以依法向人民法院申请对该保险公司进行重整或者破产清算。"},{"i":91,"n":"第九十一条","txt":"破产财产在优先清偿破产费用和共益债务后，按照下列顺序清偿："},{"i":92,"n":"第九十二条","txt":"经营有人寿保险业务的保险公司被依法撤销或者被依法宣告破产的，其持有的人寿保险合同及责任准备金，必须转让给其他经营有人寿保险业务的保险公司；不能同其他保险公司达成转让协议的，由国务院保险监督管理机构指定经营有人寿保险业务的保险公司接受转让。"},{"i":93,"n":"第九十三条","txt":"保险公司依法终止其业务活动，应当注销其经营保险业务许可证。"},{"i":94,"n":"第九十四条","txt":"保险公司，除本法另有规定外，适用《中华人民共和国公司法》的规定。"},{"i":95,"n":"第九十五条","txt":"保险公司的业务范围："},{"i":96,"n":"第九十六条","txt":"经国务院保险监督管理机构批准，保险公司可以经营本法第九十五条规定的保险业务的下列再保险业务："},{"i":97,"n":"第九十七条","txt":"保险公司应当按照其注册资本总额的百分之二十提取保证金，存入国务院保险监督管理机构指定的银行，除公司清算时用于清偿债务外，不得动用。"},{"i":98,"n":"第九十八条","txt":"保险公司应当根据保障被保险人利益、保证偿付能力的原则，提取各项责任准备金。"},{"i":99,"n":"第九十九条","txt":"保险公司应当依法提取公积金。"},{"i":100,"n":"第一百条","txt":"保险公司应当缴纳保险保障基金。"},{"i":101,"n":"第一百零一条","txt":"保险公司应当具有与其业务规模和风险程度相适应的最低偿付能力。保险公司的认可资产减去认可负债的差额不得低于国务院保险监督管理机构规定的数额；低于规定数额的，应当按照国务院保险监督管理机构的要求采取相应措施达到规定的数额。"},{"i":102,"n":"第一百零二条","txt":"经营财产保险业务的保险公司当年自留保险费，不得超过其实有资本金加公积金总和的四倍。"},{"i":103,"n":"第一百零三条","txt":"保险公司对每一危险单位，即对一次保险事故可能造成的最大损失范围所承担的责任，不得超过其实有资本金加公积金总和的百分之十；超过的部分应当办理再保险。"},{"i":104,"n":"第一百零四条","txt":"保险公司对危险单位的划分方法和巨灾风险安排方案，应当报国务院保险监督管理机构备案。"},{"i":105,"n":"第一百零五条","txt":"保险公司应当按照国务院保险监督管理机构的规定办理再保险，并审慎选择再保险接受人。"},{"i":106,"n":"第一百零六条","txt":"保险公司的资金运用必须稳健，遵循安全性原则。"},{"i":107,"n":"第一百零七条","txt":"经国务院保险监督管理机构会同国务院证券监督管理机构批准，保险公司可以设立保险资产管理公司。"},{"i":108,"n":"第一百零八条","txt":"保险公司应当按照国务院保险监督管理机构的规定，建立对关联交易的管理和信息披露制度。"},{"i":109,"n":"第一百零九条","txt":"保险公司的控股股东、实际控制人、董事、监事、高级管理人员不得利用关联交易损害公司的利益。"},{"i":110,"n":"第一百一十条","txt":"保险公司应当按照国务院保险监督管理机构的规定，真实、准确、完整地披露财务会计报告、风险管理状况、保险产品经营情况等重大事项。"},{"i":111,"n":"第一百一十一条","txt":"保险公司从事保险销售的人员应当品行良好，具有保险销售所需的专业能力。保险销售人员的行为规范和管理办法，由国务院保险监督管理机构规定。"},{"i":112,"n":"第一百一十二条","txt":"保险公司应当建立保险代理人登记管理制度，加强对保险代理人的培训和管理，不得唆使、诱导保险代理人进行违背诚信义务的活动。"},{"i":113,"n":"第一百一十三条","txt":"保险公司及其分支机构应当依法使用经营保险业务许可证，不得转让、出租、出借经营保险业务许可证。"},{"i":114,"n":"第一百一十四条","txt":"保险公司应当按照国务院保险监督管理机构的规定，公平、合理拟订保险条款和保险费率，不得损害投保人、被保险人和受益人的合法权益。"},{"i":115,"n":"第一百一十五条","txt":"保险公司开展业务，应当遵循公平竞争的原则，不得从事不正当竞争。"},{"i":116,"n":"第一百一十六条","txt":"保险公司及其工作人员在保险业务活动中不得有下列行为："},{"i":117,"n":"第一百一十七条","txt":"保险代理人是根据保险人的委托，向保险人收取佣金，并在保险人授权的范围内代为办理保险业务的机构或者个人。"},{"i":118,"n":"第一百一十八条","txt":"保险经纪人是基于投保人的利益，为投保人与保险人订立保险合同提供中介服务，并依法收取佣金的机构。"},{"i":119,"n":"第一百一十九条","txt":"保险代理机构、保险经纪人应当具备国务院保险监督管理机构规定的条件，取得保险监督管理机构颁发的经营保险代理业务许可证、保险经纪业务许可证。"},{"i":120,"n":"第一百二十条","txt":"以公司形式设立保险专业代理机构、保险经纪人，其注册资本最低限额适用《中华人民共和国公司法》的规定。"},{"i":121,"n":"第一百二十一条","txt":"保险专业代理机构、保险经纪人的高级管理人员，应当品行良好，熟悉保险法律、行政法规，具有履行职责所需的经营管理能力，并在任职前取得保险监督管理机构核准的任职资格。"},{"i":122,"n":"第一百二十二条","txt":"个人保险代理人、保险代理机构的代理从业人员、保险经纪人的经纪从业人员，应当品行良好，具有从事保险代理业务或者保险经纪业务所需的专业能力。"},{"i":123,"n":"第一百二十三条","txt":"保险代理机构、保险经纪人应当有自己的经营场所，设立专门账簿记载保险代理业务、经纪业务的收支情况。"},{"i":124,"n":"第一百二十四条","txt":"保险代理机构、保险经纪人应当按照国务院保险监督管理机构的规定缴存保证金或者投保职业责任保险。"},{"i":125,"n":"第一百二十五条","txt":"个人保险代理人在代为办理人寿保险业务时，不得同时接受两个以上保险人的委托。"},{"i":126,"n":"第一百二十六条","txt":"保险人委托保险代理人代为办理保险业务，应当与保险代理人签订委托代理协议，依法约定双方的权利和义务。"},{"i":127,"n":"第一百二十七条","txt":"保险代理人根据保险人的授权代为办理保险业务的行为，由保险人承担责任。"},{"i":128,"n":"第一百二十八条","txt":"保险经纪人因过错给投保人、被保险人造成损失的，依法承担赔偿责任。"},{"i":129,"n":"第一百二十九条","txt":"保险活动当事人可以委托保险公估机构等依法设立的独立评估机构或者具有相关专业知识的人员，对保险事故进行评估和鉴定。"},{"i":130,"n":"第一百三十条","txt":"保险佣金只限于向保险代理人、保险经纪人支付，不得向其他人支付。"},{"i":131,"n":"第一百三十一条","txt":"保险代理人、保险经纪人及其从业人员在办理保险业务活动中不得有下列行为："},{"i":132,"n":"第一百三十二条","txt":"本法第八十六条第一款、第一百一十三条的规定，适用于保险代理机构和保险经纪人。"},{"i":133,"n":"第一百三十三条","txt":"保险监督管理机构依照本法和国务院规定的职责，遵循依法、公开、公正的原则，对保险业实施监督管理，维护保险市场秩序，保护投保人、被保险人和受益人的合法权益。"},{"i":134,"n":"第一百三十四条","txt":"国务院保险监督管理机构依照法律、行政法规制定并发布有关保险业监督管理的规章。"},{"i":135,"n":"第一百三十五条","txt":"关系社会公众利益的保险险种、依法实行强制保险的险种和新开发的人寿保险险种等的保险条款和保险费率，应当报国务院保险监督管理机构批准。国务院保险监督管理机构审批时，应当遵循保护社会公众利益和防止不正当竞争的原则。其他保险险种的保险条款和保险费率，应当报保险监督管理机构备案。"},{"i":136,"n":"第一百三十六条","txt":"保险公司使用的保险条款和保险费率违反法律、行政法规或者国务院保险监督管理机构的有关规定的，由保险监督管理机构责令停止使用，限期修改；情节严重的，可以在一定期限内禁止申报新的保险条款和保险费率。"},{"i":137,"n":"第一百三十七条","txt":"国务院保险监督管理机构应当建立健全保险公司偿付能力监管体系，对保险公司的偿付能力实施监控。"},{"i":138,"n":"第一百三十八条","txt":"对偿付能力不足的保险公司，国务院保险监督管理机构应当将其列为重点监管对象，并可以根据具体情况采取下列措施："},{"i":139,"n":"第一百三十九条","txt":"保险公司未依照本法规定提取或者结转各项责任准备金，或者未依照本法规定办理再保险，或者严重违反本法关于资金运用的规定的，由保险监督管理机构责令限期改正，并可以责令调整负责人及有关管理人员。"},{"i":140,"n":"第一百四十条","txt":"保险监督管理机构依照本法第一百三十九条的规定作出限期改正的决定后，保险公司逾期未改正的，国务院保险监督管理机构可以决定选派保险专业人员和指定该保险公司的有关人员组成整顿组，对公司进行整顿。"},{"i":141,"n":"第一百四十一条","txt":"整顿组有权监督被整顿保险公司的日常业务。被整顿公司的负责人及有关管理人员应当在整顿组的监督下行使职权。"},{"i":142,"n":"第一百四十二条","txt":"整顿过程中，被整顿保险公司的原有业务继续进行。但是，国务院保险监督管理机构可以责令被整顿公司停止部分原有业务、停止接受新业务，调整资金运用。"},{"i":143,"n":"第一百四十三条","txt":"被整顿保险公司经整顿已纠正其违反本法规定的行为，恢复正常经营状况的，由整顿组提出报告，经国务院保险监督管理机构批准，结束整顿，并由国务院保险监督管理机构予以公告。"},{"i":144,"n":"第一百四十四条","txt":"保险公司有下列情形之一的，国务院保险监督管理机构可以对其实行接管："},{"i":145,"n":"第一百四十五条","txt":"接管组的组成和接管的实施办法，由国务院保险监督管理机构决定，并予以公告。"},{"i":146,"n":"第一百四十六条","txt":"接管期限届满，国务院保险监督管理机构可以决定延长接管期限，但接管期限最长不得超过二年。"},{"i":147,"n":"第一百四十七条","txt":"接管期限届满，被接管的保险公司已恢复正常经营能力的，由国务院保险监督管理机构决定终止接管，并予以公告。"},{"i":148,"n":"第一百四十八条","txt":"被整顿、被接管的保险公司有《中华人民共和国企业破产法》第二条规定情形的，国务院保险监督管理机构可以依法向人民法院申请对该保险公司进行重整或者破产清算。"},{"i":149,"n":"第一百四十九条","txt":"保险公司因违法经营被依法吊销经营保险业务许可证的，或者偿付能力低于国务院保险监督管理机构规定标准，不予撤销将严重危害保险市场秩序、损害公共利益的，由国务院保险监督管理机构予以撤销并公告，依法及时组织清算组进行清算。"},{"i":150,"n":"第一百五十条","txt":"国务院保险监督管理机构有权要求保险公司股东、实际控制人在指定的期限内提供有关信息和资料。"},{"i":151,"n":"第一百五十一条","txt":"保险公司的股东利用关联交易严重损害公司利益，危及公司偿付能力的，由国务院保险监督管理机构责令改正。在按照要求改正前，国务院保险监督管理机构可以限制其股东权利；拒不改正的，可以责令其转让所持的保险公司股权。"},{"i":152,"n":"第一百五十二条","txt":"保险监督管理机构根据履行监督管理职责的需要，可以与保险公司董事、监事和高级管理人员进行监督管理谈话，要求其就公司的业务活动和风险管理的重大事项作出说明。"},{"i":153,"n":"第一百五十三条","txt":"保险公司在整顿、接管、撤销清算期间，或者出现重大风险时，国务院保险监督管理机构可以对该公司直接负责的董事、监事、高级管理人员和其他直接责任人员采取以下措施："},{"i":154,"n":"第一百五十四条","txt":"保险监督管理机构依法履行职责，可以采取下列措施："},{"i":155,"n":"第一百五十五条","txt":"保险监督管理机构依法履行职责，被检查、调查的单位和个人应当配合。"},{"i":156,"n":"第一百五十六条","txt":"保险监督管理机构工作人员应当忠于职守，依法办事，公正廉洁，不得利用职务便利牟取不正当利益，不得泄露所知悉的有关单位和个人的商业秘密。"},{"i":157,"n":"第一百五十七条","txt":"国务院保险监督管理机构应当与中国人民银行、国务院其他金融监督管理机构建立监督管理信息共享机制。"},{"i":158,"n":"第一百五十八条","txt":"违反本法规定，擅自设立保险公司、保险资产管理公司或者非法经营商业保险业务的，由保险监督管理机构予以取缔，没收违法所得，并处违法所得一倍以上五倍以下的罚款；没有违法所得或者违法所得不足二十万元的，处二十万元以上一百万元以下的罚款。"},{"i":159,"n":"第一百五十九条","txt":"违反本法规定，擅自设立保险专业代理机构、保险经纪人，或者未取得经营保险代理业务许可证、保险经纪业务许可证从事保险代理业务、保险经纪业务的，由保险监督管理机构予以取缔，没收违法所得，并处违法所得一倍以上五倍以下的罚款；没有违法所得或者违法所得不足五万元的，处五万元以上三十万元以下的罚款。"},{"i":160,"n":"第一百六十条","txt":"保险公司违反本法规定，超出批准的业务范围经营的，由保险监督管理机构责令限期改正，没收违法所得，并处违法所得一倍以上五倍以下的罚款；没有违法所得或者违法所得不足十万元的，处十万元以上五十万元以下的罚款。逾期不改正或者造成严重后果的，责令停业整顿或者吊销业务许可证。"},{"i":161,"n":"第一百六十一条","txt":"保险公司有本法第一百一十六条规定行为之一的，由保险监督管理机构责令改正，处五万元以上三十万元以下的罚款；情节严重的，限制其业务范围、责令停止接受新业务或者吊销业务许可证。"},{"i":162,"n":"第一百六十二条","txt":"保险公司违反本法第八十四条规定的，由保险监督管理机构责令改正，处一万元以上十万元以下的罚款。"},{"i":163,"n":"第一百六十三条","txt":"保险公司违反本法规定，有下列行为之一的，由保险监督管理机构责令改正，处五万元以上三十万元以下的罚款："},{"i":164,"n":"第一百六十四条","txt":"违反本法规定，有下列行为之一的，由保险监督管理机构责令改正，处五万元以上三十万元以下的罚款；情节严重的，可以限制其业务范围、责令停止接受新业务或者吊销业务许可证："},{"i":165,"n":"第一百六十五条","txt":"保险代理机构、保险经纪人有本法第一百三十一条规定行为之一的，由保险监督管理机构责令改正，处五万元以上三十万元以下的罚款；情节严重的，吊销业务许可证。"},{"i":166,"n":"第一百六十六条","txt":"保险代理机构、保险经纪人违反本法规定，有下列行为之一的，由保险监督管理机构责令改正，处二万元以上十万元以下的罚款；情节严重的，责令停业整顿或者吊销业务许可证："},{"i":167,"n":"第一百六十七条","txt":"违反本法规定，聘任不具有任职资格的人员的，由保险监督管理机构责令改正，处二万元以上十万元以下的罚款。"},{"i":168,"n":"第一百六十八条","txt":"违反本法规定，转让、出租、出借业务许可证的，由保险监督管理机构处一万元以上十万元以下的罚款；情节严重的，责令停业整顿或者吊销业务许可证。"},{"i":169,"n":"第一百六十九条","txt":"违反本法规定，有下列行为之一的，由保险监督管理机构责令限期改正；逾期不改正的，处一万元以上十万元以下的罚款："},{"i":170,"n":"第一百七十条","txt":"违反本法规定，有下列行为之一的，由保险监督管理机构责令改正，处十万元以上五十万元以下的罚款；情节严重的，可以限制其业务范围、责令停止接受新业务或者吊销业务许可证："},{"i":171,"n":"第一百七十一条","txt":"保险公司、保险资产管理公司、保险专业代理机构、保险经纪人违反本法规定的，保险监督管理机构除分别依照本法第一百六十条至第一百七十条的规定对该单位给予处罚外，对其直接负责的主管人员和其他直接责任人员给予警告，并处一万元以上十万元以下的罚款；情节严重的，撤销任职资格。"},{"i":172,"n":"第一百七十二条","txt":"个人保险代理人违反本法规定的，由保险监督管理机构给予警告，可以并处二万元以下的罚款；情节严重的，处二万元以上十万元以下的罚款。"},{"i":173,"n":"第一百七十三条","txt":"外国保险机构未经国务院保险监督管理机构批准，擅自在中华人民共和国境内设立代表机构的，由国务院保险监督管理机构予以取缔，处五万元以上三十万元以下的罚款。"},{"i":174,"n":"第一百七十四条","txt":"投保人、被保险人或者受益人有下列行为之一，进行保险诈骗活动，尚不构成犯罪的，依法给予行政处罚："},{"i":175,"n":"第一百七十五条","txt":"违反本法规定，给他人造成损害的，依法承担民事责任。"},{"i":176,"n":"第一百七十六条","txt":"拒绝、阻碍保险监督管理机构及其工作人员依法行使监督检查、调查职权，未使用暴力、威胁方法的，依法给予治安管理处罚。"},{"i":177,"n":"第一百七十七条","txt":"违反法律、行政法规的规定，情节严重的，国务院保险监督管理机构可以禁止有关责任人员一定期限直至终身进入保险业。"},{"i":178,"n":"第一百七十八条","txt":"保险监督管理机构从事监督管理工作的人员有下列情形之一的，依法给予处分："},{"i":179,"n":"第一百七十九条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":180,"n":"第一百八十条","txt":"保险公司应当加入保险行业协会。保险代理人、保险经纪人、保险公估机构可以加入保险行业协会。"},{"i":181,"n":"第一百八十一条","txt":"保险公司以外的其他依法设立的保险组织经营的商业保险业务，适用本法。"},{"i":182,"n":"第一百八十二条","txt":"海上保险适用《中华人民共和国海商法》的有关规定；《中华人民共和国海商法》未规定的，适用本法的有关规定。"},{"i":183,"n":"第一百八十三条","txt":"中外合资保险公司、外资独资保险公司、外国保险公司分公司适用本法规定；法律、行政法规另有规定的，适用其规定。"},{"i":184,"n":"第一百八十四条","txt":"国家支持发展为农业生产服务的保险事业。农业保险由法律、行政法规另行规定。"},{"i":185,"n":"第一百八十五条","txt":"本法自2009年10月1日起施行。"}],"xintuofa":[{"i":1,"n":"第一条","txt":"为了调整信托关系，规范信托行为，保护信托当事人的合法权益，促进信托事业的健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称信托，是指委托人基于对受托人的信任，将其财产权委托给受托人，由受托人按委托人的意愿以自己的名义，为受益人的利益或者特定目的，进行管理或者处分的行为。"},{"i":3,"n":"第三条","txt":"委托人、受托人、受益人（以下统称信托当事人）在中华人民共和国境内进行民事、营业、公益信托活动，适用本法。"},{"i":4,"n":"第四条","txt":"受托人采取信托机构形式从事信托活动，其组织和管理由国务院制定具体办法。"},{"i":5,"n":"第五条","txt":"信托当事人进行信托活动，必须遵守法律、行政法规，遵循自愿、公平和诚实信用原则，不得损害国家利益和社会公共利益。"},{"i":6,"n":"第六条","txt":"设立信托，必须有合法的信托目的。"},{"i":7,"n":"第七条","txt":"设立信托，必须有确定的信托财产，并且该信托财产必须是委托人合法所有的财产。"},{"i":8,"n":"第八条","txt":"设立信托，应当采取书面形式。"},{"i":9,"n":"第九条","txt":"设立信托，其书面文件应当载明下列事项："},{"i":10,"n":"第十条","txt":"设立信托，对于信托财产，有关法律、行政法规规定应当办理登记手续的，应当依法办理信托登记。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，信托无效："},{"i":12,"n":"第十二条","txt":"委托人设立信托损害其债权人利益的，债权人有权申请人民法院撤销该信托。"},{"i":13,"n":"第十三条","txt":"设立遗嘱信托，应当遵守继承法关于遗嘱的规定。"},{"i":14,"n":"第十四条","txt":"受托人因承诺信托而取得的财产是信托财产。"},{"i":15,"n":"第十五条","txt":"信托财产与委托人未设立信托的其他财产相区别。设立信托后，委托人死亡或者依法解散、被依法撤销、被宣告破产时，委托人是唯一受益人的，信托终止，信托财产作为其遗产或者清算财产；委托人不是唯一受益人的，信托存续，信托财产不作为其遗产或者清算财产；但作为共同受益人的委托人死亡或者依法解散、被依法撤销、被宣告破产时，其信托受益权作为其遗产或者清算财产。"},{"i":16,"n":"第十六条","txt":"信托财产与属于受托人所有的财产（以下简称固有财产）相区别，不得归入受托人的固有财产或者成为固有财产的一部分。"},{"i":17,"n":"第十七条","txt":"除因下列情形之一外，对信托财产不得强制执行："},{"i":18,"n":"第十八条","txt":"受托人管理运用、处分信托财产所产生的债权，不得与其固有财产产生的债务相抵销。"},{"i":19,"n":"第十九条","txt":"委托人应当是具有完全民事行为能力的自然人、法人或者依法成立的其他组织。"},{"i":20,"n":"第二十条","txt":"委托人有权了解其信托财产的管理运用、处分及收支情况，并有权要求受托人作出说明。"},{"i":21,"n":"第二十一条","txt":"因设立信托时未能预见的特别事由，致使信托财产的管理方法不利于实现信托目的或者不符合受益人的利益时，委托人有权要求受托人调整该信托财产的管理方法。"},{"i":22,"n":"第二十二条","txt":"受托人违反信托目的处分信托财产或者因违背管理职责、处理信托事务不当致使信托财产受到损失的，委托人有权申请人民法院撤销该处分行为，并有权要求受托人恢复信托财产的原状或者予以赔偿；该信托财产的受让人明知是违反信托目的而接受该财产的，应当予以返还或者予以赔偿。"},{"i":23,"n":"第二十三条","txt":"受托人违反信托目的处分信托财产或者管理运用、处分信托财产有重大过失的，委托人有权依照信托文件的规定解任受托人，或者申请人民法院解任受托人。"},{"i":24,"n":"第二十四条","txt":"受托人应当是具有完全民事行为能力的自然人、法人。"},{"i":25,"n":"第二十五条","txt":"受托人应当遵守信托文件的规定，为受益人的最大利益处理信托事务。"},{"i":26,"n":"第二十六条","txt":"受托人除依照本法规定取得报酬外，不得利用信托财产为自己谋取利益。"},{"i":27,"n":"第二十七条","txt":"受托人不得将信托财产转为其固有财产。受托人将信托财产转为其固有财产的，必须恢复该信托财产的原状；造成信托财产损失的，应当承担赔偿责任。"},{"i":28,"n":"第二十八条","txt":"受托人不得将其固有财产与信托财产进行交易或者将不同委托人的信托财产进行相互交易，但信托文件另有规定或者经委托人或者受益人同意，并以公平的市场价格进行交易的除外。"},{"i":29,"n":"第二十九条","txt":"受托人必须将信托财产与其固有财产分别管理、分别记帐，并将不同委托人的信托财产分别管理、分别记帐。"},{"i":30,"n":"第三十条","txt":"受托人应当自己处理信托事务，但信托文件另有规定或者有不得已事由的，可以委托他人代为处理。"},{"i":31,"n":"第三十一条","txt":"同一信托的受托人有两个以上的，为共同受托人。"},{"i":32,"n":"第三十二条","txt":"共同受托人处理信托事务对第三人所负债务，应当承担连带清偿责任。第三人对共同受托人之一所作的意思表示，对其他受托人同样有效。"},{"i":33,"n":"第三十三条","txt":"受托人必须保存处理信托事务的完整记录。"},{"i":34,"n":"第三十四条","txt":"受托人以信托财产为限向受益人承担支付信托利益的义务。"},{"i":35,"n":"第三十五条","txt":"受托人有权依照信托文件的约定取得报酬。信托文件未作事先约定的，经信托当事人协商同意，可以作出补充约定；未作事先约定和补充约定的，不得收取报酬。"},{"i":36,"n":"第三十六条","txt":"受托人违反信托目的处分信托财产或者因违背管理职责、处理信托事务不当致使信托财产受到损失的，在未恢复信托财产的原状或者未予赔偿前，不得请求给付报酬。"},{"i":37,"n":"第三十七条","txt":"受托人因处理信托事务所支出的费用、对第三人所负债务，以信托财产承担。受托人以其固有财产先行支付的，对信托财产享有优先受偿的权利。"},{"i":38,"n":"第三十八条","txt":"设立信托后，经委托人和受益人同意，受托人可以辞任。本法对公益信托的受托人辞任另有规定的，从其规定。"},{"i":39,"n":"第三十九条","txt":"受托人有下列情形之一的，其职责终止："},{"i":40,"n":"第四十条","txt":"受托人职责终止的，依照信托文件规定选任新受托人；信托文件未规定的，由委托人选任；委托人不指定或者无能力指定的，由受益人选任；受益人为无民事行为能力人或者限制民事行为能力人的，依法由其监护人代行选任。"},{"i":41,"n":"第四十一条","txt":"受托人有本法第三十九条第一款第（三）项至第（六）项所列情形之一，职责终止的，应当作出处理信托事务的报告，并向新受托人办理信托财产和信托事务的移交手续。"},{"i":42,"n":"第四十二条","txt":"共同受托人之一职责终止的，信托财产由其他受托人管理和处分。"},{"i":43,"n":"第四十三条","txt":"受益人是在信托中享有信托受益权的人。受益人可以是自然人、法人或者依法成立的其他组织。"},{"i":44,"n":"第四十四条","txt":"受益人自信托生效之日起享有信托受益权。信托文件另有规定的，从其规定。"},{"i":45,"n":"第四十五条","txt":"共同受益人按照信托文件的规定享受信托利益。信托文件对信托利益的分配比例或者分配方法未作规定的，各受益人按照均等的比例享受信托利益。"},{"i":46,"n":"第四十六条","txt":"受益人可以放弃信托受益权。"},{"i":47,"n":"第四十七条","txt":"受益人不能清偿到期债务的，其信托受益权可以用于清偿债务，但法律、行政法规以及信托文件有限制性规定的除外。"},{"i":48,"n":"第四十八条","txt":"受益人的信托受益权可以依法转让和继承，但信托文件有限制性规定的除外。"},{"i":49,"n":"第四十九条","txt":"受益人可以行使本法第二十条至第二十三条规定的委托人享有的权利。受益人行使上述权利，与委托人意见不一致时，可以申请人民法院作出裁定。"},{"i":50,"n":"第五十条","txt":"委托人是唯一受益人的，委托人或者其继承人可以解除信托。信托文件另有规定的，从其规定。"},{"i":51,"n":"第五十一条","txt":"设立信托后，有下列情形之一的，委托人可以变更受益人或者处分受益人的信托受益权："},{"i":52,"n":"第五十二条","txt":"信托不因委托人或者受托人的死亡、丧失民事行为能力、依法解散、被依法撤销或者被宣告破产而终止，也不因受托人的辞任而终止。但本法或者信托文件另有规定的除外。"},{"i":53,"n":"第五十三条","txt":"有下列情形之一的，信托终止："},{"i":54,"n":"第五十四条","txt":"信托终止的，信托财产归属于信托文件规定的人；信托文件未规定的，按下列顺序确定归属："},{"i":55,"n":"第五十五条","txt":"依照前条规定，信托财产的归属确定后，在该信托财产转移给权利归属人的过程中，信托视为存续，权利归属人视为受益人。"},{"i":56,"n":"第五十六条","txt":"信托终止后，人民法院依据本法第十七条的规定对原信托财产进行强制执行的，以权利归属人为被执行人。"},{"i":57,"n":"第五十七条","txt":"信托终止后，受托人依照本法规定行使请求给付报酬、从信托财产中获得补偿的权利时，可以留置信托财产或者对信托财产的权利归属人提出请求。"},{"i":58,"n":"第五十八条","txt":"信托终止的，受托人应当作出处理信托事务的清算报告。受益人或者信托财产的权利归属人对清算报告无异议的，受托人就清算报告所列事项解除责任。但受托人有不正当行为的除外。"},{"i":59,"n":"第五十九条","txt":"公益信托适用本章规定。本章未规定的，适用本法及其他相关法律的规定。"},{"i":60,"n":"第六十条","txt":"为了下列公共利益目的之一而设立的信托，属于公益信托："},{"i":61,"n":"第六十一条","txt":"国家鼓励发展公益信托。"},{"i":62,"n":"第六十二条","txt":"公益信托的设立和确定其受托人，应当经有关公益事业的管理机构（以下简称公益事业管理机构）批准。"},{"i":63,"n":"第六十三条","txt":"公益信托的信托财产及其收益，不得用于非公益目的。"},{"i":64,"n":"第六十四条","txt":"公益信托应当设置信托监察人。"},{"i":65,"n":"第六十五条","txt":"信托监察人有权以自己的名义，为维护受益人的利益，提起诉讼或者实施其他法律行为。"},{"i":66,"n":"第六十六条","txt":"公益信托的受托人未经公益事业管理机构批准，不得辞任。"},{"i":67,"n":"第六十七条","txt":"公益事业管理机构应当检查受托人处理公益信托事务的情况及财产状况。"},{"i":68,"n":"第六十八条","txt":"公益信托的受托人违反信托义务或者无能力履行其职责的，由公益事业管理机构变更受托人。"},{"i":69,"n":"第六十九条","txt":"公益信托成立后，发生设立信托时不能预见的情形，公益事业管理机构可以根据信托目的，变更信托文件中的有关条款。"},{"i":70,"n":"第七十条","txt":"公益信托终止的，受托人应当于终止事由发生之日起十五日内，将终止事由和终止日期报告公益事业管理机构。"},{"i":71,"n":"第七十一条","txt":"公益信托终止的，受托人作出的处理信托事务的清算报告，应当经信托监察人认可后，报公益事业管理机构核准，并由受托人予以公告。"},{"i":72,"n":"第七十二条","txt":"公益信托终止，没有信托财产权利归属人或者信托财产权利归属人是不特定的社会公众的，经公益事业管理机构批准，受托人应当将信托财产用于与原公益目的相近似的目的，或者将信托财产转移给具有近似目的的公益组织或者其他公益信托。"},{"i":73,"n":"第七十三条","txt":"公益事业管理机构违反本法规定的，委托人、受托人或者受益人有权向人民法院起诉。"},{"i":74,"n":"第七十四条","txt":"本法自2001年10月1日起施行。"}],"gongsifa":[{"i":1,"n":"第一条","txt":"为了规范公司的组织和行为，保护公司、股东、职工和债权人的合法权益，完善中国特色现代企业制度，弘扬企业家精神，维护社会经济秩序，促进社会主义市场经济的发展，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称公司，是指依照本法在中华人民共和国境内设立的有限责任公司和股份有限公司。"},{"i":3,"n":"第三条","txt":"公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。"},{"i":4,"n":"第四条","txt":"有限责任公司的股东以其认缴的出资额为限对公司承担责任；股份有限公司的股东以其认购的股份为限对公司承担责任。"},{"i":5,"n":"第五条","txt":"设立公司应当依法制定公司章程。公司章程对公司、股东、董事、监事、高级管理人员具有约束力。"},{"i":6,"n":"第六条","txt":"公司应当有自己的名称。公司名称应当符合国家有关规定。"},{"i":7,"n":"第七条","txt":"依照本法设立的有限责任公司，应当在公司名称中标明有限责任公司或者有限公司字样。"},{"i":8,"n":"第八条","txt":"公司以其主要办事机构所在地为住所。"},{"i":9,"n":"第九条","txt":"公司的经营范围由公司章程规定。公司可以修改公司章程，变更经营范围。"},{"i":10,"n":"第十条","txt":"公司的法定代表人按照公司章程的规定，由代表公司执行公司事务的董事或者经理担任。"},{"i":11,"n":"第十一条","txt":"法定代表人以公司名义从事的民事活动，其法律后果由公司承受。"},{"i":12,"n":"第十二条","txt":"有限责任公司变更为股份有限公司，应当符合本法规定的股份有限公司的条件。股份有限公司变更为有限责任公司，应当符合本法规定的有限责任公司的条件。"},{"i":13,"n":"第十三条","txt":"公司可以设立子公司。子公司具有法人资格，依法独立承担民事责任。"},{"i":14,"n":"第十四条","txt":"公司可以向其他企业投资。"},{"i":15,"n":"第十五条","txt":"公司向其他企业投资或者为他人提供担保，按照公司章程的规定，由董事会或者股东会决议；公司章程对投资或者担保的总额及单项投资或者担保的数额有限额规定的，不得超过规定的限额。"},{"i":16,"n":"第十六条","txt":"公司应当保护职工的合法权益，依法与职工签订劳动合同，参加社会保险，加强劳动保护，实现安全生产。"},{"i":17,"n":"第十七条","txt":"公司职工依照《中华人民共和国工会法》组织工会，开展工会活动，维护职工合法权益。公司应当为本公司工会提供必要的活动条件。公司工会代表职工就职工的劳动报酬、工作时间、休息休假、劳动安全卫生和保险福利等事项依法与公司签订集体合同。"},{"i":18,"n":"第十八条","txt":"在公司中，根据中国共产党章程的规定，设立中国共产党的组织，开展党的活动。公司应当为党组织的活动提供必要条件。"},{"i":19,"n":"第十九条","txt":"公司从事经营活动，应当遵守法律法规，遵守社会公德、商业道德，诚实守信，接受政府和社会公众的监督。"},{"i":20,"n":"第二十条","txt":"公司从事经营活动，应当充分考虑公司职工、消费者等利益相关者的利益以及生态环境保护等社会公共利益，承担社会责任。"},{"i":21,"n":"第二十一条","txt":"公司股东应当遵守法律、行政法规和公司章程，依法行使股东权利，不得滥用股东权利损害公司或者其他股东的利益。"},{"i":22,"n":"第二十二条","txt":"公司的控股股东、实际控制人、董事、监事、高级管理人员不得利用关联关系损害公司利益。"},{"i":23,"n":"第二十三条","txt":"公司股东滥用公司法人独立地位和股东有限责任，逃避债务，严重损害公司债权人利益的，应当对公司债务承担连带责任。"},{"i":24,"n":"第二十四条","txt":"公司股东会、董事会、监事会召开会议和表决可以采用电子通信方式，公司章程另有规定的除外。"},{"i":25,"n":"第二十五条","txt":"公司股东会、董事会的决议内容违反法律、行政法规的无效。"},{"i":26,"n":"第二十六条","txt":"公司股东会、董事会的会议召集程序、表决方式违反法律、行政法规或者公司章程，或者决议内容违反公司章程的，股东自决议作出之日起六十日内，可以请求人民法院撤销。但是，股东会、董事会的会议召集程序或者表决方式仅有轻微瑕疵，对决议未产生实质影响的除外。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，公司股东会、董事会的决议不成立："},{"i":28,"n":"第二十八条","txt":"公司股东会、董事会决议被人民法院宣告无效、撤销或者确认不成立的，公司应当向公司登记机关申请撤销根据该决议已办理的登记。"},{"i":29,"n":"第二十九条","txt":"设立公司，应当依法向公司登记机关申请设立登记。"},{"i":30,"n":"第三十条","txt":"申请设立公司，应当提交设立登记申请书、公司章程等文件，提交的相关材料应当真实、合法和有效。"},{"i":31,"n":"第三十一条","txt":"申请设立公司，符合本法规定的设立条件的，由公司登记机关分别登记为有限责任公司或者股份有限公司；不符合本法规定的设立条件的，不得登记为有限责任公司或者股份有限公司。"},{"i":32,"n":"第三十二条","txt":"公司登记事项包括："},{"i":33,"n":"第三十三条","txt":"依法设立的公司，由公司登记机关发给公司营业执照。公司营业执照签发日期为公司成立日期。"},{"i":34,"n":"第三十四条","txt":"公司登记事项发生变更的，应当依法办理变更登记。"},{"i":35,"n":"第三十五条","txt":"公司申请变更登记，应当向公司登记机关提交公司法定代表人签署的变更登记申请书、依法作出的变更决议或者决定等文件。"},{"i":36,"n":"第三十六条","txt":"公司营业执照记载的事项发生变更的，公司办理变更登记后，由公司登记机关换发营业执照。"},{"i":37,"n":"第三十七条","txt":"公司因解散、被宣告破产或者其他法定事由需要终止的，应当依法向公司登记机关申请注销登记，由公司登记机关公告公司终止。"},{"i":38,"n":"第三十八条","txt":"公司设立分公司，应当向公司登记机关申请登记，领取营业执照。"},{"i":39,"n":"第三十九条","txt":"虚报注册资本、提交虚假材料或者采取其他欺诈手段隐瞒重要事实取得公司设立登记的，公司登记机关应当依照法律、行政法规的规定予以撤销。"},{"i":40,"n":"第四十条","txt":"公司应当按照规定通过国家企业信用信息公示系统公示下列事项："},{"i":41,"n":"第四十一条","txt":"公司登记机关应当优化公司登记办理流程，提高公司登记效率，加强信息化建设，推行网上办理等便捷方式，提升公司登记便利化水平。"},{"i":42,"n":"第四十二条","txt":"有限责任公司由一个以上五十个以下股东出资设立。"},{"i":43,"n":"第四十三条","txt":"有限责任公司设立时的股东可以签订设立协议，明确各自在公司设立过程中的权利和义务。"},{"i":44,"n":"第四十四条","txt":"有限责任公司设立时的股东为设立公司从事的民事活动，其法律后果由公司承受。"},{"i":45,"n":"第四十五条","txt":"设立有限责任公司，应当由股东共同制定公司章程。"},{"i":46,"n":"第四十六条","txt":"有限责任公司章程应当载明下列事项："},{"i":47,"n":"第四十七条","txt":"有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额。全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。"},{"i":48,"n":"第四十八条","txt":"股东可以用货币出资，也可以用实物、知识产权、土地使用权、股权、债权等可以用货币估价并可以依法转让的非货币财产作价出资；但是，法律、行政法规规定不得作为出资的财产除外。"},{"i":49,"n":"第四十九条","txt":"股东应当按期足额缴纳公司章程规定的各自所认缴的出资额。"},{"i":50,"n":"第五十条","txt":"有限责任公司设立时，股东未按照公司章程规定实际缴纳出资，或者实际出资的非货币财产的实际价额显著低于所认缴的出资额的，设立时的其他股东与该股东在出资不足的范围内承担连带责任。"},{"i":51,"n":"第五十一条","txt":"有限责任公司成立后，董事会应当对股东的出资情况进行核查，发现股东未按期足额缴纳公司章程规定的出资的，应当由公司向该股东发出书面催缴书，催缴出资。"},{"i":52,"n":"第五十二条","txt":"股东未按照公司章程规定的出资日期缴纳出资，公司依照前条第一款规定发出书面催缴书催缴出资的，可以载明缴纳出资的宽限期；宽限期自公司发出催缴书之日起，不得少于六十日。宽限期届满，股东仍未履行出资义务的，公司经董事会决议可以向该股东发出失权通知，通知应当以书面形式发出。自通知发出之日起，该股东丧失其未缴纳出资的股权。"},{"i":53,"n":"第五十三条","txt":"公司成立后，股东不得抽逃出资。"},{"i":54,"n":"第五十四条","txt":"公司不能清偿到期债务的，公司或者已到期债权的债权人有权要求已认缴出资但未届出资期限的股东提前缴纳出资。"},{"i":55,"n":"第五十五条","txt":"有限责任公司成立后，应当向股东签发出资证明书，记载下列事项："},{"i":56,"n":"第五十六条","txt":"有限责任公司应当置备股东名册，记载下列事项："},{"i":57,"n":"第五十七条","txt":"股东有权查阅、复制公司章程、股东名册、股东会会议记录、董事会会议决议、监事会会议决议和财务会计报告。"},{"i":58,"n":"第五十八条","txt":"有限责任公司股东会由全体股东组成。股东会是公司的权力机构，依照本法行使职权。"},{"i":59,"n":"第五十九条","txt":"股东会行使下列职权："},{"i":60,"n":"第六十条","txt":"只有一个股东的有限责任公司不设股东会。股东作出前条第一款所列事项的决定时，应当采用书面形式，并由股东签名或者盖章后置备于公司。"},{"i":61,"n":"第六十一条","txt":"首次股东会会议由出资最多的股东召集和主持，依照本法规定行使职权。"},{"i":62,"n":"第六十二条","txt":"股东会会议分为定期会议和临时会议。"},{"i":63,"n":"第六十三条","txt":"股东会会议由董事会召集，董事长主持；董事长不能履行职务或者不履行职务的，由副董事长主持；副董事长不能履行职务或者不履行职务的，由过半数的董事共同推举一名董事主持。"},{"i":64,"n":"第六十四条","txt":"召开股东会会议，应当于会议召开十五日前通知全体股东；但是，公司章程另有规定或者全体股东另有约定的除外。"},{"i":65,"n":"第六十五条","txt":"股东会会议由股东按照出资比例行使表决权；但是，公司章程另有规定的除外。"},{"i":66,"n":"第六十六条","txt":"股东会的议事方式和表决程序，除本法有规定的外，由公司章程规定。"},{"i":67,"n":"第六十七条","txt":"有限责任公司设董事会，本法第七十五条另有规定的除外。"},{"i":68,"n":"第六十八条","txt":"有限责任公司董事会成员为三人以上，其成员中可以有公司职工代表。职工人数三百人以上的有限责任公司，除依法设监事会并有公司职工代表的外，其董事会成员中应当有公司职工代表。董事会中的职工代表由公司职工通过职工代表大会、职工大会或者其他形式民主选举产生。"},{"i":69,"n":"第六十九条","txt":"有限责任公司可以按照公司章程的规定在董事会中设置由董事组成的审计委员会，行使本法规定的监事会的职权，不设监事会或者监事。公司董事会成员中的职工代表可以成为审计委员会成员。"},{"i":70,"n":"第七十条","txt":"董事任期由公司章程规定，但每届任期不得超过三年。董事任期届满，连选可以连任。"},{"i":71,"n":"第七十一条","txt":"股东会可以决议解任董事，决议作出之日解任生效。"},{"i":72,"n":"第七十二条","txt":"董事会会议由董事长召集和主持；董事长不能履行职务或者不履行职务的，由副董事长召集和主持；副董事长不能履行职务或者不履行职务的，由过半数的董事共同推举一名董事召集和主持。"},{"i":73,"n":"第七十三条","txt":"董事会的议事方式和表决程序，除本法有规定的外，由公司章程规定。"},{"i":74,"n":"第七十四条","txt":"有限责任公司可以设经理，由董事会决定聘任或者解聘。"},{"i":75,"n":"第七十五条","txt":"规模较小或者股东人数较少的有限责任公司，可以不设董事会，设一名董事，行使本法规定的董事会的职权。该董事可以兼任公司经理。"},{"i":76,"n":"第七十六条","txt":"有限责任公司设监事会，本法第六十九条、第八十三条另有规定的除外。"},{"i":77,"n":"第七十七条","txt":"监事的任期每届为三年。监事任期届满，连选可以连任。"},{"i":78,"n":"第七十八条","txt":"监事会行使下列职权："},{"i":79,"n":"第七十九条","txt":"监事可以列席董事会会议，并对董事会决议事项提出质询或者建议。"},{"i":80,"n":"第八十条","txt":"监事会可以要求董事、高级管理人员提交执行职务的报告。"},{"i":81,"n":"第八十一条","txt":"监事会每年度至少召开一次会议，监事可以提议召开临时监事会会议。"},{"i":82,"n":"第八十二条","txt":"监事会行使职权所必需的费用，由公司承担。"},{"i":83,"n":"第八十三条","txt":"规模较小或者股东人数较少的有限责任公司，可以不设监事会，设一名监事，行使本法规定的监事会的职权；经全体股东一致同意，也可以不设监事。"},{"i":84,"n":"第八十四条","txt":"有限责任公司的股东之间可以相互转让其全部或者部分股权。"},{"i":85,"n":"第八十五条","txt":"人民法院依照法律规定的强制执行程序转让股东的股权时，应当通知公司及全体股东，其他股东在同等条件下有优先购买权。其他股东自人民法院通知之日起满二十日不行使优先购买权的，视为放弃优先购买权。"},{"i":86,"n":"第八十六条","txt":"股东转让股权的，应当书面通知公司，请求变更股东名册；需要办理变更登记的，并请求公司向公司登记机关办理变更登记。公司拒绝或者在合理期限内不予答复的，转让人、受让人可以依法向人民法院提起诉讼。"},{"i":87,"n":"第八十七条","txt":"依照本法转让股权后，公司应当及时注销原股东的出资证明书，向新股东签发出资证明书，并相应修改公司章程和股东名册中有关股东及其出资额的记载。对公司章程的该项修改不需再由股东会表决。"},{"i":88,"n":"第八十八条","txt":"股东转让已认缴出资但未届出资期限的股权的，由受让人承担缴纳该出资的义务；受让人未按期足额缴纳出资的，转让人对受让人未按期缴纳的出资承担补充责任。"},{"i":89,"n":"第八十九条","txt":"有下列情形之一的，对股东会该项决议投反对票的股东可以请求公司按照合理的价格收购其股权："},{"i":90,"n":"第九十条","txt":"自然人股东死亡后，其合法继承人可以继承股东资格；但是，公司章程另有规定的除外。"},{"i":91,"n":"第九十一条","txt":"设立股份有限公司，可以采取发起设立或者募集设立的方式。"},{"i":92,"n":"第九十二条","txt":"设立股份有限公司，应当有一人以上二百人以下为发起人，其中应当有半数以上的发起人在中华人民共和国境内有住所。"},{"i":93,"n":"第九十三条","txt":"股份有限公司发起人承担公司筹办事务。"},{"i":94,"n":"第九十四条","txt":"设立股份有限公司，应当由发起人共同制订公司章程。"},{"i":95,"n":"第九十五条","txt":"股份有限公司章程应当载明下列事项："},{"i":96,"n":"第九十六条","txt":"股份有限公司的注册资本为在公司登记机关登记的已发行股份的股本总额。在发起人认购的股份缴足前，不得向他人募集股份。"},{"i":97,"n":"第九十七条","txt":"以发起设立方式设立股份有限公司的，发起人应当认足公司章程规定的公司设立时应发行的股份。"},{"i":98,"n":"第九十八条","txt":"发起人应当在公司成立前按照其认购的股份全额缴纳股款。"},{"i":99,"n":"第九十九条","txt":"发起人不按照其认购的股份缴纳股款，或者作为出资的非货币财产的实际价额显著低于所认购的股份的，其他发起人与该发起人在出资不足的范围内承担连带责任。"},{"i":100,"n":"第一百条","txt":"发起人向社会公开募集股份，应当公告招股说明书，并制作认股书。认股书应当载明本法第一百五十四条第二款、第三款所列事项，由认股人填写认购的股份数、金额、住所，并签名或者盖章。认股人应当按照所认购股份足额缴纳股款。"},{"i":101,"n":"第一百零一条","txt":"向社会公开募集股份的股款缴足后，应当经依法设立的验资机构验资并出具证明。"},{"i":102,"n":"第一百零二条","txt":"股份有限公司应当制作股东名册并置备于公司。股东名册应当记载下列事项："},{"i":103,"n":"第一百零三条","txt":"募集设立股份有限公司的发起人应当自公司设立时应发行股份的股款缴足之日起三十日内召开公司成立大会。发起人应当在成立大会召开十五日前将会议日期通知各认股人或者予以公告。成立大会应当有持有表决权过半数的认股人出席，方可举行。"},{"i":104,"n":"第一百零四条","txt":"公司成立大会行使下列职权："},{"i":105,"n":"第一百零五条","txt":"公司设立时应发行的股份未募足，或者发行股份的股款缴足后，发起人在三十日内未召开成立大会的，认股人可以按照所缴股款并加算银行同期存款利息，要求发起人返还。"},{"i":106,"n":"第一百零六条","txt":"董事会应当授权代表，于公司成立大会结束后三十日内向公司登记机关申请设立登记。"},{"i":107,"n":"第一百零七条","txt":"本法第四十四条、第四十九条第三款、第五十一条、第五十二条、第五十三条的规定，适用于股份有限公司。"},{"i":108,"n":"第一百零八条","txt":"有限责任公司变更为股份有限公司时，折合的实收股本总额不得高于公司净资产额。有限责任公司变更为股份有限公司，为增加注册资本公开发行股份时，应当依法办理。"},{"i":109,"n":"第一百零九条","txt":"股份有限公司应当将公司章程、股东名册、股东会会议记录、董事会会议记录、监事会会议记录、财务会计报告、债券持有人名册置备于本公司。"},{"i":110,"n":"第一百一十条","txt":"股东有权查阅、复制公司章程、股东名册、股东会会议记录、董事会会议决议、监事会会议决议、财务会计报告，对公司的经营提出建议或者质询。"},{"i":111,"n":"第一百一十一条","txt":"股份有限公司股东会由全体股东组成。股东会是公司的权力机构，依照本法行使职权。"},{"i":112,"n":"第一百一十二条","txt":"本法第五十九条第一款、第二款关于有限责任公司股东会职权的规定，适用于股份有限公司股东会。"},{"i":113,"n":"第一百一十三条","txt":"股东会应当每年召开一次年会。有下列情形之一的，应当在两个月内召开临时股东会会议："},{"i":114,"n":"第一百一十四条","txt":"股东会会议由董事会召集，董事长主持；董事长不能履行职务或者不履行职务的，由副董事长主持；副董事长不能履行职务或者不履行职务的，由过半数的董事共同推举一名董事主持。"},{"i":115,"n":"第一百一十五条","txt":"召开股东会会议，应当将会议召开的时间、地点和审议的事项于会议召开二十日前通知各股东；临时股东会会议应当于会议召开十五日前通知各股东。"},{"i":116,"n":"第一百一十六条","txt":"股东出席股东会会议，所持每一股份有一表决权，类别股股东除外。公司持有的本公司股份没有表决权。"},{"i":117,"n":"第一百一十七条","txt":"股东会选举董事、监事，可以按照公司章程的规定或者股东会的决议，实行累积投票制。"},{"i":118,"n":"第一百一十八条","txt":"股东委托代理人出席股东会会议的，应当明确代理人代理的事项、权限和期限；代理人应当向公司提交股东授权委托书，并在授权范围内行使表决权。"},{"i":119,"n":"第一百一十九条","txt":"股东会应当对所议事项的决定作成会议记录，主持人、出席会议的董事应当在会议记录上签名。会议记录应当与出席股东的签名册及代理出席的委托书一并保存。"},{"i":120,"n":"第一百二十条","txt":"股份有限公司设董事会，本法第一百二十八条另有规定的除外。"},{"i":121,"n":"第一百二十一条","txt":"股份有限公司可以按照公司章程的规定在董事会中设置由董事组成的审计委员会，行使本法规定的监事会的职权，不设监事会或者监事。"},{"i":122,"n":"第一百二十二条","txt":"董事会设董事长一人，可以设副董事长。董事长和副董事长由董事会以全体董事的过半数选举产生。"},{"i":123,"n":"第一百二十三条","txt":"董事会每年度至少召开两次会议，每次会议应当于会议召开十日前通知全体董事和监事。"},{"i":124,"n":"第一百二十四条","txt":"董事会会议应当有过半数的董事出席方可举行。董事会作出决议，应当经全体董事的过半数通过。"},{"i":125,"n":"第一百二十五条","txt":"董事会会议，应当由董事本人出席；董事因故不能出席，可以书面委托其他董事代为出席，委托书应当载明授权范围。"},{"i":126,"n":"第一百二十六条","txt":"股份有限公司设经理，由董事会决定聘任或者解聘。"},{"i":127,"n":"第一百二十七条","txt":"公司董事会可以决定由董事会成员兼任经理。"},{"i":128,"n":"第一百二十八条","txt":"规模较小或者股东人数较少的股份有限公司，可以不设董事会，设一名董事，行使本法规定的董事会的职权。该董事可以兼任公司经理。"},{"i":129,"n":"第一百二十九条","txt":"公司应当定期向股东披露董事、监事、高级管理人员从公司获得报酬的情况。"},{"i":130,"n":"第一百三十条","txt":"股份有限公司设监事会，本法第一百二十一条第一款、第一百三十三条另有规定的除外。"},{"i":131,"n":"第一百三十一条","txt":"本法第七十八条至第八十条的规定，适用于股份有限公司监事会。"},{"i":132,"n":"第一百三十二条","txt":"监事会每六个月至少召开一次会议。监事可以提议召开临时监事会会议。"},{"i":133,"n":"第一百三十三条","txt":"规模较小或者股东人数较少的股份有限公司，可以不设监事会，设一名监事，行使本法规定的监事会的职权。"},{"i":134,"n":"第一百三十四条","txt":"本法所称上市公司，是指其股票在证券交易所上市交易的股份有限公司。"},{"i":135,"n":"第一百三十五条","txt":"上市公司在一年内购买、出售重大资产或者向他人提供担保的金额超过公司资产总额百分之三十的，应当由股东会作出决议，并经出席会议的股东所持表决权的三分之二以上通过。"},{"i":136,"n":"第一百三十六条","txt":"上市公司设独立董事，具体管理办法由国务院证券监督管理机构规定。"},{"i":137,"n":"第一百三十七条","txt":"上市公司在董事会中设置审计委员会的，董事会对下列事项作出决议前应当经审计委员会全体成员过半数通过："},{"i":138,"n":"第一百三十八条","txt":"上市公司设董事会秘书，负责公司股东会和董事会会议的筹备、文件保管以及公司股东资料的管理，办理信息披露事务等事宜。"},{"i":139,"n":"第一百三十九条","txt":"上市公司董事与董事会会议决议事项所涉及的企业或者个人有关联关系的，该董事应当及时向董事会书面报告。有关联关系的董事不得对该项决议行使表决权，也不得代理其他董事行使表决权。该董事会会议由过半数的无关联关系董事出席即可举行，董事会会议所作决议须经无关联关系董事过半数通过。出席董事会会议的无关联关系董事人数不足三人的，应当将该事项提交上市公司股东会审议。"},{"i":140,"n":"第一百四十条","txt":"上市公司应当依法披露股东、实际控制人的信息，相关信息应当真实、准确、完整。"},{"i":141,"n":"第一百四十一条","txt":"上市公司控股子公司不得取得该上市公司的股份。"},{"i":142,"n":"第一百四十二条","txt":"公司的资本划分为股份。公司的全部股份，根据公司章程的规定择一采用面额股或者无面额股。采用面额股的，每一股的金额相等。"},{"i":143,"n":"第一百四十三条","txt":"股份的发行，实行公平、公正的原则，同类别的每一股份应当具有同等权利。"},{"i":144,"n":"第一百四十四条","txt":"公司可以按照公司章程的规定发行下列与普通股权利不同的类别股："},{"i":145,"n":"第一百四十五条","txt":"发行类别股的公司，应当在公司章程中载明以下事项："},{"i":146,"n":"第一百四十六条","txt":"发行类别股的公司，有本法第一百一十六条第三款规定的事项等可能影响类别股股东权利的，除应当依照第一百一十六条第三款的规定经股东会决议外，还应当经出席类别股股东会议的股东所持表决权的三分之二以上通过。"},{"i":147,"n":"第一百四十七条","txt":"公司的股份采取股票的形式。股票是公司签发的证明股东所持股份的凭证。"},{"i":148,"n":"第一百四十八条","txt":"面额股股票的发行价格可以按票面金额，也可以超过票面金额，但不得低于票面金额。"},{"i":149,"n":"第一百四十九条","txt":"股票采用纸面形式或者国务院证券监督管理机构规定的其他形式。"},{"i":150,"n":"第一百五十条","txt":"股份有限公司成立后，即向股东正式交付股票。公司成立前不得向股东交付股票。"},{"i":151,"n":"第一百五十一条","txt":"公司发行新股，股东会应当对下列事项作出决议："},{"i":152,"n":"第一百五十二条","txt":"公司章程或者股东会可以授权董事会在三年内决定发行不超过已发行股份百分之五十的股份。但以非货币财产作价出资的应当经股东会决议。"},{"i":153,"n":"第一百五十三条","txt":"公司章程或者股东会授权董事会决定发行新股的，董事会决议应当经全体董事三分之二以上通过。"},{"i":154,"n":"第一百五十四条","txt":"公司向社会公开募集股份，应当经国务院证券监督管理机构注册，公告招股说明书。"},{"i":155,"n":"第一百五十五条","txt":"公司向社会公开募集股份，应当由依法设立的证券公司承销，签订承销协议。"},{"i":156,"n":"第一百五十六条","txt":"公司向社会公开募集股份，应当同银行签订代收股款协议。"},{"i":157,"n":"第一百五十七条","txt":"股份有限公司的股东持有的股份可以向其他股东转让，也可以向股东以外的人转让；公司章程对股份转让有限制的，其转让按照公司章程的规定进行。"},{"i":158,"n":"第一百五十八条","txt":"股东转让其股份，应当在依法设立的证券交易场所进行或者按照国务院规定的其他方式进行。"},{"i":159,"n":"第一百五十九条","txt":"股票的转让，由股东以背书方式或者法律、行政法规规定的其他方式进行；转让后由公司将受让人的姓名或者名称及住所记载于股东名册。"},{"i":160,"n":"第一百六十条","txt":"公司公开发行股份前已发行的股份，自公司股票在证券交易所上市交易之日起一年内不得转让。法律、行政法规或者国务院证券监督管理机构对上市公司的股东、实际控制人转让其所持有的本公司股份另有规定的，从其规定。"},{"i":161,"n":"第一百六十一条","txt":"有下列情形之一的，对股东会该项决议投反对票的股东可以请求公司按照合理的价格收购其股份，公开发行股份的公司除外："},{"i":162,"n":"第一百六十二条","txt":"公司不得收购本公司股份。但是，有下列情形之一的除外："},{"i":163,"n":"第一百六十三条","txt":"公司不得为他人取得本公司或者其母公司的股份提供赠与、借款、担保以及其他财务资助，公司实施员工持股计划的除外。"},{"i":164,"n":"第一百六十四条","txt":"股票被盗、遗失或者灭失，股东可以依照《中华人民共和国民事诉讼法》规定的公示催告程序，请求人民法院宣告该股票失效。人民法院宣告该股票失效后，股东可以向公司申请补发股票。"},{"i":165,"n":"第一百六十五条","txt":"上市公司的股票，依照有关法律、行政法规及证券交易所交易规则上市交易。"},{"i":166,"n":"第一百六十六条","txt":"上市公司应当依照法律、行政法规的规定披露相关信息。"},{"i":167,"n":"第一百六十七条","txt":"自然人股东死亡后，其合法继承人可以继承股东资格；但是，股份转让受限的股份有限公司的章程另有规定的除外。"},{"i":168,"n":"第一百六十八条","txt":"国家出资公司的组织机构，适用本章规定；本章没有规定的，适用本法其他规定。"},{"i":169,"n":"第一百六十九条","txt":"国家出资公司，由国务院或者地方人民政府分别代表国家依法履行出资人职责，享有出资人权益。国务院或者地方人民政府可以授权国有资产监督管理机构或者其他部门、机构代表本级人民政府对国家出资公司履行出资人职责。"},{"i":170,"n":"第一百七十条","txt":"国家出资公司中中国共产党的组织，按照中国共产党章程的规定发挥领导作用，研究讨论公司重大经营管理事项，支持公司的组织机构依法行使职权。"},{"i":171,"n":"第一百七十一条","txt":"国有独资公司章程由履行出资人职责的机构制定。"},{"i":172,"n":"第一百七十二条","txt":"国有独资公司不设股东会，由履行出资人职责的机构行使股东会职权。履行出资人职责的机构可以授权公司董事会行使股东会的部分职权，但公司章程的制定和修改，公司的合并、分立、解散、申请破产，增加或者减少注册资本，分配利润，应当由履行出资人职责的机构决定。"},{"i":173,"n":"第一百七十三条","txt":"国有独资公司的董事会依照本法规定行使职权。"},{"i":174,"n":"第一百七十四条","txt":"国有独资公司的经理由董事会聘任或者解聘。"},{"i":175,"n":"第一百七十五条","txt":"国有独资公司的董事、高级管理人员，未经履行出资人职责的机构同意，不得在其他有限责任公司、股份有限公司或者其他经济组织兼职。"},{"i":176,"n":"第一百七十六条","txt":"国有独资公司在董事会中设置由董事组成的审计委员会行使本法规定的监事会职权的，不设监事会或者监事。"},{"i":177,"n":"第一百七十七条","txt":"国家出资公司应当依法建立健全内部监督管理和风险控制制度，加强内部合规管理。"},{"i":178,"n":"第一百七十八条","txt":"有下列情形之一的，不得担任公司的董事、监事、高级管理人员："},{"i":179,"n":"第一百七十九条","txt":"董事、监事、高级管理人员应当遵守法律、行政法规和公司章程。"},{"i":180,"n":"第一百八十条","txt":"董事、监事、高级管理人员对公司负有忠实义务，应当采取措施避免自身利益与公司利益冲突，不得利用职权牟取不正当利益。"},{"i":181,"n":"第一百八十一条","txt":"董事、监事、高级管理人员不得有下列行为："},{"i":182,"n":"第一百八十二条","txt":"董事、监事、高级管理人员，直接或者间接与本公司订立合同或者进行交易，应当就与订立合同或者进行交易有关的事项向董事会或者股东会报告，并按照公司章程的规定经董事会或者股东会决议通过。"},{"i":183,"n":"第一百八十三条","txt":"董事、监事、高级管理人员，不得利用职务便利为自己或者他人谋取属于公司的商业机会。但是，有下列情形之一的除外："},{"i":184,"n":"第一百八十四条","txt":"董事、监事、高级管理人员未向董事会或者股东会报告，并按照公司章程的规定经董事会或者股东会决议通过，不得自营或者为他人经营与其任职公司同类的业务。"},{"i":185,"n":"第一百八十五条","txt":"董事会对本法第一百八十二条至第一百八十四条规定的事项决议时，关联董事不得参与表决，其表决权不计入表决权总数。出席董事会会议的无关联关系董事人数不足三人的，应当将该事项提交股东会审议。"},{"i":186,"n":"第一百八十六条","txt":"董事、监事、高级管理人员违反本法第一百八十一条至第一百八十四条规定所得的收入应当归公司所有。"},{"i":187,"n":"第一百八十七条","txt":"股东会要求董事、监事、高级管理人员列席会议的，董事、监事、高级管理人员应当列席并接受股东的质询。"},{"i":188,"n":"第一百八十八条","txt":"董事、监事、高级管理人员执行职务违反法律、行政法规或者公司章程的规定，给公司造成损失的，应当承担赔偿责任。"},{"i":189,"n":"第一百八十九条","txt":"董事、高级管理人员有前条规定的情形的，有限责任公司的股东、股份有限公司连续一百八十日以上单独或者合计持有公司百分之一以上股份的股东，可以书面请求监事会向人民法院提起诉讼；监事有前条规定的情形的，前述股东可以书面请求董事会向人民法院提起诉讼。"},{"i":190,"n":"第一百九十条","txt":"董事、高级管理人员违反法律、行政法规或者公司章程的规定，损害股东利益的，股东可以向人民法院提起诉讼。"},{"i":191,"n":"第一百九十一条","txt":"董事、高级管理人员执行职务，给他人造成损害的，公司应当承担赔偿责任；董事、高级管理人员存在故意或者重大过失的，也应当承担赔偿责任。"},{"i":192,"n":"第一百九十二条","txt":"公司的控股股东、实际控制人指示董事、高级管理人员从事损害公司或者股东利益的行为的，与该董事、高级管理人员承担连带责任。"},{"i":193,"n":"第一百九十三条","txt":"公司可以在董事任职期间为董事因执行公司职务承担的赔偿责任投保责任保险。"},{"i":194,"n":"第一百九十四条","txt":"本法所称公司债券，是指公司发行的约定按期还本付息的有价证券。"},{"i":195,"n":"第一百九十五条","txt":"公开发行公司债券，应当经国务院证券监督管理机构注册，公告公司债券募集办法。"},{"i":196,"n":"第一百九十六条","txt":"公司以纸面形式发行公司债券的，应当在债券上载明公司名称、债券票面金额、利率、偿还期限等事项，并由法定代表人签名，公司盖章。"},{"i":197,"n":"第一百九十七条","txt":"公司债券应当为记名债券。"},{"i":198,"n":"第一百九十八条","txt":"公司发行公司债券应当置备公司债券持有人名册。"},{"i":199,"n":"第一百九十九条","txt":"公司债券的登记结算机构应当建立债券登记、存管、付息、兑付等相关制度。"},{"i":200,"n":"第二百条","txt":"公司债券可以转让，转让价格由转让人与受让人约定。"},{"i":201,"n":"第二百零一条","txt":"公司债券由债券持有人以背书方式或者法律、行政法规规定的其他方式转让；转让后由公司将受让人的姓名或者名称及住所记载于公司债券持有人名册。"},{"i":202,"n":"第二百零二条","txt":"股份有限公司经股东会决议，或者经公司章程、股东会授权由董事会决议，可以发行可转换为股票的公司债券，并规定具体的转换办法。上市公司发行可转换为股票的公司债券，应当经国务院证券监督管理机构注册。"},{"i":203,"n":"第二百零三条","txt":"发行可转换为股票的公司债券的，公司应当按照其转换办法向债券持有人换发股票，但债券持有人对转换股票或者不转换股票有选择权。法律、行政法规另有规定的除外。"},{"i":204,"n":"第二百零四条","txt":"公开发行公司债券的，应当为同期债券持有人设立债券持有人会议，并在债券募集办法中对债券持有人会议的召集程序、会议规则和其他重要事项作出规定。债券持有人会议可以对与债券持有人有利害关系的事项作出决议。"},{"i":205,"n":"第二百零五条","txt":"公开发行公司债券的，发行人应当为债券持有人聘请债券受托管理人，由其为债券持有人办理受领清偿、债权保全、与债券相关的诉讼以及参与债务人破产程序等事项。"},{"i":206,"n":"第二百零六条","txt":"债券受托管理人应当勤勉尽责，公正履行受托管理职责，不得损害债券持有人利益。"},{"i":207,"n":"第二百零七条","txt":"公司应当依照法律、行政法规和国务院财政部门的规定建立本公司的财务、会计制度。"},{"i":208,"n":"第二百零八条","txt":"公司应当在每一会计年度终了时编制财务会计报告，并依法经会计师事务所审计。"},{"i":209,"n":"第二百零九条","txt":"有限责任公司应当按照公司章程规定的期限将财务会计报告送交各股东。"},{"i":210,"n":"第二百一十条","txt":"公司分配当年税后利润时，应当提取利润的百分之十列入公司法定公积金。公司法定公积金累计额为公司注册资本的百分之五十以上的，可以不再提取。"},{"i":211,"n":"第二百一十一条","txt":"公司违反本法规定向股东分配利润的，股东应当将违反规定分配的利润退还公司；给公司造成损失的，股东及负有责任的董事、监事、高级管理人员应当承担赔偿责任。"},{"i":212,"n":"第二百一十二条","txt":"股东会作出分配利润的决议的，董事会应当在股东会决议作出之日起六个月内进行分配。"},{"i":213,"n":"第二百一十三条","txt":"公司以超过股票票面金额的发行价格发行股份所得的溢价款、发行无面额股所得股款未计入注册资本的金额以及国务院财政部门规定列入资本公积金的其他项目，应当列为公司资本公积金。"},{"i":214,"n":"第二百一十四条","txt":"公司的公积金用于弥补公司的亏损、扩大公司生产经营或者转为增加公司注册资本。"},{"i":215,"n":"第二百一十五条","txt":"公司聘用、解聘承办公司审计业务的会计师事务所，按照公司章程的规定，由股东会、董事会或者监事会决定。"},{"i":216,"n":"第二百一十六条","txt":"公司应当向聘用的会计师事务所提供真实、完整的会计凭证、会计账簿、财务会计报告及其他会计资料，不得拒绝、隐匿、谎报。"},{"i":217,"n":"第二百一十七条","txt":"公司除法定的会计账簿外，不得另立会计账簿。"},{"i":218,"n":"第二百一十八条","txt":"公司合并可以采取吸收合并或者新设合并。"},{"i":219,"n":"第二百一十九条","txt":"公司与其持股百分之九十以上的公司合并，被合并的公司不需经股东会决议，但应当通知其他股东，其他股东有权请求公司按照合理的价格收购其股权或者股份。"},{"i":220,"n":"第二百二十条","txt":"公司合并，应当由合并各方签订合并协议，并编制资产负债表及财产清单。公司应当自作出合并决议之日起十日内通知债权人，并于三十日内在报纸上或者国家企业信用信息公示系统公告。债权人自接到通知之日起三十日内，未接到通知的自公告之日起四十五日内，可以要求公司清偿债务或者提供相应的担保。"},{"i":221,"n":"第二百二十一条","txt":"公司合并时，合并各方的债权、债务，应当由合并后存续的公司或者新设的公司承继。"},{"i":222,"n":"第二百二十二条","txt":"公司分立，其财产作相应的分割。"},{"i":223,"n":"第二百二十三条","txt":"公司分立前的债务由分立后的公司承担连带责任。但是，公司在分立前与债权人就债务清偿达成的书面协议另有约定的除外。"},{"i":224,"n":"第二百二十四条","txt":"公司减少注册资本，应当编制资产负债表及财产清单。"},{"i":225,"n":"第二百二十五条","txt":"公司依照本法第二百一十四条第二款的规定弥补亏损后，仍有亏损的，可以减少注册资本弥补亏损。减少注册资本弥补亏损的，公司不得向股东分配，也不得免除股东缴纳出资或者股款的义务。"},{"i":226,"n":"第二百二十六条","txt":"违反本法规定减少注册资本的，股东应当退还其收到的资金，减免股东出资的应当恢复原状；给公司造成损失的，股东及负有责任的董事、监事、高级管理人员应当承担赔偿责任。"},{"i":227,"n":"第二百二十七条","txt":"有限责任公司增加注册资本时，股东在同等条件下有权优先按照实缴的出资比例认缴出资。但是，全体股东约定不按照出资比例优先认缴出资的除外。"},{"i":228,"n":"第二百二十八条","txt":"有限责任公司增加注册资本时，股东认缴新增资本的出资，依照本法设立有限责任公司缴纳出资的有关规定执行。"},{"i":229,"n":"第二百二十九条","txt":"公司因下列原因解散："},{"i":230,"n":"第二百三十条","txt":"公司有前条第一款第一项、第二项情形，且尚未向股东分配财产的，可以通过修改公司章程或者经股东会决议而存续。"},{"i":231,"n":"第二百三十一条","txt":"公司经营管理发生严重困难，继续存续会使股东利益受到重大损失，通过其他途径不能解决的，持有公司百分之十以上表决权的股东，可以请求人民法院解散公司。"},{"i":232,"n":"第二百三十二条","txt":"公司因本法第二百二十九条第一款第一项、第二项、第四项、第五项规定而解散的，应当清算。董事为公司清算义务人，应当在解散事由出现之日起十五日内组成清算组进行清算。"},{"i":233,"n":"第二百三十三条","txt":"公司依照前条第一款的规定应当清算，逾期不成立清算组进行清算或者成立清算组后不清算的，利害关系人可以申请人民法院指定有关人员组成清算组进行清算。人民法院应当受理该申请，并及时组织清算组进行清算。"},{"i":234,"n":"第二百三十四条","txt":"清算组在清算期间行使下列职权："},{"i":235,"n":"第二百三十五条","txt":"清算组应当自成立之日起十日内通知债权人，并于六十日内在报纸上或者国家企业信用信息公示系统公告。债权人应当自接到通知之日起三十日内，未接到通知的自公告之日起四十五日内，向清算组申报其债权。"},{"i":236,"n":"第二百三十六条","txt":"清算组在清理公司财产、编制资产负债表和财产清单后，应当制订清算方案，并报股东会或者人民法院确认。"},{"i":237,"n":"第二百三十七条","txt":"清算组在清理公司财产、编制资产负债表和财产清单后，发现公司财产不足清偿债务的，应当依法向人民法院申请破产清算。"},{"i":238,"n":"第二百三十八条","txt":"清算组成员履行清算职责，负有忠实义务和勤勉义务。"},{"i":239,"n":"第二百三十九条","txt":"公司清算结束后，清算组应当制作清算报告，报股东会或者人民法院确认，并报送公司登记机关，申请注销公司登记。"},{"i":240,"n":"第二百四十条","txt":"公司在存续期间未产生债务，或者已清偿全部债务的，经全体股东承诺，可以按照规定通过简易程序注销公司登记。"},{"i":241,"n":"第二百四十一条","txt":"公司被吊销营业执照、责令关闭或者被撤销，满三年未向公司登记机关申请注销公司登记的，公司登记机关可以通过国家企业信用信息公示系统予以公告，公告期限不少于六十日。公告期限届满后，未有异议的，公司登记机关可以注销公司登记。"},{"i":242,"n":"第二百四十二条","txt":"公司被依法宣告破产的，依照有关企业破产的法律实施破产清算。"},{"i":243,"n":"第二百四十三条","txt":"本法所称外国公司，是指依照外国法律在中华人民共和国境外设立的公司。"},{"i":244,"n":"第二百四十四条","txt":"外国公司在中华人民共和国境内设立分支机构，应当向中国主管机关提出申请，并提交其公司章程、所属国的公司登记证书等有关文件，经批准后，向公司登记机关依法办理登记，领取营业执照。"},{"i":245,"n":"第二百四十五条","txt":"外国公司在中华人民共和国境内设立分支机构，应当在中华人民共和国境内指定负责该分支机构的代表人或者代理人，并向该分支机构拨付与其所从事的经营活动相适应的资金。"},{"i":246,"n":"第二百四十六条","txt":"外国公司的分支机构应当在其名称中标明该外国公司的国籍及责任形式。"},{"i":247,"n":"第二百四十七条","txt":"外国公司在中华人民共和国境内设立的分支机构不具有中国法人资格。"},{"i":248,"n":"第二百四十八条","txt":"经批准设立的外国公司分支机构，在中华人民共和国境内从事业务活动，应当遵守中国的法律，不得损害中国的社会公共利益，其合法权益受中国法律保护。"},{"i":249,"n":"第二百四十九条","txt":"外国公司撤销其在中华人民共和国境内的分支机构时，应当依法清偿债务，依照本法有关公司清算程序的规定进行清算。未清偿债务之前，不得将其分支机构的财产转移至中华人民共和国境外。"},{"i":250,"n":"第二百五十条","txt":"违反本法规定，虚报注册资本、提交虚假材料或者采取其他欺诈手段隐瞒重要事实取得公司登记的，由公司登记机关责令改正，对虚报注册资本的公司，处以虚报注册资本金额百分之五以上百分之十五以下的罚款；对提交虚假材料或者采取其他欺诈手段隐瞒重要事实的公司，处以五万元以上二百万元以下的罚款；情节严重的，吊销营业执照；对直接负责的主管人员和其他直接责任人员处以三万元以上三十万元以下的罚款。"},{"i":251,"n":"第二百五十一条","txt":"公司未依照本法第四十条规定公示有关信息或者不如实公示有关信息的，由公司登记机关责令改正，可以处以一万元以上五万元以下的罚款。情节严重的，处以五万元以上二十万元以下的罚款；对直接负责的主管人员和其他直接责任人员处以一万元以上十万元以下的罚款。"},{"i":252,"n":"第二百五十二条","txt":"公司的发起人、股东虚假出资，未交付或者未按期交付作为出资的货币或者非货币财产的，由公司登记机关责令改正，可以处以五万元以上二十万元以下的罚款；情节严重的，处以虚假出资或者未出资金额百分之五以上百分之十五以下的罚款；对直接负责的主管人员和其他直接责任人员处以一万元以上十万元以下的罚款。"},{"i":253,"n":"第二百五十三条","txt":"公司的发起人、股东在公司成立后，抽逃其出资的，由公司登记机关责令改正，处以所抽逃出资金额百分之五以上百分之十五以下的罚款；对直接负责的主管人员和其他直接责任人员处以三万元以上三十万元以下的罚款。"},{"i":254,"n":"第二百五十四条","txt":"有下列行为之一的，由县级以上人民政府财政部门依照《中华人民共和国会计法》等法律、行政法规的规定处罚："},{"i":255,"n":"第二百五十五条","txt":"公司在合并、分立、减少注册资本或者进行清算时，不依照本法规定通知或者公告债权人的，由公司登记机关责令改正，对公司处以一万元以上十万元以下的罚款。"},{"i":256,"n":"第二百五十六条","txt":"公司在进行清算时，隐匿财产，对资产负债表或者财产清单作虚假记载，或者在未清偿债务前分配公司财产的，由公司登记机关责令改正，对公司处以隐匿财产或者未清偿债务前分配公司财产金额百分之五以上百分之十以下的罚款；对直接负责的主管人员和其他直接责任人员处以一万元以上十万元以下的罚款。"},{"i":257,"n":"第二百五十七条","txt":"承担资产评估、验资或者验证的机构提供虚假材料或者提供有重大遗漏的报告的，由有关部门依照《中华人民共和国资产评估法》、《中华人民共和国注册会计师法》等法律、行政法规的规定处罚。"},{"i":258,"n":"第二百五十八条","txt":"公司登记机关违反法律、行政法规规定未履行职责或者履行职责不当的，对负有责任的领导人员和直接责任人员依法给予政务处分。"},{"i":259,"n":"第二百五十九条","txt":"未依法登记为有限责任公司或者股份有限公司，而冒用有限责任公司或者股份有限公司名义的，或者未依法登记为有限责任公司或者股份有限公司的分公司，而冒用有限责任公司或者股份有限公司的分公司名义的，由公司登记机关责令改正或者予以取缔，可以并处十万元以下的罚款。"},{"i":260,"n":"第二百六十条","txt":"公司成立后无正当理由超过六个月未开业的，或者开业后自行停业连续六个月以上的，公司登记机关可以吊销营业执照，但公司依法办理歇业的除外。"},{"i":261,"n":"第二百六十一条","txt":"外国公司违反本法规定，擅自在中华人民共和国境内设立分支机构的，由公司登记机关责令改正或者关闭，可以并处五万元以上二十万元以下的罚款。"},{"i":262,"n":"第二百六十二条","txt":"利用公司名义从事危害国家安全、社会公共利益的严重违法行为的，吊销营业执照。"},{"i":263,"n":"第二百六十三条","txt":"公司违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金的，其财产不足以支付时，先承担民事赔偿责任。"},{"i":264,"n":"第二百六十四条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":265,"n":"第二百六十五条","txt":"本法下列用语的含义："},{"i":266,"n":"第二百六十六条","txt":"本法自2024年7月1日起施行。"}],"nongcuntudichengbaofa":[{"i":1,"n":"第一条","txt":"为了巩固和完善以家庭承包经营为基础、统分结合的双层经营体制，保持农村土地承包关系稳定并长久不变，维护农村土地承包经营当事人的合法权益，促进农业、农村经济发展和农村社会和谐稳定，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称农村土地，是指农民集体所有和国家所有依法由农民集体使用的耕地、林地、草地，以及其他依法用于农业的土地。"},{"i":3,"n":"第三条","txt":"国家实行农村土地承包经营制度。"},{"i":4,"n":"第四条","txt":"农村土地承包后，土地的所有权性质不变。承包地不得买卖。"},{"i":5,"n":"第五条","txt":"农村集体经济组织成员有权依法承包由本集体经济组织发包的农村土地。"},{"i":6,"n":"第六条","txt":"农村土地承包，妇女与男子享有平等的权利。承包中应当保护妇女的合法权益，任何组织和个人不得剥夺、侵害妇女应当享有的土地承包经营权。"},{"i":7,"n":"第七条","txt":"农村土地承包应当坚持公开、公平、公正的原则，正确处理国家、集体、个人三者的利益关系。"},{"i":8,"n":"第八条","txt":"国家保护集体土地所有者的合法权益，保护承包方的土地承包经营权，任何组织和个人不得侵犯。"},{"i":9,"n":"第九条","txt":"承包方承包土地后，享有土地承包经营权，可以自己经营，也可以保留土地承包权，流转其承包地的土地经营权，由他人经营。"},{"i":10,"n":"第十条","txt":"国家保护承包方依法、自愿、有偿流转土地经营权，保护土地经营权人的合法权益，任何组织和个人不得侵犯。"},{"i":11,"n":"第十一条","txt":"农村土地承包经营应当遵守法律、法规，保护土地资源的合理开发和可持续利用。未经依法批准不得将承包地用于非农建设。"},{"i":12,"n":"第十二条","txt":"国务院农业农村、林业和草原主管部门分别依照国务院规定的职责负责全国农村土地承包经营及承包经营合同管理的指导。"},{"i":13,"n":"第十三条","txt":"农民集体所有的土地依法属于村农民集体所有的，由村集体经济组织或者村民委员会发包；已经分别属于村内两个以上农村集体经济组织的农民集体所有的，由村内各该农村集体经济组织或者村民小组发包。村集体经济组织或者村民委员会发包的，不得改变村内各集体经济组织农民集体所有的土地的所有权。"},{"i":14,"n":"第十四条","txt":"发包方享有下列权利："},{"i":15,"n":"第十五条","txt":"发包方承担下列义务："},{"i":16,"n":"第十六条","txt":"家庭承包的承包方是本集体经济组织的农户。"},{"i":17,"n":"第十七条","txt":"承包方享有下列权利："},{"i":18,"n":"第十八条","txt":"承包方承担下列义务："},{"i":19,"n":"第十九条","txt":"土地承包应当遵循以下原则："},{"i":20,"n":"第二十条","txt":"土地承包应当按照以下程序进行："},{"i":21,"n":"第二十一条","txt":"耕地的承包期为三十年。草地的承包期为三十年至五十年。林地的承包期为三十年至七十年。"},{"i":22,"n":"第二十二条","txt":"发包方应当与承包方签订书面承包合同。"},{"i":23,"n":"第二十三条","txt":"承包合同自成立之日起生效。承包方自承包合同生效时取得土地承包经营权。"},{"i":24,"n":"第二十四条","txt":"国家对耕地、林地和草地等实行统一登记，登记机构应当向承包方颁发土地承包经营权证或者林权证等证书，并登记造册，确认土地承包经营权。"},{"i":25,"n":"第二十五条","txt":"承包合同生效后，发包方不得因承办人或者负责人的变动而变更或者解除，也不得因集体经济组织的分立或者合并而变更或者解除。"},{"i":26,"n":"第二十六条","txt":"国家机关及其工作人员不得利用职权干涉农村土地承包或者变更、解除承包合同。"},{"i":27,"n":"第二十七条","txt":"承包期内，发包方不得收回承包地。"},{"i":28,"n":"第二十八条","txt":"承包期内，发包方不得调整承包地。"},{"i":29,"n":"第二十九条","txt":"下列土地应当用于调整承包土地或者承包给新增人口："},{"i":30,"n":"第三十条","txt":"承包期内，承包方可以自愿将承包地交回发包方。承包方自愿交回承包地的，可以获得合理补偿，但是应当提前半年以书面形式通知发包方。承包方在承包期内交回承包地的，在承包期内不得再要求承包土地。"},{"i":31,"n":"第三十一条","txt":"承包期内，妇女结婚，在新居住地未取得承包地的，发包方不得收回其原承包地；妇女离婚或者丧偶，仍在原居住地生活或者不在原居住地生活但在新居住地未取得承包地的，发包方不得收回其原承包地。"},{"i":32,"n":"第三十二条","txt":"承包人应得的承包收益，依照继承法的规定继承。"},{"i":33,"n":"第三十三条","txt":"承包方之间为方便耕种或者各自需要，可以对属于同一集体经济组织的土地的土地承包经营权进行互换，并向发包方备案。"},{"i":34,"n":"第三十四条","txt":"经发包方同意，承包方可以将全部或者部分的土地承包经营权转让给本集体经济组织的其他农户，由该农户同发包方确立新的承包关系，原承包方与发包方在该土地上的承包关系即行终止。"},{"i":35,"n":"第三十五条","txt":"土地承包经营权互换、转让的，当事人可以向登记机构申请登记。未经登记，不得对抗善意第三人。"},{"i":36,"n":"第三十六条","txt":"承包方可以自主决定依法采取出租（转包）、入股或者其他方式向他人流转土地经营权，并向发包方备案。"},{"i":37,"n":"第三十七条","txt":"土地经营权人有权在合同约定的期限内占有农村土地，自主开展农业生产经营并取得收益。"},{"i":38,"n":"第三十八条","txt":"土地经营权流转应当遵循以下原则："},{"i":39,"n":"第三十九条","txt":"土地经营权流转的价款，应当由当事人双方协商确定。流转的收益归承包方所有，任何组织和个人不得擅自截留、扣缴。"},{"i":40,"n":"第四十条","txt":"土地经营权流转，当事人双方应当签订书面流转合同。"},{"i":41,"n":"第四十一条","txt":"土地经营权流转期限为五年以上的，当事人可以向登记机构申请土地经营权登记。未经登记，不得对抗善意第三人。"},{"i":42,"n":"第四十二条","txt":"承包方不得单方解除土地经营权流转合同，但受让方有下列情形之一的除外："},{"i":43,"n":"第四十三条","txt":"经承包方同意，受让方可以依法投资改良土壤，建设农业生产附属、配套设施，并按照合同约定对其投资部分获得合理补偿。"},{"i":44,"n":"第四十四条","txt":"承包方流转土地经营权的，其与发包方的承包关系不变。"},{"i":45,"n":"第四十五条","txt":"县级以上地方人民政府应当建立工商企业等社会资本通过流转取得土地经营权的资格审查、项目审核和风险防范制度。"},{"i":46,"n":"第四十六条","txt":"经承包方书面同意，并向本集体经济组织备案，受让方可以再流转土地经营权。"},{"i":47,"n":"第四十七条","txt":"承包方可以用承包地的土地经营权向金融机构融资担保，并向发包方备案。受让方通过流转取得的土地经营权，经承包方书面同意并向发包方备案，可以向金融机构融资担保。"},{"i":48,"n":"第四十八条","txt":"不宜采取家庭承包方式的荒山、荒沟、荒丘、荒滩等农村土地，通过招标、拍卖、公开协商等方式承包的，适用本章规定。"},{"i":49,"n":"第四十九条","txt":"以其他方式承包农村土地的，应当签订承包合同，承包方取得土地经营权。当事人的权利和义务、承包期限等，由双方协商确定。以招标、拍卖方式承包的，承包费通过公开竞标、竞价确定；以公开协商等方式承包的，承包费由双方议定。"},{"i":50,"n":"第五十条","txt":"荒山、荒沟、荒丘、荒滩等可以直接通过招标、拍卖、公开协商等方式实行承包经营，也可以将土地经营权折股分给本集体经济组织成员后，再实行承包经营或者股份合作经营。"},{"i":51,"n":"第五十一条","txt":"以其他方式承包农村土地，在同等条件下，本集体经济组织成员有权优先承包。"},{"i":52,"n":"第五十二条","txt":"发包方将农村土地发包给本集体经济组织以外的单位或者个人承包，应当事先经本集体经济组织成员的村民会议三分之二以上成员或者三分之二以上村民代表的同意，并报乡（镇）人民政府批准。"},{"i":53,"n":"第五十三条","txt":"通过招标、拍卖、公开协商等方式承包农村土地，经依法登记取得权属证书的，可以依法采取出租、入股、抵押或者其他方式流转土地经营权。"},{"i":54,"n":"第五十四条","txt":"依照本章规定通过招标、拍卖、公开协商等方式取得土地经营权的，该承包人死亡，其应得的承包收益，依照继承法的规定继承；在承包期内，其继承人可以继续承包。"},{"i":55,"n":"第五十五条","txt":"因土地承包经营发生纠纷的，双方当事人可以通过协商解决，也可以请求村民委员会、乡（镇）人民政府等调解解决。"},{"i":56,"n":"第五十六条","txt":"任何组织和个人侵害土地承包经营权、土地经营权的，应当承担民事责任。"},{"i":57,"n":"第五十七条","txt":"发包方有下列行为之一的，应当承担停止侵害、排除妨碍、消除危险、返还财产、恢复原状、赔偿损失等民事责任："},{"i":58,"n":"第五十八条","txt":"承包合同中违背承包方意愿或者违反法律、行政法规有关不得收回、调整承包地等强制性规定的约定无效。"},{"i":59,"n":"第五十九条","txt":"当事人一方不履行合同义务或者履行义务不符合约定的，应当依法承担违约责任。"},{"i":60,"n":"第六十条","txt":"任何组织和个人强迫进行土地承包经营权互换、转让或者土地经营权流转的，该互换、转让或者流转无效。"},{"i":61,"n":"第六十一条","txt":"任何组织和个人擅自截留、扣缴土地承包经营权互换、转让或者土地经营权流转收益的，应当退还。"},{"i":62,"n":"第六十二条","txt":"违反土地管理法规，非法征收、征用、占用土地或者贪污、挪用土地征收、征用补偿费用，构成犯罪的，依法追究刑事责任；造成他人损害的，应当承担损害赔偿等责任。"},{"i":63,"n":"第六十三条","txt":"承包方、土地经营权人违法将承包地用于非农建设的，由县级以上地方人民政府有关主管部门依法予以处罚。"},{"i":64,"n":"第六十四条","txt":"土地经营权人擅自改变土地的农业用途、弃耕抛荒连续两年以上、给土地造成严重损害或者严重破坏土地生态环境，承包方在合理期限内不解除土地经营权流转合同的，发包方有权要求终止土地经营权流转合同。土地经营权人对土地和土地生态环境造成的损害应当予以赔偿。"},{"i":65,"n":"第六十五条","txt":"国家机关及其工作人员有利用职权干涉农村土地承包经营，变更、解除承包经营合同，干涉承包经营当事人依法享有的生产经营自主权，强迫、阻碍承包经营当事人进行土地承包经营权互换、转让或者土地经营权流转等侵害土地承包经营权、土地经营权的行为，给承包经营当事人造成损失的，应当承担损害赔偿等责任；情节严重的，由上级机关或者所在单位给予直接责任人员处分；构成犯罪的，依法追究刑事责任。"},{"i":66,"n":"第六十六条","txt":"本法实施前已经按照国家有关农村土地承包的规定承包，包括承包期限长于本法规定的，本法实施后继续有效，不得重新承包土地。未向承包方颁发土地承包经营权证或者林权证等证书的，应当补发证书。"},{"i":67,"n":"第六十七条","txt":"本法实施前已经预留机动地的，机动地面积不得超过本集体经济组织耕地总面积的百分之五。不足百分之五的，不得再增加机动地。"},{"i":68,"n":"第六十八条","txt":"各省、自治区、直辖市人民代表大会常务委员会可以根据本法，结合本行政区域的实际情况，制定实施办法。"},{"i":69,"n":"第六十九条","txt":"确认农村集体经济组织成员身份的原则、程序等，由法律、法规规定。"},{"i":70,"n":"第七十条","txt":"本法自2003年3月1日起施行。"}],"nongcunjitijingjizuzhifa":[{"i":1,"n":"第一条","txt":"为了维护农村集体经济组织及其成员的合法权益，规范农村集体经济组织及其运行管理，促进新型农村集体经济高质量发展，巩固和完善农村基本经营制度和社会主义基本经济制度，推进乡村全面振兴，加快建设农业强国，促进共同富裕，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称农村集体经济组织，是指以土地集体所有为基础，依法代表成员集体行使所有权，实行家庭承包经营为基础、统分结合双层经营体制的区域性经济组织，包括乡镇级农村集体经济组织、村级农村集体经济组织、组级农村集体经济组织。"},{"i":3,"n":"第三条","txt":"农村集体经济组织是发展壮大新型农村集体经济、巩固社会主义公有制、促进共同富裕的重要主体，是健全乡村治理体系、实现乡村善治的重要力量，是提升中国共产党农村基层组织凝聚力、巩固党在农村执政根基的重要保障。"},{"i":4,"n":"第四条","txt":"农村集体经济组织应当坚持以下原则："},{"i":5,"n":"第五条","txt":"农村集体经济组织依法代表成员集体行使所有权，履行下列职能："},{"i":6,"n":"第六条","txt":"农村集体经济组织依照本法登记，取得特别法人资格，依法从事与其履行职能相适应的民事活动。"},{"i":7,"n":"第七条","txt":"农村集体经济组织从事经营管理和服务活动，应当遵守法律法规，遵守社会公德、商业道德，诚实守信，承担社会责任。"},{"i":8,"n":"第八条","txt":"国家保护农村集体经济组织及其成员的合法权益，任何组织和个人不得侵犯。"},{"i":9,"n":"第九条","txt":"国家通过财政、税收、金融、土地、人才以及产业政策等扶持措施，促进农村集体经济组织发展，壮大新型农村集体经济。"},{"i":10,"n":"第十条","txt":"国务院农业农村主管部门负责指导全国农村集体经济组织的建设和发展。国务院其他有关部门在各自职责范围内负责有关的工作。"},{"i":11,"n":"第十一条","txt":"户籍在或者曾经在农村集体经济组织并与农村集体经济组织形成稳定的权利义务关系，以农村集体经济组织成员集体所有的土地等财产为基本生活保障的居民，为农村集体经济组织成员。"},{"i":12,"n":"第十二条","txt":"农村集体经济组织通过成员大会，依据前条规定确认农村集体经济组织成员。"},{"i":13,"n":"第十三条","txt":"农村集体经济组织成员享有下列权利："},{"i":14,"n":"第十四条","txt":"农村集体经济组织成员履行下列义务："},{"i":15,"n":"第十五条","txt":"非农村集体经济组织成员长期在农村集体经济组织工作，对集体做出贡献的，经农村集体经济组织成员大会全体成员四分之三以上同意，可以享有本法第十三条第七项、第九项、第十项规定的权利。"},{"i":16,"n":"第十六条","txt":"农村集体经济组织成员提出书面申请并经农村集体经济组织同意的，可以自愿退出农村集体经济组织。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，丧失农村集体经济组织成员身份："},{"i":18,"n":"第十八条","txt":"农村集体经济组织成员不因就学、服役、务工、经商、离婚、丧偶、服刑等原因而丧失农村集体经济组织成员身份。"},{"i":19,"n":"第十九条","txt":"农村集体经济组织应当具备下列条件："},{"i":20,"n":"第二十条","txt":"农村集体经济组织章程应当载明下列事项："},{"i":21,"n":"第二十一条","txt":"农村集体经济组织的名称中应当标明“集体经济组织”字样，以及所在县、不设区的市、市辖区、乡、民族乡、镇、村或者组的名称。"},{"i":22,"n":"第二十二条","txt":"农村集体经济组织成员大会表决通过本农村集体经济组织章程、确认本农村集体经济组织成员、选举本农村集体经济组织理事会成员、监事会成员或者监事后，应当及时向县级以上地方人民政府农业农村主管部门申请登记，取得农村集体经济组织登记证书。"},{"i":23,"n":"第二十三条","txt":"农村集体经济组织合并的，应当在清产核资的基础上编制资产负债表和财产清单。"},{"i":24,"n":"第二十四条","txt":"农村集体经济组织分立的，应当在清产核资的基础上分配财产、分解债权债务。"},{"i":25,"n":"第二十五条","txt":"农村集体经济组织合并、分立或者登记事项变动的，应当办理变更登记。"},{"i":26,"n":"第二十六条","txt":"农村集体经济组织成员大会由具有完全民事行为能力的全体成员组成，是本农村集体经济组织的权力机构，依法行使下列职权："},{"i":27,"n":"第二十七条","txt":"农村集体经济组织召开成员大会，应当将会议召开的时间、地点和审议的事项于会议召开十日前通知全体成员，有三分之二以上具有完全民事行为能力的成员参加。成员无法在现场参加会议的，可以通过即时通讯工具在线参加会议，或者书面委托本农村集体经济组织同一户内具有完全民事行为能力的其他家庭成员代为参加会议。"},{"i":28,"n":"第二十八条","txt":"农村集体经济组织成员较多的，可以按照农村集体经济组织章程规定设立成员代表大会。"},{"i":29,"n":"第二十九条","txt":"农村集体经济组织设理事会，一般由三至七名单数成员组成。理事会设理事长一名，可以设副理事长。理事长、副理事长、理事的产生办法由农村集体经济组织章程规定。理事会成员之间应当实行近亲属回避。理事会成员的任期为五年，可以连选连任。"},{"i":30,"n":"第三十条","txt":"理事会对成员大会、成员代表大会负责，行使下列职权："},{"i":31,"n":"第三十一条","txt":"理事会会议应当有三分之二以上的理事会成员出席。"},{"i":32,"n":"第三十二条","txt":"农村集体经济组织设监事会，成员较少的可以设一至二名监事，行使监督理事会执行成员大会和成员代表大会决定、监督检查集体财产经营管理情况、审核监督本农村集体经济组织财务状况等内部监督职权。必要时，监事会或者监事可以组织对本农村集体经济组织的财务进行内部审计，审计结果应当向成员大会、成员代表大会报告。"},{"i":33,"n":"第三十三条","txt":"农村集体经济组织成员大会、成员代表大会、理事会、监事会或者监事召开会议，应当按照规定制作、保存会议记录。"},{"i":34,"n":"第三十四条","txt":"农村集体经济组织理事会成员、监事会成员或者监事与村党组织领导班子成员、村民委员会成员可以根据情况交叉任职。"},{"i":35,"n":"第三十五条","txt":"农村集体经济组织理事会成员、监事会成员或者监事应当遵守法律法规和农村集体经济组织章程，履行诚实信用、勤勉谨慎的义务，为农村集体经济组织及其成员的利益管理集体财产，处理农村集体经济组织事务。"},{"i":36,"n":"第三十六条","txt":"集体财产主要包括："},{"i":37,"n":"第三十七条","txt":"集体所有和国家所有依法由农民集体使用的耕地、林地、草地以及其他依法用于农业的土地，依照农村土地承包的法律实行承包经营。"},{"i":38,"n":"第三十八条","txt":"依法应当实行家庭承包的耕地、林地、草地以外的其他农村土地，农村集体经济组织可以直接组织经营或者依法实行承包经营，也可以依法采取土地经营权出租、入股等方式经营。"},{"i":39,"n":"第三十九条","txt":"对符合国家规定的集体经营性建设用地，农村集体经济组织应当优先用于保障乡村产业发展和乡村建设，也可以依法通过出让、出租等方式交由单位或者个人有偿使用。"},{"i":40,"n":"第四十条","txt":"农村集体经济组织可以将集体所有的经营性财产的收益权以份额形式量化到本农村集体经济组织成员，作为其参与集体收益分配的基本依据。"},{"i":41,"n":"第四十一条","txt":"农村集体经济组织可以探索通过资源发包、物业出租、居间服务、经营性财产参股等多样化途径发展新型农村集体经济。"},{"i":42,"n":"第四十二条","txt":"农村集体经济组织当年收益应当按照农村集体经济组织章程规定提取公积公益金，用于弥补亏损、扩大生产经营等，剩余的可分配收益按照量化给农村集体经济组织成员的集体经营性财产收益权份额进行分配。"},{"i":43,"n":"第四十三条","txt":"农村集体经济组织应当加强集体财产管理，建立集体财产清查、保管、使用、处置、公开等制度，促进集体财产保值增值。"},{"i":44,"n":"第四十四条","txt":"农村集体经济组织应当按照国务院有关部门制定的农村集体经济组织财务会计制度进行财务管理和会计核算。"},{"i":45,"n":"第四十五条","txt":"农村集体经济组织应当定期将财务情况向农村集体经济组织成员公布。集体财产使用管理情况、涉及农村集体经济组织及其成员利益的重大事项应当及时公布。农村集体经济组织理事会应当保证所公布事项的真实性。"},{"i":46,"n":"第四十六条","txt":"农村集体经济组织应当编制年度经营报告、年度财务会计报告和收益分配方案，并于成员大会、成员代表大会召开十日前，提供给农村集体经济组织成员查阅。"},{"i":47,"n":"第四十七条","txt":"农村集体经济组织应当依法接受审计监督。"},{"i":48,"n":"第四十八条","txt":"农村集体经济组织应当自觉接受有关机关和组织对集体财产使用管理情况的监督。"},{"i":49,"n":"第四十九条","txt":"县级以上人民政府应当合理安排资金，支持农村集体经济组织发展新型农村集体经济、服务集体成员。"},{"i":50,"n":"第五十条","txt":"农村集体经济组织依法履行纳税义务，依法享受税收优惠。"},{"i":51,"n":"第五十一条","txt":"农村集体经济组织用于集体公益和综合服务、保障村级组织和村务运转等支出，按照国家规定计入相应成本。"},{"i":52,"n":"第五十二条","txt":"国家鼓励政策性金融机构立足职能定位，在业务范围内采取多种形式对农村集体经济组织发展新型农村集体经济提供多渠道资金支持。"},{"i":53,"n":"第五十三条","txt":"乡镇人民政府编制村庄规划应当根据实际需要合理安排集体经济发展各项建设用地。"},{"i":54,"n":"第五十四条","txt":"县级人民政府和乡镇人民政府、街道办事处应当加强农村集体经济组织经营管理队伍建设，制定农村集体经济组织人才培养计划，完善激励机制，支持和引导各类人才服务新型农村集体经济发展。"},{"i":55,"n":"第五十五条","txt":"各级人民政府应当在用水、用电、用气以及网络、交通等公共设施和农村人居环境基础设施配置方面为农村集体经济组织建设发展提供支持。"},{"i":56,"n":"第五十六条","txt":"对确认农村集体经济组织成员身份有异议，或者农村集体经济组织因内部管理、运行、收益分配等发生纠纷的，当事人可以请求乡镇人民政府、街道办事处或者县级人民政府农业农村主管部门调解解决；不愿调解或者调解不成的，可以向农村土地承包仲裁机构申请仲裁，也可以直接向人民法院提起诉讼。"},{"i":57,"n":"第五十七条","txt":"农村集体经济组织成员大会、成员代表大会、理事会或者农村集体经济组织负责人作出的决定侵害农村集体经济组织成员合法权益的，受侵害的农村集体经济组织成员可以请求人民法院予以撤销。但是，农村集体经济组织按照该决定与善意相对人形成的民事法律关系不受影响。"},{"i":58,"n":"第五十八条","txt":"农村集体经济组织理事会成员、监事会成员或者监事、主要经营管理人员有本法第三十五条第二款规定行为的，由乡镇人民政府、街道办事处或者县级人民政府农业农村主管部门责令限期改正；情节严重的，依法给予处分或者行政处罚；造成集体财产损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":59,"n":"第五十九条","txt":"对于侵害农村集体经济组织合法权益的行为，农村集体经济组织可以依法向人民法院提起诉讼。"},{"i":60,"n":"第六十条","txt":"农村集体经济组织理事会成员、监事会成员或者监事、主要经营管理人员执行职务时违反法律法规或者农村集体经济组织章程的规定，给农村集体经济组织造成损失的，应当依法承担赔偿责任。"},{"i":61,"n":"第六十一条","txt":"农村集体经济组织章程或者农村集体经济组织成员大会、成员代表大会所作的决定违反本法或者其他法律法规规定的，由乡镇人民政府、街道办事处或者县级人民政府农业农村主管部门责令限期改正。"},{"i":62,"n":"第六十二条","txt":"地方人民政府及其有关部门非法干预农村集体经济组织经营管理和财产管理活动或者未依法履行相应监管职责的，由上级人民政府责令限期改正；情节严重的，依法追究相关责任人员的法律责任。"},{"i":63,"n":"第六十三条","txt":"农村集体经济组织对行政机关的行政行为不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":64,"n":"第六十四条","txt":"未设立农村集体经济组织的，村民委员会、村民小组可以依法代行农村集体经济组织的职能。"},{"i":65,"n":"第六十五条","txt":"本法施行前已经按照国家规定登记的农村集体经济组织及其名称，本法施行后在法人登记证书有效期限内继续有效。"},{"i":66,"n":"第六十六条","txt":"本法施行前农村集体经济组织开展农村集体产权制度改革时已经被确认的成员，本法施行后不需要重新确认。"},{"i":67,"n":"第六十七条","txt":"本法自2025年5月1日起施行。"}],"nongminzhuanyehezuoshefa":[{"i":1,"n":"第一条","txt":"为了规范农民专业合作社的组织和行为，鼓励、支持、引导农民专业合作社的发展，保护农民专业合作社及其成员的合法权益，推进农业农村现代化，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称农民专业合作社，是指在农村家庭承包经营基础上，农产品的生产经营者或者农业生产经营服务的提供者、利用者，自愿联合、民主管理的互助性经济组织。"},{"i":3,"n":"第三条","txt":"农民专业合作社以其成员为主要服务对象，开展以下一种或者多种业务："},{"i":4,"n":"第四条","txt":"农民专业合作社应当遵循下列原则："},{"i":5,"n":"第五条","txt":"农民专业合作社依照本法登记，取得法人资格。"},{"i":6,"n":"第六条","txt":"农民专业合作社成员以其账户内记载的出资额和公积金份额为限对农民专业合作社承担责任。"},{"i":7,"n":"第七条","txt":"国家保障农民专业合作社享有与其他市场主体平等的法律地位。"},{"i":8,"n":"第八条","txt":"农民专业合作社从事生产经营活动，应当遵守法律，遵守社会公德、商业道德，诚实守信，不得从事与章程规定无关的活动。"},{"i":9,"n":"第九条","txt":"农民专业合作社为扩大生产经营和服务的规模，发展产业化经营，提高市场竞争力，可以依法自愿设立或者加入农民专业合作社联合社。"},{"i":10,"n":"第十条","txt":"国家通过财政支持、税收优惠和金融、科技、人才的扶持以及产业政策引导等措施，促进农民专业合作社的发展。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府应当建立农民专业合作社工作的综合协调机制，统筹指导、协调、推动农民专业合作社的建设和发展。"},{"i":12,"n":"第十二条","txt":"设立农民专业合作社，应当具备下列条件："},{"i":13,"n":"第十三条","txt":"农民专业合作社成员可以用货币出资，也可以用实物、知识产权、土地经营权、林权等可以用货币估价并可以依法转让的非货币财产，以及章程规定的其他方式作价出资；但是，法律、行政法规规定不得作为出资的财产除外。"},{"i":14,"n":"第十四条","txt":"设立农民专业合作社，应当召开由全体设立人参加的设立大会。设立时自愿成为该社成员的人为设立人。"},{"i":15,"n":"第十五条","txt":"农民专业合作社章程应当载明下列事项："},{"i":16,"n":"第十六条","txt":"设立农民专业合作社，应当向工商行政管理部门提交下列文件，申请设立登记："},{"i":17,"n":"第十七条","txt":"农民专业合作社应当按照国家有关规定，向登记机关报送年度报告，并向社会公示。"},{"i":18,"n":"第十八条","txt":"农民专业合作社可以依法向公司等企业投资，以其出资额为限对所投资企业承担责任。"},{"i":19,"n":"第十九条","txt":"具有民事行为能力的公民，以及从事与农民专业合作社业务直接有关的生产经营活动的企业、事业单位或者社会组织，能够利用农民专业合作社提供的服务，承认并遵守农民专业合作社章程，履行章程规定的入社手续的，可以成为农民专业合作社的成员。但是，具有管理公共事务职能的单位不得加入农民专业合作社。"},{"i":20,"n":"第二十条","txt":"农民专业合作社的成员中，农民至少应当占成员总数的百分之八十。"},{"i":21,"n":"第二十一条","txt":"农民专业合作社成员享有下列权利："},{"i":22,"n":"第二十二条","txt":"农民专业合作社成员大会选举和表决，实行一人一票制，成员各享有一票的基本表决权。"},{"i":23,"n":"第二十三条","txt":"农民专业合作社成员承担下列义务："},{"i":24,"n":"第二十四条","txt":"符合本法第十九条、第二十条规定的公民、企业、事业单位或者社会组织，要求加入已成立的农民专业合作社，应当向理事长或者理事会提出书面申请，经成员大会或者成员代表大会表决通过后，成为本社成员。"},{"i":25,"n":"第二十五条","txt":"农民专业合作社成员要求退社的，应当在会计年度终了的三个月前向理事长或者理事会提出书面申请；其中，企业、事业单位或者社会组织成员退社，应当在会计年度终了的六个月前提出；章程另有规定的，从其规定。退社成员的成员资格自会计年度终了时终止。"},{"i":26,"n":"第二十六条","txt":"农民专业合作社成员不遵守农民专业合作社的章程、成员大会或者成员代表大会的决议，或者严重危害其他成员及农民专业合作社利益的，可以予以除名。"},{"i":27,"n":"第二十七条","txt":"成员在其资格终止前与农民专业合作社已订立的合同，应当继续履行；章程另有规定或者与本社另有约定的除外。"},{"i":28,"n":"第二十八条","txt":"成员资格终止的，农民专业合作社应当按照章程规定的方式和期限，退还记载在该成员账户内的出资额和公积金份额；对成员资格终止前的可分配盈余，依照本法第四十四条的规定向其返还。"},{"i":29,"n":"第二十九条","txt":"农民专业合作社成员大会由全体成员组成，是本社的权力机构，行使下列职权："},{"i":30,"n":"第三十条","txt":"农民专业合作社召开成员大会，出席人数应当达到成员总数三分之二以上。"},{"i":31,"n":"第三十一条","txt":"农民专业合作社成员大会每年至少召开一次，会议的召集由章程规定。有下列情形之一的，应当在二十日内召开临时成员大会："},{"i":32,"n":"第三十二条","txt":"农民专业合作社成员超过一百五十人的，可以按照章程规定设立成员代表大会。成员代表大会按照章程规定可以行使成员大会的部分或者全部职权。"},{"i":33,"n":"第三十三条","txt":"农民专业合作社设理事长一名，可以设理事会。理事长为本社的法定代表人。"},{"i":34,"n":"第三十四条","txt":"农民专业合作社的成员大会、成员代表大会、理事会、监事会，应当将所议事项的决定作成会议记录，出席会议的成员、成员代表、理事、监事应当在会议记录上签名。"},{"i":35,"n":"第三十五条","txt":"农民专业合作社的理事长或者理事会可以按照成员大会的决定聘任经理和财务会计人员，理事长或者理事可以兼任经理。经理按照章程规定或者理事会的决定，可以聘任其他人员。"},{"i":36,"n":"第三十六条","txt":"农民专业合作社的理事长、理事和管理人员不得有下列行为："},{"i":37,"n":"第三十七条","txt":"农民专业合作社的理事长、理事、经理不得兼任业务性质相同的其他农民专业合作社的理事长、理事、监事、经理。"},{"i":38,"n":"第三十八条","txt":"执行与农民专业合作社业务有关公务的人员，不得担任农民专业合作社的理事长、理事、监事、经理或者财务会计人员。"},{"i":39,"n":"第三十九条","txt":"农民专业合作社应当按照国务院财政部门制定的财务会计制度进行财务管理和会计核算。"},{"i":40,"n":"第四十条","txt":"农民专业合作社的理事长或者理事会应当按照章程规定，组织编制年度业务报告、盈余分配方案、亏损处理方案以及财务会计报告，于成员大会召开的十五日前，置备于办公地点，供成员查阅。"},{"i":41,"n":"第四十一条","txt":"农民专业合作社与其成员的交易、与利用其提供的服务的非成员的交易，应当分别核算。"},{"i":42,"n":"第四十二条","txt":"农民专业合作社可以按照章程规定或者成员大会决议从当年盈余中提取公积金。公积金用于弥补亏损、扩大生产经营或者转为成员出资。"},{"i":43,"n":"第四十三条","txt":"农民专业合作社应当为每个成员设立成员账户，主要记载下列内容："},{"i":44,"n":"第四十四条","txt":"在弥补亏损、提取公积金后的当年盈余，为农民专业合作社的可分配盈余。可分配盈余主要按照成员与本社的交易量（额）比例返还。"},{"i":45,"n":"第四十五条","txt":"设立执行监事或者监事会的农民专业合作社，由执行监事或者监事会负责对本社的财务进行内部审计，审计结果应当向成员大会报告。"},{"i":46,"n":"第四十六条","txt":"农民专业合作社合并，应当自合并决议作出之日起十日内通知债权人。合并各方的债权、债务应当由合并后存续或者新设的组织承继。"},{"i":47,"n":"第四十七条","txt":"农民专业合作社分立，其财产作相应的分割，并应当自分立决议作出之日起十日内通知债权人。分立前的债务由分立后的组织承担连带责任。但是，在分立前与债权人就债务清偿达成的书面协议另有约定的除外。"},{"i":48,"n":"第四十八条","txt":"农民专业合作社因下列原因解散："},{"i":49,"n":"第四十九条","txt":"清算组自成立之日起接管农民专业合作社，负责处理与清算有关未了结业务，清理财产和债权、债务，分配清偿债务后的剩余财产，代表农民专业合作社参与诉讼、仲裁或者其他法律程序，并在清算结束时办理注销登记。"},{"i":50,"n":"第五十条","txt":"清算组应当自成立之日起十日内通知农民专业合作社成员和债权人，并于六十日内在报纸上公告。债权人应当自接到通知之日起三十日内，未接到通知的自公告之日起四十五日内，向清算组申报债权。如果在规定期间内全部成员、债权人均已收到通知，免除清算组的公告义务。"},{"i":51,"n":"第五十一条","txt":"农民专业合作社因本法第四十八条第一款的原因解散，或者人民法院受理破产申请时，不能办理成员退社手续。"},{"i":52,"n":"第五十二条","txt":"清算组负责制定包括清偿农民专业合作社员工的工资及社会保险费用，清偿所欠税款和其他各项债务，以及分配剩余财产在内的清算方案，经成员大会通过或者申请人民法院确认后实施。"},{"i":53,"n":"第五十三条","txt":"农民专业合作社接受国家财政直接补助形成的财产，在解散、破产清算时，不得作为可分配剩余资产分配给成员，具体按照国务院财政部门有关规定执行。"},{"i":54,"n":"第五十四条","txt":"清算组成员应当忠于职守，依法履行清算义务，因故意或者重大过失给农民专业合作社成员及债权人造成损失的，应当承担赔偿责任。"},{"i":55,"n":"第五十五条","txt":"农民专业合作社破产适用企业破产法的有关规定。但是，破产财产在清偿破产费用和共益债务后，应当优先清偿破产前与农民成员已发生交易但尚未结清的款项。"},{"i":56,"n":"第五十六条","txt":"三个以上的农民专业合作社在自愿的基础上，可以出资设立农民专业合作社联合社。"},{"i":57,"n":"第五十七条","txt":"农民专业合作社联合社依照本法登记，取得法人资格，领取营业执照，登记类型为农民专业合作社联合社。"},{"i":58,"n":"第五十八条","txt":"农民专业合作社联合社以其全部财产对该社的债务承担责任；农民专业合作社联合社的成员以其出资额为限对农民专业合作社联合社承担责任。"},{"i":59,"n":"第五十九条","txt":"农民专业合作社联合社应当设立由全体成员参加的成员大会，其职权包括修改农民专业合作社联合社章程，选举和罢免农民专业合作社联合社理事长、理事和监事，决定农民专业合作社联合社的经营方案及盈余分配，决定对外投资和担保方案等重大事项。"},{"i":60,"n":"第六十条","txt":"农民专业合作社联合社的成员大会选举和表决，实行一社一票。"},{"i":61,"n":"第六十一条","txt":"农民专业合作社联合社可分配盈余的分配办法，按照本法规定的原则由农民专业合作社联合社章程规定。"},{"i":62,"n":"第六十二条","txt":"农民专业合作社联合社成员退社，应当在会计年度终了的六个月前以书面形式向理事会提出。退社成员的成员资格自会计年度终了时终止。"},{"i":63,"n":"第六十三条","txt":"本章对农民专业合作社联合社没有规定的，适用本法关于农民专业合作社的规定。"},{"i":64,"n":"第六十四条","txt":"国家支持发展农业和农村经济的建设项目，可以委托和安排有条件的农民专业合作社实施。"},{"i":65,"n":"第六十五条","txt":"中央和地方财政应当分别安排资金，支持农民专业合作社开展信息、培训、农产品标准与认证、农业生产基础设施建设、市场营销和技术推广等服务。国家对革命老区、民族地区、边疆地区和贫困地区的农民专业合作社给予优先扶助。"},{"i":66,"n":"第六十六条","txt":"国家政策性金融机构应当采取多种形式，为农民专业合作社提供多渠道的资金支持。具体支持政策由国务院规定。"},{"i":67,"n":"第六十七条","txt":"农民专业合作社享受国家规定的对农业生产、加工、流通、服务和其他涉农经济活动相应的税收优惠。"},{"i":68,"n":"第六十八条","txt":"农民专业合作社从事农产品初加工用电执行农业生产用电价格，农民专业合作社生产性配套辅助设施用地按农用地管理，具体办法由国务院有关部门规定。"},{"i":69,"n":"第六十九条","txt":"侵占、挪用、截留、私分或者以其他方式侵犯农民专业合作社及其成员的合法财产，非法干预农民专业合作社及其成员的生产经营活动，向农民专业合作社及其成员摊派，强迫农民专业合作社及其成员接受有偿服务，造成农民专业合作社经济损失的，依法追究法律责任。"},{"i":70,"n":"第七十条","txt":"农民专业合作社向登记机关提供虚假登记材料或者采取其他欺诈手段取得登记的，由登记机关责令改正，可以处五千元以下罚款；情节严重的，撤销登记或者吊销营业执照。"},{"i":71,"n":"第七十一条","txt":"农民专业合作社连续两年未从事经营活动的，吊销其营业执照。"},{"i":72,"n":"第七十二条","txt":"农民专业合作社在依法向有关主管部门提供的财务报告等材料中，作虚假记载或者隐瞒重要事实的，依法追究法律责任。"},{"i":73,"n":"第七十三条","txt":"国有农场、林场、牧场、渔场等企业中实行承包租赁经营、从事农业生产经营或者服务的职工，兴办农民专业合作社适用本法。"},{"i":74,"n":"第七十四条","txt":"本法自2018年7月1日起施行。"}],"hehuoqiyefa":[{"i":1,"n":"第一条","txt":"为了规范合伙企业的行为，保护合伙企业及其合伙人、债权人的合法权益，维护社会经济秩序，促进社会主义市场经济的发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称合伙企业，是指自然人、法人和其他组织依照本法在中国境内设立的普通合伙企业和有限合伙企业。"},{"i":3,"n":"第三条","txt":"国有独资公司、国有企业、上市公司以及公益性的事业单位、社会团体不得成为普通合伙人。"},{"i":4,"n":"第四条","txt":"合伙协议依法由全体合伙人协商一致、以书面形式订立。"},{"i":5,"n":"第五条","txt":"订立合伙协议、设立合伙企业，应当遵循自愿、平等、公平、诚实信用原则。"},{"i":6,"n":"第六条","txt":"合伙企业的生产经营所得和其他所得，按照国家有关税收规定，由合伙人分别缴纳所得税。"},{"i":7,"n":"第七条","txt":"合伙企业及其合伙人必须遵守法律、行政法规，遵守社会公德、商业道德，承担社会责任。"},{"i":8,"n":"第八条","txt":"合伙企业及其合伙人的合法财产及其权益受法律保护。"},{"i":9,"n":"第九条","txt":"申请设立合伙企业，应当向企业登记机关提交登记申请书、合伙协议书、合伙人身份证明等文件。"},{"i":10,"n":"第十条","txt":"申请人提交的登记申请材料齐全、符合法定形式，企业登记机关能够当场登记的，应予当场登记，发给营业执照。"},{"i":11,"n":"第十一条","txt":"合伙企业的营业执照签发日期，为合伙企业成立日期。"},{"i":12,"n":"第十二条","txt":"合伙企业设立分支机构，应当向分支机构所在地的企业登记机关申请登记，领取营业执照。"},{"i":13,"n":"第十三条","txt":"合伙企业登记事项发生变更的，执行合伙事务的合伙人应当自作出变更决定或者发生变更事由之日起十五日内，向企业登记机关申请办理变更登记。"},{"i":14,"n":"第十四条","txt":"设立合伙企业，应当具备下列条件："},{"i":15,"n":"第十五条","txt":"合伙企业名称中应当标明“普通合伙”字样。"},{"i":16,"n":"第十六条","txt":"合伙人可以用货币、实物、知识产权、土地使用权或者其他财产权利出资，也可以用劳务出资。"},{"i":17,"n":"第十七条","txt":"合伙人应当按照合伙协议约定的出资方式、数额和缴付期限，履行出资义务。"},{"i":18,"n":"第十八条","txt":"合伙协议应当载明下列事项："},{"i":19,"n":"第十九条","txt":"合伙协议经全体合伙人签名、盖章后生效。合伙人按照合伙协议享有权利，履行义务。"},{"i":20,"n":"第二十条","txt":"合伙人的出资、以合伙企业名义取得的收益和依法取得的其他财产，均为合伙企业的财产。"},{"i":21,"n":"第二十一条","txt":"合伙人在合伙企业清算前，不得请求分割合伙企业的财产；但是，本法另有规定的除外。"},{"i":22,"n":"第二十二条","txt":"除合伙协议另有约定外，合伙人向合伙人以外的人转让其在合伙企业中的全部或者部分财产份额时，须经其他合伙人一致同意。"},{"i":23,"n":"第二十三条","txt":"合伙人向合伙人以外的人转让其在合伙企业中的财产份额的，在同等条件下，其他合伙人有优先购买权；但是，合伙协议另有约定的除外。"},{"i":24,"n":"第二十四条","txt":"合伙人以外的人依法受让合伙人在合伙企业中的财产份额的，经修改合伙协议即成为合伙企业的合伙人，依照本法和修改后的合伙协议享有权利，履行义务。"},{"i":25,"n":"第二十五条","txt":"合伙人以其在合伙企业中的财产份额出质的，须经其他合伙人一致同意；未经其他合伙人一致同意，其行为无效，由此给善意第三人造成损失的，由行为人依法承担赔偿责任。"},{"i":26,"n":"第二十六条","txt":"合伙人对执行合伙事务享有同等的权利。"},{"i":27,"n":"第二十七条","txt":"依照本法第二十六条第二款规定委托一个或者数个合伙人执行合伙事务的，其他合伙人不再执行合伙事务。"},{"i":28,"n":"第二十八条","txt":"由一个或者数个合伙人执行合伙事务的，执行事务合伙人应当定期向其他合伙人报告事务执行情况以及合伙企业的经营和财务状况，其执行合伙事务所产生的收益归合伙企业，所产生的费用和亏损由合伙企业承担。"},{"i":29,"n":"第二十九条","txt":"合伙人分别执行合伙事务的，执行事务合伙人可以对其他合伙人执行的事务提出异议。提出异议时，应当暂停该项事务的执行。如果发生争议，依照本法第三十条规定作出决定。"},{"i":30,"n":"第三十条","txt":"合伙人对合伙企业有关事项作出决议，按照合伙协议约定的表决办法办理。合伙协议未约定或者约定不明确的，实行合伙人一人一票并经全体合伙人过半数通过的表决办法。"},{"i":31,"n":"第三十一条","txt":"除合伙协议另有约定外，合伙企业的下列事项应当经全体合伙人一致同意："},{"i":32,"n":"第三十二条","txt":"合伙人不得自营或者同他人合作经营与本合伙企业相竞争的业务。"},{"i":33,"n":"第三十三条","txt":"合伙企业的利润分配、亏损分担，按照合伙协议的约定办理；合伙协议未约定或者约定不明确的，由合伙人协商决定；协商不成的，由合伙人按照实缴出资比例分配、分担；无法确定出资比例的，由合伙人平均分配、分担。"},{"i":34,"n":"第三十四条","txt":"合伙人按照合伙协议的约定或者经全体合伙人决定，可以增加或者减少对合伙企业的出资。"},{"i":35,"n":"第三十五条","txt":"被聘任的合伙企业的经营管理人员应当在合伙企业授权范围内履行职务。"},{"i":36,"n":"第三十六条","txt":"合伙企业应当依照法律、行政法规的规定建立企业财务、会计制度。"},{"i":37,"n":"第三十七条","txt":"合伙企业对合伙人执行合伙事务以及对外代表合伙企业权利的限制，不得对抗善意第三人。"},{"i":38,"n":"第三十八条","txt":"合伙企业对其债务，应先以其全部财产进行清偿。"},{"i":39,"n":"第三十九条","txt":"合伙企业不能清偿到期债务的，合伙人承担无限连带责任。"},{"i":40,"n":"第四十条","txt":"合伙人由于承担无限连带责任，清偿数额超过本法第三十三条第一款规定的其亏损分担比例的，有权向其他合伙人追偿。"},{"i":41,"n":"第四十一条","txt":"合伙人发生与合伙企业无关的债务，相关债权人不得以其债权抵销其对合伙企业的债务；也不得代位行使合伙人在合伙企业中的权利。"},{"i":42,"n":"第四十二条","txt":"合伙人的自有财产不足清偿其与合伙企业无关的债务的，该合伙人可以以其从合伙企业中分取的收益用于清偿；债权人也可以依法请求人民法院强制执行该合伙人在合伙企业中的财产份额用于清偿。"},{"i":43,"n":"第四十三条","txt":"新合伙人入伙，除合伙协议另有约定外，应当经全体合伙人一致同意，并依法订立书面入伙协议。"},{"i":44,"n":"第四十四条","txt":"入伙的新合伙人与原合伙人享有同等权利，承担同等责任。入伙协议另有约定的，从其约定。"},{"i":45,"n":"第四十五条","txt":"合伙协议约定合伙期限的，在合伙企业存续期间，有下列情形之一的，合伙人可以退伙："},{"i":46,"n":"第四十六条","txt":"合伙协议未约定合伙期限的，合伙人在不给合伙企业事务执行造成不利影响的情况下，可以退伙，但应当提前三十日通知其他合伙人。"},{"i":47,"n":"第四十七条","txt":"合伙人违反本法第四十五条、第四十六条的规定退伙的，应当赔偿由此给合伙企业造成的损失。"},{"i":48,"n":"第四十八条","txt":"合伙人有下列情形之一的，当然退伙："},{"i":49,"n":"第四十九条","txt":"合伙人有下列情形之一的，经其他合伙人一致同意，可以决议将其除名："},{"i":50,"n":"第五十条","txt":"合伙人死亡或者被依法宣告死亡的，对该合伙人在合伙企业中的财产份额享有合法继承权的继承人，按照合伙协议的约定或者经全体合伙人一致同意，从继承开始之日起，取得该合伙企业的合伙人资格。"},{"i":51,"n":"第五十一条","txt":"合伙人退伙，其他合伙人应当与该退伙人按照退伙时的合伙企业财产状况进行结算，退还退伙人的财产份额。退伙人对给合伙企业造成的损失负有赔偿责任的，相应扣减其应当赔偿的数额。"},{"i":52,"n":"第五十二条","txt":"退伙人在合伙企业中财产份额的退还办法，由合伙协议约定或者由全体合伙人决定，可以退还货币，也可以退还实物。"},{"i":53,"n":"第五十三条","txt":"退伙人对基于其退伙前的原因发生的合伙企业债务，承担无限连带责任。"},{"i":54,"n":"第五十四条","txt":"合伙人退伙时，合伙企业财产少于合伙企业债务的，退伙人应当依照本法第三十三条第一款的规定分担亏损。"},{"i":55,"n":"第五十五条","txt":"以专业知识和专门技能为客户提供有偿服务的专业服务机构，可以设立为特殊的普通合伙企业。"},{"i":56,"n":"第五十六条","txt":"特殊的普通合伙企业名称中应当标明“特殊普通合伙”字样。"},{"i":57,"n":"第五十七条","txt":"一个合伙人或者数个合伙人在执业活动中因故意或者重大过失造成合伙企业债务的，应当承担无限责任或者无限连带责任，其他合伙人以其在合伙企业中的财产份额为限承担责任。"},{"i":58,"n":"第五十八条","txt":"合伙人执业活动中因故意或者重大过失造成的合伙企业债务，以合伙企业财产对外承担责任后，该合伙人应当按照合伙协议的约定对给合伙企业造成的损失承担赔偿责任。"},{"i":59,"n":"第五十九条","txt":"特殊的普通合伙企业应当建立执业风险基金、办理职业保险。"},{"i":60,"n":"第六十条","txt":"有限合伙企业及其合伙人适用本章规定；本章未作规定的，适用本法第二章第一节至第五节关于普通合伙企业及其合伙人的规定。"},{"i":61,"n":"第六十一条","txt":"有限合伙企业由二个以上五十个以下合伙人设立；但是，法律另有规定的除外。"},{"i":62,"n":"第六十二条","txt":"有限合伙企业名称中应当标明“有限合伙”字样。"},{"i":63,"n":"第六十三条","txt":"合伙协议除符合本法第十八条的规定外，还应当载明下列事项："},{"i":64,"n":"第六十四条","txt":"有限合伙人可以用货币、实物、知识产权、土地使用权或者其他财产权利作价出资。"},{"i":65,"n":"第六十五条","txt":"有限合伙人应当按照合伙协议的约定按期足额缴纳出资；未按期足额缴纳的，应当承担补缴义务，并对其他合伙人承担违约责任。"},{"i":66,"n":"第六十六条","txt":"有限合伙企业登记事项中应当载明有限合伙人的姓名或者名称及认缴的出资数额。"},{"i":67,"n":"第六十七条","txt":"有限合伙企业由普通合伙人执行合伙事务。执行事务合伙人可以要求在合伙协议中确定执行事务的报酬及报酬提取方式。"},{"i":68,"n":"第六十八条","txt":"有限合伙人不执行合伙事务，不得对外代表有限合伙企业。"},{"i":69,"n":"第六十九条","txt":"有限合伙企业不得将全部利润分配给部分合伙人；但是，合伙协议另有约定的除外。"},{"i":70,"n":"第七十条","txt":"有限合伙人可以同本有限合伙企业进行交易；但是，合伙协议另有约定的除外。"},{"i":71,"n":"第七十一条","txt":"有限合伙人可以自营或者同他人合作经营与本有限合伙企业相竞争的业务；但是，合伙协议另有约定的除外。"},{"i":72,"n":"第七十二条","txt":"有限合伙人可以将其在有限合伙企业中的财产份额出质；但是，合伙协议另有约定的除外。"},{"i":73,"n":"第七十三条","txt":"有限合伙人可以按照合伙协议的约定向合伙人以外的人转让其在有限合伙企业中的财产份额，但应当提前三十日通知其他合伙人。"},{"i":74,"n":"第七十四条","txt":"有限合伙人的自有财产不足清偿其与合伙企业无关的债务的，该合伙人可以以其从有限合伙企业中分取的收益用于清偿；债权人也可以依法请求人民法院强制执行该合伙人在有限合伙企业中的财产份额用于清偿。"},{"i":75,"n":"第七十五条","txt":"有限合伙企业仅剩有限合伙人的，应当解散；有限合伙企业仅剩普通合伙人的，转为普通合伙企业。"},{"i":76,"n":"第七十六条","txt":"第三人有理由相信有限合伙人为普通合伙人并与其交易的，该有限合伙人对该笔交易承担与普通合伙人同样的责任。"},{"i":77,"n":"第七十七条","txt":"新入伙的有限合伙人对入伙前有限合伙企业的债务，以其认缴的出资额为限承担责任。"},{"i":78,"n":"第七十八条","txt":"有限合伙人有本法第四十八条第一款第一项、第三项至第五项所列情形之一的，当然退伙。"},{"i":79,"n":"第七十九条","txt":"作为有限合伙人的自然人在有限合伙企业存续期间丧失民事行为能力的，其他合伙人不得因此要求其退伙。"},{"i":80,"n":"第八十条","txt":"作为有限合伙人的自然人死亡、被依法宣告死亡或者作为有限合伙人的法人及其他组织终止时，其继承人或者权利承受人可以依法取得该有限合伙人在有限合伙企业中的资格。"},{"i":81,"n":"第八十一条","txt":"有限合伙人退伙后，对基于其退伙前的原因发生的有限合伙企业债务，以其退伙时从有限合伙企业中取回的财产承担责任。"},{"i":82,"n":"第八十二条","txt":"除合伙协议另有约定外，普通合伙人转变为有限合伙人，或者有限合伙人转变为普通合伙人，应当经全体合伙人一致同意。"},{"i":83,"n":"第八十三条","txt":"有限合伙人转变为普通合伙人的，对其作为有限合伙人期间有限合伙企业发生的债务承担无限连带责任。"},{"i":84,"n":"第八十四条","txt":"普通合伙人转变为有限合伙人的，对其作为普通合伙人期间合伙企业发生的债务承担无限连带责任。"},{"i":85,"n":"第八十五条","txt":"合伙企业有下列情形之一的，应当解散："},{"i":86,"n":"第八十六条","txt":"合伙企业解散，应当由清算人进行清算。"},{"i":87,"n":"第八十七条","txt":"清算人在清算期间执行下列事务："},{"i":88,"n":"第八十八条","txt":"清算人自被确定之日起十日内将合伙企业解散事项通知债权人，并于六十日内在报纸上公告。债权人应当自接到通知书之日起三十日内，未接到通知书的自公告之日起四十五日内，向清算人申报债权。"},{"i":89,"n":"第八十九条","txt":"合伙企业财产在支付清算费用和职工工资、社会保险费用、法定补偿金以及缴纳所欠税款、清偿债务后的剩余财产，依照本法第三十三条第一款的规定进行分配。"},{"i":90,"n":"第九十条","txt":"清算结束，清算人应当编制清算报告，经全体合伙人签名、盖章后，在十五日内向企业登记机关报送清算报告，申请办理合伙企业注销登记。"},{"i":91,"n":"第九十一条","txt":"合伙企业注销后，原普通合伙人对合伙企业存续期间的债务仍应承担无限连带责任。"},{"i":92,"n":"第九十二条","txt":"合伙企业不能清偿到期债务的，债权人可以依法向人民法院提出破产清算申请，也可以要求普通合伙人清偿。"},{"i":93,"n":"第九十三条","txt":"违反本法规定，提交虚假文件或者采取其他欺骗手段，取得合伙企业登记的，由企业登记机关责令改正，处以五千元以上五万元以下的罚款；情节严重的，撤销企业登记，并处以五万元以上二十万元以下的罚款。"},{"i":94,"n":"第九十四条","txt":"违反本法规定，合伙企业未在其名称中标明“普通合伙”、“特殊普通合伙”或者“有限合伙”字样的，由企业登记机关责令限期改正，处以二千元以上一万元以下的罚款。"},{"i":95,"n":"第九十五条","txt":"违反本法规定，未领取营业执照，而以合伙企业或者合伙企业分支机构名义从事合伙业务的，由企业登记机关责令停止，处以五千元以上五万元以下的罚款。"},{"i":96,"n":"第九十六条","txt":"合伙人执行合伙事务，或者合伙企业从业人员利用职务上的便利，将应当归合伙企业的利益据为己有的，或者采取其他手段侵占合伙企业财产的，应当将该利益和财产退还合伙企业；给合伙企业或者其他合伙人造成损失的，依法承担赔偿责任。"},{"i":97,"n":"第九十七条","txt":"合伙人对本法规定或者合伙协议约定必须经全体合伙人一致同意始得执行的事务擅自处理，给合伙企业或者其他合伙人造成损失的，依法承担赔偿责任。"},{"i":98,"n":"第九十八条","txt":"不具有事务执行权的合伙人擅自执行合伙事务，给合伙企业或者其他合伙人造成损失的，依法承担赔偿责任。"},{"i":99,"n":"第九十九条","txt":"合伙人违反本法规定或者合伙协议的约定，从事与本合伙企业相竞争的业务或者与本合伙企业进行交易的，该收益归合伙企业所有；给合伙企业或者其他合伙人造成损失的，依法承担赔偿责任。"},{"i":100,"n":"第一百条","txt":"清算人未依照本法规定向企业登记机关报送清算报告，或者报送清算报告隐瞒重要事实，或者有重大遗漏的，由企业登记机关责令改正。由此产生的费用和损失，由清算人承担和赔偿。"},{"i":101,"n":"第一百零一条","txt":"清算人执行清算事务，牟取非法收入或者侵占合伙企业财产的，应当将该收入和侵占的财产退还合伙企业；给合伙企业或者其他合伙人造成损失的，依法承担赔偿责任。"},{"i":102,"n":"第一百零二条","txt":"清算人违反本法规定，隐匿、转移合伙企业财产，对资产负债表或者财产清单作虚假记载，或者在未清偿债务前分配财产，损害债权人利益的，依法承担赔偿责任。"},{"i":103,"n":"第一百零三条","txt":"合伙人违反合伙协议的，应当依法承担违约责任。"},{"i":104,"n":"第一百零四条","txt":"有关行政管理机关的工作人员违反本法规定，滥用职权、徇私舞弊、收受贿赂、侵害合伙企业合法权益的，依法给予行政处分。"},{"i":105,"n":"第一百零五条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":106,"n":"第一百零六条","txt":"违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金，其财产不足以同时支付的，先承担民事赔偿责任。"},{"i":107,"n":"第一百零七条","txt":"非企业专业服务机构依据有关法律采取合伙制的，其合伙人承担责任的形式可以适用本法关于特殊的普通合伙企业合伙人承担责任的规定。"},{"i":108,"n":"第一百零八条","txt":"外国企业或者个人在中国境内设立合伙企业的管理办法由国务院规定。"},{"i":109,"n":"第一百零九条","txt":"本法自2007年6月1日起施行。"}],"shangyeyinhangfa":[{"i":1,"n":"第一条","txt":"为了保护商业银行、存款人和其他客户的合法权益，规范商业银行的行为，提高信贷资产质量，加强监督管理，保障商业银行的稳健运行，维护金融秩序，促进社会主义市场经济的发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称的商业银行是指依照本法和《中华人民共和国公司法》设立的吸收公众存款、发放贷款、办理结算等业务的企业法人。"},{"i":3,"n":"第三条","txt":"商业银行可以经营下列部分或者全部业务："},{"i":4,"n":"第四条","txt":"商业银行以安全性、流动性、效益性为经营原则，实行自主经营，自担风险，自负盈亏，自我约束。"},{"i":5,"n":"第五条","txt":"商业银行与客户的业务往来，应当遵循平等、自愿、公平和诚实信用的原则。"},{"i":6,"n":"第六条","txt":"商业银行应当保障存款人的合法权益不受任何单位和个人的侵犯。"},{"i":7,"n":"第七条","txt":"商业银行开展信贷业务，应当严格审查借款人的资信，实行担保，保障按期收回贷款。"},{"i":8,"n":"第八条","txt":"商业银行开展业务，应当遵守法律、行政法规的有关规定，不得损害国家利益、社会公共利益。"},{"i":9,"n":"第九条","txt":"商业银行开展业务，应当遵守公平竞争的原则，不得从事不正当竞争。"},{"i":10,"n":"第十条","txt":"商业银行依法接受国务院银行业监督管理机构的监督管理，但法律规定其有关业务接受其他监督管理部门或者机构监督管理的，依照其规定。"},{"i":11,"n":"第十一条","txt":"设立商业银行，应当经国务院银行业监督管理机构审查批准。"},{"i":12,"n":"第十二条","txt":"设立商业银行，应当具备下列条件："},{"i":13,"n":"第十三条","txt":"设立全国性商业银行的注册资本最低限额为十亿元人民币。设立城市商业银行的注册资本最低限额为一亿元人民币，设立农村商业银行的注册资本最低限额为五千万元人民币。注册资本应当是实缴资本。"},{"i":14,"n":"第十四条","txt":"设立商业银行，申请人应当向国务院银行业监督管理机构提交下列文件、资料："},{"i":15,"n":"第十五条","txt":"设立商业银行的申请经审查符合本法第十四条规定的，申请人应当填写正式申请表，并提交下列文件、资料："},{"i":16,"n":"第十六条","txt":"经批准设立的商业银行，由国务院银行业监督管理机构颁发经营许可证，并凭该许可证向工商行政管理部门办理登记，领取营业执照。"},{"i":17,"n":"第十七条","txt":"商业银行的组织形式、组织机构适用《中华人民共和国公司法》的规定。"},{"i":18,"n":"第十八条","txt":"国有独资商业银行设立监事会。监事会的产生办法由国务院规定。"},{"i":19,"n":"第十九条","txt":"商业银行根据业务需要可以在中华人民共和国境内外设立分支机构。设立分支机构必须经国务院银行业监督管理机构审查批准。在中华人民共和国境内的分支机构，不按行政区划设立。"},{"i":20,"n":"第二十条","txt":"设立商业银行分支机构，申请人应当向国务院银行业监督管理机构提交下列文件、资料："},{"i":21,"n":"第二十一条","txt":"经批准设立的商业银行分支机构，由国务院银行业监督管理机构颁发经营许可证，并凭该许可证向工商行政管理部门办理登记，领取营业执照。"},{"i":22,"n":"第二十二条","txt":"商业银行对其分支机构实行全行统一核算，统一调度资金，分级管理的财务制度。"},{"i":23,"n":"第二十三条","txt":"经批准设立的商业银行及其分支机构，由国务院银行业监督管理机构予以公告。"},{"i":24,"n":"第二十四条","txt":"商业银行有下列变更事项之一的，应当经国务院银行业监督管理机构批准："},{"i":25,"n":"第二十五条","txt":"商业银行的分立、合并，适用《中华人民共和国公司法》的规定。"},{"i":26,"n":"第二十六条","txt":"商业银行应当依照法律、行政法规的规定使用经营许可证。禁止伪造、变造、转让、出租、出借经营许可证。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，不得担任商业银行的董事、高级管理人员："},{"i":28,"n":"第二十八条","txt":"任何单位和个人购买商业银行股份总额百分之五以上的，应当事先经国务院银行业监督管理机构批准。"},{"i":29,"n":"第二十九条","txt":"商业银行办理个人储蓄存款业务，应当遵循存款自愿、取款自由、存款有息、为存款人保密的原则。"},{"i":30,"n":"第三十条","txt":"对单位存款，商业银行有权拒绝任何单位或者个人查询，但法律、行政法规另有规定的除外；有权拒绝任何单位或者个人冻结、扣划，但法律另有规定的除外。"},{"i":31,"n":"第三十一条","txt":"商业银行应当按照中国人民银行规定的存款利率的上下限，确定存款利率，并予以公告。"},{"i":32,"n":"第三十二条","txt":"商业银行应当按照中国人民银行的规定，向中国人民银行交存存款准备金，留足备付金。"},{"i":33,"n":"第三十三条","txt":"商业银行应当保证存款本金和利息的支付，不得拖延、拒绝支付存款本金和利息。"},{"i":34,"n":"第三十四条","txt":"商业银行根据国民经济和社会发展的需要，在国家产业政策指导下开展贷款业务。"},{"i":35,"n":"第三十五条","txt":"商业银行贷款，应当对借款人的借款用途、偿还能力、还款方式等情况进行严格审查。"},{"i":36,"n":"第三十六条","txt":"商业银行贷款，借款人应当提供担保。商业银行应当对保证人的偿还能力，抵押物、质物的权属和价值以及实现抵押权、质权的可行性进行严格审查。"},{"i":37,"n":"第三十七条","txt":"商业银行贷款，应当与借款人订立书面合同。合同应当约定贷款种类、借款用途、金额、利率、还款期限、还款方式、违约责任和双方认为需要约定的其他事项。"},{"i":38,"n":"第三十八条","txt":"商业银行应当按照中国人民银行规定的贷款利率的上下限，确定贷款利率。"},{"i":39,"n":"第三十九条","txt":"商业银行贷款，应当遵守下列资产负债比例管理的规定："},{"i":40,"n":"第四十条","txt":"商业银行不得向关系人发放信用贷款；向关系人发放担保贷款的条件不得优于其他借款人同类贷款的条件。"},{"i":41,"n":"第四十一条","txt":"任何单位和个人不得强令商业银行发放贷款或者提供担保。商业银行有权拒绝任何单位和个人强令要求其发放贷款或者提供担保。"},{"i":42,"n":"第四十二条","txt":"借款人应当按期归还贷款的本金和利息。"},{"i":43,"n":"第四十三条","txt":"商业银行在中华人民共和国境内不得从事信托投资和证券经营业务，不得向非自用不动产投资或者向非银行金融机构和企业投资，但国家另有规定的除外。"},{"i":44,"n":"第四十四条","txt":"商业银行办理票据承兑、汇兑、委托收款等结算业务，应当按照规定的期限兑现，收付入账，不得压单、压票或者违反规定退票。有关兑现、收付入账期限的规定应当公布。"},{"i":45,"n":"第四十五条","txt":"商业银行发行金融债券或者到境外借款，应当依照法律、行政法规的规定报经批准。"},{"i":46,"n":"第四十六条","txt":"同业拆借，应当遵守中国人民银行的规定。禁止利用拆入资金发放固定资产贷款或者用于投资。"},{"i":47,"n":"第四十七条","txt":"商业银行不得违反规定提高或者降低利率以及采用其他不正当手段，吸收存款，发放贷款。"},{"i":48,"n":"第四十八条","txt":"企业事业单位可以自主选择一家商业银行的营业场所开立一个办理日常转账结算和现金收付的基本账户，不得开立两个以上基本账户。"},{"i":49,"n":"第四十九条","txt":"商业银行的营业时间应当方便客户，并予以公告。商业银行应当在公告的营业时间内营业，不得擅自停止营业或者缩短营业时间。"},{"i":50,"n":"第五十条","txt":"商业银行办理业务，提供服务，按照规定收取手续费。收费项目和标准由国务院银行业监督管理机构、中国人民银行根据职责分工，分别会同国务院价格主管部门制定。"},{"i":51,"n":"第五十一条","txt":"商业银行应当按照国家有关规定保存财务会计报表、业务合同以及其他资料。"},{"i":52,"n":"第五十二条","txt":"商业银行的工作人员应当遵守法律、行政法规和其他各项业务管理的规定，不得有下列行为："},{"i":53,"n":"第五十三条","txt":"商业银行的工作人员不得泄露其在任职期间知悉的国家秘密、商业秘密。"},{"i":54,"n":"第五十四条","txt":"商业银行应当依照法律和国家统一的会计制度以及国务院银行业监督管理机构的有关规定，建立、健全本行的财务、会计制度。"},{"i":55,"n":"第五十五条","txt":"商业银行应当按照国家有关规定，真实记录并全面反映其业务活动和财务状况，编制年度财务会计报告，及时向国务院银行业监督管理机构、中国人民银行和国务院财政部门报送。商业银行不得在法定的会计账册外另立会计账册。"},{"i":56,"n":"第五十六条","txt":"商业银行应当于每一会计年度终了三个月内，按照国务院银行业监督管理机构的规定，公布其上一年度的经营业绩和审计报告。"},{"i":57,"n":"第五十七条","txt":"商业银行应当按照国家有关规定，提取呆账准备金，冲销呆账。"},{"i":58,"n":"第五十八条","txt":"商业银行的会计年度自公历l月1日起至12月31日止。"},{"i":59,"n":"第五十九条","txt":"商业银行应当按照有关规定，制定本行的业务规则，建立、健全本行的风险管理和内部控制制度。"},{"i":60,"n":"第六十条","txt":"商业银行应当建立、健全本行对存款、贷款、结算、呆账等各项情况的稽核、检查制度。"},{"i":61,"n":"第六十一条","txt":"商业银行应当按照规定向国务院银行业监督管理机构、中国人民银行报送资产负债表、利润表以及其他财务会计、统计报表和资料。"},{"i":62,"n":"第六十二条","txt":"国务院银行业监督管理机构有权依照本法第三章、第四章、第五章的规定，随时对商业银行的存款、贷款、结算、呆账等情况进行检查监督。检查监督时，检查监督人员应当出示合法的证件。商业银行应当按照国务院银行业监督管理机构的要求，提供财务会计资料、业务合同和有关经营管理方面的其他信息。"},{"i":63,"n":"第六十三条","txt":"商业银行应当依法接受审计机关的审计监督。"},{"i":64,"n":"第六十四条","txt":"商业银行已经或者可能发生信用危机，严重影响存款人的利益时，国务院银行业监督管理机构可以对该银行实行接管。"},{"i":65,"n":"第六十五条","txt":"接管由国务院银行业监督管理机构决定，并组织实施。国务院银行业监督管理机构的接管决定应当载明下列内容："},{"i":66,"n":"第六十六条","txt":"接管自接管决定实施之日起开始。"},{"i":67,"n":"第六十七条","txt":"接管期限届满，国务院银行业监督管理机构可以决定延期，但接管期限最长不得超过二年。"},{"i":68,"n":"第六十八条","txt":"有下列情形之一的，接管终止："},{"i":69,"n":"第六十九条","txt":"商业银行因分立、合并或者出现公司章程规定的解散事由需要解散的，应当向国务院银行业监督管理机构提出申请，并附解散的理由和支付存款的本金和利息等债务清偿计划。经国务院银行业监督管理机构批准后解散。"},{"i":70,"n":"第七十条","txt":"商业银行因吊销经营许可证被撤销的，国务院银行业监督管理机构应当依法及时组织成立清算组，进行清算，按照清偿计划及时偿还存款本金和利息等债务。"},{"i":71,"n":"第七十一条","txt":"商业银行不能支付到期债务，经国务院银行业监督管理机构同意，由人民法院依法宣告其破产。商业银行被宣告破产的，由人民法院组织国务院银行业监督管理机构等有关部门和有关人员成立清算组，进行清算。"},{"i":72,"n":"第七十二条","txt":"商业银行因解散、被撤销和被宣告破产而终止。"},{"i":73,"n":"第七十三条","txt":"商业银行有下列情形之一，对存款人或者其他客户造成财产损害的，应当承担支付迟延履行的利息以及其他民事责任："},{"i":74,"n":"第七十四条","txt":"商业银行有下列情形之一，由国务院银行业监督管理机构责令改正，有违法所得的，没收违法所得，违法所得五十万元以上的，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足五十万元的，处五十万元以上二百万元以下罚款；情节特别严重或者逾期不改正的，可以责令停业整顿或者吊销其经营许可证；构成犯罪的，依法追究刑事责任："},{"i":75,"n":"第七十五条","txt":"商业银行有下列情形之一，由国务院银行业监督管理机构责令改正，并处二十万元以上五十万元以下罚款；情节特别严重或者逾期不改正的，可以责令停业整顿或者吊销其经营许可证；构成犯罪的，依法追究刑事责任："},{"i":76,"n":"第七十六条","txt":"商业银行有下列情形之一，由中国人民银行责令改正，有违法所得的，没收违法所得，违法所得五十万元以上的，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足五十万元的，处五十万元以上二百万元以下罚款；情节特别严重或者逾期不改正的，中国人民银行可以建议国务院银行业监督管理机构责令停业整顿或者吊销其经营许可证；构成犯罪的，依法追究刑事责任："},{"i":77,"n":"第七十七条","txt":"商业银行有下列情形之一，由中国人民银行责令改正，并处二十万元以上五十万元以下罚款；情节特别严重或者逾期不改正的，中国人民银行可以建议国务院银行业监督管理机构责令停业整顿或者吊销其经营许可证；构成犯罪的，依法追究刑事责任："},{"i":78,"n":"第七十八条","txt":"商业银行有本法第七十三条至第七十七条规定情形的，对直接负责的董事、高级管理人员和其他直接责任人员，应当给予纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":79,"n":"第七十九条","txt":"有下列情形之一，由国务院银行业监督管理机构责令改正，有违法所得的，没收违法所得，违法所得五万元以上的，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足五万元的，处五万元以上五十万元以下罚款："},{"i":80,"n":"第八十条","txt":"商业银行不按照规定向国务院银行业监督管理机构报送有关文件、资料的，由国务院银行业监督管理机构责令改正，逾期不改正的，处十万元以上三十万元以下罚款。"},{"i":81,"n":"第八十一条","txt":"未经国务院银行业监督管理机构批准，擅自设立商业银行，或者非法吸收公众存款、变相吸收公众存款，构成犯罪的，依法追究刑事责任；并由国务院银行业监督管理机构予以取缔。"},{"i":82,"n":"第八十二条","txt":"借款人采取欺诈手段骗取贷款，构成犯罪的，依法追究刑事责任。"},{"i":83,"n":"第八十三条","txt":"有本法第八十一条、第八十二条规定的行为，尚不构成犯罪的，由国务院银行业监督管理机构没收违法所得，违法所得五十万元以上的，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足五十万元的，处五十万元以上二百万元以下罚款。"},{"i":84,"n":"第八十四条","txt":"商业银行工作人员利用职务上的便利，索取、收受贿赂或者违反国家规定收受各种名义的回扣、手续费，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，应当给予纪律处分。"},{"i":85,"n":"第八十五条","txt":"商业银行工作人员利用职务上的便利，贪污、挪用、侵占本行或者客户资金，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，应当给予纪律处分。"},{"i":86,"n":"第八十六条","txt":"商业银行工作人员违反本法规定玩忽职守造成损失的，应当给予纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":87,"n":"第八十七条","txt":"商业银行工作人员泄露在任职期间知悉的国家秘密、商业秘密的，应当给予纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":88,"n":"第八十八条","txt":"单位或者个人强令商业银行发放贷款或者提供担保的，应当对直接负责的主管人员和其他直接责任人员或者个人给予纪律处分；造成损失的，应当承担全部或者部分赔偿责任。"},{"i":89,"n":"第八十九条","txt":"商业银行违反本法规定的，国务院银行业监督管理机构可以区别不同情形，取消其直接负责的董事、高级管理人员一定期限直至终身的任职资格，禁止直接负责的董事、高级管理人员和其他直接责任人员一定期限直至终身从事银行业工作。"},{"i":90,"n":"第九十条","txt":"商业银行及其工作人员对国务院银行业监督管理机构、中国人民银行的处罚决定不服的，可以依照《中华人民共和国行政诉讼法》的规定向人民法院提起诉讼。"},{"i":91,"n":"第九十一条","txt":"本法施行前，按照国务院的规定经批准设立的商业银行不再办理审批手续。"},{"i":92,"n":"第九十二条","txt":"外资商业银行、中外合资商业银行、外国商业银行分行适用本法规定，法律、行政法规另有规定的，依照其规定。"},{"i":93,"n":"第九十三条","txt":"城市信用合作社、农村信用合作社办理存款、贷款和结算等业务，适用本法有关规定。"},{"i":94,"n":"第九十四条","txt":"邮政企业办理商业银行的有关业务，适用本法有关规定。"},{"i":95,"n":"第九十五条","txt":"本法自2015年10月1日起施行。"}],"shangbiaofa-2":[{"i":1,"n":"第一条","txt":"为了保护注册商标专用权，加强商标管理，规范商标的注册与使用，促使生产经营者保证商品和服务质量，维护商标信誉，保障消费者和生产经营者的利益，促进社会主义市场经济健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称商标，是指用以识别和区分商品或者服务来源的标志，包括商品商标和服务商标。本法有关商品商标的规定，适用于服务商标。"},{"i":3,"n":"第三条","txt":"商标工作应当贯彻党和国家知识产权战略部署，提升商标保护、运用、管理和服务水平。"},{"i":4,"n":"第四条","txt":"国务院商标管理部门负责全国商标注册、管理工作。县级以上地方人民政府管理商标工作的部门负责本行政区域的商标管理工作。"},{"i":5,"n":"第五条","txt":"经国务院商标管理部门核准注册的商标为注册商标，商标注册人有权标明“注册商标”或者注册标记，享有注册商标专用权，受法律保护。"},{"i":6,"n":"第六条","txt":"本法所称集体商标，是指以行业协会等社会团体或者其他组织名义注册，供该组织成员在商事活动中使用，以表明使用者在该组织中的成员资格的标志。"},{"i":7,"n":"第七条","txt":"两个以上的自然人、法人或者非法人组织可以共同向国务院商标管理部门申请注册同一商标，共同享有和行使该注册商标专用权。"},{"i":8,"n":"第八条","txt":"法律、行政法规规定必须使用注册商标的商品，应当申请商标注册，未经核准注册的，不得在市场销售。"},{"i":9,"n":"第九条","txt":"申请注册和使用商标，应当遵循诚信原则，不得滥用权利损害国家利益、社会公共利益或者他人合法权益。"},{"i":10,"n":"第十条","txt":"申请商标注册或者办理其他商标事宜，可以自行办理，也可以委托依法设立的商标代理机构办理。"},{"i":11,"n":"第十一条","txt":"外国人、外国企业或者外国其他组织在中国申请商标注册的，应当按其所属国和中华人民共和国签订的协议或者共同参加的国际条约办理，或者按对等原则办理。"},{"i":12,"n":"第十二条","txt":"商标国际注册遵循中华人民共和国缔结或者参加的有关国际条约确立的制度，具体办法由国务院规定。"},{"i":13,"n":"第十三条","txt":"国务院商标管理部门加强信息化、智能化商标公共服务体系建设，提升商标业务办理的便利化程度，完整、准确、及时发布商标信息，提高商标信息服务和管理水平。"},{"i":14,"n":"第十四条","txt":"任何能够将自然人、法人或者非法人组织的商品与他人的商品区别开的标志，包括文字、图形、字母、数字、三维标志、颜色组合、声音、动态标志等，以及上述要素的组合，均可以作为商标申请注册。"},{"i":15,"n":"第十五条","txt":"下列标志不得作为商标注册和使用："},{"i":16,"n":"第十六条","txt":"县级以上行政区划名称或者公众知晓的外国地名，不得作为商标注册和使用。但是，地名具有其他含义或者作为集体商标、证明商标组成部分的除外；已经注册的使用地名的商标继续有效。"},{"i":17,"n":"第十七条","txt":"申请注册的商标，应当有显著特征，便于识别。下列标志不得作为商标注册："},{"i":18,"n":"第十八条","txt":"以三维标志、颜色组合、声音、动态标志等申请注册商标的，仅由商品自身的性质产生的、为获得技术效果而需有的或者使商品具有实质性价值的形状、颜色组合、声音、动态效果等，不得注册为商标。"},{"i":19,"n":"第十九条","txt":"不以使用为目的，且明显超出正常生产经营需要申请商标注册的，不予注册。"},{"i":20,"n":"第二十条","txt":"申请注册的商标，不得同他人在同一种商品或者类似商品上已经注册或者在先申请的商标相同或者近似。"},{"i":21,"n":"第二十一条","txt":"就相同或者类似商品申请注册的商标是复制、摹仿或者翻译他人未在中国注册的驰名商标，容易导致混淆的，不予注册并禁止使用。"},{"i":22,"n":"第二十二条","txt":"未经授权，代理人或者代表人以自己的名义将被代理人或者被代表人的商标进行注册，被代理人或者被代表人提出异议的，不予注册并禁止使用。"},{"i":23,"n":"第二十三条","txt":"商标中有商品的地理标志，而该商品并非来源于该标志所标示的地区，误导公众的，不予注册并禁止使用；但是，已经善意取得注册的继续有效。"},{"i":24,"n":"第二十四条","txt":"申请商标注册不得损害他人现有的在先合法权益，也不得故意抢先注册他人已经使用并有一定影响的商标。"},{"i":25,"n":"第二十五条","txt":"商标代理机构除对其代理服务申请商标注册外，不得申请注册其他商标。"},{"i":26,"n":"第二十六条","txt":"商标注册申请人应当按规定的商品分类表填报使用商标的商品类别和商品名称，提出注册申请。"},{"i":27,"n":"第二十七条","txt":"注册商标需要在核定使用范围之外的商品上取得注册商标专用权的，应当另行提出注册申请。"},{"i":28,"n":"第二十八条","txt":"注册商标需要改变其标志的，应当重新提出注册申请。"},{"i":29,"n":"第二十九条","txt":"商标注册申请人自其商标在外国第一次提出商标注册申请之日起六个月内，又在中国就相同商品以同一商标提出商标注册申请的，依照该外国同中国签订的协议或者共同参加的国际条约，或者按照相互承认优先权的原则，可以享有优先权。"},{"i":30,"n":"第三十条","txt":"商标在中国政府主办的或者承认的国际展览会展出的商品上首次使用的，自该商品展出之日起六个月内，该商标的注册申请人可以享有优先权。"},{"i":31,"n":"第三十一条","txt":"为申请商标注册所申报的事项和所提供的材料应当真实、准确、完整。"},{"i":32,"n":"第三十二条","txt":"对申请注册的商标，国务院商标管理部门应当自收到商标注册申请文件之日起九个月内审查完毕，符合本法有关规定的，予以初步审定公告。"},{"i":33,"n":"第三十三条","txt":"在审查过程中，国务院商标管理部门认为商标注册申请内容需要说明或者修正的，可以要求申请人作出说明或者修正。申请人未作出说明或者修正的，不影响国务院商标管理部门作出审查决定。"},{"i":34,"n":"第三十四条","txt":"申请注册的商标，凡不符合本法有关规定的，由国务院商标管理部门驳回申请，不予公告。"},{"i":35,"n":"第三十五条","txt":"两个或者两个以上的商标注册申请人，在同一种商品或者类似商品上，以相同或者近似的商标申请注册的，初步审定并公告申请在先的商标；同一天申请的，初步审定并公告使用在先的商标，驳回其他人的申请，不予公告。"},{"i":36,"n":"第三十六条","txt":"对初步审定公告的商标，自公告之日起二个月内，在先权利人、利害关系人认为违反本法第二十条至第二十二条、第二十三条第一款、第二十四条规定的，或者任何人认为违反本法第十五条、第十六条第一款、第十七条至第十九条、第二十五条规定的，可以向国务院商标管理部门提出异议。公告期满无异议的，予以核准注册，发给商标注册证，并予公告。"},{"i":37,"n":"第三十七条","txt":"对驳回申请、不予公告的商标，国务院商标管理部门应当书面通知商标注册申请人。商标注册申请人不服的，可以自收到通知之日起十五日内向国务院商标管理部门申请复审。国务院商标管理部门应当自收到申请之日起九个月内作出决定，并书面通知申请人。有特殊情况需要延长的，经国务院商标管理部门负责人批准，可以延长三个月。当事人对复审决定不服的，可以自收到通知之日起三十日内向人民法院起诉。"},{"i":38,"n":"第三十八条","txt":"对初步审定公告的商标提出异议的，国务院商标管理部门应当听取异议人和被异议人陈述事实和理由，经调查核实后，自公告期满之日起十二个月内作出是否准予注册的决定，并书面通知异议人和被异议人。有特殊情况需要延长的，经国务院商标管理部门负责人批准，可以延长六个月。"},{"i":39,"n":"第三十九条","txt":"法定期限届满，当事人对国务院商标管理部门作出的驳回申请决定、不予注册决定不申请复审，或者对复审决定不向人民法院起诉的，驳回申请决定、不予注册决定或者复审决定生效。"},{"i":40,"n":"第四十条","txt":"对商标注册申请和商标复审申请，国务院商标管理部门应当及时进行审查。"},{"i":41,"n":"第四十一条","txt":"国务院商标管理部门在商标异议审查、驳回复审、不予注册复审和无效宣告案件审理过程中，所涉及的在先权益的确定必须以人民法院正在审理或者行政机关正在处理的另一案件的结果为依据的，可以中止审查审理。中止原因消除后，应当及时恢复审查审理程序。"},{"i":42,"n":"第四十二条","txt":"商标注册申请人或者注册人发现商标申请文件或者注册文件有明显错误的，可以申请更正。国务院商标管理部门依法在其职权范围内作出更正，并通知当事人。"},{"i":43,"n":"第四十三条","txt":"注册商标的有效期为十年，自核准注册之日起计算。"},{"i":44,"n":"第四十四条","txt":"注册商标有效期满，需要继续使用的，商标注册人应当在期满前十二个月内按照规定办理续展手续；在此期间未能办理的，可以给予六个月的宽展期。每次续展注册的有效期为十年，自该商标上一届有效期满次日起计算。宽展期满未办理续展手续的，注销其注册商标。"},{"i":45,"n":"第四十五条","txt":"注册商标需要变更注册人的名义、地址或者其他注册事项的，应当提出变更申请。"},{"i":46,"n":"第四十六条","txt":"转让注册商标的，转让人和受让人应当签订转让协议，并共同向国务院商标管理部门提出申请。受让人应当保证使用该注册商标的商品质量。"},{"i":47,"n":"第四十七条","txt":"转让集体商标、证明商标的，受让人应当具备相应的主体资格和监督能力。"},{"i":48,"n":"第四十八条","txt":"商标注册人申请注销其注册商标或者注销其商标在部分指定商品上的注册，经国务院商标管理部门核准注销的，予以公告；该注册商标专用权或者该注册商标专用权在该部分指定商品上的效力自公告之日起终止。"},{"i":49,"n":"第四十九条","txt":"商标注册人申请注销其注册商标的，自注销公告之日起一年内，国务院商标管理部门对他人在同一种或者类似商品上与该商标相同或者近似的商标注册申请，不予核准。"},{"i":50,"n":"第五十条","txt":"已经注册的商标，违反本法第十五条、第十六条第一款、第十七条至第十九条、第二十五条规定的，由国务院商标管理部门宣告该注册商标无效；其他单位或者个人可以请求国务院商标管理部门宣告该注册商标无效。"},{"i":51,"n":"第五十一条","txt":"已经注册的商标，违反本法第二十条至第二十二条、第二十三条第一款、第二十四条规定的，自商标注册之日起五年内，在先权利人或者利害关系人可以请求国务院商标管理部门宣告该注册商标无效。对恶意注册的，驰名商标持有人不受五年的时间限制。"},{"i":52,"n":"第五十二条","txt":"法定期限届满，当事人对国务院商标管理部门宣告注册商标无效的决定不申请复审或者对复审决定、维持注册商标或者宣告注册商标无效的裁定不向人民法院起诉的，国务院商标管理部门的决定、裁定生效。"},{"i":53,"n":"第五十三条","txt":"依照本法第五十条、第五十一条的规定宣告无效的注册商标，由国务院商标管理部门予以公告，该注册商标专用权视为自始即不存在。"},{"i":54,"n":"第五十四条","txt":"商标注册申请人存在下列恶意申请商标注册行为之一，造成不良影响的，由负责商标执法的部门给予警告，可以并处十万元以下的罚款："},{"i":55,"n":"第五十五条","txt":"商标注册人可以自己使用商标，也可以通过签订商标使用许可合同，许可他人使用其注册商标。许可人应当监督被许可人使用其注册商标的商品质量。被许可人应当保证使用该注册商标的商品质量。被许可人不履行质量保证义务的，许可人有权解除商标使用许可合同。"},{"i":56,"n":"第五十六条","txt":"以误导公众的方式使用注册商标的，由负责商标执法的部门责令限期改正，违法经营额五万元以上的，可以处违法经营额五倍以下的罚款；没有违法经营额或者违法经营额不足五万元的，可以处二十五万元以下的罚款。逾期不改正的，由国务院商标管理部门撤销其注册商标。"},{"i":57,"n":"第五十七条","txt":"商标注册人在使用注册商标的过程中，自行改变注册商标、注册人名义、地址或者其他注册事项，由负责商标执法的部门责令限期改正；逾期不改正的，处五万元以下的罚款；情节严重的，由国务院商标管理部门撤销其注册商标。"},{"i":58,"n":"第五十八条","txt":"对国务院商标管理部门撤销或者不予撤销注册商标的决定，当事人不服的，可以自收到通知之日起十五日内向国务院商标管理部门申请复审。国务院商标管理部门应当自收到申请之日起九个月内作出决定，并书面通知当事人。有特殊情况需要延长的，经国务院商标管理部门负责人批准，可以延长三个月。当事人对复审决定不服的，可以自收到通知之日起三十日内向人民法院起诉。"},{"i":59,"n":"第五十九条","txt":"法定期限届满，当事人对国务院商标管理部门作出的撤销注册商标的决定不申请复审或者对复审决定不向人民法院起诉的，撤销注册商标的决定、复审决定生效。"},{"i":60,"n":"第六十条","txt":"集体商标、证明商标注册人有下列行为之一的，由负责商标执法的部门责令限期改正；逾期不改正的，处一万元以下的罚款；情节严重的，处一万元以上十万元以下的罚款："},{"i":61,"n":"第六十一条","txt":"违反本法第八条规定的，由负责商标执法的部门责令限期申请注册，违法经营额五万元以上的，可以处违法经营额百分之二十以下的罚款；没有违法经营额或者违法经营额不足五万元的，可以处一万元以下的罚款。"},{"i":62,"n":"第六十二条","txt":"将未注册商标冒充注册商标使用的，或者使用未注册商标违反本法第十五条、第十六条第一款规定的，由负责商标执法的部门责令限期改正，违法经营额五万元以上的，可以处违法经营额百分之二十以下的罚款；没有违法经营额或者违法经营额不足五万元的，可以处一万元以下的罚款。"},{"i":63,"n":"第六十三条","txt":"为相关公众所熟知的商标，持有人认为其权利受到侵害时，可以依照本法规定请求驰名商标保护。"},{"i":64,"n":"第六十四条","txt":"生产经营者不得将“驰名商标”字样用于商品、商品包装或者容器上，或者用于广告宣传、展览以及其他商业活动中。"},{"i":65,"n":"第六十五条","txt":"商标代理机构和商标代理从业人员应当遵循诚信原则，遵守法律、行政法规，恪守职业道德、执业纪律，履行勤勉尽责义务，维护委托人的合法权益，不得实施或者帮助委托人实施损害国家利益、社会公共利益或者他人合法权益的行为。"},{"i":66,"n":"第六十六条","txt":"商标代理行业组织是商标代理行业的自律性组织。"},{"i":67,"n":"第六十七条","txt":"商标代理机构有下列行为之一的，由负责商标执法的部门责令限期改正，处一万元以上十万元以下的罚款，情节严重的，处十万元以上二十万元以下的罚款；对直接负责的主管人员和其他直接责任人员给予警告，并处五千元以上五万元以下的罚款，情节严重的，并处五万元以上十万元以下的罚款："},{"i":68,"n":"第六十八条","txt":"商标代理从业人员有下列行为之一的，由负责商标执法的部门责令限期改正，给予警告，并处五千元以上五万元以下的罚款；情节严重的，并处五万元以上十万元以下的罚款："},{"i":69,"n":"第六十九条","txt":"在境外商标注册审查审理或者处理商标案件过程中，需要证明商标在中国境内为相关公众所熟知的，应当事人请求，国务院商标管理部门可以依照本法第六十三条的规定对商标驰名情况作出确认。"},{"i":70,"n":"第七十条","txt":"对于以误导公众的方式使用注册商标、侵犯注册商标专用权等违法行为，任何单位或者个人有权向负责商标管理工作、商标执法的部门投诉、举报。"},{"i":71,"n":"第七十一条","txt":"注册商标的专用权，以核准注册的商标和核定使用的商品为限。"},{"i":72,"n":"第七十二条","txt":"有下列行为之一的，均属侵犯注册商标专用权："},{"i":73,"n":"第七十三条","txt":"注册商标中含有的本商品的通用名称、图形、型号，或者直接表示商品的种类、性质、质量、主要原料、功能、用途、重量、数量、价值、地理来源及其他特点，或者含有的地名，注册商标专用权人无权禁止他人正当使用。"},{"i":74,"n":"第七十四条","txt":"有本法第七十二条所列侵犯注册商标专用权行为之一，引起纠纷的，由当事人协商解决；不愿协商或者协商不成的，商标注册人或者利害关系人可以向人民法院起诉，也可以请求负责商标执法的部门处理。"},{"i":75,"n":"第七十五条","txt":"对侵犯注册商标专用权的行为，负责商标执法的部门有权依法查处。"},{"i":76,"n":"第七十六条","txt":"负责商标执法的部门根据已经取得的违法嫌疑证据或者投诉举报，对涉嫌侵犯他人注册商标专用权的行为进行查处时，可以行使下列职权："},{"i":77,"n":"第七十七条","txt":"侵犯注册商标专用权的赔偿数额，按照权利人因被侵权所受到的实际损失或者侵权人因侵权所获得的利益确定；权利人的损失或者侵权人获得的利益难以确定的，参照该商标许可使用费的倍数合理确定。对故意侵犯注册商标专用权，情节严重的，可以在按照上述方法确定数额的一倍以上五倍以下确定赔偿数额。"},{"i":78,"n":"第七十八条","txt":"注册商标专用权人请求赔偿，被控侵权人以注册商标专用权人未使用注册商标提出抗辩的，人民法院可以要求注册商标专用权人提供侵权行为发生前三年内实际使用该注册商标的证据。注册商标专用权人不能证明此前三年内实际使用过该注册商标，也不能证明因侵权行为受到其他损失的，被控侵权人不承担赔偿责任。"},{"i":79,"n":"第七十九条","txt":"商标注册人或者利害关系人有证据证明他人正在实施或者即将实施侵犯其注册商标专用权的行为，如不及时制止将会使其合法权益受到难以弥补的损害的，可以依法在起诉前向人民法院申请采取责令停止有关行为和财产保全的措施。"},{"i":80,"n":"第八十条","txt":"为制止侵权行为，在证据可能灭失或者以后难以取得的情况下，商标注册人或者利害关系人可以依法在起诉前向人民法院申请保全证据。"},{"i":81,"n":"第八十一条","txt":"对以恶意串通、单方捏造基本事实等方式提起商标诉讼的，由人民法院依法给予处罚；给对方当事人造成损失的，应当依法承担民事责任。"},{"i":82,"n":"第八十二条","txt":"从事商标注册、管理和执法等工作的公职人员必须秉公执法，廉洁自律，忠于职守，文明服务。"},{"i":83,"n":"第八十三条","txt":"负责商标注册、管理工作的部门和负责商标执法的部门应当建立健全内部监督制度，对负责商标注册、管理和执法等工作的公职人员执行法律、行政法规和遵守纪律的情况，进行监督检查。"},{"i":84,"n":"第八十四条","txt":"从事商标注册、管理和执法等工作的公职人员，违反本法规定，从事商标代理业务、商品生产经营活动的，或者滥用职权、玩忽职守、徇私舞弊，有下列情形之一的，依法给予处分："},{"i":85,"n":"第八十五条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":86,"n":"第八十六条","txt":"申请商标注册和办理其他商标事宜的，应当缴纳费用，具体收费标准另定。"},{"i":87,"n":"第八十七条","txt":"本法自2027年1月1日起施行。"}],"shangbiaofa":[{"i":1,"n":"第一条","txt":"为了加强商标管理，保护商标专用权，促使生产、经营者保证商品和服务质量，维护商标信誉，以保障消费者和生产、经营者的利益，促进社会主义市场经济的发展，特制定本法。"},{"i":2,"n":"第二条","txt":"国务院工商行政管理部门商标局主管全国商标注册和管理的工作。"},{"i":3,"n":"第三条","txt":"经商标局核准注册的商标为注册商标，包括商品商标、服务商标和集体商标、证明商标；商标注册人享有商标专用权，受法律保护。"},{"i":4,"n":"第四条","txt":"自然人、法人或者其他组织在生产经营活动中，对其商品或者服务需要取得商标专用权的，应当向商标局申请商标注册。不以使用为目的的恶意商标注册申请，应当予以驳回。"},{"i":5,"n":"第五条","txt":"两个以上的自然人、法人或者其他组织可以共同向商标局申请注册同一商标，共同享有和行使该商标专用权。"},{"i":6,"n":"第六条","txt":"法律、行政法规规定必须使用注册商标的商品，必须申请商标注册，未经核准注册的，不得在市场销售。"},{"i":7,"n":"第七条","txt":"申请注册和使用商标，应当遵循诚实信用原则。"},{"i":8,"n":"第八条","txt":"任何能够将自然人、法人或者其他组织的商品与他人的商品区别开的标志，包括文字、图形、字母、数字、三维标志、颜色组合和声音等，以及上述要素的组合，均可以作为商标申请注册。"},{"i":9,"n":"第九条","txt":"申请注册的商标，应当有显著特征，便于识别，并不得与他人在先取得的合法权利相冲突。"},{"i":10,"n":"第十条","txt":"下列标志不得作为商标使用："},{"i":11,"n":"第十一条","txt":"下列标志不得作为商标注册："},{"i":12,"n":"第十二条","txt":"以三维标志申请注册商标的，仅由商品自身的性质产生的形状、为获得技术效果而需有的商品形状或者使商品具有实质性价值的形状，不得注册。"},{"i":13,"n":"第十三条","txt":"为相关公众所熟知的商标，持有人认为其权利受到侵害时，可以依照本法规定请求驰名商标保护。"},{"i":14,"n":"第十四条","txt":"驰名商标应当根据当事人的请求，作为处理涉及商标案件需要认定的事实进行认定。认定驰名商标应当考虑下列因素："},{"i":15,"n":"第十五条","txt":"未经授权，代理人或者代表人以自己的名义将被代理人或者被代表人的商标进行注册，被代理人或者被代表人提出异议的，不予注册并禁止使用。"},{"i":16,"n":"第十六条","txt":"商标中有商品的地理标志，而该商品并非来源于该标志所标示的地区，误导公众的，不予注册并禁止使用；但是，已经善意取得注册的继续有效。"},{"i":17,"n":"第十七条","txt":"外国人或者外国企业在中国申请商标注册的，应当按其所属国和中华人民共和国签订的协议或者共同参加的国际条约办理，或者按对等原则办理。"},{"i":18,"n":"第十八条","txt":"申请商标注册或者办理其他商标事宜，可以自行办理，也可以委托依法设立的商标代理机构办理。"},{"i":19,"n":"第十九条","txt":"商标代理机构应当遵循诚实信用原则，遵守法律、行政法规，按照被代理人的委托办理商标注册申请或者其他商标事宜；对在代理过程中知悉的被代理人的商业秘密，负有保密义务。"},{"i":20,"n":"第二十条","txt":"商标代理行业组织应当按照章程规定，严格执行吸纳会员的条件，对违反行业自律规范的会员实行惩戒。商标代理行业组织对其吸纳的会员和对会员的惩戒情况，应当及时向社会公布。"},{"i":21,"n":"第二十一条","txt":"商标国际注册遵循中华人民共和国缔结或者参加的有关国际条约确立的制度，具体办法由国务院规定。"},{"i":22,"n":"第二十二条","txt":"商标注册申请人应当按规定的商品分类表填报使用商标的商品类别和商品名称，提出注册申请。"},{"i":23,"n":"第二十三条","txt":"注册商标需要在核定使用范围之外的商品上取得商标专用权的，应当另行提出注册申请。"},{"i":24,"n":"第二十四条","txt":"注册商标需要改变其标志的，应当重新提出注册申请。"},{"i":25,"n":"第二十五条","txt":"商标注册申请人自其商标在外国第一次提出商标注册申请之日起六个月内，又在中国就相同商品以同一商标提出商标注册申请的，依照该外国同中国签订的协议或者共同参加的国际条约，或者按照相互承认优先权的原则，可以享有优先权。"},{"i":26,"n":"第二十六条","txt":"商标在中国政府主办的或者承认的国际展览会展出的商品上首次使用的，自该商品展出之日起六个月内，该商标的注册申请人可以享有优先权。"},{"i":27,"n":"第二十七条","txt":"为申请商标注册所申报的事项和所提供的材料应当真实、准确、完整。"},{"i":28,"n":"第二十八条","txt":"对申请注册的商标，商标局应当自收到商标注册申请文件之日起九个月内审查完毕，符合本法有关规定的，予以初步审定公告。"},{"i":29,"n":"第二十九条","txt":"在审查过程中，商标局认为商标注册申请内容需要说明或者修正的，可以要求申请人做出说明或者修正。申请人未做出说明或者修正的，不影响商标局做出审查决定。"},{"i":30,"n":"第三十条","txt":"申请注册的商标，凡不符合本法有关规定或者同他人在同一种商品或者类似商品上已经注册的或者初步审定的商标相同或者近似的，由商标局驳回申请，不予公告。"},{"i":31,"n":"第三十一条","txt":"两个或者两个以上的商标注册申请人，在同一种商品或者类似商品上，以相同或者近似的商标申请注册的，初步审定并公告申请在先的商标；同一天申请的，初步审定并公告使用在先的商标，驳回其他人的申请，不予公告。"},{"i":32,"n":"第三十二条","txt":"申请商标注册不得损害他人现有的在先权利，也不得以不正当手段抢先注册他人已经使用并有一定影响的商标。"},{"i":33,"n":"第三十三条","txt":"对初步审定公告的商标，自公告之日起三个月内，在先权利人、利害关系人认为违反本法第十三条第二款和第三款、第十五条、第十六条第一款、第三十条、第三十一条、第三十二条规定的，或者任何人认为违反本法第四条、第十条、第十一条、第十二条、第十九条第四款规定的，可以向商标局提出异议。公告期满无异议的，予以核准注册，发给商标注册证，并予公告。"},{"i":34,"n":"第三十四条","txt":"对驳回申请、不予公告的商标，商标局应当书面通知商标注册申请人。商标注册申请人不服的，可以自收到通知之日起十五日内向商标评审委员会申请复审。商标评审委员会应当自收到申请之日起九个月内做出决定，并书面通知申请人。有特殊情况需要延长的，经国务院工商行政管理部门批准，可以延长三个月。当事人对商标评审委员会的决定不服的，可以自收到通知之日起三十日内向人民法院起诉。"},{"i":35,"n":"第三十五条","txt":"对初步审定公告的商标提出异议的，商标局应当听取异议人和被异议人陈述事实和理由，经调查核实后，自公告期满之日起十二个月内做出是否准予注册的决定，并书面通知异议人和被异议人。有特殊情况需要延长的，经国务院工商行政管理部门批准，可以延长六个月。"},{"i":36,"n":"第三十六条","txt":"法定期限届满，当事人对商标局做出的驳回申请决定、不予注册决定不申请复审或者对商标评审委员会做出的复审决定不向人民法院起诉的，驳回申请决定、不予注册决定或者复审决定生效。"},{"i":37,"n":"第三十七条","txt":"对商标注册申请和商标复审申请应当及时进行审查。"},{"i":38,"n":"第三十八条","txt":"商标注册申请人或者注册人发现商标申请文件或者注册文件有明显错误的，可以申请更正。商标局依法在其职权范围内作出更正，并通知当事人。"},{"i":39,"n":"第三十九条","txt":"注册商标的有效期为十年，自核准注册之日起计算。"},{"i":40,"n":"第四十条","txt":"注册商标有效期满，需要继续使用的，商标注册人应当在期满前十二个月内按照规定办理续展手续；在此期间未能办理的，可以给予六个月的宽展期。每次续展注册的有效期为十年，自该商标上一届有效期满次日起计算。期满未办理续展手续的，注销其注册商标。"},{"i":41,"n":"第四十一条","txt":"注册商标需要变更注册人的名义、地址或者其他注册事项的，应当提出变更申请。"},{"i":42,"n":"第四十二条","txt":"转让注册商标的，转让人和受让人应当签订转让协议，并共同向商标局提出申请。受让人应当保证使用该注册商标的商品质量。"},{"i":43,"n":"第四十三条","txt":"商标注册人可以通过签订商标使用许可合同，许可他人使用其注册商标。许可人应当监督被许可人使用其注册商标的商品质量。被许可人应当保证使用该注册商标的商品质量。"},{"i":44,"n":"第四十四条","txt":"已经注册的商标，违反本法第四条、第十条、第十一条、第十二条、第十九条第四款规定的，或者是以欺骗手段或者其他不正当手段取得注册的，由商标局宣告该注册商标无效；其他单位或者个人可以请求商标评审委员会宣告该注册商标无效。"},{"i":45,"n":"第四十五条","txt":"已经注册的商标，违反本法第十三条第二款和第三款、第十五条、第十六条第一款、第三十条、第三十一条、第三十二条规定的，自商标注册之日起五年内，在先权利人或者利害关系人可以请求商标评审委员会宣告该注册商标无效。对恶意注册的，驰名商标所有人不受五年的时间限制。"},{"i":46,"n":"第四十六条","txt":"法定期限届满，当事人对商标局宣告注册商标无效的决定不申请复审或者对商标评审委员会的复审决定、维持注册商标或者宣告注册商标无效的裁定不向人民法院起诉的，商标局的决定或者商标评审委员会的复审决定、裁定生效。"},{"i":47,"n":"第四十七条","txt":"依照本法第四十四条、第四十五条的规定宣告无效的注册商标，由商标局予以公告，该注册商标专用权视为自始即不存在。"},{"i":48,"n":"第四十八条","txt":"本法所称商标的使用，是指将商标用于商品、商品包装或者容器以及商品交易文书上，或者将商标用于广告宣传、展览以及其他商业活动中，用于识别商品来源的行为。"},{"i":49,"n":"第四十九条","txt":"商标注册人在使用注册商标的过程中，自行改变注册商标、注册人名义、地址或者其他注册事项的，由地方工商行政管理部门责令限期改正；期满不改正的，由商标局撤销其注册商标。"},{"i":50,"n":"第五十条","txt":"注册商标被撤销、被宣告无效或者期满不再续展的，自撤销、宣告无效或者注销之日起一年内，商标局对与该商标相同或者近似的商标注册申请，不予核准。"},{"i":51,"n":"第五十一条","txt":"违反本法第六条规定的，由地方工商行政管理部门责令限期申请注册，违法经营额五万元以上的，可以处违法经营额百分之二十以下的罚款，没有违法经营额或者违法经营额不足五万元的，可以处一万元以下的罚款。"},{"i":52,"n":"第五十二条","txt":"将未注册商标冒充注册商标使用的，或者使用未注册商标违反本法第十条规定的，由地方工商行政管理部门予以制止，限期改正，并可以予以通报，违法经营额五万元以上的，可以处违法经营额百分之二十以下的罚款，没有违法经营额或者违法经营额不足五万元的，可以处一万元以下的罚款。"},{"i":53,"n":"第五十三条","txt":"违反本法第十四条第五款规定的，由地方工商行政管理部门责令改正，处十万元罚款。"},{"i":54,"n":"第五十四条","txt":"对商标局撤销或者不予撤销注册商标的决定，当事人不服的，可以自收到通知之日起十五日内向商标评审委员会申请复审。商标评审委员会应当自收到申请之日起九个月内做出决定，并书面通知当事人。有特殊情况需要延长的，经国务院工商行政管理部门批准，可以延长三个月。当事人对商标评审委员会的决定不服的，可以自收到通知之日起三十日内向人民法院起诉。"},{"i":55,"n":"第五十五条","txt":"法定期限届满，当事人对商标局做出的撤销注册商标的决定不申请复审或者对商标评审委员会做出的复审决定不向人民法院起诉的，撤销注册商标的决定、复审决定生效。"},{"i":56,"n":"第五十六条","txt":"注册商标的专用权，以核准注册的商标和核定使用的商品为限。"},{"i":57,"n":"第五十七条","txt":"有下列行为之一的，均属侵犯注册商标专用权："},{"i":58,"n":"第五十八条","txt":"将他人注册商标、未注册的驰名商标作为企业名称中的字号使用，误导公众，构成不正当竞争行为的，依照《中华人民共和国反不正当竞争法》处理。"},{"i":59,"n":"第五十九条","txt":"注册商标中含有的本商品的通用名称、图形、型号，或者直接表示商品的质量、主要原料、功能、用途、重量、数量及其他特点，或者含有的地名，注册商标专用权人无权禁止他人正当使用。"},{"i":60,"n":"第六十条","txt":"有本法第五十七条所列侵犯注册商标专用权行为之一，引起纠纷的，由当事人协商解决；不愿协商或者协商不成的，商标注册人或者利害关系人可以向人民法院起诉，也可以请求工商行政管理部门处理。"},{"i":61,"n":"第六十一条","txt":"对侵犯注册商标专用权的行为，工商行政管理部门有权依法查处；涉嫌犯罪的，应当及时移送司法机关依法处理。"},{"i":62,"n":"第六十二条","txt":"县级以上工商行政管理部门根据已经取得的违法嫌疑证据或者举报，对涉嫌侵犯他人注册商标专用权的行为进行查处时，可以行使下列职权："},{"i":63,"n":"第六十三条","txt":"侵犯商标专用权的赔偿数额，按照权利人因被侵权所受到的实际损失确定；实际损失难以确定的，可以按照侵权人因侵权所获得的利益确定；权利人的损失或者侵权人获得的利益难以确定的，参照该商标许可使用费的倍数合理确定。对恶意侵犯商标专用权，情节严重的，可以在按照上述方法确定数额的一倍以上五倍以下确定赔偿数额。赔偿数额应当包括权利人为制止侵权行为所支付的合理开支。"},{"i":64,"n":"第六十四条","txt":"注册商标专用权人请求赔偿，被控侵权人以注册商标专用权人未使用注册商标提出抗辩的，人民法院可以要求注册商标专用权人提供此前三年内实际使用该注册商标的证据。注册商标专用权人不能证明此前三年内实际使用过该注册商标，也不能证明因侵权行为受到其他损失的，被控侵权人不承担赔偿责任。"},{"i":65,"n":"第六十五条","txt":"商标注册人或者利害关系人有证据证明他人正在实施或者即将实施侵犯其注册商标专用权的行为，如不及时制止将会使其合法权益受到难以弥补的损害的，可以依法在起诉前向人民法院申请采取责令停止有关行为和财产保全的措施。"},{"i":66,"n":"第六十六条","txt":"为制止侵权行为，在证据可能灭失或者以后难以取得的情况下，商标注册人或者利害关系人可以依法在起诉前向人民法院申请保全证据。"},{"i":67,"n":"第六十七条","txt":"未经商标注册人许可，在同一种商品上使用与其注册商标相同的商标，构成犯罪的，除赔偿被侵权人的损失外，依法追究刑事责任。"},{"i":68,"n":"第六十八条","txt":"商标代理机构有下列行为之一的，由工商行政管理部门责令限期改正，给予警告，处一万元以上十万元以下的罚款；对直接负责的主管人员和其他直接责任人员给予警告，处五千元以上五万元以下的罚款；构成犯罪的，依法追究刑事责任："},{"i":69,"n":"第六十九条","txt":"从事商标注册、管理和复审工作的国家机关工作人员必须秉公执法，廉洁自律，忠于职守，文明服务。"},{"i":70,"n":"第七十条","txt":"工商行政管理部门应当建立健全内部监督制度，对负责商标注册、管理和复审工作的国家机关工作人员执行法律、行政法规和遵守纪律的情况，进行监督检查。"},{"i":71,"n":"第七十一条","txt":"从事商标注册、管理和复审工作的国家机关工作人员玩忽职守、滥用职权、徇私舞弊，违法办理商标注册、管理和复审事项，收受当事人财物，牟取不正当利益，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":72,"n":"第七十二条","txt":"申请商标注册和办理其他商标事宜的，应当缴纳费用，具体收费标准另定。"},{"i":73,"n":"第七十三条","txt":"本法自1983年3月1日起施行。1963年4月10日国务院公布的《商标管理条例》同时废止；其他有关商标管理的规定，凡与本法抵触的，同时失效。"}],"paimaifa":[{"i":1,"n":"第一条","txt":"为了规范拍卖行为，维护拍卖秩序，保护拍卖活动各方当事人的合法权益，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于中华人民共和国境内拍卖企业进行的拍卖活动。"},{"i":3,"n":"第三条","txt":"拍卖是指以公开竞价的形式，将特定物品或者财产权利转让给最高应价者的买卖方式。"},{"i":4,"n":"第四条","txt":"拍卖活动应当遵守有关法律、行政法规，遵循公开、公平、公正、诚实信用的原则。"},{"i":5,"n":"第五条","txt":"国务院负责管理拍卖业的部门对全国拍卖业实施监督管理。"},{"i":6,"n":"第六条","txt":"拍卖标的应当是委托人所有或者依法可以处分的物品或者财产权利。"},{"i":7,"n":"第七条","txt":"法律、行政法规禁止买卖的物品或者财产权利，不得作为拍卖标的。"},{"i":8,"n":"第八条","txt":"依照法律或者按照国务院规定需经审批才能转让的物品或者财产权利，在拍卖前，应当依法办理审批手续。"},{"i":9,"n":"第九条","txt":"国家行政机关依法没收的物品，充抵税款、罚款的物品和其他物品，按照国务院规定应当委托拍卖的，由财产所在地的省、自治区、直辖市的人民政府和设区的市的人民政府指定的拍卖人进行拍卖。"},{"i":10,"n":"第十条","txt":"拍卖人是指依照本法和《中华人民共和国公司法》设立的从事拍卖活动的企业法人。"},{"i":11,"n":"第十一条","txt":"企业取得从事拍卖业务的许可必须经所在地的省、自治区、直辖市人民政府负责管理拍卖业的部门审核批准。拍卖企业可以在设区的市设立。"},{"i":12,"n":"第十二条","txt":"企业申请取得从事拍卖业务的许可，应当具备下列条件："},{"i":13,"n":"第十三条","txt":"拍卖企业经营文物拍卖的，应当有一千万元人民币以上的注册资本，有具有文物拍卖专业知识的人员。"},{"i":14,"n":"第十四条","txt":"拍卖活动应当由拍卖师主持。"},{"i":15,"n":"第十五条","txt":"拍卖师应当具备下列条件："},{"i":16,"n":"第十六条","txt":"拍卖师资格考核，由拍卖行业协会统一组织。经考核合格的，由拍卖行业协会发给拍卖师资格证书。"},{"i":17,"n":"第十七条","txt":"拍卖行业协会是依法成立的社会团体法人，是拍卖业的自律性组织。拍卖行业协会依照本法并根据章程，对拍卖企业和拍卖师进行监督。"},{"i":18,"n":"第十八条","txt":"拍卖人有权要求委托人说明拍卖标的的来源和瑕疵。"},{"i":19,"n":"第十九条","txt":"拍卖人对委托人交付拍卖的物品负有保管义务。"},{"i":20,"n":"第二十条","txt":"拍卖人接受委托后，未经委托人同意，不得委托其他拍卖人拍卖。"},{"i":21,"n":"第二十一条","txt":"委托人、买受人要求对其身份保密的，拍卖人应当为其保密。"},{"i":22,"n":"第二十二条","txt":"拍卖人及其工作人员不得以竞买人的身份参与自己组织的拍卖活动，并不得委托他人代为竞买。"},{"i":23,"n":"第二十三条","txt":"拍卖人不得在自己组织的拍卖活动中拍卖自己的物品或者财产权利。"},{"i":24,"n":"第二十四条","txt":"拍卖成交后，拍卖人应当按照约定向委托人交付拍卖标的的价款，并按照约定将拍卖标的移交给买受人。"},{"i":25,"n":"第二十五条","txt":"委托人是指委托拍卖人拍卖物品或者财产权利的公民、法人或者其他组织。"},{"i":26,"n":"第二十六条","txt":"委托人可以自行办理委托拍卖手续，也可以由其代理人代为办理委托拍卖手续。"},{"i":27,"n":"第二十七条","txt":"委托人应当向拍卖人说明拍卖标的的来源和瑕疵。"},{"i":28,"n":"第二十八条","txt":"委托人有权确定拍卖标的的保留价并要求拍卖人保密。"},{"i":29,"n":"第二十九条","txt":"委托人在拍卖开始前可以撤回拍卖标的。委托人撤回拍卖标的的，应当向拍卖人支付约定的费用；未作约定的，应当向拍卖人支付为拍卖支出的合理费用。"},{"i":30,"n":"第三十条","txt":"委托人不得参与竞买，也不得委托他人代为竞买。"},{"i":31,"n":"第三十一条","txt":"按照约定由委托人移交拍卖标的的，拍卖成交后，委托人应当将拍卖标的移交给买受人。"},{"i":32,"n":"第三十二条","txt":"竞买人是指参加竞购拍卖标的的公民、法人或者其他组织。"},{"i":33,"n":"第三十三条","txt":"法律、行政法规对拍卖标的的买卖条件有规定的，竞买人应当具备规定的条件。"},{"i":34,"n":"第三十四条","txt":"竞买人可以自行参加竞买，也可以委托其代理人参加竞买。"},{"i":35,"n":"第三十五条","txt":"竞买人有权了解拍卖标的的瑕疵，有权查验拍卖标的和查阅有关拍卖资料。"},{"i":36,"n":"第三十六条","txt":"竞买人一经应价，不得撤回，当其他竞买人有更高应价时，其应价即丧失约束力。"},{"i":37,"n":"第三十七条","txt":"竞买人之间、竞买人与拍卖人之间不得恶意串通，损害他人利益。"},{"i":38,"n":"第三十八条","txt":"买受人是指以最高应价购得拍卖标的的竞买人。"},{"i":39,"n":"第三十九条","txt":"买受人应当按照约定支付拍卖标的的价款，未按照约定支付价款的，应当承担违约责任，或者由拍卖人征得委托人的同意，将拍卖标的再行拍卖。"},{"i":40,"n":"第四十条","txt":"买受人未能按照约定取得拍卖标的的，有权要求拍卖人或者委托人承担违约责任。"},{"i":41,"n":"第四十一条","txt":"委托人委托拍卖物品或者财产权利，应当提供身份证明和拍卖人要求提供的拍卖标的的所有权证明或者依法可以处分拍卖标的的证明及其他资料。"},{"i":42,"n":"第四十二条","txt":"拍卖人应当对委托人提供的有关文件、资料进行核实。拍卖人接受委托的，应当与委托人签订书面委托拍卖合同。"},{"i":43,"n":"第四十三条","txt":"拍卖人认为需要对拍卖标的进行鉴定的，可以进行鉴定。"},{"i":44,"n":"第四十四条","txt":"委托拍卖合同应当载明以下事项："},{"i":45,"n":"第四十五条","txt":"拍卖人应当于拍卖日七日前发布拍卖公告。"},{"i":46,"n":"第四十六条","txt":"拍卖公告应当载明下列事项："},{"i":47,"n":"第四十七条","txt":"拍卖公告应当通过报纸或者其他新闻媒介发布。"},{"i":48,"n":"第四十八条","txt":"拍卖人应当在拍卖前展示拍卖标的，并提供查看拍卖标的的条件及有关资料。拍卖标的的展示时间不得少于两日。"},{"i":49,"n":"第四十九条","txt":"拍卖师应当于拍卖前宣布拍卖规则和注意事项。"},{"i":50,"n":"第五十条","txt":"拍卖标的无保留价的，拍卖师应当在拍卖前予以说明。"},{"i":51,"n":"第五十一条","txt":"竞买人的最高应价经拍卖师落槌或者以其他公开表示买定的方式确认后，拍卖成交。"},{"i":52,"n":"第五十二条","txt":"拍卖成交后，买受人和拍卖人应当签署成交确认书。"},{"i":53,"n":"第五十三条","txt":"拍卖人进行拍卖时，应当制作拍卖笔录。拍卖笔录应当由拍卖师、记录人签名；拍卖成交的，还应当由买受人签名。"},{"i":54,"n":"第五十四条","txt":"拍卖人应当妥善保管有关业务经营活动的完整账簿、拍卖笔录和其他有关资料。"},{"i":55,"n":"第五十五条","txt":"拍卖标的需要依法办理证照变更、产权过户手续的，委托人、买受人应当持拍卖人出具的成交证明和有关材料，向有关行政管理机关办理手续。"},{"i":56,"n":"第五十六条","txt":"委托人、买受人可以与拍卖人约定佣金的比例。"},{"i":57,"n":"第五十七条","txt":"拍卖本法第九条规定的物品成交的，拍卖人可以向买受人收取不超过拍卖成交价百分之五的佣金。收取佣金的比例按照同拍卖成交价成反比的原则确定。"},{"i":58,"n":"第五十八条","txt":"委托人违反本法第六条的规定，委托拍卖其没有所有权或者依法不得处分的物品或者财产权利的，应当依法承担责任。拍卖人明知委托人对拍卖的物品或者财产权利没有所有权或者依法不得处分的，应当承担连带责任。"},{"i":59,"n":"第五十九条","txt":"国家机关违反本法第九条的规定，将应当委托财产所在地的省、自治区、直辖市的人民政府或者设区的市的人民政府指定的拍卖人拍卖的物品擅自处理的，对负有直接责任的主管人员和其他直接责任人员依法给予行政处分，给国家造成损失的，还应当承担赔偿责任。"},{"i":60,"n":"第六十条","txt":"违反本法第十一条的规定，未经许可从事拍卖业务的，由工商行政管理部门予以取缔，没收违法所得，并可以处违法所得一倍以上五倍以下的罚款。"},{"i":61,"n":"第六十一条","txt":"拍卖人、委托人违反本法第十八条第二款、第二十七条的规定，未说明拍卖标的的瑕疵，给买受人造成损害的，买受人有权向拍卖人要求赔偿；属于委托人责任的，拍卖人有权向委托人追偿。"},{"i":62,"n":"第六十二条","txt":"拍卖人及其工作人员违反本法第二十二条的规定，参与竞买或者委托他人代为竞买的，由工商行政管理部门对拍卖人给予警告，可以处拍卖佣金一倍以上五倍以下的罚款；情节严重的，吊销营业执照。"},{"i":63,"n":"第六十三条","txt":"违反本法第二十三条的规定，拍卖人在自己组织的拍卖活动中拍卖自己的物品或者财产权利的，由工商行政管理部门没收拍卖所得。"},{"i":64,"n":"第六十四条","txt":"违反本法第三十条的规定，委托人参与竞买或者委托他人代为竞买的，工商行政管理部门可以对委托人处拍卖成交价百分之三十以下的罚款。"},{"i":65,"n":"第六十五条","txt":"违反本法第三十七条的规定，竞买人之间、竞买人与拍卖人之间恶意串通，给他人造成损害的，拍卖无效，应当依法承担赔偿责任。由工商行政管理部门对参与恶意串通的竞买人处最高应价百分之十以上百分之三十以下的罚款；对参与恶意串通的拍卖人处最高应价百分之十以上百分之五十以下的罚款。"},{"i":66,"n":"第六十六条","txt":"违反本法第四章第四节关于佣金比例的规定收取佣金的，拍卖人应当将超收部分返还委托人、买受人。物价管理部门可以对拍卖人处拍卖佣金一倍以上五倍以下的罚款。"},{"i":67,"n":"第六十七条","txt":"外国人、外国企业和组织在中华人民共和国境内委托拍卖或者参加竞买的，适用本法。"},{"i":68,"n":"第六十八条","txt":"本法自1997年1月1日起施行。"}],"zhaobiaotoubiaofa":[{"i":1,"n":"第一条","txt":"为了规范招标投标活动，保护国家利益、社会公共利益和招标投标活动当事人的合法权益，提高经济效益，保证项目质量，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内进行招标投标活动，适用本法。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内进行下列工程建设项目包括项目的勘察、设计、施工、监理以及与工程建设有关的重要设备、材料等的采购，必须进行招标："},{"i":4,"n":"第四条","txt":"任何单位和个人不得将依法必须进行招标的项目化整为零或者以其他任何方式规避招标。"},{"i":5,"n":"第五条","txt":"招标投标活动应当遵循公开、公平、公正和诚实信用的原则。"},{"i":6,"n":"第六条","txt":"依法必须进行招标的项目，其招标投标活动不受地区或者部门的限制。任何单位和个人不得违法限制或者排斥本地区、本系统以外的法人或者其他组织参加投标，不得以任何方式非法干涉招标投标活动。"},{"i":7,"n":"第七条","txt":"招标投标活动及其当事人应当接受依法实施的监督。"},{"i":8,"n":"第八条","txt":"招标人是依照本法规定提出招标项目、进行招标的法人或者其他组织。"},{"i":9,"n":"第九条","txt":"招标项目按照国家有关规定需要履行项目审批手续的，应当先履行审批手续，取得批准。"},{"i":10,"n":"第十条","txt":"招标分为公开招标和邀请招标。"},{"i":11,"n":"第十一条","txt":"国务院发展计划部门确定的国家重点项目和省、自治区、直辖市人民政府确定的地方重点项目不适宜公开招标的，经国务院发展计划部门或者省、自治区、直辖市人民政府批准，可以进行邀请招标。"},{"i":12,"n":"第十二条","txt":"招标人有权自行选择招标代理机构，委托其办理招标事宜。任何单位和个人不得以任何方式为招标人指定招标代理机构。"},{"i":13,"n":"第十三条","txt":"招标代理机构是依法设立、从事招标代理业务并提供相关服务的社会中介组织。"},{"i":14,"n":"第十四条","txt":"招标代理机构与行政机关和其他国家机关不得存在隶属关系或者其他利益关系。"},{"i":15,"n":"第十五条","txt":"招标代理机构应当在招标人委托的范围内办理招标事宜，并遵守本法关于招标人的规定。"},{"i":16,"n":"第十六条","txt":"招标人采用公开招标方式的，应当发布招标公告。依法必须进行招标的项目的招标公告，应当通过国家指定的报刊、信息网络或者其他媒介发布。"},{"i":17,"n":"第十七条","txt":"招标人采用邀请招标方式的，应当向三个以上具备承担招标项目的能力、资信良好的特定的法人或者其他组织发出投标邀请书。"},{"i":18,"n":"第十八条","txt":"招标人可以根据招标项目本身的要求，在招标公告或者投标邀请书中，要求潜在投标人提供有关资质证明文件和业绩情况，并对潜在投标人进行资格审查；国家对投标人的资格条件有规定的，依照其规定。"},{"i":19,"n":"第十九条","txt":"招标人应当根据招标项目的特点和需要编制招标文件。招标文件应当包括招标项目的技术要求、对投标人资格审查的标准、投标报价要求和评标标准等所有实质性要求和条件以及拟签订合同的主要条款。"},{"i":20,"n":"第二十条","txt":"招标文件不得要求或者标明特定的生产供应者以及含有倾向或者排斥潜在投标人的其他内容。"},{"i":21,"n":"第二十一条","txt":"招标人根据招标项目的具体情况，可以组织潜在投标人踏勘项目现场。"},{"i":22,"n":"第二十二条","txt":"招标人不得向他人透露已获取招标文件的潜在投标人的名称、数量以及可能影响公平竞争的有关招标投标的其他情况。"},{"i":23,"n":"第二十三条","txt":"招标人对已发出的招标文件进行必要的澄清或者修改的，应当在招标文件要求提交投标文件截止时间至少十五日前，以书面形式通知所有招标文件收受人。该澄清或者修改的内容为招标文件的组成部分。"},{"i":24,"n":"第二十四条","txt":"招标人应当确定投标人编制投标文件所需要的合理时间；但是，依法必须进行招标的项目，自招标文件开始发出之日起至投标人提交投标文件截止之日止，最短不得少于二十日。"},{"i":25,"n":"第二十五条","txt":"投标人是响应招标、参加投标竞争的法人或者其他组织。"},{"i":26,"n":"第二十六条","txt":"投标人应当具备承担招标项目的能力；国家有关规定对投标人资格条件或者招标文件对投标人资格条件有规定的，投标人应当具备规定的资格条件。"},{"i":27,"n":"第二十七条","txt":"投标人应当按照招标文件的要求编制投标文件。投标文件应当对招标文件提出的实质性要求和条件作出响应。"},{"i":28,"n":"第二十八条","txt":"投标人应当在招标文件要求提交投标文件的截止时间前，将投标文件送达投标地点。招标人收到投标文件后，应当签收保存，不得开启。投标人少于三个的，招标人应当依照本法重新招标。"},{"i":29,"n":"第二十九条","txt":"投标人在招标文件要求提交投标文件的截止时间前，可以补充、修改或者撤回已提交的投标文件，并书面通知招标人。补充、修改的内容为投标文件的组成部分。"},{"i":30,"n":"第三十条","txt":"投标人根据招标文件载明的项目实际情况，拟在中标后将中标项目的部分非主体、非关键性工作进行分包的，应当在投标文件中载明。"},{"i":31,"n":"第三十一条","txt":"两个以上法人或者其他组织可以组成一个联合体，以一个投标人的身份共同投标。"},{"i":32,"n":"第三十二条","txt":"投标人不得相互串通投标报价，不得排挤其他投标人的公平竞争，损害招标人或者其他投标人的合法权益。"},{"i":33,"n":"第三十三条","txt":"投标人不得以低于成本的报价竞标，也不得以他人名义投标或者以其他方式弄虚作假，骗取中标。"},{"i":34,"n":"第三十四条","txt":"开标应当在招标文件确定的提交投标文件截止时间的同一时间公开进行；开标地点应当为招标文件中预先确定的地点。"},{"i":35,"n":"第三十五条","txt":"开标由招标人主持，邀请所有投标人参加。"},{"i":36,"n":"第三十六条","txt":"开标时，由投标人或者其推选的代表检查投标文件的密封情况，也可以由招标人委托的公证机构检查并公证；经确认无误后，由工作人员当众拆封，宣读投标人名称、投标价格和投标文件的其他主要内容。"},{"i":37,"n":"第三十七条","txt":"评标由招标人依法组建的评标委员会负责。"},{"i":38,"n":"第三十八条","txt":"招标人应当采取必要的措施，保证评标在严格保密的情况下进行。"},{"i":39,"n":"第三十九条","txt":"评标委员会可以要求投标人对投标文件中含义不明确的内容作必要的澄清或者说明，但是澄清或者说明不得超出投标文件的范围或者改变投标文件的实质性内容。"},{"i":40,"n":"第四十条","txt":"评标委员会应当按照招标文件确定的评标标准和方法，对投标文件进行评审和比较；设有标底的，应当参考标底。评标委员会完成评标后，应当向招标人提出书面评标报告，并推荐合格的中标候选人。"},{"i":41,"n":"第四十一条","txt":"中标人的投标应当符合下列条件之一："},{"i":42,"n":"第四十二条","txt":"评标委员会经评审，认为所有投标都不符合招标文件要求的，可以否决所有投标。"},{"i":43,"n":"第四十三条","txt":"在确定中标人前，招标人不得与投标人就投标价格、投标方案等实质性内容进行谈判。"},{"i":44,"n":"第四十四条","txt":"评标委员会成员应当客观、公正地履行职务，遵守职业道德，对所提出的评审意见承担个人责任。"},{"i":45,"n":"第四十五条","txt":"中标人确定后，招标人应当向中标人发出中标通知书，并同时将中标结果通知所有未中标的投标人。"},{"i":46,"n":"第四十六条","txt":"招标人和中标人应当自中标通知书发出之日起三十日内，按照招标文件和中标人的投标文件订立书面合同。招标人和中标人不得再行订立背离合同实质性内容的其他协议。"},{"i":47,"n":"第四十七条","txt":"依法必须进行招标的项目，招标人应当自确定中标人之日起十五日内，向有关行政监督部门提交招标投标情况的书面报告。"},{"i":48,"n":"第四十八条","txt":"中标人应当按照合同约定履行义务，完成中标项目。中标人不得向他人转让中标项目，也不得将中标项目肢解后分别向他人转让。"},{"i":49,"n":"第四十九条","txt":"违反本法规定，必须进行招标的项目而不招标的，将必须进行招标的项目化整为零或者以其他任何方式规避招标的，责令限期改正，可以处项目合同金额千分之五以上千分之十以下的罚款；对全部或者部分使用国有资金的项目，可以暂停项目执行或者暂停资金拨付；对单位直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":50,"n":"第五十条","txt":"招标代理机构违反本法规定，泄露应当保密的与招标投标活动有关的情况和资料的，或者与招标人、投标人串通损害国家利益、社会公共利益或者他人合法权益的，处五万元以上二十五万元以下的罚款；对单位直接负责的主管人员和其他直接责任人员处单位罚款数额百分之五以上百分之十以下的罚款；有违法所得的，并处没收违法所得；情节严重的，禁止其一年至二年内代理依法必须进行招标的项目并予以公告，直至由工商行政管理机关吊销营业执照；构成犯罪的，依法追究刑事责任。给他人造成损失的，依法承担赔偿责任。"},{"i":51,"n":"第五十一条","txt":"招标人以不合理的条件限制或者排斥潜在投标人的，对潜在投标人实行歧视待遇的，强制要求投标人组成联合体共同投标的，或者限制投标人之间竞争的，责令改正，可以处一万元以上五万元以下的罚款。"},{"i":52,"n":"第五十二条","txt":"依法必须进行招标的项目的招标人向他人透露已获取招标文件的潜在投标人的名称、数量或者可能影响公平竞争的有关招标投标的其他情况的，或者泄露标底的，给予警告，可以并处一万元以上十万元以下的罚款；对单位直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"投标人相互串通投标或者与招标人串通投标的，投标人以向招标人或者评标委员会成员行贿的手段谋取中标的，中标无效，处中标项目金额千分之五以上千分之十以下的罚款，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额百分之五以上百分之十以下的罚款；有违法所得的，并处没收违法所得；情节严重的，取消其一年至二年内参加依法必须进行招标的项目的投标资格并予以公告，直至由工商行政管理机关吊销营业执照；构成犯罪的，依法追究刑事责任。给他人造成损失的，依法承担赔偿责任。"},{"i":54,"n":"第五十四条","txt":"投标人以他人名义投标或者以其他方式弄虚作假，骗取中标的，中标无效，给招标人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"依法必须进行招标的项目，招标人违反本法规定，与投标人就投标价格、投标方案等实质性内容进行谈判的，给予警告，对单位直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":56,"n":"第五十六条","txt":"评标委员会成员收受投标人的财物或者其他好处的，评标委员会成员或者参加评标的有关工作人员向他人透露对投标文件的评审和比较、中标候选人的推荐以及与评标有关的其他情况的，给予警告，没收收受的财物，可以并处三千元以上五万元以下的罚款，对有所列违法行为的评标委员会成员取消担任评标委员会成员的资格，不得再参加任何依法必须进行招标的项目的评标；构成犯罪的，依法追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"招标人在评标委员会依法推荐的中标候选人以外确定中标人的，依法必须进行招标的项目在所有投标被评标委员会否决后自行确定中标人的，中标无效，责令改正，可以处中标项目金额千分之五以上千分之十以下的罚款；对单位直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":58,"n":"第五十八条","txt":"中标人将中标项目转让给他人的，将中标项目肢解后分别转让给他人的，违反本法规定将中标项目的部分主体、关键性工作分包给他人的，或者分包人再次分包的，转让、分包无效，处转让、分包项目金额千分之五以上千分之十以下的罚款；有违法所得的，并处没收违法所得；可以责令停业整顿；情节严重的，由工商行政管理机关吊销营业执照。"},{"i":59,"n":"第五十九条","txt":"招标人与中标人不按照招标文件和中标人的投标文件订立合同的，或者招标人、中标人订立背离合同实质性内容的协议的，责令改正；可以处中标项目金额千分之五以上千分之十以下的罚款。"},{"i":60,"n":"第六十条","txt":"中标人不履行与招标人订立的合同的，履约保证金不予退还，给招标人造成的损失超过履约保证金数额的，还应当对超过部分予以赔偿；没有提交履约保证金的，应当对招标人的损失承担赔偿责任。"},{"i":61,"n":"第六十一条","txt":"本章规定的行政处罚，由国务院规定的有关行政监督部门决定。本法已对实施行政处罚的机关作出规定的除外。"},{"i":62,"n":"第六十二条","txt":"任何单位违反本法规定，限制或者排斥本地区、本系统以外的法人或者其他组织参加投标的，为招标人指定招标代理机构的，强制招标人委托招标代理机构办理招标事宜的，或者以其他方式干涉招标投标活动的，责令改正；对单位直接负责的主管人员和其他直接责任人员依法给予警告、记过、记大过的处分，情节较重的，依法给予降级、撤职、开除的处分。"},{"i":63,"n":"第六十三条","txt":"对招标投标活动依法负有行政监督职责的国家机关工作人员徇私舞弊、滥用职权或者玩忽职守，构成犯罪的，依法追究刑事责任；不构成犯罪的，依法给予行政处分。"},{"i":64,"n":"第六十四条","txt":"依法必须进行招标的项目违反本法规定，中标无效的，应当依照本法规定的中标条件从其余投标人中重新确定中标人或者依照本法重新进行招标。"},{"i":65,"n":"第六十五条","txt":"投标人和其他利害关系人认为招标投标活动不符合本法有关规定的，有权向招标人提出异议或者依法向有关行政监督部门投诉。"},{"i":66,"n":"第六十六条","txt":"涉及国家安全、国家秘密、抢险救灾或者属于利用扶贫资金实行以工代赈、需要使用农民工等特殊情况，不适宜进行招标的项目，按照国家有关规定可以不进行招标。"},{"i":67,"n":"第六十七条","txt":"使用国际组织或者外国政府贷款、援助资金的项目进行招标，贷款方、资金提供方对招标投标的具体条件和程序有不同规定的，可以适用其规定，但违背中华人民共和国的社会公共利益的除外。"},{"i":68,"n":"第六十八条","txt":"本法自2000年1月1日起施行。"}],"qihuoheyanshengpinfa":[{"i":1,"n":"第一条","txt":"为了规范期货交易和衍生品交易行为，保障各方合法权益，维护市场秩序和社会公共利益，促进期货市场和衍生品市场服务国民经济，防范化解金融风险，维护国家经济安全，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，期货交易和衍生品交易及相关活动，适用本法。"},{"i":3,"n":"第三条","txt":"本法所称期货交易，是指以期货合约或者标准化期权合约为交易标的的交易活动。"},{"i":4,"n":"第四条","txt":"国家支持期货市场健康发展，发挥发现价格、管理风险、配置资源的功能。"},{"i":5,"n":"第五条","txt":"期货市场和衍生品市场应当建立和完善风险的监测监控与化解处置制度机制，依法限制过度投机行为，防范市场系统性风险。"},{"i":6,"n":"第六条","txt":"期货交易和衍生品交易活动，应当遵守法律、行政法规和国家有关规定，遵循公开、公平、公正的原则，禁止欺诈、操纵市场和内幕交易的行为。"},{"i":7,"n":"第七条","txt":"参与期货交易和衍生品交易活动的各方具有平等的法律地位，应当遵守自愿、有偿、诚实信用的原则。"},{"i":8,"n":"第八条","txt":"国务院期货监督管理机构依法对全国期货市场实行集中统一监督管理。国务院对利率、汇率期货的监督管理另有规定的，适用其规定。"},{"i":9,"n":"第九条","txt":"期货和衍生品行业协会依法实行自律管理。"},{"i":10,"n":"第十条","txt":"国家审计机关依法对期货经营机构、期货交易场所、期货结算机构、国务院期货监督管理机构进行审计监督。"},{"i":11,"n":"第十一条","txt":"期货交易应当在依法设立的期货交易所或者国务院期货监督管理机构依法批准组织开展期货交易的其他期货交易场所（以下统称期货交易场所），采用公开的集中交易方式或者国务院期货监督管理机构批准的其他方式进行。"},{"i":12,"n":"第十二条","txt":"任何单位和个人不得操纵期货市场或者衍生品市场。"},{"i":13,"n":"第十三条","txt":"期货交易和衍生品交易的内幕信息的知情人和非法获取内幕信息的人，在内幕信息公开前不得从事相关期货交易或者衍生品交易，明示、暗示他人从事与内幕信息有关的期货交易或者衍生品交易，或者泄露内幕信息。"},{"i":14,"n":"第十四条","txt":"本法所称内幕信息，是指可能对期货交易或者衍生品交易的交易价格产生重大影响的尚未公开的信息。"},{"i":15,"n":"第十五条","txt":"本法所称内幕信息的知情人，是指由于经营地位、管理地位、监督地位或者职务便利等，能够接触或者获得内幕信息的单位和个人。"},{"i":16,"n":"第十六条","txt":"禁止任何单位和个人编造、传播虚假信息或者误导性信息，扰乱期货市场和衍生品市场。"},{"i":17,"n":"第十七条","txt":"期货合约品种和标准化期权合约品种的上市应当符合国务院期货监督管理机构的规定，由期货交易场所依法报经国务院期货监督管理机构注册。"},{"i":18,"n":"第十八条","txt":"期货交易实行账户实名制。交易者进行期货交易的，应当持有证明身份的合法证件，以本人名义申请开立账户。"},{"i":19,"n":"第十九条","txt":"在期货交易场所进行期货交易的，应当是期货交易场所会员或者符合国务院期货监督管理机构规定的其他参与者。"},{"i":20,"n":"第二十条","txt":"交易者委托期货经营机构进行交易的，可以通过书面、电话、自助终端、网络等方式下达交易指令。交易指令应当明确、具体、全面。"},{"i":21,"n":"第二十一条","txt":"通过计算机程序自动生成或者下达交易指令进行程序化交易的，应当符合国务院期货监督管理机构的规定，并向期货交易场所报告，不得影响期货交易场所系统安全或者正常交易秩序。"},{"i":22,"n":"第二十二条","txt":"期货交易实行保证金制度，期货结算机构向结算参与人收取保证金，结算参与人向交易者收取保证金。保证金用于结算和履约保障。"},{"i":23,"n":"第二十三条","txt":"期货交易实行持仓限额制度，防范合约持仓过度集中的风险。"},{"i":24,"n":"第二十四条","txt":"期货交易实行交易者实际控制关系报备管理制度。交易者应当按照国务院期货监督管理机构的规定向期货经营机构或者期货交易场所报备实际控制关系。"},{"i":25,"n":"第二十五条","txt":"期货交易的收费应当合理，收费项目、收费标准和管理办法应当公开。"},{"i":26,"n":"第二十六条","txt":"依照期货交易场所依法制定的业务规则进行的交易，不得改变其交易结果，本法第八十九条第二款规定的除外。"},{"i":27,"n":"第二十七条","txt":"期货交易场所会员和交易者应当按照国务院期货监督管理机构的规定，报告有关交易、持仓、保证金等重大事项。"},{"i":28,"n":"第二十八条","txt":"任何单位和个人不得违规使用信贷资金、财政资金进行期货交易。"},{"i":29,"n":"第二十九条","txt":"期货经营机构、期货交易场所、期货结算机构、期货服务机构等机构及其从业人员对发现的禁止的交易行为，应当及时向国务院期货监督管理机构报告。"},{"i":30,"n":"第三十条","txt":"依法设立的场所，经国务院授权的部门或者国务院期货监督管理机构审批，可以组织开展衍生品交易。"},{"i":31,"n":"第三十一条","txt":"金融机构开展衍生品交易业务，应当依法经过批准或者核准，履行交易者适当性管理义务，并应当遵守国家有关监督管理规定。"},{"i":32,"n":"第三十二条","txt":"衍生品交易采用主协议方式的，主协议、主协议项下的全部补充协议以及交易双方就各项具体交易作出的约定等，共同构成交易双方之间一个完整的单一协议，具有法律约束力。"},{"i":33,"n":"第三十三条","txt":"本法第三十二条规定的主协议等合同范本，应当按照国务院授权的部门或者国务院期货监督管理机构的规定报送备案。"},{"i":34,"n":"第三十四条","txt":"进行衍生品交易，可以依法通过质押等方式提供履约保障。"},{"i":35,"n":"第三十五条","txt":"依法采用主协议方式从事衍生品交易的，发生约定的情形时，可以依照协议约定终止交易，并按净额对协议项下的全部交易盈亏进行结算。"},{"i":36,"n":"第三十六条","txt":"国务院授权的部门、国务院期货监督管理机构应当建立衍生品交易报告库，对衍生品交易标的、规模、对手方等信息进行集中收集、保存、分析和管理，并按照规定及时向市场披露有关信息。具体办法由国务院授权的部门、国务院期货监督管理机构规定。"},{"i":37,"n":"第三十七条","txt":"衍生品交易，由国务院授权的部门或者国务院期货监督管理机构批准的结算机构作为中央对手方进行集中结算的，可以依法进行终止净额结算；结算财产应当优先用于结算和交割，不得被查封、冻结、扣押或者强制执行；在结算和交割完成前，任何人不得动用。"},{"i":38,"n":"第三十八条","txt":"对衍生品交易及相关活动进行规范和监督管理的具体办法，由国务院依照本法的原则规定。"},{"i":39,"n":"第三十九条","txt":"期货交易实行当日无负债结算制度。在期货交易场所规定的时间，期货结算机构应当在当日按照结算价对结算参与人进行结算；结算参与人应当根据期货结算机构的结算结果对交易者进行结算。结算结果应当在当日及时通知结算参与人和交易者。"},{"i":40,"n":"第四十条","txt":"期货结算机构、结算参与人收取的保证金、权利金等，应当与其自有资金分开，按照国务院期货监督管理机构的规定，在期货保证金存管机构专户存放，分别管理，禁止违规挪用。"},{"i":41,"n":"第四十一条","txt":"结算参与人的保证金不符合期货结算机构业务规则规定标准的，期货结算机构应当按照业务规则的规定通知结算参与人在规定时间内追加保证金或者自行平仓；结算参与人未在规定时间内追加保证金或者自行平仓的，通知期货交易场所强行平仓。"},{"i":42,"n":"第四十二条","txt":"结算参与人在结算过程中违约的，期货结算机构按照业务规则动用结算参与人的保证金、结算担保金以及结算机构的风险准备金、自有资金等完成结算；期货结算机构以其风险准备金、自有资金等完成结算的，可以依法对该结算参与人进行追偿。"},{"i":43,"n":"第四十三条","txt":"期货结算机构依照其业务规则收取和提取的保证金、权利金、结算担保金、风险准备金等资产，应当优先用于结算和交割，不得被查封、冻结、扣押或者强制执行。"},{"i":44,"n":"第四十四条","txt":"期货合约到期时，交易者应当通过实物交割或者现金交割，了结到期未平仓合约。"},{"i":45,"n":"第四十五条","txt":"期货合约采取实物交割的，由期货结算机构负责组织货款与标准仓单等合约标的物权利凭证的交付。"},{"i":46,"n":"第四十六条","txt":"期货交易的实物交割在期货交易场所指定的交割库、交割港口或者其他符合期货交易场所要求的地点进行。实物交割不得限制交割总量。采用标准仓单以外的单据凭证或者其他方式进行实物交割的，期货交易场所应当明确规定交割各方的权利和义务。"},{"i":47,"n":"第四十七条","txt":"结算参与人在交割过程中违约的，期货结算机构有权对结算参与人的标准仓单等合约标的物权利凭证进行处置。"},{"i":48,"n":"第四十八条","txt":"不符合结算参与人条件的期货经营机构可以委托结算参与人代为其客户进行结算。不符合结算参与人条件的期货经营机构与结算参与人、交易者之间的权利义务关系，参照本章关于结算参与人与交易者之间权利义务的规定执行。"},{"i":49,"n":"第四十九条","txt":"期货交易者是指依照本法从事期货交易，承担交易结果的自然人、法人和非法人组织。"},{"i":50,"n":"第五十条","txt":"期货经营机构向交易者提供服务时，应当按照规定充分了解交易者的基本情况、财产状况、金融资产状况、交易知识和经验、专业能力等相关信息；如实说明服务的重要内容，充分揭示交易风险；提供与交易者上述状况相匹配的服务。"},{"i":51,"n":"第五十一条","txt":"根据财产状况、金融资产状况、交易知识和经验、专业能力等因素，交易者可以分为普通交易者和专业交易者。专业交易者的标准由国务院期货监督管理机构规定。"},{"i":52,"n":"第五十二条","txt":"参与期货交易的法人和非法人组织，应当建立与其交易合约类型、规模、目的等相适应的内部控制制度和风险控制制度。"},{"i":53,"n":"第五十三条","txt":"期货经营机构、期货交易场所、期货结算机构的从业人员，国务院期货监督管理机构、期货业协会的工作人员，以及法律、行政法规和国务院期货监督管理机构规定禁止参与期货交易的其他人员，不得进行期货交易。"},{"i":54,"n":"第五十四条","txt":"交易者有权查询其委托记录、交易记录、保证金余额、与其接受服务有关的其他重要信息。"},{"i":55,"n":"第五十五条","txt":"期货经营机构、期货交易场所、期货结算机构、期货服务机构及其工作人员应当依法为交易者的信息保密，不得非法买卖、提供或者公开交易者的信息。"},{"i":56,"n":"第五十六条","txt":"交易者与期货经营机构等发生纠纷的，双方可以向行业协会等申请调解。普通交易者与期货经营机构发生期货业务纠纷并提出调解请求的，期货经营机构不得拒绝。"},{"i":57,"n":"第五十七条","txt":"交易者提起操纵市场、内幕交易等期货民事赔偿诉讼时，诉讼标的是同一种类，且当事人一方人数众多的，可以依法推选代表人进行诉讼。"},{"i":58,"n":"第五十八条","txt":"国家设立期货交易者保障基金。期货交易者保障基金的筹集、管理和使用的具体办法，由国务院期货监督管理机构会同国务院财政部门制定。"},{"i":59,"n":"第五十九条","txt":"期货经营机构是指依照《中华人民共和国公司法》和本法设立的期货公司以及国务院期货监督管理机构核准从事期货业务的其他机构。"},{"i":60,"n":"第六十条","txt":"设立期货公司，应当具备下列条件，并经国务院期货监督管理机构核准："},{"i":61,"n":"第六十一条","txt":"期货公司应当在其名称中标明“期货”字样，国务院期货监督管理机构另有规定的除外。"},{"i":62,"n":"第六十二条","txt":"期货公司办理下列事项，应当经国务院期货监督管理机构核准："},{"i":63,"n":"第六十三条","txt":"期货公司经国务院期货监督管理机构核准可以从事下列期货业务："},{"i":64,"n":"第六十四条","txt":"期货公司的董事、监事、高级管理人员，应当正直诚实、品行良好，熟悉期货法律、行政法规，具有履行职责所需的经营管理能力。期货公司任免董事、监事、高级管理人员，应当报国务院期货监督管理机构备案。"},{"i":65,"n":"第六十五条","txt":"期货经营机构应当依法经营，勤勉尽责，诚实守信。期货经营机构应当建立健全内部控制制度，采取有效隔离措施，防范经营机构与客户之间、不同客户之间的利益冲突。"},{"i":66,"n":"第六十六条","txt":"期货经营机构接受交易者委托为其进行期货交易，应当签订书面委托合同，以自己的名义为交易者进行期货交易，交易结果由交易者承担。"},{"i":67,"n":"第六十七条","txt":"期货经营机构从事资产管理业务，接受客户委托，运用客户资产进行投资的，应当公平对待所管理的不同客户资产，不得违背受托义务。"},{"i":68,"n":"第六十八条","txt":"期货经营机构不得违反规定为其股东、实际控制人或者股东、实际控制人的关联人提供融资或者担保，不得违反规定对外担保。"},{"i":69,"n":"第六十九条","txt":"期货经营机构从事期货业务的人员应当正直诚实、品行良好，具备从事期货业务所需的专业能力。"},{"i":70,"n":"第七十条","txt":"国务院期货监督管理机构应当制定期货经营机构持续性经营规则，对期货经营机构及其分支机构的经营条件、风险管理、内部控制、保证金存管、合规管理、风险监管指标、关联交易等方面作出规定。期货经营机构应当符合持续性经营规则。"},{"i":71,"n":"第七十一条","txt":"期货经营机构应当按照规定向国务院期货监督管理机构报送业务、财务等经营管理信息和资料。国务院期货监督管理机构有权要求期货经营机构及其主要股东、实际控制人、其他关联人在指定的期限内提供有关信息、资料。"},{"i":72,"n":"第七十二条","txt":"期货经营机构涉及重大诉讼、仲裁，股权被冻结或者用于担保，以及发生其他重大事件时，应当自该事件发生之日起五日内向国务院期货监督管理机构提交书面报告。"},{"i":73,"n":"第七十三条","txt":"期货经营机构不符合持续性经营规则或者出现经营风险的，国务院期货监督管理机构应当责令其限期改正；期货经营机构逾期未改正的，或者其行为严重危及该期货经营机构的稳健运行、损害交易者合法权益的，或者涉嫌严重违法违规正在被国务院期货监督管理机构调查的，国务院期货监督管理机构可以区别情形，对其采取下列措施："},{"i":74,"n":"第七十四条","txt":"期货经营机构违法经营或者出现重大风险，严重危害期货市场秩序、损害交易者利益的，国务院期货监督管理机构可以对该期货经营机构采取责令停业整顿、指定其他机构托管或者接管等监督管理措施。"},{"i":75,"n":"第七十五条","txt":"期货经营机构的股东有虚假出资、抽逃出资行为的，国务院期货监督管理机构应当责令其限期改正，并可责令其转让所持期货经营机构的股权。"},{"i":76,"n":"第七十六条","txt":"期货经营机构有下列情形之一的，国务院期货监督管理机构应当依法办理相关业务许可证注销手续："},{"i":77,"n":"第七十七条","txt":"国务院期货监督管理机构认为必要时，可以委托期货服务机构对期货经营机构的财务状况、内部控制状况、资产价值进行审计或者评估。具体办法由国务院期货监督管理机构会同有关主管部门制定。"},{"i":78,"n":"第七十八条","txt":"禁止期货经营机构从事下列损害交易者利益的行为："},{"i":79,"n":"第七十九条","txt":"期货交易场所应当遵循社会公共利益优先原则，为期货交易提供场所和设施，组织和监督期货交易，维护市场的公平、有序和透明，实行自律管理。"},{"i":80,"n":"第八十条","txt":"设立、变更和解散期货交易所，应当由国务院期货监督管理机构批准。"},{"i":81,"n":"第八十一条","txt":"期货交易所应当在其名称中标明“商品交易所”或者“期货交易所”等字样。其他任何单位或者个人不得使用期货交易所或者其他可能产生混淆或者误导的名称。"},{"i":82,"n":"第八十二条","txt":"期货交易所可以采取会员制或者公司制的组织形式。"},{"i":83,"n":"第八十三条","txt":"期货交易所依照法律、行政法规和国务院期货监督管理机构的规定，制定有关业务规则；其中交易规则的制定和修改应当报国务院期货监督管理机构批准。"},{"i":84,"n":"第八十四条","txt":"期货交易所的负责人由国务院期货监督管理机构提名或者任免。"},{"i":85,"n":"第八十五条","txt":"期货交易场所应当依照本法和国务院期货监督管理机构的规定，加强对交易活动的风险控制和对会员以及交易场所工作人员的监督管理，依法履行下列职责："},{"i":86,"n":"第八十六条","txt":"期货交易所的所得收益按照国家有关规定管理和使用，应当首先用于保证期货交易的场所、设施的运行和改善。"},{"i":87,"n":"第八十七条","txt":"期货交易场所应当加强对期货交易的风险监测，出现异常情况的，期货交易场所可以依照业务规则，单独或者会同期货结算机构采取下列紧急措施，并立即报告国务院期货监督管理机构："},{"i":88,"n":"第八十八条","txt":"期货交易场所应当实时公布期货交易即时行情，并按交易日制作期货市场行情表，予以公布。"},{"i":89,"n":"第八十九条","txt":"因突发性事件影响期货交易正常进行时，为维护期货交易正常秩序和市场公平，期货交易场所可以按照本法和业务规则规定采取必要的处置措施，并应当及时向国务院期货监督管理机构报告。"},{"i":90,"n":"第九十条","txt":"期货交易场所对其依照本法第八十七条、第八十九条规定采取措施造成的损失，不承担民事赔偿责任，但存在重大过错的除外。"},{"i":91,"n":"第九十一条","txt":"期货结算机构是指依法设立，为期货交易提供结算、交割服务，实行自律管理的法人。"},{"i":92,"n":"第九十二条","txt":"独立的期货结算机构的设立、变更和解散，应当经国务院期货监督管理机构批准。"},{"i":93,"n":"第九十三条","txt":"期货结算机构作为中央对手方，是结算参与人共同对手方，进行净额结算，为期货交易提供集中履约保障。"},{"i":94,"n":"第九十四条","txt":"期货结算机构履行下列职责："},{"i":95,"n":"第九十五条","txt":"期货结算机构应当按照国务院期货监督管理机构的规定，在其业务规则中规定结算参与人制度、风险控制制度、信息安全管理制度、违规违约处理制度、应急处理及临时处置措施等事项。期货结算机构制定和修改章程、业务规则，应当经国务院期货监督管理机构批准。参与期货结算，应当遵守期货结算机构制定的业务规则。"},{"i":96,"n":"第九十六条","txt":"期货结算机构应当建立流动性管理制度，保障结算活动的稳健运行。"},{"i":97,"n":"第九十七条","txt":"本法第八十四条，第八十五条第二款，第八十六条，第八十八条第三款、第四款的规定，适用于独立的期货结算机构和经批准从事期货交易结算、交割业务的证券结算机构。"},{"i":98,"n":"第九十八条","txt":"会计师事务所、律师事务所、资产评估机构、期货保证金存管机构、交割库、信息技术服务机构等期货服务机构，应当勤勉尽责、恪尽职守，按照相关业务规则为期货交易及相关活动提供服务，并按照国务院期货监督管理机构的要求提供相关资料。"},{"i":99,"n":"第九十九条","txt":"会计师事务所、律师事务所、资产评估机构等期货服务机构接受期货经营机构、期货交易场所、期货结算机构的委托出具审计报告、法律意见书等文件，应当对所依据的文件资料内容的真实性、准确性、完整性进行核查和验证。"},{"i":100,"n":"第一百条","txt":"交割库包括交割仓库和交割厂库等。交割库为期货交易的交割提供相关服务，应当符合期货交易场所规定的条件。期货交易场所应当与交割库签订协议，明确双方的权利和义务。"},{"i":101,"n":"第一百零一条","txt":"为期货交易及相关活动提供信息技术系统服务的机构，应当符合国家及期货行业信息安全相关的技术管理规定和标准，并向国务院期货监督管理机构备案。"},{"i":102,"n":"第一百零二条","txt":"期货业协会是期货行业的自律性组织，是社会团体法人。"},{"i":103,"n":"第一百零三条","txt":"期货业协会的权力机构为会员大会。"},{"i":104,"n":"第一百零四条","txt":"期货业协会履行下列职责："},{"i":105,"n":"第一百零五条","txt":"国务院期货监督管理机构依法对期货市场实行监督管理，维护期货市场公开、公平、公正，防范系统性风险，维护交易者合法权益，促进期货市场健康发展。"},{"i":106,"n":"第一百零六条","txt":"国务院期货监督管理机构依法履行职责，有权采取下列措施："},{"i":107,"n":"第一百零七条","txt":"国务院期货监督管理机构依法履行职责，进行监督检查或者调查，其监督检查、调查的人员不得少于二人，并应当出示执法证件和检查、调查、查询等相关执法文书。监督检查、调查的人员少于二人或者未出示执法证件和有关执法文书的，被检查、调查的单位或者个人有权拒绝。"},{"i":108,"n":"第一百零八条","txt":"国务院期货监督管理机构的工作人员，应当依法办事，忠于职守，公正廉洁，保守国家秘密和有关当事人的商业秘密，不得利用职务便利牟取不正当利益。"},{"i":109,"n":"第一百零九条","txt":"国务院期货监督管理机构依法履行职责，被检查、调查的单位和个人应当配合，如实作出说明或者提供有关文件和资料，不得拒绝、阻碍和隐瞒。"},{"i":110,"n":"第一百一十条","txt":"对涉嫌期货违法、违规行为，任何单位和个人有权向国务院期货监督管理机构举报。"},{"i":111,"n":"第一百一十一条","txt":"国务院期货监督管理机构制定的规章、规则和监督管理工作制度应当依法公开。"},{"i":112,"n":"第一百一十二条","txt":"国务院期货监督管理机构对涉嫌期货违法的单位或者个人进行调查期间，被调查的当事人书面申请，承诺在国务院期货监督管理机构认可的期限内纠正涉嫌违法行为，赔偿有关交易者损失，消除损害或者不良影响的，国务院期货监督管理机构可以决定中止调查。被调查的当事人履行承诺的，国务院期货监督管理机构可以决定终止调查；被调查的当事人未履行承诺或者有国务院规定的其他情形的，应当恢复调查。具体办法由国务院规定。"},{"i":113,"n":"第一百一十三条","txt":"国务院期货监督管理机构依法将有关期货市场主体遵守本法的情况纳入期货市场诚信档案。"},{"i":114,"n":"第一百一十四条","txt":"国务院期货监督管理机构依法履行职责，发现期货违法行为涉嫌犯罪的，应当依法将案件移送司法机关处理；发现公职人员涉嫌职务违法或者职务犯罪的，应当依法移送监察机关处理。"},{"i":115,"n":"第一百一十五条","txt":"国务院期货监督管理机构应当建立健全期货市场监测监控制度，通过专门机构加强保证金安全存管监控。"},{"i":116,"n":"第一百一十六条","txt":"为防范交易及结算的风险，期货经营机构、期货交易场所、期货结算机构和非期货经营机构结算参与人应当从业务收入中按照国务院期货监督管理机构、国务院财政部门的规定提取、管理和使用风险准备金。"},{"i":117,"n":"第一百一十七条","txt":"期货经营机构、期货交易场所、期货结算机构、期货服务机构和非期货经营机构结算参与人等应当按照规定妥善保存与业务经营相关的资料和信息，任何人不得泄露、隐匿、伪造、篡改或者毁损。期货经营机构、期货交易场所、期货结算机构和非期货经营机构结算参与人的信息和资料的保存期限不得少于二十年；期货服务机构的信息和资料的保存期限不得少于十年。"},{"i":118,"n":"第一百一十八条","txt":"境外期货交易场所向境内单位或者个人提供直接接入该交易场所交易系统进行交易服务的，应当向国务院期货监督管理机构申请注册，接受国务院期货监督管理机构的监督管理，国务院期货监督管理机构另有规定的除外。"},{"i":119,"n":"第一百一十九条","txt":"境外期货交易场所上市的期货合约、期权合约和衍生品合约，以境内期货交易场所上市的合约价格进行挂钩结算的，应当符合国务院期货监督管理机构的规定。"},{"i":120,"n":"第一百二十条","txt":"境内单位或者个人从事境外期货交易，应当委托具有境外期货经纪业务资格的境内期货经营机构进行，国务院另有规定的除外。"},{"i":121,"n":"第一百二十一条","txt":"境外期货交易场所在境内设立代表机构的，应当向国务院期货监督管理机构备案。"},{"i":122,"n":"第一百二十二条","txt":"境外机构在境内从事期货市场营销、推介及招揽活动，应当经国务院期货监督管理机构批准，适用本法的相关规定。"},{"i":123,"n":"第一百二十三条","txt":"国务院期货监督管理机构可以和境外期货监督管理机构建立监督管理合作机制，或者加入国际组织，实施跨境监督管理。"},{"i":124,"n":"第一百二十四条","txt":"国务院期货监督管理机构可以按照与境外期货监督管理机构达成的监管合作安排，接受境外期货监督管理机构的请求，依照本法规定的职责和程序为其进行调查取证。境外期货监督管理机构应当提供有关案件材料，并说明其正在就被调查当事人涉嫌违反请求方当地期货法律法规的行为进行调查。境外期货监督管理机构不得在中华人民共和国境内直接进行调查取证等活动。"},{"i":125,"n":"第一百二十五条","txt":"违反本法第十二条的规定，操纵期货市场或者衍生品市场的，责令改正，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足一百万元的，处以一百万元以上一千万元以下的罚款。单位操纵市场的，还应当对直接负责的主管人员和其他直接责任人员给予警告，并处以五十万元以上五百万元以下的罚款。"},{"i":126,"n":"第一百二十六条","txt":"违反本法第十三条的规定从事内幕交易的，责令改正，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款。单位从事内幕交易的，还应当对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":127,"n":"第一百二十七条","txt":"违反本法第十六条第一款、第三款的规定，编造、传播虚假信息或者误导性信息，扰乱期货市场、衍生品市场的，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足二十万元的，处以二十万元以上二百万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以十万元以上一百万元以下的罚款。"},{"i":128,"n":"第一百二十八条","txt":"违反本法第十八条第二款的规定，出借自己的期货账户或者借用他人的期货账户从事期货交易的，责令改正，给予警告，可以处五十万元以下的罚款。"},{"i":129,"n":"第一百二十九条","txt":"违反本法第二十一条的规定，采取程序化交易影响期货交易场所系统安全或者正常交易秩序的，责令改正，并处以五十万元以上五百万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以十万元以上一百万元以下的罚款。"},{"i":130,"n":"第一百三十条","txt":"违反本法第二十七条规定，未报告有关重大事项的，责令改正，给予警告，可以处一百万元以下的罚款。"},{"i":131,"n":"第一百三十一条","txt":"法律、行政法规和国务院期货监督管理机构规定禁止参与期货交易的人员，违反本法第五十三条的规定，直接或者以化名、借他人名义参与期货交易的，责令改正，给予警告，没收违法所得，并处以五万元以上五十万元以下的罚款；属于国家工作人员的，还应当依法给予处分。"},{"i":132,"n":"第一百三十二条","txt":"非法设立期货公司，或者未经核准从事相关期货业务的，予以取缔，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足一百万元的，处以一百万元以上一千万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":133,"n":"第一百三十三条","txt":"提交虚假申请文件或者采取其他欺诈手段骗取期货公司设立许可、重大事项变更核准或者期货经营机构期货业务许可的，撤销相关许可，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足二十万元的，处以二十万元以上二百万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":134,"n":"第一百三十四条","txt":"期货经营机构违反本法第四十条、第六十二条、第六十五条、第六十八条、第七十一条、第七十二条的，责令改正，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足二十万元的，处以二十万元以上二百万元以下的罚款；情节严重的，责令停业整顿或者吊销期货业务许可证。对直接负责的主管人员和其他直接责任人员给予警告，并处以五万元以上五十万元以下的罚款。"},{"i":135,"n":"第一百三十五条","txt":"期货经营机构违反本法第五十条交易者适当性管理规定，或者违反本法第六十六条规定从事经纪业务接受交易者全权委托，或者有第七十八条损害交易者利益行为的，责令改正，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款；情节严重的，吊销相关业务许可。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":136,"n":"第一百三十六条","txt":"违反本法第十一条、第八十条、第九十二条规定，非法设立期货交易场所、期货结算机构，或者以其他形式组织期货交易的，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足一百万元的，处以一百万元以上一千万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。非法设立期货交易场所的，由县级以上人民政府予以取缔。"},{"i":137,"n":"第一百三十七条","txt":"期货交易场所、期货结算机构违反本法第十七条、第四十条、第八十五条第二款规定的，责令改正，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足二十万元的，处以二十万元以上二百万元以下的罚款；情节严重的，责令停业整顿。对直接负责的主管人员和其他直接责任人员处以五万元以上五十万元以下的罚款。"},{"i":138,"n":"第一百三十八条","txt":"期货交易场所、期货结算机构违反本法第八十八条第三款规定发布价格预测信息的，责令改正，给予警告，并处以二十万元以上二百万元以下的罚款。对直接负责的主管人员和其他直接责任人员处以五万元以上五十万元以下的罚款。"},{"i":139,"n":"第一百三十九条","txt":"期货服务机构违反本法第九十八条的规定，从事期货服务业务未按照要求提供相关资料的，责令改正，可以处二十万元以下的罚款。"},{"i":140,"n":"第一百四十条","txt":"会计师事务所、律师事务所、资产评估机构等期货服务机构违反本法第九十九条的规定，未勤勉尽责，所制作、出具的文件有虚假记载、误导性陈述或者重大遗漏的，责令改正，没收业务收入，并处以业务收入一倍以上十倍以下的罚款；没有业务收入或者业务收入不足五十万元的，处以五十万元以上五百万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":141,"n":"第一百四十一条","txt":"交割库有本法第一百条所列行为之一的，责令改正，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足十万元的，处以十万元以上一百万元以下的罚款；情节严重的，责令期货交易场所暂停或者取消其交割库资格。对直接负责的主管人员和其他直接责任人员给予警告，并处以五万元以上五十万元以下的罚款。"},{"i":142,"n":"第一百四十二条","txt":"信息技术服务机构违反本法第一百零一条规定未报备案的，责令改正，可以处二十万元以下的罚款。"},{"i":143,"n":"第一百四十三条","txt":"违反本法第一百一十六条的规定，期货经营机构、期货交易场所、期货结算机构和非期货经营机构结算参与人未按照规定提取、管理和使用风险准备金的，责令改正，给予警告。对直接负责的主管人员和其他直接责任人员给予警告，并处以十万元以上一百万元以下的罚款。"},{"i":144,"n":"第一百四十四条","txt":"违反本法第一百一十七条的规定，期货经营机构、期货交易场所、期货结算机构、期货服务机构和非期货经营机构结算参与人等未按照规定妥善保存与业务经营相关的资料和信息的，责令改正，给予警告，并处以十万元以上一百万元以下的罚款；泄露、隐匿、伪造、篡改或者毁损有关文件资料的，责令改正，给予警告，并处以二十万元以上二百万元以下的罚款；情节严重的，处以五十万元以上五百万元以下的罚款，并暂停、吊销相关业务许可或者禁止从事相关业务。对直接负责的主管人员和其他直接责任人员给予警告，并处以十万元以上一百万元以下的罚款。"},{"i":145,"n":"第一百四十五条","txt":"境外期货交易场所和期货经营机构违反本法第一百一十八条和第一百二十条的规定，未向国务院期货监督管理机构申请注册的，责令改正，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以十万元以上一百万元以下的罚款。"},{"i":146,"n":"第一百四十六条","txt":"境内单位或者个人违反本法第一百二十条第一款规定的，责令改正，给予警告，没收违法所得，并处以十万元以上一百万元以下的罚款；情节严重的，暂停其境外期货交易。对直接负责的主管人员和其他直接责任人员给予警告，并处以五万元以上五十万元以下的罚款。"},{"i":147,"n":"第一百四十七条","txt":"境外期货交易场所在境内设立的代表机构及其工作人员违反本法第一百二十一条的规定，从事或者变相从事任何经营活动的，责令改正，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以十万元以上一百万元以下的罚款。"},{"i":148,"n":"第一百四十八条","txt":"违反本法第一百二十二条的规定在境内从事市场营销、推介及招揽活动的，责令改正，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以十万元以上一百万元以下的罚款。"},{"i":149,"n":"第一百四十九条","txt":"拒绝、阻碍国务院期货监督管理机构或者国务院授权的部门及其工作人员依法行使监督检查、调查职权的，责令改正，处以十万元以上一百万元以下的罚款，并由公安机关依法给予治安管理处罚。"},{"i":150,"n":"第一百五十条","txt":"违反法律、行政法规或者国务院期货监督管理机构的有关规定，情节严重的，国务院期货监督管理机构可以对有关责任人员采取期货市场禁入的措施。"},{"i":151,"n":"第一百五十一条","txt":"本法规定的行政处罚，由国务院期货监督管理机构、国务院授权的部门按照国务院规定的职责分工作出决定；法律、行政法规另有规定的，适用其规定。"},{"i":152,"n":"第一百五十二条","txt":"国务院期货监督管理机构或者国务院授权的部门的工作人员，不履行本法规定的职责，滥用职权、玩忽职守，利用职务便利牟取不正当利益，或者泄露所知悉的有关单位和个人的商业秘密的，依法追究法律责任。"},{"i":153,"n":"第一百五十三条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":154,"n":"第一百五十四条","txt":"违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金、违法所得，违法行为人的财产不足以支付的，优先用于承担民事赔偿责任。"},{"i":155,"n":"第一百五十五条","txt":"本法自2022年8月1日起施行。"}],"minfadian":[{"i":1,"n":"第一条","txt":"为了保护民事主体的合法权益，调整民事关系，维护社会和经济秩序，适应中国特色社会主义发展要求，弘扬社会主义核心价值观，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"民法调整平等主体的自然人、法人和非法人组织之间的人身关系和财产关系。"},{"i":3,"n":"第三条","txt":"民事主体的人身权利、财产权利以及其他合法权益受法律保护，任何组织或者个人不得侵犯。"},{"i":4,"n":"第四条","txt":"民事主体在民事活动中的法律地位一律平等。"},{"i":5,"n":"第五条","txt":"民事主体从事民事活动，应当遵循自愿原则，按照自己的意思设立、变更、终止民事法律关系。"},{"i":6,"n":"第六条","txt":"民事主体从事民事活动，应当遵循公平原则，合理确定各方的权利和义务。"},{"i":7,"n":"第七条","txt":"民事主体从事民事活动，应当遵循诚信原则，秉持诚实，恪守承诺。"},{"i":8,"n":"第八条","txt":"民事主体从事民事活动，不得违反法律，不得违背公序良俗。"},{"i":9,"n":"第九条","txt":"民事主体从事民事活动，应当有利于节约资源、保护生态环境。"},{"i":10,"n":"第十条","txt":"处理民事纠纷，应当依照法律；法律没有规定的，可以适用习惯，但是不得违背公序良俗。"},{"i":11,"n":"第十一条","txt":"其他法律对民事关系有特别规定的，依照其规定。"},{"i":12,"n":"第十二条","txt":"中华人民共和国领域内的民事活动，适用中华人民共和国法律。法律另有规定的，依照其规定。"},{"i":13,"n":"第十三条","txt":"自然人从出生时起到死亡时止，具有民事权利能力，依法享有民事权利，承担民事义务。"},{"i":14,"n":"第十四条","txt":"自然人的民事权利能力一律平等。"},{"i":15,"n":"第十五条","txt":"自然人的出生时间和死亡时间，以出生证明、死亡证明记载的时间为准；没有出生证明、死亡证明的，以户籍登记或者其他有效身份登记记载的时间为准。有其他证据足以推翻以上记载时间的，以该证据证明的时间为准。"},{"i":16,"n":"第十六条","txt":"涉及遗产继承、接受赠与等胎儿利益保护的，胎儿视为具有民事权利能力。但是，胎儿娩出时为死体的，其民事权利能力自始不存在。"},{"i":17,"n":"第十七条","txt":"十八周岁以上的自然人为成年人。不满十八周岁的自然人为未成年人。"},{"i":18,"n":"第十八条","txt":"成年人为完全民事行为能力人，可以独立实施民事法律行为。"},{"i":19,"n":"第十九条","txt":"八周岁以上的未成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或者经其法定代理人同意、追认；但是，可以独立实施纯获利益的民事法律行为或者与其年龄、智力相适应的民事法律行为。"},{"i":20,"n":"第二十条","txt":"不满八周岁的未成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。"},{"i":21,"n":"第二十一条","txt":"不能辨认自己行为的成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。"},{"i":22,"n":"第二十二条","txt":"不能完全辨认自己行为的成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或者经其法定代理人同意、追认；但是，可以独立实施纯获利益的民事法律行为或者与其智力、精神健康状况相适应的民事法律行为。"},{"i":23,"n":"第二十三条","txt":"无民事行为能力人、限制民事行为能力人的监护人是其法定代理人。"},{"i":24,"n":"第二十四条","txt":"不能辨认或者不能完全辨认自己行为的成年人，其利害关系人或者有关组织，可以向人民法院申请认定该成年人为无民事行为能力人或者限制民事行为能力人。"},{"i":25,"n":"第二十五条","txt":"自然人以户籍登记或者其他有效身份登记记载的居所为住所；经常居所与住所不一致的，经常居所视为住所。"},{"i":26,"n":"第二十六条","txt":"父母对未成年子女负有抚养、教育和保护的义务。"},{"i":27,"n":"第二十七条","txt":"父母是未成年子女的监护人。"},{"i":28,"n":"第二十八条","txt":"无民事行为能力或者限制民事行为能力的成年人，由下列有监护能力的人按顺序担任监护人："},{"i":29,"n":"第二十九条","txt":"被监护人的父母担任监护人的，可以通过遗嘱指定监护人。"},{"i":30,"n":"第三十条","txt":"依法具有监护资格的人之间可以协议确定监护人。协议确定监护人应当尊重被监护人的真实意愿。"},{"i":31,"n":"第三十一条","txt":"对监护人的确定有争议的，由被监护人住所地的居民委员会、村民委员会或者民政部门指定监护人，有关当事人对指定不服的，可以向人民法院申请指定监护人；有关当事人也可以直接向人民法院申请指定监护人。"},{"i":32,"n":"第三十二条","txt":"没有依法具有监护资格的人的，监护人由民政部门担任，也可以由具备履行监护职责条件的被监护人住所地的居民委员会、村民委员会担任。"},{"i":33,"n":"第三十三条","txt":"具有完全民事行为能力的成年人，可以与其近亲属、其他愿意担任监护人的个人或者组织事先协商，以书面形式确定自己的监护人，在自己丧失或者部分丧失民事行为能力时，由该监护人履行监护职责。"},{"i":34,"n":"第三十四条","txt":"监护人的职责是代理被监护人实施民事法律行为，保护被监护人的人身权利、财产权利以及其他合法权益等。"},{"i":35,"n":"第三十五条","txt":"监护人应当按照最有利于被监护人的原则履行监护职责。监护人除为维护被监护人利益外，不得处分被监护人的财产。"},{"i":36,"n":"第三十六条","txt":"监护人有下列情形之一的，人民法院根据有关个人或者组织的申请，撤销其监护人资格，安排必要的临时监护措施，并按照最有利于被监护人的原则依法指定监护人："},{"i":37,"n":"第三十七条","txt":"依法负担被监护人抚养费、赡养费、扶养费的父母、子女、配偶等，被人民法院撤销监护人资格后，应当继续履行负担的义务。"},{"i":38,"n":"第三十八条","txt":"被监护人的父母或者子女被人民法院撤销监护人资格后，除对被监护人实施故意犯罪的外，确有悔改表现的，经其申请，人民法院可以在尊重被监护人真实意愿的前提下，视情况恢复其监护人资格，人民法院指定的监护人与被监护人的监护关系同时终止。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一的，监护关系终止："},{"i":40,"n":"第四十条","txt":"自然人下落不明满二年的，利害关系人可以向人民法院申请宣告该自然人为失踪人。"},{"i":41,"n":"第四十一条","txt":"自然人下落不明的时间自其失去音讯之日起计算。战争期间下落不明的，下落不明的时间自战争结束之日或者有关机关确定的下落不明之日起计算。"},{"i":42,"n":"第四十二条","txt":"失踪人的财产由其配偶、成年子女、父母或者其他愿意担任财产代管人的人代管。"},{"i":43,"n":"第四十三条","txt":"财产代管人应当妥善管理失踪人的财产，维护其财产权益。"},{"i":44,"n":"第四十四条","txt":"财产代管人不履行代管职责、侵害失踪人财产权益或者丧失代管能力的，失踪人的利害关系人可以向人民法院申请变更财产代管人。"},{"i":45,"n":"第四十五条","txt":"失踪人重新出现，经本人或者利害关系人申请，人民法院应当撤销失踪宣告。"},{"i":46,"n":"第四十六条","txt":"自然人有下列情形之一的，利害关系人可以向人民法院申请宣告该自然人死亡："},{"i":47,"n":"第四十七条","txt":"对同一自然人，有的利害关系人申请宣告死亡，有的利害关系人申请宣告失踪，符合本法规定的宣告死亡条件的，人民法院应当宣告死亡。"},{"i":48,"n":"第四十八条","txt":"被宣告死亡的人，人民法院宣告死亡的判决作出之日视为其死亡的日期；因意外事件下落不明宣告死亡的，意外事件发生之日视为其死亡的日期。"},{"i":49,"n":"第四十九条","txt":"自然人被宣告死亡但是并未死亡的，不影响该自然人在被宣告死亡期间实施的民事法律行为的效力。"},{"i":50,"n":"第五十条","txt":"被宣告死亡的人重新出现，经本人或者利害关系人申请，人民法院应当撤销死亡宣告。"},{"i":51,"n":"第五十一条","txt":"被宣告死亡的人的婚姻关系，自死亡宣告之日起消除。死亡宣告被撤销的，婚姻关系自撤销死亡宣告之日起自行恢复。但是，其配偶再婚或者向婚姻登记机关书面声明不愿意恢复的除外。"},{"i":52,"n":"第五十二条","txt":"被宣告死亡的人在被宣告死亡期间，其子女被他人依法收养的，在死亡宣告被撤销后，不得以未经本人同意为由主张收养行为无效。"},{"i":53,"n":"第五十三条","txt":"被撤销死亡宣告的人有权请求依照本法第六编取得其财产的民事主体返还财产；无法返还的，应当给予适当补偿。"},{"i":54,"n":"第五十四条","txt":"自然人从事工商业经营，经依法登记，为个体工商户。个体工商户可以起字号。"},{"i":55,"n":"第五十五条","txt":"农村集体经济组织的成员，依法取得农村土地承包经营权，从事家庭承包经营的，为农村承包经营户。"},{"i":56,"n":"第五十六条","txt":"个体工商户的债务，个人经营的，以个人财产承担；家庭经营的，以家庭财产承担；无法区分的，以家庭财产承担。"},{"i":57,"n":"第五十七条","txt":"法人是具有民事权利能力和民事行为能力，依法独立享有民事权利和承担民事义务的组织。"},{"i":58,"n":"第五十八条","txt":"法人应当依法成立。"},{"i":59,"n":"第五十九条","txt":"法人的民事权利能力和民事行为能力，从法人成立时产生，到法人终止时消灭。"},{"i":60,"n":"第六十条","txt":"法人以其全部财产独立承担民事责任。"},{"i":61,"n":"第六十一条","txt":"依照法律或者法人章程的规定，代表法人从事民事活动的负责人，为法人的法定代表人。"},{"i":62,"n":"第六十二条","txt":"法定代表人因执行职务造成他人损害的，由法人承担民事责任。"},{"i":63,"n":"第六十三条","txt":"法人以其主要办事机构所在地为住所。依法需要办理法人登记的，应当将主要办事机构所在地登记为住所。"},{"i":64,"n":"第六十四条","txt":"法人存续期间登记事项发生变化的，应当依法向登记机关申请变更登记。"},{"i":65,"n":"第六十五条","txt":"法人的实际情况与登记的事项不一致的，不得对抗善意相对人。"},{"i":66,"n":"第六十六条","txt":"登记机关应当依法及时公示法人登记的有关信息。"},{"i":67,"n":"第六十七条","txt":"法人合并的，其权利和义务由合并后的法人享有和承担。"},{"i":68,"n":"第六十八条","txt":"有下列原因之一并依法完成清算、注销登记的，法人终止："},{"i":69,"n":"第六十九条","txt":"有下列情形之一的，法人解散："},{"i":70,"n":"第七十条","txt":"法人解散的，除合并或者分立的情形外，清算义务人应当及时组成清算组进行清算。"},{"i":71,"n":"第七十一条","txt":"法人的清算程序和清算组职权，依照有关法律的规定；没有规定的，参照适用公司法律的有关规定。"},{"i":72,"n":"第七十二条","txt":"清算期间法人存续，但是不得从事与清算无关的活动。"},{"i":73,"n":"第七十三条","txt":"法人被宣告破产的，依法进行破产清算并完成法人注销登记时，法人终止。"},{"i":74,"n":"第七十四条","txt":"法人可以依法设立分支机构。法律、行政法规规定分支机构应当登记的，依照其规定。"},{"i":75,"n":"第七十五条","txt":"设立人为设立法人从事的民事活动，其法律后果由法人承受；法人未成立的，其法律后果由设立人承受，设立人为二人以上的，享有连带债权，承担连带债务。"},{"i":76,"n":"第七十六条","txt":"以取得利润并分配给股东等出资人为目的成立的法人，为营利法人。"},{"i":77,"n":"第七十七条","txt":"营利法人经依法登记成立。"},{"i":78,"n":"第七十八条","txt":"依法设立的营利法人，由登记机关发给营利法人营业执照。营业执照签发日期为营利法人的成立日期。"},{"i":79,"n":"第七十九条","txt":"设立营利法人应当依法制定法人章程。"},{"i":80,"n":"第八十条","txt":"营利法人应当设权力机构。"},{"i":81,"n":"第八十一条","txt":"营利法人应当设执行机构。"},{"i":82,"n":"第八十二条","txt":"营利法人设监事会或者监事等监督机构的，监督机构依法行使检查法人财务，监督执行机构成员、高级管理人员执行法人职务的行为，以及法人章程规定的其他职权。"},{"i":83,"n":"第八十三条","txt":"营利法人的出资人不得滥用出资人权利损害法人或者其他出资人的利益；滥用出资人权利造成法人或者其他出资人损失的，应当依法承担民事责任。"},{"i":84,"n":"第八十四条","txt":"营利法人的控股出资人、实际控制人、董事、监事、高级管理人员不得利用其关联关系损害法人的利益；利用关联关系造成法人损失的，应当承担赔偿责任。"},{"i":85,"n":"第八十五条","txt":"营利法人的权力机构、执行机构作出决议的会议召集程序、表决方式违反法律、行政法规、法人章程，或者决议内容违反法人章程的，营利法人的出资人可以请求人民法院撤销该决议。但是，营利法人依据该决议与善意相对人形成的民事法律关系不受影响。"},{"i":86,"n":"第八十六条","txt":"营利法人从事经营活动，应当遵守商业道德，维护交易安全，接受政府和社会的监督，承担社会责任。"},{"i":87,"n":"第八十七条","txt":"为公益目的或者其他非营利目的成立，不向出资人、设立人或者会员分配所取得利润的法人，为非营利法人。"},{"i":88,"n":"第八十八条","txt":"具备法人条件，为适应经济社会发展需要，提供公益服务设立的事业单位，经依法登记成立，取得事业单位法人资格；依法不需要办理法人登记的，从成立之日起，具有事业单位法人资格。"},{"i":89,"n":"第八十九条","txt":"事业单位法人设理事会的，除法律另有规定外，理事会为其决策机构。事业单位法人的法定代表人依照法律、行政法规或者法人章程的规定产生。"},{"i":90,"n":"第九十条","txt":"具备法人条件，基于会员共同意愿，为公益目的或者会员共同利益等非营利目的设立的社会团体，经依法登记成立，取得社会团体法人资格；依法不需要办理法人登记的，从成立之日起，具有社会团体法人资格。"},{"i":91,"n":"第九十一条","txt":"设立社会团体法人应当依法制定法人章程。"},{"i":92,"n":"第九十二条","txt":"具备法人条件，为公益目的以捐助财产设立的基金会、社会服务机构等，经依法登记成立，取得捐助法人资格。"},{"i":93,"n":"第九十三条","txt":"设立捐助法人应当依法制定法人章程。"},{"i":94,"n":"第九十四条","txt":"捐助人有权向捐助法人查询捐助财产的使用、管理情况，并提出意见和建议，捐助法人应当及时、如实答复。"},{"i":95,"n":"第九十五条","txt":"为公益目的成立的非营利法人终止时，不得向出资人、设立人或者会员分配剩余财产。剩余财产应当按照法人章程的规定或者权力机构的决议用于公益目的；无法按照法人章程的规定或者权力机构的决议处理的，由主管机关主持转给宗旨相同或者相近的法人，并向社会公告。"},{"i":96,"n":"第九十六条","txt":"本节规定的机关法人、农村集体经济组织法人、城镇农村的合作经济组织法人、基层群众性自治组织法人，为特别法人。"},{"i":97,"n":"第九十七条","txt":"有独立经费的机关和承担行政职能的法定机构从成立之日起，具有机关法人资格，可以从事为履行职能所需要的民事活动。"},{"i":98,"n":"第九十八条","txt":"机关法人被撤销的，法人终止，其民事权利和义务由继任的机关法人享有和承担；没有继任的机关法人的，由作出撤销决定的机关法人享有和承担。"},{"i":99,"n":"第九十九条","txt":"农村集体经济组织依法取得法人资格。"},{"i":100,"n":"第一百条","txt":"城镇农村的合作经济组织依法取得法人资格。"},{"i":101,"n":"第一百零一条","txt":"居民委员会、村民委员会具有基层群众性自治组织法人资格，可以从事为履行职能所需要的民事活动。"},{"i":102,"n":"第一百零二条","txt":"非法人组织是不具有法人资格，但是能够依法以自己的名义从事民事活动的组织。"},{"i":103,"n":"第一百零三条","txt":"非法人组织应当依照法律的规定登记。"},{"i":104,"n":"第一百零四条","txt":"非法人组织的财产不足以清偿债务的，其出资人或者设立人承担无限责任。法律另有规定的，依照其规定。"},{"i":105,"n":"第一百零五条","txt":"非法人组织可以确定一人或者数人代表该组织从事民事活动。"},{"i":106,"n":"第一百零六条","txt":"有下列情形之一的，非法人组织解散："},{"i":107,"n":"第一百零七条","txt":"非法人组织解散的，应当依法进行清算。"},{"i":108,"n":"第一百零八条","txt":"非法人组织除适用本章规定外，参照适用本编第三章第一节的有关规定。"},{"i":109,"n":"第一百零九条","txt":"自然人的人身自由、人格尊严受法律保护。"},{"i":110,"n":"第一百一十条","txt":"自然人享有生命权、身体权、健康权、姓名权、肖像权、名誉权、荣誉权、隐私权、婚姻自主权等权利。"},{"i":111,"n":"第一百一十一条","txt":"自然人的个人信息受法律保护。任何组织或者个人需要获取他人个人信息的，应当依法取得并确保信息安全，不得非法收集、使用、加工、传输他人个人信息，不得非法买卖、提供或者公开他人个人信息。"},{"i":112,"n":"第一百一十二条","txt":"自然人因婚姻家庭关系等产生的人身权利受法律保护。"},{"i":113,"n":"第一百一十三条","txt":"民事主体的财产权利受法律平等保护。"},{"i":114,"n":"第一百一十四条","txt":"民事主体依法享有物权。"},{"i":115,"n":"第一百一十五条","txt":"物包括不动产和动产。法律规定权利作为物权客体的，依照其规定。"},{"i":116,"n":"第一百一十六条","txt":"物权的种类和内容，由法律规定。"},{"i":117,"n":"第一百一十七条","txt":"为了公共利益的需要，依照法律规定的权限和程序征收、征用不动产或者动产的，应当给予公平、合理的补偿。"},{"i":118,"n":"第一百一十八条","txt":"民事主体依法享有债权。"},{"i":119,"n":"第一百一十九条","txt":"依法成立的合同，对当事人具有法律约束力。"},{"i":120,"n":"第一百二十条","txt":"民事权益受到侵害的，被侵权人有权请求侵权人承担侵权责任。"},{"i":121,"n":"第一百二十一条","txt":"没有法定的或者约定的义务，为避免他人利益受损失而进行管理的人，有权请求受益人偿还由此支出的必要费用。"},{"i":122,"n":"第一百二十二条","txt":"因他人没有法律根据，取得不当利益，受损失的人有权请求其返还不当利益。"},{"i":123,"n":"第一百二十三条","txt":"民事主体依法享有知识产权。"},{"i":124,"n":"第一百二十四条","txt":"自然人依法享有继承权。"},{"i":125,"n":"第一百二十五条","txt":"民事主体依法享有股权和其他投资性权利。"},{"i":126,"n":"第一百二十六条","txt":"民事主体享有法律规定的其他民事权利和利益。"},{"i":127,"n":"第一百二十七条","txt":"法律对数据、网络虚拟财产的保护有规定的，依照其规定。"},{"i":128,"n":"第一百二十八条","txt":"法律对未成年人、老年人、残疾人、妇女、消费者等的民事权利保护有特别规定的，依照其规定。"},{"i":129,"n":"第一百二十九条","txt":"民事权利可以依据民事法律行为、事实行为、法律规定的事件或者法律规定的其他方式取得。"},{"i":130,"n":"第一百三十条","txt":"民事主体按照自己的意愿依法行使民事权利，不受干涉。"},{"i":131,"n":"第一百三十一条","txt":"民事主体行使权利时，应当履行法律规定的和当事人约定的义务。"},{"i":132,"n":"第一百三十二条","txt":"民事主体不得滥用民事权利损害国家利益、社会公共利益或者他人合法权益。"},{"i":133,"n":"第一百三十三条","txt":"民事法律行为是民事主体通过意思表示设立、变更、终止民事法律关系的行为。"},{"i":134,"n":"第一百三十四条","txt":"民事法律行为可以基于双方或者多方的意思表示一致成立，也可以基于单方的意思表示成立。"},{"i":135,"n":"第一百三十五条","txt":"民事法律行为可以采用书面形式、口头形式或者其他形式；法律、行政法规规定或者当事人约定采用特定形式的，应当采用特定形式。"},{"i":136,"n":"第一百三十六条","txt":"民事法律行为自成立时生效，但是法律另有规定或者当事人另有约定的除外。"},{"i":137,"n":"第一百三十七条","txt":"以对话方式作出的意思表示，相对人知道其内容时生效。"},{"i":138,"n":"第一百三十八条","txt":"无相对人的意思表示，表示完成时生效。法律另有规定的，依照其规定。"},{"i":139,"n":"第一百三十九条","txt":"以公告方式作出的意思表示，公告发布时生效。"},{"i":140,"n":"第一百四十条","txt":"行为人可以明示或者默示作出意思表示。"},{"i":141,"n":"第一百四十一条","txt":"行为人可以撤回意思表示。撤回意思表示的通知应当在意思表示到达相对人前或者与意思表示同时到达相对人。"},{"i":142,"n":"第一百四十二条","txt":"有相对人的意思表示的解释，应当按照所使用的词句，结合相关条款、行为的性质和目的、习惯以及诚信原则，确定意思表示的含义。"},{"i":143,"n":"第一百四十三条","txt":"具备下列条件的民事法律行为有效："},{"i":144,"n":"第一百四十四条","txt":"无民事行为能力人实施的民事法律行为无效。"},{"i":145,"n":"第一百四十五条","txt":"限制民事行为能力人实施的纯获利益的民事法律行为或者与其年龄、智力、精神健康状况相适应的民事法律行为有效；实施的其他民事法律行为经法定代理人同意或者追认后有效。"},{"i":146,"n":"第一百四十六条","txt":"行为人与相对人以虚假的意思表示实施的民事法律行为无效。"},{"i":147,"n":"第一百四十七条","txt":"基于重大误解实施的民事法律行为，行为人有权请求人民法院或者仲裁机构予以撤销。"},{"i":148,"n":"第一百四十八条","txt":"一方以欺诈手段，使对方在违背真实意思的情况下实施的民事法律行为，受欺诈方有权请求人民法院或者仲裁机构予以撤销。"},{"i":149,"n":"第一百四十九条","txt":"第三人实施欺诈行为，使一方在违背真实意思的情况下实施的民事法律行为，对方知道或者应当知道该欺诈行为的，受欺诈方有权请求人民法院或者仲裁机构予以撤销。"},{"i":150,"n":"第一百五十条","txt":"一方或者第三人以胁迫手段，使对方在违背真实意思的情况下实施的民事法律行为，受胁迫方有权请求人民法院或者仲裁机构予以撤销。"},{"i":151,"n":"第一百五十一条","txt":"一方利用对方处于危困状态、缺乏判断能力等情形，致使民事法律行为成立时显失公平的，受损害方有权请求人民法院或者仲裁机构予以撤销。"},{"i":152,"n":"第一百五十二条","txt":"有下列情形之一的，撤销权消灭："},{"i":153,"n":"第一百五十三条","txt":"违反法律、行政法规的强制性规定的民事法律行为无效。但是，该强制性规定不导致该民事法律行为无效的除外。"},{"i":154,"n":"第一百五十四条","txt":"行为人与相对人恶意串通，损害他人合法权益的民事法律行为无效。"},{"i":155,"n":"第一百五十五条","txt":"无效的或者被撤销的民事法律行为自始没有法律约束力。"},{"i":156,"n":"第一百五十六条","txt":"民事法律行为部分无效，不影响其他部分效力的，其他部分仍然有效。"},{"i":157,"n":"第一百五十七条","txt":"民事法律行为无效、被撤销或者确定不发生效力后，行为人因该行为取得的财产，应当予以返还；不能返还或者没有必要返还的，应当折价补偿。有过错的一方应当赔偿对方由此所受到的损失；各方都有过错的，应当各自承担相应的责任。法律另有规定的，依照其规定。"},{"i":158,"n":"第一百五十八条","txt":"民事法律行为可以附条件，但是根据其性质不得附条件的除外。附生效条件的民事法律行为，自条件成就时生效。附解除条件的民事法律行为，自条件成就时失效。"},{"i":159,"n":"第一百五十九条","txt":"附条件的民事法律行为，当事人为自己的利益不正当地阻止条件成就的，视为条件已经成就；不正当地促成条件成就的，视为条件不成就。"},{"i":160,"n":"第一百六十条","txt":"民事法律行为可以附期限，但是根据其性质不得附期限的除外。附生效期限的民事法律行为，自期限届至时生效。附终止期限的民事法律行为，自期限届满时失效。"},{"i":161,"n":"第一百六十一条","txt":"民事主体可以通过代理人实施民事法律行为。"},{"i":162,"n":"第一百六十二条","txt":"代理人在代理权限内，以被代理人名义实施的民事法律行为，对被代理人发生效力。"},{"i":163,"n":"第一百六十三条","txt":"代理包括委托代理和法定代理。"},{"i":164,"n":"第一百六十四条","txt":"代理人不履行或者不完全履行职责，造成被代理人损害的，应当承担民事责任。"},{"i":165,"n":"第一百六十五条","txt":"委托代理授权采用书面形式的，授权委托书应当载明代理人的姓名或者名称、代理事项、权限和期限，并由被代理人签名或者盖章。"},{"i":166,"n":"第一百六十六条","txt":"数人为同一代理事项的代理人的，应当共同行使代理权，但是当事人另有约定的除外。"},{"i":167,"n":"第一百六十七条","txt":"代理人知道或者应当知道代理事项违法仍然实施代理行为，或者被代理人知道或者应当知道代理人的代理行为违法未作反对表示的，被代理人和代理人应当承担连带责任。"},{"i":168,"n":"第一百六十八条","txt":"代理人不得以被代理人的名义与自己实施民事法律行为，但是被代理人同意或者追认的除外。"},{"i":169,"n":"第一百六十九条","txt":"代理人需要转委托第三人代理的，应当取得被代理人的同意或者追认。"},{"i":170,"n":"第一百七十条","txt":"执行法人或者非法人组织工作任务的人员，就其职权范围内的事项，以法人或者非法人组织的名义实施的民事法律行为，对法人或者非法人组织发生效力。"},{"i":171,"n":"第一百七十一条","txt":"行为人没有代理权、超越代理权或者代理权终止后，仍然实施代理行为，未经被代理人追认的，对被代理人不发生效力。"},{"i":172,"n":"第一百七十二条","txt":"行为人没有代理权、超越代理权或者代理权终止后，仍然实施代理行为，相对人有理由相信行为人有代理权的，代理行为有效。"},{"i":173,"n":"第一百七十三条","txt":"有下列情形之一的，委托代理终止："},{"i":174,"n":"第一百七十四条","txt":"被代理人死亡后，有下列情形之一的，委托代理人实施的代理行为有效："},{"i":175,"n":"第一百七十五条","txt":"有下列情形之一的，法定代理终止："},{"i":176,"n":"第一百七十六条","txt":"民事主体依照法律规定或者按照当事人约定，履行民事义务，承担民事责任。"},{"i":177,"n":"第一百七十七条","txt":"二人以上依法承担按份责任，能够确定责任大小的，各自承担相应的责任；难以确定责任大小的，平均承担责任。"},{"i":178,"n":"第一百七十八条","txt":"二人以上依法承担连带责任的，权利人有权请求部分或者全部连带责任人承担责任。"},{"i":179,"n":"第一百七十九条","txt":"承担民事责任的方式主要有："},{"i":180,"n":"第一百八十条","txt":"因不可抗力不能履行民事义务的，不承担民事责任。法律另有规定的，依照其规定。"},{"i":181,"n":"第一百八十一条","txt":"因正当防卫造成损害的，不承担民事责任。"},{"i":182,"n":"第一百八十二条","txt":"因紧急避险造成损害的，由引起险情发生的人承担民事责任。"},{"i":183,"n":"第一百八十三条","txt":"因保护他人民事权益使自己受到损害的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任，受害人请求补偿的，受益人应当给予适当补偿。"},{"i":184,"n":"第一百八十四条","txt":"因自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任。"},{"i":185,"n":"第一百八十五条","txt":"侵害英雄烈士等的姓名、肖像、名誉、荣誉，损害社会公共利益的，应当承担民事责任。"},{"i":186,"n":"第一百八十六条","txt":"因当事人一方的违约行为，损害对方人身权益、财产权益的，受损害方有权选择请求其承担违约责任或者侵权责任。"},{"i":187,"n":"第一百八十七条","txt":"民事主体因同一行为应当承担民事责任、行政责任和刑事责任的，承担行政责任或者刑事责任不影响承担民事责任；民事主体的财产不足以支付的，优先用于承担民事责任。"},{"i":188,"n":"第一百八十八条","txt":"向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。"},{"i":189,"n":"第一百八十九条","txt":"当事人约定同一债务分期履行的，诉讼时效期间自最后一期履行期限届满之日起计算。"},{"i":190,"n":"第一百九十条","txt":"无民事行为能力人或者限制民事行为能力人对其法定代理人的请求权的诉讼时效期间，自该法定代理终止之日起计算。"},{"i":191,"n":"第一百九十一条","txt":"未成年人遭受性侵害的损害赔偿请求权的诉讼时效期间，自受害人年满十八周岁之日起计算。"},{"i":192,"n":"第一百九十二条","txt":"诉讼时效期间届满的，义务人可以提出不履行义务的抗辩。"},{"i":193,"n":"第一百九十三条","txt":"人民法院不得主动适用诉讼时效的规定。"},{"i":194,"n":"第一百九十四条","txt":"在诉讼时效期间的最后六个月内，因下列障碍，不能行使请求权的，诉讼时效中止："},{"i":195,"n":"第一百九十五条","txt":"有下列情形之一的，诉讼时效中断，从中断、有关程序终结时起，诉讼时效期间重新计算："},{"i":196,"n":"第一百九十六条","txt":"下列请求权不适用诉讼时效的规定："},{"i":197,"n":"第一百九十七条","txt":"诉讼时效的期间、计算方法以及中止、中断的事由由法律规定，当事人约定无效。"},{"i":198,"n":"第一百九十八条","txt":"法律对仲裁时效有规定的，依照其规定；没有规定的，适用诉讼时效的规定。"},{"i":199,"n":"第一百九十九条","txt":"法律规定或者当事人约定的撤销权、解除权等权利的存续期间，除法律另有规定外，自权利人知道或者应当知道权利产生之日起计算，不适用有关诉讼时效中止、中断和延长的规定。存续期间届满，撤销权、解除权等权利消灭。"},{"i":200,"n":"第二百条","txt":"民法所称的期间按照公历年、月、日、小时计算。"},{"i":201,"n":"第二百零一条","txt":"按照年、月、日计算期间的，开始的当日不计入，自下一日开始计算。"},{"i":202,"n":"第二百零二条","txt":"按照年、月计算期间的，到期月的对应日为期间的最后一日；没有对应日的，月末日为期间的最后一日。"},{"i":203,"n":"第二百零三条","txt":"期间的最后一日是法定休假日的，以法定休假日结束的次日为期间的最后一日。"},{"i":204,"n":"第二百零四条","txt":"期间的计算方法依照本法的规定，但是法律另有规定或者当事人另有约定的除外。"},{"i":205,"n":"第二百零五条","txt":"本编调整因物的归属和利用产生的民事关系。"},{"i":206,"n":"第二百零六条","txt":"国家坚持和完善公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制等社会主义基本经济制度。"},{"i":207,"n":"第二百零七条","txt":"国家、集体、私人的物权和其他权利人的物权受法律平等保护，任何组织或者个人不得侵犯。"},{"i":208,"n":"第二百零八条","txt":"不动产物权的设立、变更、转让和消灭，应当依照法律规定登记。动产物权的设立和转让，应当依照法律规定交付。"},{"i":209,"n":"第二百零九条","txt":"不动产物权的设立、变更、转让和消灭，经依法登记，发生效力；未经登记，不发生效力，但是法律另有规定的除外。"},{"i":210,"n":"第二百一十条","txt":"不动产登记，由不动产所在地的登记机构办理。"},{"i":211,"n":"第二百一十一条","txt":"当事人申请登记，应当根据不同登记事项提供权属证明和不动产界址、面积等必要材料。"},{"i":212,"n":"第二百一十二条","txt":"登记机构应当履行下列职责："},{"i":213,"n":"第二百一十三条","txt":"登记机构不得有下列行为："},{"i":214,"n":"第二百一十四条","txt":"不动产物权的设立、变更、转让和消灭，依照法律规定应当登记的，自记载于不动产登记簿时发生效力。"},{"i":215,"n":"第二百一十五条","txt":"当事人之间订立有关设立、变更、转让和消灭不动产物权的合同，除法律另有规定或者当事人另有约定外，自合同成立时生效；未办理物权登记的，不影响合同效力。"},{"i":216,"n":"第二百一十六条","txt":"不动产登记簿是物权归属和内容的根据。"},{"i":217,"n":"第二百一十七条","txt":"不动产权属证书是权利人享有该不动产物权的证明。不动产权属证书记载的事项，应当与不动产登记簿一致；记载不一致的，除有证据证明不动产登记簿确有错误外，以不动产登记簿为准。"},{"i":218,"n":"第二百一十八条","txt":"权利人、利害关系人可以申请查询、复制不动产登记资料，登记机构应当提供。"},{"i":219,"n":"第二百一十九条","txt":"利害关系人不得公开、非法使用权利人的不动产登记资料。"},{"i":220,"n":"第二百二十条","txt":"权利人、利害关系人认为不动产登记簿记载的事项错误的，可以申请更正登记。不动产登记簿记载的权利人书面同意更正或者有证据证明登记确有错误的，登记机构应当予以更正。"},{"i":221,"n":"第二百二十一条","txt":"当事人签订买卖房屋的协议或者签订其他不动产物权的协议，为保障将来实现物权，按照约定可以向登记机构申请预告登记。预告登记后，未经预告登记的权利人同意，处分该不动产的，不发生物权效力。"},{"i":222,"n":"第二百二十二条","txt":"当事人提供虚假材料申请登记，造成他人损害的，应当承担赔偿责任。"},{"i":223,"n":"第二百二十三条","txt":"不动产登记费按件收取，不得按照不动产的面积、体积或者价款的比例收取。"},{"i":224,"n":"第二百二十四条","txt":"动产物权的设立和转让，自交付时发生效力，但是法律另有规定的除外。"},{"i":225,"n":"第二百二十五条","txt":"船舶、航空器和机动车等的物权的设立、变更、转让和消灭，未经登记，不得对抗善意第三人。"},{"i":226,"n":"第二百二十六条","txt":"动产物权设立和转让前，权利人已经占有该动产的，物权自民事法律行为生效时发生效力。"},{"i":227,"n":"第二百二十七条","txt":"动产物权设立和转让前，第三人占有该动产的，负有交付义务的人可以通过转让请求第三人返还原物的权利代替交付。"},{"i":228,"n":"第二百二十八条","txt":"动产物权转让时，当事人又约定由出让人继续占有该动产的，物权自该约定生效时发生效力。"},{"i":229,"n":"第二百二十九条","txt":"因人民法院、仲裁机构的法律文书或者人民政府的征收决定等，导致物权设立、变更、转让或者消灭的，自法律文书或者征收决定等生效时发生效力。"},{"i":230,"n":"第二百三十条","txt":"因继承取得物权的，自继承开始时发生效力。"},{"i":231,"n":"第二百三十一条","txt":"因合法建造、拆除房屋等事实行为设立或者消灭物权的，自事实行为成就时发生效力。"},{"i":232,"n":"第二百三十二条","txt":"处分依照本节规定享有的不动产物权，依照法律规定需要办理登记的，未经登记，不发生物权效力。"},{"i":233,"n":"第二百三十三条","txt":"物权受到侵害的，权利人可以通过和解、调解、仲裁、诉讼等途径解决。"},{"i":234,"n":"第二百三十四条","txt":"因物权的归属、内容发生争议的，利害关系人可以请求确认权利。"},{"i":235,"n":"第二百三十五条","txt":"无权占有不动产或者动产的，权利人可以请求返还原物。"},{"i":236,"n":"第二百三十六条","txt":"妨害物权或者可能妨害物权的，权利人可以请求排除妨害或者消除危险。"},{"i":237,"n":"第二百三十七条","txt":"造成不动产或者动产毁损的，权利人可以依法请求修理、重作、更换或者恢复原状。"},{"i":238,"n":"第二百三十八条","txt":"侵害物权，造成权利人损害的，权利人可以依法请求损害赔偿，也可以依法请求承担其他民事责任。"},{"i":239,"n":"第二百三十九条","txt":"本章规定的物权保护方式，可以单独适用，也可以根据权利被侵害的情形合并适用。"},{"i":240,"n":"第二百四十条","txt":"所有权人对自己的不动产或者动产，依法享有占有、使用、收益和处分的权利。"},{"i":241,"n":"第二百四十一条","txt":"所有权人有权在自己的不动产或者动产上设立用益物权和担保物权。用益物权人、担保物权人行使权利，不得损害所有权人的权益。"},{"i":242,"n":"第二百四十二条","txt":"法律规定专属于国家所有的不动产和动产，任何组织或者个人不能取得所有权。"},{"i":243,"n":"第二百四十三条","txt":"为了公共利益的需要，依照法律规定的权限和程序可以征收集体所有的土地和组织、个人的房屋以及其他不动产。"},{"i":244,"n":"第二百四十四条","txt":"国家对耕地实行特殊保护，严格限制农用地转为建设用地，控制建设用地总量。不得违反法律规定的权限和程序征收集体所有的土地。"},{"i":245,"n":"第二百四十五条","txt":"因抢险救灾、疫情防控等紧急需要，依照法律规定的权限和程序可以征用组织、个人的不动产或者动产。被征用的不动产或者动产使用后，应当返还被征用人。组织、个人的不动产或者动产被征用或者征用后毁损、灭失的，应当给予补偿。"},{"i":246,"n":"第二百四十六条","txt":"法律规定属于国家所有的财产，属于国家所有即全民所有。"},{"i":247,"n":"第二百四十七条","txt":"矿藏、水流、海域属于国家所有。"},{"i":248,"n":"第二百四十八条","txt":"无居民海岛属于国家所有，国务院代表国家行使无居民海岛所有权。"},{"i":249,"n":"第二百四十九条","txt":"城市的土地，属于国家所有。法律规定属于国家所有的农村和城市郊区的土地，属于国家所有。"},{"i":250,"n":"第二百五十条","txt":"森林、山岭、草原、荒地、滩涂等自然资源，属于国家所有，但是法律规定属于集体所有的除外。"},{"i":251,"n":"第二百五十一条","txt":"法律规定属于国家所有的野生动植物资源，属于国家所有。"},{"i":252,"n":"第二百五十二条","txt":"无线电频谱资源属于国家所有。"},{"i":253,"n":"第二百五十三条","txt":"法律规定属于国家所有的文物，属于国家所有。"},{"i":254,"n":"第二百五十四条","txt":"国防资产属于国家所有。"},{"i":255,"n":"第二百五十五条","txt":"国家机关对其直接支配的不动产和动产，享有占有、使用以及依照法律和国务院的有关规定处分的权利。"},{"i":256,"n":"第二百五十六条","txt":"国家举办的事业单位对其直接支配的不动产和动产，享有占有、使用以及依照法律和国务院的有关规定收益、处分的权利。"},{"i":257,"n":"第二百五十七条","txt":"国家出资的企业，由国务院、地方人民政府依照法律、行政法规规定分别代表国家履行出资人职责，享有出资人权益。"},{"i":258,"n":"第二百五十八条","txt":"国家所有的财产受法律保护，禁止任何组织或者个人侵占、哄抢、私分、截留、破坏。"},{"i":259,"n":"第二百五十九条","txt":"履行国有财产管理、监督职责的机构及其工作人员，应当依法加强对国有财产的管理、监督，促进国有财产保值增值，防止国有财产损失；滥用职权，玩忽职守，造成国有财产损失的，应当依法承担法律责任。"},{"i":260,"n":"第二百六十条","txt":"集体所有的不动产和动产包括："},{"i":261,"n":"第二百六十一条","txt":"农民集体所有的不动产和动产，属于本集体成员集体所有。"},{"i":262,"n":"第二百六十二条","txt":"对于集体所有的土地和森林、山岭、草原、荒地、滩涂等，依照下列规定行使所有权："},{"i":263,"n":"第二百六十三条","txt":"城镇集体所有的不动产和动产，依照法律、行政法规的规定由本集体享有占有、使用、收益和处分的权利。"},{"i":264,"n":"第二百六十四条","txt":"农村集体经济组织或者村民委员会、村民小组应当依照法律、行政法规以及章程、村规民约向本集体成员公布集体财产的状况。集体成员有权查阅、复制相关资料。"},{"i":265,"n":"第二百六十五条","txt":"集体所有的财产受法律保护，禁止任何组织或者个人侵占、哄抢、私分、破坏。"},{"i":266,"n":"第二百六十六条","txt":"私人对其合法的收入、房屋、生活用品、生产工具、原材料等不动产和动产享有所有权。"},{"i":267,"n":"第二百六十七条","txt":"私人的合法财产受法律保护，禁止任何组织或者个人侵占、哄抢、破坏。"},{"i":268,"n":"第二百六十八条","txt":"国家、集体和私人依法可以出资设立有限责任公司、股份有限公司或者其他企业。国家、集体和私人所有的不动产或者动产投到企业的，由出资人按照约定或者出资比例享有资产收益、重大决策以及选择经营管理者等权利并履行义务。"},{"i":269,"n":"第二百六十九条","txt":"营利法人对其不动产和动产依照法律、行政法规以及章程享有占有、使用、收益和处分的权利。"},{"i":270,"n":"第二百七十条","txt":"社会团体法人、捐助法人依法所有的不动产和动产，受法律保护。"},{"i":271,"n":"第二百七十一条","txt":"业主对建筑物内的住宅、经营性用房等专有部分享有所有权，对专有部分以外的共有部分享有共有和共同管理的权利。"},{"i":272,"n":"第二百七十二条","txt":"业主对其建筑物专有部分享有占有、使用、收益和处分的权利。业主行使权利不得危及建筑物的安全，不得损害其他业主的合法权益。"},{"i":273,"n":"第二百七十三条","txt":"业主对建筑物专有部分以外的共有部分，享有权利，承担义务；不得以放弃权利为由不履行义务。"},{"i":274,"n":"第二百七十四条","txt":"建筑区划内的道路，属于业主共有，但是属于城镇公共道路的除外。建筑区划内的绿地，属于业主共有，但是属于城镇公共绿地或者明示属于个人的除外。建筑区划内的其他公共场所、公用设施和物业服务用房，属于业主共有。"},{"i":275,"n":"第二百七十五条","txt":"建筑区划内，规划用于停放汽车的车位、车库的归属，由当事人通过出售、附赠或者出租等方式约定。"},{"i":276,"n":"第二百七十六条","txt":"建筑区划内，规划用于停放汽车的车位、车库应当首先满足业主的需要。"},{"i":277,"n":"第二百七十七条","txt":"业主可以设立业主大会，选举业主委员会。业主大会、业主委员会成立的具体条件和程序，依照法律、法规的规定。"},{"i":278,"n":"第二百七十八条","txt":"下列事项由业主共同决定："},{"i":279,"n":"第二百七十九条","txt":"业主不得违反法律、法规以及管理规约，将住宅改变为经营性用房。业主将住宅改变为经营性用房的，除遵守法律、法规以及管理规约外，应当经有利害关系的业主一致同意。"},{"i":280,"n":"第二百八十条","txt":"业主大会或者业主委员会的决定，对业主具有法律约束力。"},{"i":281,"n":"第二百八十一条","txt":"建筑物及其附属设施的维修资金，属于业主共有。经业主共同决定，可以用于电梯、屋顶、外墙、无障碍设施等共有部分的维修、更新和改造。建筑物及其附属设施的维修资金的筹集、使用情况应当定期公布。"},{"i":282,"n":"第二百八十二条","txt":"建设单位、物业服务企业或者其他管理人等利用业主的共有部分产生的收入，在扣除合理成本之后，属于业主共有。"},{"i":283,"n":"第二百八十三条","txt":"建筑物及其附属设施的费用分摊、收益分配等事项，有约定的，按照约定；没有约定或者约定不明确的，按照业主专有部分面积所占比例确定。"},{"i":284,"n":"第二百八十四条","txt":"业主可以自行管理建筑物及其附属设施，也可以委托物业服务企业或者其他管理人管理。"},{"i":285,"n":"第二百八十五条","txt":"物业服务企业或者其他管理人根据业主的委托，依照本法第三编有关物业服务合同的规定管理建筑区划内的建筑物及其附属设施，接受业主的监督，并及时答复业主对物业服务情况提出的询问。"},{"i":286,"n":"第二百八十六条","txt":"业主应当遵守法律、法规以及管理规约，相关行为应当符合节约资源、保护生态环境的要求。对于物业服务企业或者其他管理人执行政府依法实施的应急处置措施和其他管理措施，业主应当依法予以配合。"},{"i":287,"n":"第二百八十七条","txt":"业主对建设单位、物业服务企业或者其他管理人以及其他业主侵害自己合法权益的行为，有权请求其承担民事责任。"},{"i":288,"n":"第二百八十八条","txt":"不动产的相邻权利人应当按照有利生产、方便生活、团结互助、公平合理的原则，正确处理相邻关系。"},{"i":289,"n":"第二百八十九条","txt":"法律、法规对处理相邻关系有规定的，依照其规定；法律、法规没有规定的，可以按照当地习惯。"},{"i":290,"n":"第二百九十条","txt":"不动产权利人应当为相邻权利人用水、排水提供必要的便利。"},{"i":291,"n":"第二百九十一条","txt":"不动产权利人对相邻权利人因通行等必须利用其土地的，应当提供必要的便利。"},{"i":292,"n":"第二百九十二条","txt":"不动产权利人因建造、修缮建筑物以及铺设电线、电缆、水管、暖气和燃气管线等必须利用相邻土地、建筑物的，该土地、建筑物的权利人应当提供必要的便利。"},{"i":293,"n":"第二百九十三条","txt":"建造建筑物，不得违反国家有关工程建设标准，不得妨碍相邻建筑物的通风、采光和日照。"},{"i":294,"n":"第二百九十四条","txt":"不动产权利人不得违反国家规定弃置固体废物，排放大气污染物、水污染物、土壤污染物、噪声、光辐射、电磁辐射等有害物质。"},{"i":295,"n":"第二百九十五条","txt":"不动产权利人挖掘土地、建造建筑物、铺设管线以及安装设备等，不得危及相邻不动产的安全。"},{"i":296,"n":"第二百九十六条","txt":"不动产权利人因用水、排水、通行、铺设管线等利用相邻不动产的，应当尽量避免对相邻的不动产权利人造成损害。"},{"i":297,"n":"第二百九十七条","txt":"不动产或者动产可以由两个以上组织、个人共有。共有包括按份共有和共同共有。"},{"i":298,"n":"第二百九十八条","txt":"按份共有人对共有的不动产或者动产按照其份额享有所有权。"},{"i":299,"n":"第二百九十九条","txt":"共同共有人对共有的不动产或者动产共同享有所有权。"},{"i":300,"n":"第三百条","txt":"共有人按照约定管理共有的不动产或者动产；没有约定或者约定不明确的，各共有人都有管理的权利和义务。"},{"i":301,"n":"第三百零一条","txt":"处分共有的不动产或者动产以及对共有的不动产或者动产作重大修缮、变更性质或者用途的，应当经占份额三分之二以上的按份共有人或者全体共同共有人同意，但是共有人之间另有约定的除外。"},{"i":302,"n":"第三百零二条","txt":"共有人对共有物的管理费用以及其他负担，有约定的，按照其约定；没有约定或者约定不明确的，按份共有人按照其份额负担，共同共有人共同负担。"},{"i":303,"n":"第三百零三条","txt":"共有人约定不得分割共有的不动产或者动产，以维持共有关系的，应当按照约定，但是共有人有重大理由需要分割的，可以请求分割；没有约定或者约定不明确的，按份共有人可以随时请求分割，共同共有人在共有的基础丧失或者有重大理由需要分割时可以请求分割。因分割造成其他共有人损害的，应当给予赔偿。"},{"i":304,"n":"第三百零四条","txt":"共有人可以协商确定分割方式。达不成协议，共有的不动产或者动产可以分割且不会因分割减损价值的，应当对实物予以分割；难以分割或者因分割会减损价值的，应当对折价或者拍卖、变卖取得的价款予以分割。"},{"i":305,"n":"第三百零五条","txt":"按份共有人可以转让其享有的共有的不动产或者动产份额。其他共有人在同等条件下享有优先购买的权利。"},{"i":306,"n":"第三百零六条","txt":"按份共有人转让其享有的共有的不动产或者动产份额的，应当将转让条件及时通知其他共有人。其他共有人应当在合理期限内行使优先购买权。"},{"i":307,"n":"第三百零七条","txt":"因共有的不动产或者动产产生的债权债务，在对外关系上，共有人享有连带债权、承担连带债务，但是法律另有规定或者第三人知道共有人不具有连带债权债务关系的除外；在共有人内部关系上，除共有人另有约定外，按份共有人按照份额享有债权、承担债务，共同共有人共同享有债权、承担债务。偿还债务超过自己应当承担份额的按份共有人，有权向其他共有人追偿。"},{"i":308,"n":"第三百零八条","txt":"共有人对共有的不动产或者动产没有约定为按份共有或者共同共有，或者约定不明确的，除共有人具有家庭关系等外，视为按份共有。"},{"i":309,"n":"第三百零九条","txt":"按份共有人对共有的不动产或者动产享有的份额，没有约定或者约定不明确的，按照出资额确定；不能确定出资额的，视为等额享有。"},{"i":310,"n":"第三百一十条","txt":"两个以上组织、个人共同享有用益物权、担保物权的，参照适用本章的有关规定。"},{"i":311,"n":"第三百一十一条","txt":"无处分权人将不动产或者动产转让给受让人的，所有权人有权追回；除法律另有规定外，符合下列情形的，受让人取得该不动产或者动产的所有权："},{"i":312,"n":"第三百一十二条","txt":"所有权人或者其他权利人有权追回遗失物。该遗失物通过转让被他人占有的，权利人有权向无处分权人请求损害赔偿，或者自知道或者应当知道受让人之日起二年内向受让人请求返还原物；但是，受让人通过拍卖或者向具有经营资格的经营者购得该遗失物的，权利人请求返还原物时应当支付受让人所付的费用。权利人向受让人支付所付费用后，有权向无处分权人追偿。"},{"i":313,"n":"第三百一十三条","txt":"善意受让人取得动产后，该动产上的原有权利消灭。但是，善意受让人在受让时知道或者应当知道该权利的除外。"},{"i":314,"n":"第三百一十四条","txt":"拾得遗失物，应当返还权利人。拾得人应当及时通知权利人领取，或者送交公安等有关部门。"},{"i":315,"n":"第三百一十五条","txt":"有关部门收到遗失物，知道权利人的，应当及时通知其领取；不知道的，应当及时发布招领公告。"},{"i":316,"n":"第三百一十六条","txt":"拾得人在遗失物送交有关部门前，有关部门在遗失物被领取前，应当妥善保管遗失物。因故意或者重大过失致使遗失物毁损、灭失的，应当承担民事责任。"},{"i":317,"n":"第三百一十七条","txt":"权利人领取遗失物时，应当向拾得人或者有关部门支付保管遗失物等支出的必要费用。"},{"i":318,"n":"第三百一十八条","txt":"遗失物自发布招领公告之日起一年内无人认领的，归国家所有。"},{"i":319,"n":"第三百一十九条","txt":"拾得漂流物、发现埋藏物或者隐藏物的，参照适用拾得遗失物的有关规定。法律另有规定的，依照其规定。"},{"i":320,"n":"第三百二十条","txt":"主物转让的，从物随主物转让，但是当事人另有约定的除外。"},{"i":321,"n":"第三百二十一条","txt":"天然孳息，由所有权人取得；既有所有权人又有用益物权人的，由用益物权人取得。当事人另有约定的，按照其约定。"},{"i":322,"n":"第三百二十二条","txt":"因加工、附合、混合而产生的物的归属，有约定的，按照约定；没有约定或者约定不明确的，依照法律规定；法律没有规定的，按照充分发挥物的效用以及保护无过错当事人的原则确定。因一方当事人的过错或者确定物的归属造成另一方当事人损害的，应当给予赔偿或者补偿。"},{"i":323,"n":"第三百二十三条","txt":"用益物权人对他人所有的不动产或者动产，依法享有占有、使用和收益的权利。"},{"i":324,"n":"第三百二十四条","txt":"国家所有或者国家所有由集体使用以及法律规定属于集体所有的自然资源，组织、个人依法可以占有、使用和收益。"},{"i":325,"n":"第三百二十五条","txt":"国家实行自然资源有偿使用制度，但是法律另有规定的除外。"},{"i":326,"n":"第三百二十六条","txt":"用益物权人行使权利，应当遵守法律有关保护和合理开发利用资源、保护生态环境的规定。所有权人不得干涉用益物权人行使权利。"},{"i":327,"n":"第三百二十七条","txt":"因不动产或者动产被征收、征用致使用益物权消灭或者影响用益物权行使的，用益物权人有权依据本法第二百四十三条、第二百四十五条的规定获得相应补偿。"},{"i":328,"n":"第三百二十八条","txt":"依法取得的海域使用权受法律保护。"},{"i":329,"n":"第三百二十九条","txt":"依法取得的探矿权、采矿权、取水权和使用水域、滩涂从事养殖、捕捞的权利受法律保护。"},{"i":330,"n":"第三百三十条","txt":"农村集体经济组织实行家庭承包经营为基础、统分结合的双层经营体制。"},{"i":331,"n":"第三百三十一条","txt":"土地承包经营权人依法对其承包经营的耕地、林地、草地等享有占有、使用和收益的权利，有权从事种植业、林业、畜牧业等农业生产。"},{"i":332,"n":"第三百三十二条","txt":"耕地的承包期为三十年。草地的承包期为三十年至五十年。林地的承包期为三十年至七十年。"},{"i":333,"n":"第三百三十三条","txt":"土地承包经营权自土地承包经营权合同生效时设立。"},{"i":334,"n":"第三百三十四条","txt":"土地承包经营权人依照法律规定，有权将土地承包经营权互换、转让。未经依法批准，不得将承包地用于非农建设。"},{"i":335,"n":"第三百三十五条","txt":"土地承包经营权互换、转让的，当事人可以向登记机构申请登记；未经登记，不得对抗善意第三人。"},{"i":336,"n":"第三百三十六条","txt":"承包期内发包人不得调整承包地。"},{"i":337,"n":"第三百三十七条","txt":"承包期内发包人不得收回承包地。法律另有规定的，依照其规定。"},{"i":338,"n":"第三百三十八条","txt":"承包地被征收的，土地承包经营权人有权依据本法第二百四十三条的规定获得相应补偿。"},{"i":339,"n":"第三百三十九条","txt":"土地承包经营权人可以自主决定依法采取出租、入股或者其他方式向他人流转土地经营权。"},{"i":340,"n":"第三百四十条","txt":"土地经营权人有权在合同约定的期限内占有农村土地，自主开展农业生产经营并取得收益。"},{"i":341,"n":"第三百四十一条","txt":"流转期限为五年以上的土地经营权，自流转合同生效时设立。当事人可以向登记机构申请土地经营权登记；未经登记，不得对抗善意第三人。"},{"i":342,"n":"第三百四十二条","txt":"通过招标、拍卖、公开协商等方式承包农村土地，经依法登记取得权属证书的，可以依法采取出租、入股、抵押或者其他方式流转土地经营权。"},{"i":343,"n":"第三百四十三条","txt":"国家所有的农用地实行承包经营的，参照适用本编的有关规定。"},{"i":344,"n":"第三百四十四条","txt":"建设用地使用权人依法对国家所有的土地享有占有、使用和收益的权利，有权利用该土地建造建筑物、构筑物及其附属设施。"},{"i":345,"n":"第三百四十五条","txt":"建设用地使用权可以在土地的地表、地上或者地下分别设立。"},{"i":346,"n":"第三百四十六条","txt":"设立建设用地使用权，应当符合节约资源、保护生态环境的要求，遵守法律、行政法规关于土地用途的规定，不得损害已经设立的用益物权。"},{"i":347,"n":"第三百四十七条","txt":"设立建设用地使用权，可以采取出让或者划拨等方式。"},{"i":348,"n":"第三百四十八条","txt":"通过招标、拍卖、协议等出让方式设立建设用地使用权的，当事人应当采用书面形式订立建设用地使用权出让合同。"},{"i":349,"n":"第三百四十九条","txt":"设立建设用地使用权的，应当向登记机构申请建设用地使用权登记。建设用地使用权自登记时设立。登记机构应当向建设用地使用权人发放权属证书。"},{"i":350,"n":"第三百五十条","txt":"建设用地使用权人应当合理利用土地，不得改变土地用途；需要改变土地用途的，应当依法经有关行政主管部门批准。"},{"i":351,"n":"第三百五十一条","txt":"建设用地使用权人应当依照法律规定以及合同约定支付出让金等费用。"},{"i":352,"n":"第三百五十二条","txt":"建设用地使用权人建造的建筑物、构筑物及其附属设施的所有权属于建设用地使用权人，但是有相反证据证明的除外。"},{"i":353,"n":"第三百五十三条","txt":"建设用地使用权人有权将建设用地使用权转让、互换、出资、赠与或者抵押，但是法律另有规定的除外。"},{"i":354,"n":"第三百五十四条","txt":"建设用地使用权转让、互换、出资、赠与或者抵押的，当事人应当采用书面形式订立相应的合同。使用期限由当事人约定，但是不得超过建设用地使用权的剩余期限。"},{"i":355,"n":"第三百五十五条","txt":"建设用地使用权转让、互换、出资或者赠与的，应当向登记机构申请变更登记。"},{"i":356,"n":"第三百五十六条","txt":"建设用地使用权转让、互换、出资或者赠与的，附着于该土地上的建筑物、构筑物及其附属设施一并处分。"},{"i":357,"n":"第三百五十七条","txt":"建筑物、构筑物及其附属设施转让、互换、出资或者赠与的，该建筑物、构筑物及其附属设施占用范围内的建设用地使用权一并处分。"},{"i":358,"n":"第三百五十八条","txt":"建设用地使用权期限届满前，因公共利益需要提前收回该土地的，应当依据本法第二百四十三条的规定对该土地上的房屋以及其他不动产给予补偿，并退还相应的出让金。"},{"i":359,"n":"第三百五十九条","txt":"住宅建设用地使用权期限届满的，自动续期。续期费用的缴纳或者减免，依照法律、行政法规的规定办理。"},{"i":360,"n":"第三百六十条","txt":"建设用地使用权消灭的，出让人应当及时办理注销登记。登记机构应当收回权属证书。"},{"i":361,"n":"第三百六十一条","txt":"集体所有的土地作为建设用地的，应当依照土地管理的法律规定办理。"},{"i":362,"n":"第三百六十二条","txt":"宅基地使用权人依法对集体所有的土地享有占有和使用的权利，有权依法利用该土地建造住宅及其附属设施。"},{"i":363,"n":"第三百六十三条","txt":"宅基地使用权的取得、行使和转让，适用土地管理的法律和国家有关规定。"},{"i":364,"n":"第三百六十四条","txt":"宅基地因自然灾害等原因灭失的，宅基地使用权消灭。对失去宅基地的村民，应当依法重新分配宅基地。"},{"i":365,"n":"第三百六十五条","txt":"已经登记的宅基地使用权转让或者消灭的，应当及时办理变更登记或者注销登记。"},{"i":366,"n":"第三百六十六条","txt":"居住权人有权按照合同约定，对他人的住宅享有占有、使用的用益物权，以满足生活居住的需要。"},{"i":367,"n":"第三百六十七条","txt":"设立居住权，当事人应当采用书面形式订立居住权合同。"},{"i":368,"n":"第三百六十八条","txt":"居住权无偿设立，但是当事人另有约定的除外。设立居住权的，应当向登记机构申请居住权登记。居住权自登记时设立。"},{"i":369,"n":"第三百六十九条","txt":"居住权不得转让、继承。设立居住权的住宅不得出租，但是当事人另有约定的除外。"},{"i":370,"n":"第三百七十条","txt":"居住权期限届满或者居住权人死亡的，居住权消灭。居住权消灭的，应当及时办理注销登记。"},{"i":371,"n":"第三百七十一条","txt":"以遗嘱方式设立居住权的，参照适用本章的有关规定。"},{"i":372,"n":"第三百七十二条","txt":"地役权人有权按照合同约定，利用他人的不动产，以提高自己的不动产的效益。"},{"i":373,"n":"第三百七十三条","txt":"设立地役权，当事人应当采用书面形式订立地役权合同。"},{"i":374,"n":"第三百七十四条","txt":"地役权自地役权合同生效时设立。当事人要求登记的，可以向登记机构申请地役权登记；未经登记，不得对抗善意第三人。"},{"i":375,"n":"第三百七十五条","txt":"供役地权利人应当按照合同约定，允许地役权人利用其不动产，不得妨害地役权人行使权利。"},{"i":376,"n":"第三百七十六条","txt":"地役权人应当按照合同约定的利用目的和方法利用供役地，尽量减少对供役地权利人物权的限制。"},{"i":377,"n":"第三百七十七条","txt":"地役权期限由当事人约定；但是，不得超过土地承包经营权、建设用地使用权等用益物权的剩余期限。"},{"i":378,"n":"第三百七十八条","txt":"土地所有权人享有地役权或者负担地役权的，设立土地承包经营权、宅基地使用权等用益物权时，该用益物权人继续享有或者负担已经设立的地役权。"},{"i":379,"n":"第三百七十九条","txt":"土地上已经设立土地承包经营权、建设用地使用权、宅基地使用权等用益物权的，未经用益物权人同意，土地所有权人不得设立地役权。"},{"i":380,"n":"第三百八十条","txt":"地役权不得单独转让。土地承包经营权、建设用地使用权等转让的，地役权一并转让，但是合同另有约定的除外。"},{"i":381,"n":"第三百八十一条","txt":"地役权不得单独抵押。土地经营权、建设用地使用权等抵押的，在实现抵押权时，地役权一并转让。"},{"i":382,"n":"第三百八十二条","txt":"需役地以及需役地上的土地承包经营权、建设用地使用权等部分转让时，转让部分涉及地役权的，受让人同时享有地役权。"},{"i":383,"n":"第三百八十三条","txt":"供役地以及供役地上的土地承包经营权、建设用地使用权等部分转让时，转让部分涉及地役权的，地役权对受让人具有法律约束力。"},{"i":384,"n":"第三百八十四条","txt":"地役权人有下列情形之一的，供役地权利人有权解除地役权合同，地役权消灭："},{"i":385,"n":"第三百八十五条","txt":"已经登记的地役权变更、转让或者消灭的，应当及时办理变更登记或者注销登记。"},{"i":386,"n":"第三百八十六条","txt":"担保物权人在债务人不履行到期债务或者发生当事人约定的实现担保物权的情形，依法享有就担保财产优先受偿的权利，但是法律另有规定的除外。"},{"i":387,"n":"第三百八十七条","txt":"债权人在借贷、买卖等民事活动中，为保障实现其债权，需要担保的，可以依照本法和其他法律的规定设立担保物权。"},{"i":388,"n":"第三百八十八条","txt":"设立担保物权，应当依照本法和其他法律的规定订立担保合同。担保合同包括抵押合同、质押合同和其他具有担保功能的合同。担保合同是主债权债务合同的从合同。主债权债务合同无效的，担保合同无效，但是法律另有规定的除外。"},{"i":389,"n":"第三百八十九条","txt":"担保物权的担保范围包括主债权及其利息、违约金、损害赔偿金、保管担保财产和实现担保物权的费用。当事人另有约定的，按照其约定。"},{"i":390,"n":"第三百九十条","txt":"担保期间，担保财产毁损、灭失或者被征收等，担保物权人可以就获得的保险金、赔偿金或者补偿金等优先受偿。被担保债权的履行期限未届满的，也可以提存该保险金、赔偿金或者补偿金等。"},{"i":391,"n":"第三百九十一条","txt":"第三人提供担保，未经其书面同意，债权人允许债务人转移全部或者部分债务的，担保人不再承担相应的担保责任。"},{"i":392,"n":"第三百九十二条","txt":"被担保的债权既有物的担保又有人的担保的，债务人不履行到期债务或者发生当事人约定的实现担保物权的情形，债权人应当按照约定实现债权；没有约定或者约定不明确，债务人自己提供物的担保的，债权人应当先就该物的担保实现债权；第三人提供物的担保的，债权人可以就物的担保实现债权，也可以请求保证人承担保证责任。提供担保的第三人承担担保责任后，有权向债务人追偿。"},{"i":393,"n":"第三百九十三条","txt":"有下列情形之一的，担保物权消灭："},{"i":394,"n":"第三百九十四条","txt":"为担保债务的履行，债务人或者第三人不转移财产的占有，将该财产抵押给债权人的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，债权人有权就该财产优先受偿。"},{"i":395,"n":"第三百九十五条","txt":"债务人或者第三人有权处分的下列财产可以抵押："},{"i":396,"n":"第三百九十六条","txt":"企业、个体工商户、农业生产经营者可以将现有的以及将有的生产设备、原材料、半成品、产品抵押，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，债权人有权就抵押财产确定时的动产优先受偿。"},{"i":397,"n":"第三百九十七条","txt":"以建筑物抵押的，该建筑物占用范围内的建设用地使用权一并抵押。以建设用地使用权抵押的，该土地上的建筑物一并抵押。"},{"i":398,"n":"第三百九十八条","txt":"乡镇、村企业的建设用地使用权不得单独抵押。以乡镇、村企业的厂房等建筑物抵押的，其占用范围内的建设用地使用权一并抵押。"},{"i":399,"n":"第三百九十九条","txt":"下列财产不得抵押："},{"i":400,"n":"第四百条","txt":"设立抵押权，当事人应当采用书面形式订立抵押合同。"},{"i":401,"n":"第四百零一条","txt":"抵押权人在债务履行期限届满前，与抵押人约定债务人不履行到期债务时抵押财产归债权人所有的，只能依法就抵押财产优先受偿。"},{"i":402,"n":"第四百零二条","txt":"以本法第三百九十五条第一款第一项至第三项规定的财产或者第五项规定的正在建造的建筑物抵押的，应当办理抵押登记。抵押权自登记时设立。"},{"i":403,"n":"第四百零三条","txt":"以动产抵押的，抵押权自抵押合同生效时设立；未经登记，不得对抗善意第三人。"},{"i":404,"n":"第四百零四条","txt":"以动产抵押的，不得对抗正常经营活动中已经支付合理价款并取得抵押财产的买受人。"},{"i":405,"n":"第四百零五条","txt":"抵押权设立前，抵押财产已经出租并转移占有的，原租赁关系不受该抵押权的影响。"},{"i":406,"n":"第四百零六条","txt":"抵押期间，抵押人可以转让抵押财产。当事人另有约定的，按照其约定。抵押财产转让的，抵押权不受影响。"},{"i":407,"n":"第四百零七条","txt":"抵押权不得与债权分离而单独转让或者作为其他债权的担保。债权转让的，担保该债权的抵押权一并转让，但是法律另有规定或者当事人另有约定的除外。"},{"i":408,"n":"第四百零八条","txt":"抵押人的行为足以使抵押财产价值减少的，抵押权人有权请求抵押人停止其行为；抵押财产价值减少的，抵押权人有权请求恢复抵押财产的价值，或者提供与减少的价值相应的担保。抵押人不恢复抵押财产的价值，也不提供担保的，抵押权人有权请求债务人提前清偿债务。"},{"i":409,"n":"第四百零九条","txt":"抵押权人可以放弃抵押权或者抵押权的顺位。抵押权人与抵押人可以协议变更抵押权顺位以及被担保的债权数额等内容。但是，抵押权的变更未经其他抵押权人书面同意的，不得对其他抵押权人产生不利影响。"},{"i":410,"n":"第四百一十条","txt":"债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，抵押权人可以与抵押人协议以抵押财产折价或者以拍卖、变卖该抵押财产所得的价款优先受偿。协议损害其他债权人利益的，其他债权人可以请求人民法院撤销该协议。"},{"i":411,"n":"第四百一十一条","txt":"依据本法第三百九十六条规定设定抵押的，抵押财产自下列情形之一发生时确定："},{"i":412,"n":"第四百一十二条","txt":"债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，致使抵押财产被人民法院依法扣押的，自扣押之日起，抵押权人有权收取该抵押财产的天然孳息或者法定孳息，但是抵押权人未通知应当清偿法定孳息义务人的除外。"},{"i":413,"n":"第四百一十三条","txt":"抵押财产折价或者拍卖、变卖后，其价款超过债权数额的部分归抵押人所有，不足部分由债务人清偿。"},{"i":414,"n":"第四百一十四条","txt":"同一财产向两个以上债权人抵押的，拍卖、变卖抵押财产所得的价款依照下列规定清偿："},{"i":415,"n":"第四百一十五条","txt":"同一财产既设立抵押权又设立质权的，拍卖、变卖该财产所得的价款按照登记、交付的时间先后确定清偿顺序。"},{"i":416,"n":"第四百一十六条","txt":"动产抵押担保的主债权是抵押物的价款，标的物交付后十日内办理抵押登记的，该抵押权人优先于抵押物买受人的其他担保物权人受偿，但是留置权人除外。"},{"i":417,"n":"第四百一十七条","txt":"建设用地使用权抵押后，该土地上新增的建筑物不属于抵押财产。该建设用地使用权实现抵押权时，应当将该土地上新增的建筑物与建设用地使用权一并处分。但是，新增建筑物所得的价款，抵押权人无权优先受偿。"},{"i":418,"n":"第四百一十八条","txt":"以集体所有土地的使用权依法抵押的，实现抵押权后，未经法定程序，不得改变土地所有权的性质和土地用途。"},{"i":419,"n":"第四百一十九条","txt":"抵押权人应当在主债权诉讼时效期间行使抵押权；未行使的，人民法院不予保护。"},{"i":420,"n":"第四百二十条","txt":"为担保债务的履行，债务人或者第三人对一定期间内将要连续发生的债权提供担保财产的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，抵押权人有权在最高债权额限度内就该担保财产优先受偿。"},{"i":421,"n":"第四百二十一条","txt":"最高额抵押担保的债权确定前，部分债权转让的，最高额抵押权不得转让，但是当事人另有约定的除外。"},{"i":422,"n":"第四百二十二条","txt":"最高额抵押担保的债权确定前，抵押权人与抵押人可以通过协议变更债权确定的期间、债权范围以及最高债权额。但是，变更的内容不得对其他抵押权人产生不利影响。"},{"i":423,"n":"第四百二十三条","txt":"有下列情形之一的，抵押权人的债权确定："},{"i":424,"n":"第四百二十四条","txt":"最高额抵押权除适用本节规定外，适用本章第一节的有关规定。"},{"i":425,"n":"第四百二十五条","txt":"为担保债务的履行，债务人或者第三人将其动产出质给债权人占有的，债务人不履行到期债务或者发生当事人约定的实现质权的情形，债权人有权就该动产优先受偿。"},{"i":426,"n":"第四百二十六条","txt":"法律、行政法规禁止转让的动产不得出质。"},{"i":427,"n":"第四百二十七条","txt":"设立质权，当事人应当采用书面形式订立质押合同。"},{"i":428,"n":"第四百二十八条","txt":"质权人在债务履行期限届满前，与出质人约定债务人不履行到期债务时质押财产归债权人所有的，只能依法就质押财产优先受偿。"},{"i":429,"n":"第四百二十九条","txt":"质权自出质人交付质押财产时设立。"},{"i":430,"n":"第四百三十条","txt":"质权人有权收取质押财产的孳息，但是合同另有约定的除外。"},{"i":431,"n":"第四百三十一条","txt":"质权人在质权存续期间，未经出质人同意，擅自使用、处分质押财产，造成出质人损害的，应当承担赔偿责任。"},{"i":432,"n":"第四百三十二条","txt":"质权人负有妥善保管质押财产的义务；因保管不善致使质押财产毁损、灭失的，应当承担赔偿责任。"},{"i":433,"n":"第四百三十三条","txt":"因不可归责于质权人的事由可能使质押财产毁损或者价值明显减少，足以危害质权人权利的，质权人有权请求出质人提供相应的担保；出质人不提供的，质权人可以拍卖、变卖质押财产，并与出质人协议将拍卖、变卖所得的价款提前清偿债务或者提存。"},{"i":434,"n":"第四百三十四条","txt":"质权人在质权存续期间，未经出质人同意转质，造成质押财产毁损、灭失的，应当承担赔偿责任。"},{"i":435,"n":"第四百三十五条","txt":"质权人可以放弃质权。债务人以自己的财产出质，质权人放弃该质权的，其他担保人在质权人丧失优先受偿权益的范围内免除担保责任，但是其他担保人承诺仍然提供担保的除外。"},{"i":436,"n":"第四百三十六条","txt":"债务人履行债务或者出质人提前清偿所担保的债权的，质权人应当返还质押财产。"},{"i":437,"n":"第四百三十七条","txt":"出质人可以请求质权人在债务履行期限届满后及时行使质权；质权人不行使的，出质人可以请求人民法院拍卖、变卖质押财产。"},{"i":438,"n":"第四百三十八条","txt":"质押财产折价或者拍卖、变卖后，其价款超过债权数额的部分归出质人所有，不足部分由债务人清偿。"},{"i":439,"n":"第四百三十九条","txt":"出质人与质权人可以协议设立最高额质权。"},{"i":440,"n":"第四百四十条","txt":"债务人或者第三人有权处分的下列权利可以出质："},{"i":441,"n":"第四百四十一条","txt":"以汇票、本票、支票、债券、存款单、仓单、提单出质的，质权自权利凭证交付质权人时设立；没有权利凭证的，质权自办理出质登记时设立。法律另有规定的，依照其规定。"},{"i":442,"n":"第四百四十二条","txt":"汇票、本票、支票、债券、存款单、仓单、提单的兑现日期或者提货日期先于主债权到期的，质权人可以兑现或者提货，并与出质人协议将兑现的价款或者提取的货物提前清偿债务或者提存。"},{"i":443,"n":"第四百四十三条","txt":"以基金份额、股权出质的，质权自办理出质登记时设立。"},{"i":444,"n":"第四百四十四条","txt":"以注册商标专用权、专利权、著作权等知识产权中的财产权出质的，质权自办理出质登记时设立。"},{"i":445,"n":"第四百四十五条","txt":"以应收账款出质的，质权自办理出质登记时设立。"},{"i":446,"n":"第四百四十六条","txt":"权利质权除适用本节规定外，适用本章第一节的有关规定。"},{"i":447,"n":"第四百四十七条","txt":"债务人不履行到期债务，债权人可以留置已经合法占有的债务人的动产，并有权就该动产优先受偿。"},{"i":448,"n":"第四百四十八条","txt":"债权人留置的动产，应当与债权属于同一法律关系，但是企业之间留置的除外。"},{"i":449,"n":"第四百四十九条","txt":"法律规定或者当事人约定不得留置的动产，不得留置。"},{"i":450,"n":"第四百五十条","txt":"留置财产为可分物的，留置财产的价值应当相当于债务的金额。"},{"i":451,"n":"第四百五十一条","txt":"留置权人负有妥善保管留置财产的义务；因保管不善致使留置财产毁损、灭失的，应当承担赔偿责任。"},{"i":452,"n":"第四百五十二条","txt":"留置权人有权收取留置财产的孳息。"},{"i":453,"n":"第四百五十三条","txt":"留置权人与债务人应当约定留置财产后的债务履行期限；没有约定或者约定不明确的，留置权人应当给债务人六十日以上履行债务的期限，但是鲜活易腐等不易保管的动产除外。债务人逾期未履行的，留置权人可以与债务人协议以留置财产折价，也可以就拍卖、变卖留置财产所得的价款优先受偿。"},{"i":454,"n":"第四百五十四条","txt":"债务人可以请求留置权人在债务履行期限届满后行使留置权；留置权人不行使的，债务人可以请求人民法院拍卖、变卖留置财产。"},{"i":455,"n":"第四百五十五条","txt":"留置财产折价或者拍卖、变卖后，其价款超过债权数额的部分归债务人所有，不足部分由债务人清偿。"},{"i":456,"n":"第四百五十六条","txt":"同一动产上已经设立抵押权或者质权，该动产又被留置的，留置权人优先受偿。"},{"i":457,"n":"第四百五十七条","txt":"留置权人对留置财产丧失占有或者留置权人接受债务人另行提供担保的，留置权消灭。"},{"i":458,"n":"第四百五十八条","txt":"基于合同关系等产生的占有，有关不动产或者动产的使用、收益、违约责任等，按照合同约定；合同没有约定或者约定不明确的，依照有关法律规定。"},{"i":459,"n":"第四百五十九条","txt":"占有人因使用占有的不动产或者动产，致使该不动产或者动产受到损害的，恶意占有人应当承担赔偿责任。"},{"i":460,"n":"第四百六十条","txt":"不动产或者动产被占有人占有的，权利人可以请求返还原物及其孳息；但是，应当支付善意占有人因维护该不动产或者动产支出的必要费用。"},{"i":461,"n":"第四百六十一条","txt":"占有的不动产或者动产毁损、灭失，该不动产或者动产的权利人请求赔偿的，占有人应当将因毁损、灭失取得的保险金、赔偿金或者补偿金等返还给权利人；权利人的损害未得到足够弥补的，恶意占有人还应当赔偿损失。"},{"i":462,"n":"第四百六十二条","txt":"占有的不动产或者动产被侵占的，占有人有权请求返还原物；对妨害占有的行为，占有人有权请求排除妨害或者消除危险；因侵占或者妨害造成损害的，占有人有权依法请求损害赔偿。"},{"i":463,"n":"第四百六十三条","txt":"本编调整因合同产生的民事关系。"},{"i":464,"n":"第四百六十四条","txt":"合同是民事主体之间设立、变更、终止民事法律关系的协议。"},{"i":465,"n":"第四百六十五条","txt":"依法成立的合同，受法律保护。"},{"i":466,"n":"第四百六十六条","txt":"当事人对合同条款的理解有争议的，应当依据本法第一百四十二条第一款的规定，确定争议条款的含义。"},{"i":467,"n":"第四百六十七条","txt":"本法或者其他法律没有明文规定的合同，适用本编通则的规定，并可以参照适用本编或者其他法律最相类似合同的规定。"},{"i":468,"n":"第四百六十八条","txt":"非因合同产生的债权债务关系，适用有关该债权债务关系的法律规定；没有规定的，适用本编通则的有关规定，但是根据其性质不能适用的除外。"},{"i":469,"n":"第四百六十九条","txt":"当事人订立合同，可以采用书面形式、口头形式或者其他形式。"},{"i":470,"n":"第四百七十条","txt":"合同的内容由当事人约定，一般包括下列条款："},{"i":471,"n":"第四百七十一条","txt":"当事人订立合同，可以采取要约、承诺方式或者其他方式。"},{"i":472,"n":"第四百七十二条","txt":"要约是希望与他人订立合同的意思表示，该意思表示应当符合下列条件："},{"i":473,"n":"第四百七十三条","txt":"要约邀请是希望他人向自己发出要约的表示。拍卖公告、招标公告、招股说明书、债券募集办法、基金招募说明书、商业广告和宣传、寄送的价目表等为要约邀请。"},{"i":474,"n":"第四百七十四条","txt":"要约生效的时间适用本法第一百三十七条的规定。"},{"i":475,"n":"第四百七十五条","txt":"要约可以撤回。要约的撤回适用本法第一百四十一条的规定。"},{"i":476,"n":"第四百七十六条","txt":"要约可以撤销，但是有下列情形之一的除外："},{"i":477,"n":"第四百七十七条","txt":"撤销要约的意思表示以对话方式作出的，该意思表示的内容应当在受要约人作出承诺之前为受要约人所知道；撤销要约的意思表示以非对话方式作出的，应当在受要约人作出承诺之前到达受要约人。"},{"i":478,"n":"第四百七十八条","txt":"有下列情形之一的，要约失效："},{"i":479,"n":"第四百七十九条","txt":"承诺是受要约人同意要约的意思表示。"},{"i":480,"n":"第四百八十条","txt":"承诺应当以通知的方式作出；但是，根据交易习惯或者要约表明可以通过行为作出承诺的除外。"},{"i":481,"n":"第四百八十一条","txt":"承诺应当在要约确定的期限内到达要约人。"},{"i":482,"n":"第四百八十二条","txt":"要约以信件或者电报作出的，承诺期限自信件载明的日期或者电报交发之日开始计算。信件未载明日期的，自投寄该信件的邮戳日期开始计算。要约以电话、传真、电子邮件等快速通讯方式作出的，承诺期限自要约到达受要约人时开始计算。"},{"i":483,"n":"第四百八十三条","txt":"承诺生效时合同成立，但是法律另有规定或者当事人另有约定的除外。"},{"i":484,"n":"第四百八十四条","txt":"以通知方式作出的承诺，生效的时间适用本法第一百三十七条的规定。"},{"i":485,"n":"第四百八十五条","txt":"承诺可以撤回。承诺的撤回适用本法第一百四十一条的规定。"},{"i":486,"n":"第四百八十六条","txt":"受要约人超过承诺期限发出承诺，或者在承诺期限内发出承诺，按照通常情形不能及时到达要约人的，为新要约；但是，要约人及时通知受要约人该承诺有效的除外。"},{"i":487,"n":"第四百八十七条","txt":"受要约人在承诺期限内发出承诺，按照通常情形能够及时到达要约人，但是因其他原因致使承诺到达要约人时超过承诺期限的，除要约人及时通知受要约人因承诺超过期限不接受该承诺外，该承诺有效。"},{"i":488,"n":"第四百八十八条","txt":"承诺的内容应当与要约的内容一致。受要约人对要约的内容作出实质性变更的，为新要约。有关合同标的、数量、质量、价款或者报酬、履行期限、履行地点和方式、违约责任和解决争议方法等的变更，是对要约内容的实质性变更。"},{"i":489,"n":"第四百八十九条","txt":"承诺对要约的内容作出非实质性变更的，除要约人及时表示反对或者要约表明承诺不得对要约的内容作出任何变更外，该承诺有效，合同的内容以承诺的内容为准。"},{"i":490,"n":"第四百九十条","txt":"当事人采用合同书形式订立合同的，自当事人均签名、盖章或者按指印时合同成立。在签名、盖章或者按指印之前，当事人一方已经履行主要义务，对方接受时，该合同成立。"},{"i":491,"n":"第四百九十一条","txt":"当事人采用信件、数据电文等形式订立合同要求签订确认书的，签订确认书时合同成立。"},{"i":492,"n":"第四百九十二条","txt":"承诺生效的地点为合同成立的地点。"},{"i":493,"n":"第四百九十三条","txt":"当事人采用合同书形式订立合同的，最后签名、盖章或者按指印的地点为合同成立的地点，但是当事人另有约定的除外。"},{"i":494,"n":"第四百九十四条","txt":"国家根据抢险救灾、疫情防控或者其他需要下达国家订货任务、指令性任务的，有关民事主体之间应当依照有关法律、行政法规规定的权利和义务订立合同。"},{"i":495,"n":"第四百九十五条","txt":"当事人约定在将来一定期限内订立合同的认购书、订购书、预订书等，构成预约合同。"},{"i":496,"n":"第四百九十六条","txt":"格式条款是当事人为了重复使用而预先拟定，并在订立合同时未与对方协商的条款。"},{"i":497,"n":"第四百九十七条","txt":"有下列情形之一的，该格式条款无效："},{"i":498,"n":"第四百九十八条","txt":"对格式条款的理解发生争议的，应当按照通常理解予以解释。对格式条款有两种以上解释的，应当作出不利于提供格式条款一方的解释。格式条款和非格式条款不一致的，应当采用非格式条款。"},{"i":499,"n":"第四百九十九条","txt":"悬赏人以公开方式声明对完成特定行为的人支付报酬的，完成该行为的人可以请求其支付。"},{"i":500,"n":"第五百条","txt":"当事人在订立合同过程中有下列情形之一，造成对方损失的，应当承担赔偿责任："},{"i":501,"n":"第五百零一条","txt":"当事人在订立合同过程中知悉的商业秘密或者其他应当保密的信息，无论合同是否成立，不得泄露或者不正当地使用；泄露、不正当地使用该商业秘密或者信息，造成对方损失的，应当承担赔偿责任。"},{"i":502,"n":"第五百零二条","txt":"依法成立的合同，自成立时生效，但是法律另有规定或者当事人另有约定的除外。"},{"i":503,"n":"第五百零三条","txt":"无权代理人以被代理人的名义订立合同，被代理人已经开始履行合同义务或者接受相对人履行的，视为对合同的追认。"},{"i":504,"n":"第五百零四条","txt":"法人的法定代表人或者非法人组织的负责人超越权限订立的合同，除相对人知道或者应当知道其超越权限外，该代表行为有效，订立的合同对法人或者非法人组织发生效力。"},{"i":505,"n":"第五百零五条","txt":"当事人超越经营范围订立的合同的效力，应当依照本法第一编第六章第三节和本编的有关规定确定，不得仅以超越经营范围确认合同无效。"},{"i":506,"n":"第五百零六条","txt":"合同中的下列免责条款无效："},{"i":507,"n":"第五百零七条","txt":"合同不生效、无效、被撤销或者终止的，不影响合同中有关解决争议方法的条款的效力。"},{"i":508,"n":"第五百零八条","txt":"本编对合同的效力没有规定的，适用本法第一编第六章的有关规定。"},{"i":509,"n":"第五百零九条","txt":"当事人应当按照约定全面履行自己的义务。"},{"i":510,"n":"第五百一十条","txt":"合同生效后，当事人就质量、价款或者报酬、履行地点等内容没有约定或者约定不明确的，可以协议补充；不能达成补充协议的，按照合同相关条款或者交易习惯确定。"},{"i":511,"n":"第五百一十一条","txt":"当事人就有关合同内容约定不明确，依据前条规定仍不能确定的，适用下列规定："},{"i":512,"n":"第五百一十二条","txt":"通过互联网等信息网络订立的电子合同的标的为交付商品并采用快递物流方式交付的，收货人的签收时间为交付时间。电子合同的标的为提供服务的，生成的电子凭证或者实物凭证中载明的时间为提供服务时间；前述凭证没有载明时间或者载明时间与实际提供服务时间不一致的，以实际提供服务的时间为准。"},{"i":513,"n":"第五百一十三条","txt":"执行政府定价或者政府指导价的，在合同约定的交付期限内政府价格调整时，按照交付时的价格计价。逾期交付标的物的，遇价格上涨时，按照原价格执行；价格下降时，按照新价格执行。逾期提取标的物或者逾期付款的，遇价格上涨时，按照新价格执行；价格下降时，按照原价格执行。"},{"i":514,"n":"第五百一十四条","txt":"以支付金钱为内容的债，除法律另有规定或者当事人另有约定外，债权人可以请求债务人以实际履行地的法定货币履行。"},{"i":515,"n":"第五百一十五条","txt":"标的有多项而债务人只需履行其中一项的，债务人享有选择权；但是，法律另有规定、当事人另有约定或者另有交易习惯的除外。"},{"i":516,"n":"第五百一十六条","txt":"当事人行使选择权应当及时通知对方，通知到达对方时，标的确定。标的确定后不得变更，但是经对方同意的除外。"},{"i":517,"n":"第五百一十七条","txt":"债权人为二人以上，标的可分，按照份额各自享有债权的，为按份债权；债务人为二人以上，标的可分，按照份额各自负担债务的，为按份债务。"},{"i":518,"n":"第五百一十八条","txt":"债权人为二人以上，部分或者全部债权人均可以请求债务人履行债务的，为连带债权；债务人为二人以上，债权人可以请求部分或者全部债务人履行全部债务的，为连带债务。"},{"i":519,"n":"第五百一十九条","txt":"连带债务人之间的份额难以确定的，视为份额相同。"},{"i":520,"n":"第五百二十条","txt":"部分连带债务人履行、抵销债务或者提存标的物的，其他债务人对债权人的债务在相应范围内消灭；该债务人可以依据前条规定向其他债务人追偿。"},{"i":521,"n":"第五百二十一条","txt":"连带债权人之间的份额难以确定的，视为份额相同。"},{"i":522,"n":"第五百二十二条","txt":"当事人约定由债务人向第三人履行债务，债务人未向第三人履行债务或者履行债务不符合约定的，应当向债权人承担违约责任。"},{"i":523,"n":"第五百二十三条","txt":"当事人约定由第三人向债权人履行债务，第三人不履行债务或者履行债务不符合约定的，债务人应当向债权人承担违约责任。"},{"i":524,"n":"第五百二十四条","txt":"债务人不履行债务，第三人对履行该债务具有合法利益的，第三人有权向债权人代为履行；但是，根据债务性质、按照当事人约定或者依照法律规定只能由债务人履行的除外。"},{"i":525,"n":"第五百二十五条","txt":"当事人互负债务，没有先后履行顺序的，应当同时履行。一方在对方履行之前有权拒绝其履行请求。一方在对方履行债务不符合约定时，有权拒绝其相应的履行请求。"},{"i":526,"n":"第五百二十六条","txt":"当事人互负债务，有先后履行顺序，应当先履行债务一方未履行的，后履行一方有权拒绝其履行请求。先履行一方履行债务不符合约定的，后履行一方有权拒绝其相应的履行请求。"},{"i":527,"n":"第五百二十七条","txt":"应当先履行债务的当事人，有确切证据证明对方有下列情形之一的，可以中止履行："},{"i":528,"n":"第五百二十八条","txt":"当事人依据前条规定中止履行的，应当及时通知对方。对方提供适当担保的，应当恢复履行。中止履行后，对方在合理期限内未恢复履行能力且未提供适当担保的，视为以自己的行为表明不履行主要债务，中止履行的一方可以解除合同并可以请求对方承担违约责任。"},{"i":529,"n":"第五百二十九条","txt":"债权人分立、合并或者变更住所没有通知债务人，致使履行债务发生困难的，债务人可以中止履行或者将标的物提存。"},{"i":530,"n":"第五百三十条","txt":"债权人可以拒绝债务人提前履行债务，但是提前履行不损害债权人利益的除外。"},{"i":531,"n":"第五百三十一条","txt":"债权人可以拒绝债务人部分履行债务，但是部分履行不损害债权人利益的除外。"},{"i":532,"n":"第五百三十二条","txt":"合同生效后，当事人不得因姓名、名称的变更或者法定代表人、负责人、承办人的变动而不履行合同义务。"},{"i":533,"n":"第五百三十三条","txt":"合同成立后，合同的基础条件发生了当事人在订立合同时无法预见的、不属于商业风险的重大变化，继续履行合同对于当事人一方明显不公平的，受不利影响的当事人可以与对方重新协商；在合理期限内协商不成的，当事人可以请求人民法院或者仲裁机构变更或者解除合同。"},{"i":534,"n":"第五百三十四条","txt":"对当事人利用合同实施危害国家利益、社会公共利益行为的，市场监督管理和其他有关行政主管部门依照法律、行政法规的规定负责监督处理。"},{"i":535,"n":"第五百三十五条","txt":"因债务人怠于行使其债权或者与该债权有关的从权利，影响债权人的到期债权实现的，债权人可以向人民法院请求以自己的名义代位行使债务人对相对人的权利，但是该权利专属于债务人自身的除外。"},{"i":536,"n":"第五百三十六条","txt":"债权人的债权到期前，债务人的债权或者与该债权有关的从权利存在诉讼时效期间即将届满或者未及时申报破产债权等情形，影响债权人的债权实现的，债权人可以代位向债务人的相对人请求其向债务人履行、向破产管理人申报或者作出其他必要的行为。"},{"i":537,"n":"第五百三十七条","txt":"人民法院认定代位权成立的，由债务人的相对人向债权人履行义务，债权人接受履行后，债权人与债务人、债务人与相对人之间相应的权利义务终止。债务人对相对人的债权或者与该债权有关的从权利被采取保全、执行措施，或者债务人破产的，依照相关法律的规定处理。"},{"i":538,"n":"第五百三十八条","txt":"债务人以放弃其债权、放弃债权担保、无偿转让财产等方式无偿处分财产权益，或者恶意延长其到期债权的履行期限，影响债权人的债权实现的，债权人可以请求人民法院撤销债务人的行为。"},{"i":539,"n":"第五百三十九条","txt":"债务人以明显不合理的低价转让财产、以明显不合理的高价受让他人财产或者为他人的债务提供担保，影响债权人的债权实现，债务人的相对人知道或者应当知道该情形的，债权人可以请求人民法院撤销债务人的行为。"},{"i":540,"n":"第五百四十条","txt":"撤销权的行使范围以债权人的债权为限。债权人行使撤销权的必要费用，由债务人负担。"},{"i":541,"n":"第五百四十一条","txt":"撤销权自债权人知道或者应当知道撤销事由之日起一年内行使。自债务人的行为发生之日起五年内没有行使撤销权的，该撤销权消灭。"},{"i":542,"n":"第五百四十二条","txt":"债务人影响债权人的债权实现的行为被撤销的，自始没有法律约束力。"},{"i":543,"n":"第五百四十三条","txt":"当事人协商一致，可以变更合同。"},{"i":544,"n":"第五百四十四条","txt":"当事人对合同变更的内容约定不明确的，推定为未变更。"},{"i":545,"n":"第五百四十五条","txt":"债权人可以将债权的全部或者部分转让给第三人，但是有下列情形之一的除外："},{"i":546,"n":"第五百四十六条","txt":"债权人转让债权，未通知债务人的，该转让对债务人不发生效力。"},{"i":547,"n":"第五百四十七条","txt":"债权人转让债权的，受让人取得与债权有关的从权利，但是该从权利专属于债权人自身的除外。"},{"i":548,"n":"第五百四十八条","txt":"债务人接到债权转让通知后，债务人对让与人的抗辩，可以向受让人主张。"},{"i":549,"n":"第五百四十九条","txt":"有下列情形之一的，债务人可以向受让人主张抵销："},{"i":550,"n":"第五百五十条","txt":"因债权转让增加的履行费用，由让与人负担。"},{"i":551,"n":"第五百五十一条","txt":"债务人将债务的全部或者部分转移给第三人的，应当经债权人同意。"},{"i":552,"n":"第五百五十二条","txt":"第三人与债务人约定加入债务并通知债权人，或者第三人向债权人表示愿意加入债务，债权人未在合理期限内明确拒绝的，债权人可以请求第三人在其愿意承担的债务范围内和债务人承担连带债务。"},{"i":553,"n":"第五百五十三条","txt":"债务人转移债务的，新债务人可以主张原债务人对债权人的抗辩；原债务人对债权人享有债权的，新债务人不得向债权人主张抵销。"},{"i":554,"n":"第五百五十四条","txt":"债务人转移债务的，新债务人应当承担与主债务有关的从债务，但是该从债务专属于原债务人自身的除外。"},{"i":555,"n":"第五百五十五条","txt":"当事人一方经对方同意，可以将自己在合同中的权利和义务一并转让给第三人。"},{"i":556,"n":"第五百五十六条","txt":"合同的权利和义务一并转让的，适用债权转让、债务转移的有关规定。"},{"i":557,"n":"第五百五十七条","txt":"有下列情形之一的，债权债务终止："},{"i":558,"n":"第五百五十八条","txt":"债权债务终止后，当事人应当遵循诚信等原则，根据交易习惯履行通知、协助、保密、旧物回收等义务。"},{"i":559,"n":"第五百五十九条","txt":"债权债务终止时，债权的从权利同时消灭，但是法律另有规定或者当事人另有约定的除外。"},{"i":560,"n":"第五百六十条","txt":"债务人对同一债权人负担的数项债务种类相同，债务人的给付不足以清偿全部债务的，除当事人另有约定外，由债务人在清偿时指定其履行的债务。"},{"i":561,"n":"第五百六十一条","txt":"债务人在履行主债务外还应当支付利息和实现债权的有关费用，其给付不足以清偿全部债务的，除当事人另有约定外，应当按照下列顺序履行："},{"i":562,"n":"第五百六十二条","txt":"当事人协商一致，可以解除合同。"},{"i":563,"n":"第五百六十三条","txt":"有下列情形之一的，当事人可以解除合同："},{"i":564,"n":"第五百六十四条","txt":"法律规定或者当事人约定解除权行使期限，期限届满当事人不行使的，该权利消灭。"},{"i":565,"n":"第五百六十五条","txt":"当事人一方依法主张解除合同的，应当通知对方。合同自通知到达对方时解除；通知载明债务人在一定期限内不履行债务则合同自动解除，债务人在该期限内未履行债务的，合同自通知载明的期限届满时解除。对方对解除合同有异议的，任何一方当事人均可以请求人民法院或者仲裁机构确认解除行为的效力。"},{"i":566,"n":"第五百六十六条","txt":"合同解除后，尚未履行的，终止履行；已经履行的，根据履行情况和合同性质，当事人可以请求恢复原状或者采取其他补救措施，并有权请求赔偿损失。"},{"i":567,"n":"第五百六十七条","txt":"合同的权利义务关系终止，不影响合同中结算和清理条款的效力。"},{"i":568,"n":"第五百六十八条","txt":"当事人互负债务，该债务的标的物种类、品质相同的，任何一方可以将自己的债务与对方的到期债务抵销；但是，根据债务性质、按照当事人约定或者依照法律规定不得抵销的除外。"},{"i":569,"n":"第五百六十九条","txt":"当事人互负债务，标的物种类、品质不相同的，经协商一致，也可以抵销。"},{"i":570,"n":"第五百七十条","txt":"有下列情形之一，难以履行债务的，债务人可以将标的物提存："},{"i":571,"n":"第五百七十一条","txt":"债务人将标的物或者将标的物依法拍卖、变卖所得价款交付提存部门时，提存成立。"},{"i":572,"n":"第五百七十二条","txt":"标的物提存后，债务人应当及时通知债权人或者债权人的继承人、遗产管理人、监护人、财产代管人。"},{"i":573,"n":"第五百七十三条","txt":"标的物提存后，毁损、灭失的风险由债权人承担。提存期间，标的物的孳息归债权人所有。提存费用由债权人负担。"},{"i":574,"n":"第五百七十四条","txt":"债权人可以随时领取提存物。但是，债权人对债务人负有到期债务的，在债权人未履行债务或者提供担保之前，提存部门根据债务人的要求应当拒绝其领取提存物。"},{"i":575,"n":"第五百七十五条","txt":"债权人免除债务人部分或者全部债务的，债权债务部分或者全部终止，但是债务人在合理期限内拒绝的除外。"},{"i":576,"n":"第五百七十六条","txt":"债权和债务同归于一人的，债权债务终止，但是损害第三人利益的除外。"},{"i":577,"n":"第五百七十七条","txt":"当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。"},{"i":578,"n":"第五百七十八条","txt":"当事人一方明确表示或者以自己的行为表明不履行合同义务的，对方可以在履行期限届满前请求其承担违约责任。"},{"i":579,"n":"第五百七十九条","txt":"当事人一方未支付价款、报酬、租金、利息，或者不履行其他金钱债务的，对方可以请求其支付。"},{"i":580,"n":"第五百八十条","txt":"当事人一方不履行非金钱债务或者履行非金钱债务不符合约定的，对方可以请求履行，但是有下列情形之一的除外："},{"i":581,"n":"第五百八十一条","txt":"当事人一方不履行债务或者履行债务不符合约定，根据债务的性质不得强制履行的，对方可以请求其负担由第三人替代履行的费用。"},{"i":582,"n":"第五百八十二条","txt":"履行不符合约定的，应当按照当事人的约定承担违约责任。对违约责任没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，受损害方根据标的的性质以及损失的大小，可以合理选择请求对方承担修理、重作、更换、退货、减少价款或者报酬等违约责任。"},{"i":583,"n":"第五百八十三条","txt":"当事人一方不履行合同义务或者履行合同义务不符合约定的，在履行义务或者采取补救措施后，对方还有其他损失的，应当赔偿损失。"},{"i":584,"n":"第五百八十四条","txt":"当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。"},{"i":585,"n":"第五百八十五条","txt":"当事人可以约定一方违约时应当根据违约情况向对方支付一定数额的违约金，也可以约定因违约产生的损失赔偿额的计算方法。"},{"i":586,"n":"第五百八十六条","txt":"当事人可以约定一方向对方给付定金作为债权的担保。定金合同自实际交付定金时成立。"},{"i":587,"n":"第五百八十七条","txt":"债务人履行债务的，定金应当抵作价款或者收回。给付定金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，无权请求返还定金；收受定金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，应当双倍返还定金。"},{"i":588,"n":"第五百八十八条","txt":"当事人既约定违约金，又约定定金的，一方违约时，对方可以选择适用违约金或者定金条款。"},{"i":589,"n":"第五百八十九条","txt":"债务人按照约定履行债务，债权人无正当理由拒绝受领的，债务人可以请求债权人赔偿增加的费用。"},{"i":590,"n":"第五百九十条","txt":"当事人一方因不可抗力不能履行合同的，根据不可抗力的影响，部分或者全部免除责任，但是法律另有规定的除外。因不可抗力不能履行合同的，应当及时通知对方，以减轻可能给对方造成的损失，并应当在合理期限内提供证明。"},{"i":591,"n":"第五百九十一条","txt":"当事人一方违约后，对方应当采取适当措施防止损失的扩大；没有采取适当措施致使损失扩大的，不得就扩大的损失请求赔偿。"},{"i":592,"n":"第五百九十二条","txt":"当事人都违反合同的，应当各自承担相应的责任。"},{"i":593,"n":"第五百九十三条","txt":"当事人一方因第三人的原因造成违约的，应当依法向对方承担违约责任。当事人一方和第三人之间的纠纷，依照法律规定或者按照约定处理。"},{"i":594,"n":"第五百九十四条","txt":"因国际货物买卖合同和技术进出口合同争议提起诉讼或者申请仲裁的时效期间为四年。"},{"i":595,"n":"第五百九十五条","txt":"买卖合同是出卖人转移标的物的所有权于买受人，买受人支付价款的合同。"},{"i":596,"n":"第五百九十六条","txt":"买卖合同的内容一般包括标的物的名称、数量、质量、价款、履行期限、履行地点和方式、包装方式、检验标准和方法、结算方式、合同使用的文字及其效力等条款。"},{"i":597,"n":"第五百九十七条","txt":"因出卖人未取得处分权致使标的物所有权不能转移的，买受人可以解除合同并请求出卖人承担违约责任。"},{"i":598,"n":"第五百九十八条","txt":"出卖人应当履行向买受人交付标的物或者交付提取标的物的单证，并转移标的物所有权的义务。"},{"i":599,"n":"第五百九十九条","txt":"出卖人应当按照约定或者交易习惯向买受人交付提取标的物单证以外的有关单证和资料。"},{"i":600,"n":"第六百条","txt":"出卖具有知识产权的标的物的，除法律另有规定或者当事人另有约定外，该标的物的知识产权不属于买受人。"},{"i":601,"n":"第六百零一条","txt":"出卖人应当按照约定的时间交付标的物。约定交付期限的，出卖人可以在该交付期限内的任何时间交付。"},{"i":602,"n":"第六百零二条","txt":"当事人没有约定标的物的交付期限或者约定不明确的，适用本法第五百一十条、第五百一十一条第四项的规定。"},{"i":603,"n":"第六百零三条","txt":"出卖人应当按照约定的地点交付标的物。"},{"i":604,"n":"第六百零四条","txt":"标的物毁损、灭失的风险，在标的物交付之前由出卖人承担，交付之后由买受人承担，但是法律另有规定或者当事人另有约定的除外。"},{"i":605,"n":"第六百零五条","txt":"因买受人的原因致使标的物未按照约定的期限交付的，买受人应当自违反约定时起承担标的物毁损、灭失的风险。"},{"i":606,"n":"第六百零六条","txt":"出卖人出卖交由承运人运输的在途标的物，除当事人另有约定外，毁损、灭失的风险自合同成立时起由买受人承担。"},{"i":607,"n":"第六百零七条","txt":"出卖人按照约定将标的物运送至买受人指定地点并交付给承运人后，标的物毁损、灭失的风险由买受人承担。"},{"i":608,"n":"第六百零八条","txt":"出卖人按照约定或者依据本法第六百零三条第二款第二项的规定将标的物置于交付地点，买受人违反约定没有收取的，标的物毁损、灭失的风险自违反约定时起由买受人承担。"},{"i":609,"n":"第六百零九条","txt":"出卖人按照约定未交付有关标的物的单证和资料的，不影响标的物毁损、灭失风险的转移。"},{"i":610,"n":"第六百一十条","txt":"因标的物不符合质量要求，致使不能实现合同目的的，买受人可以拒绝接受标的物或者解除合同。买受人拒绝接受标的物或者解除合同的，标的物毁损、灭失的风险由出卖人承担。"},{"i":611,"n":"第六百一十一条","txt":"标的物毁损、灭失的风险由买受人承担的，不影响因出卖人履行义务不符合约定，买受人请求其承担违约责任的权利。"},{"i":612,"n":"第六百一十二条","txt":"出卖人就交付的标的物，负有保证第三人对该标的物不享有任何权利的义务，但是法律另有规定的除外。"},{"i":613,"n":"第六百一十三条","txt":"买受人订立合同时知道或者应当知道第三人对买卖的标的物享有权利的，出卖人不承担前条规定的义务。"},{"i":614,"n":"第六百一十四条","txt":"买受人有确切证据证明第三人对标的物享有权利的，可以中止支付相应的价款，但是出卖人提供适当担保的除外。"},{"i":615,"n":"第六百一十五条","txt":"出卖人应当按照约定的质量要求交付标的物。出卖人提供有关标的物质量说明的，交付的标的物应当符合该说明的质量要求。"},{"i":616,"n":"第六百一十六条","txt":"当事人对标的物的质量要求没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，适用本法第五百一十一条第一项的规定。"},{"i":617,"n":"第六百一十七条","txt":"出卖人交付的标的物不符合质量要求的，买受人可以依据本法第五百八十二条至第五百八十四条的规定请求承担违约责任。"},{"i":618,"n":"第六百一十八条","txt":"当事人约定减轻或者免除出卖人对标的物瑕疵承担的责任，因出卖人故意或者重大过失不告知买受人标的物瑕疵的，出卖人无权主张减轻或者免除责任。"},{"i":619,"n":"第六百一十九条","txt":"出卖人应当按照约定的包装方式交付标的物。对包装方式没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，应当按照通用的方式包装；没有通用方式的，应当采取足以保护标的物且有利于节约资源、保护生态环境的包装方式。"},{"i":620,"n":"第六百二十条","txt":"买受人收到标的物时应当在约定的检验期限内检验。没有约定检验期限的，应当及时检验。"},{"i":621,"n":"第六百二十一条","txt":"当事人约定检验期限的，买受人应当在检验期限内将标的物的数量或者质量不符合约定的情形通知出卖人。买受人怠于通知的，视为标的物的数量或者质量符合约定。"},{"i":622,"n":"第六百二十二条","txt":"当事人约定的检验期限过短，根据标的物的性质和交易习惯，买受人在检验期限内难以完成全面检验的，该期限仅视为买受人对标的物的外观瑕疵提出异议的期限。"},{"i":623,"n":"第六百二十三条","txt":"当事人对检验期限未作约定，买受人签收的送货单、确认单等载明标的物数量、型号、规格的，推定买受人已经对数量和外观瑕疵进行检验，但是有相关证据足以推翻的除外。"},{"i":624,"n":"第六百二十四条","txt":"出卖人依照买受人的指示向第三人交付标的物，出卖人和买受人约定的检验标准与买受人和第三人约定的检验标准不一致的，以出卖人和买受人约定的检验标准为准。"},{"i":625,"n":"第六百二十五条","txt":"依照法律、行政法规的规定或者按照当事人的约定，标的物在有效使用年限届满后应予回收的，出卖人负有自行或者委托第三人对标的物予以回收的义务。"},{"i":626,"n":"第六百二十六条","txt":"买受人应当按照约定的数额和支付方式支付价款。对价款的数额和支付方式没有约定或者约定不明确的，适用本法第五百一十条、第五百一十一条第二项和第五项的规定。"},{"i":627,"n":"第六百二十七条","txt":"买受人应当按照约定的地点支付价款。对支付地点没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，买受人应当在出卖人的营业地支付；但是，约定支付价款以交付标的物或者交付提取标的物单证为条件的，在交付标的物或者交付提取标的物单证的所在地支付。"},{"i":628,"n":"第六百二十八条","txt":"买受人应当按照约定的时间支付价款。对支付时间没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，买受人应当在收到标的物或者提取标的物单证的同时支付。"},{"i":629,"n":"第六百二十九条","txt":"出卖人多交标的物的，买受人可以接收或者拒绝接收多交的部分。买受人接收多交部分的，按照约定的价格支付价款；买受人拒绝接收多交部分的，应当及时通知出卖人。"},{"i":630,"n":"第六百三十条","txt":"标的物在交付之前产生的孳息，归出卖人所有；交付之后产生的孳息，归买受人所有。但是，当事人另有约定的除外。"},{"i":631,"n":"第六百三十一条","txt":"因标的物的主物不符合约定而解除合同的，解除合同的效力及于从物。因标的物的从物不符合约定被解除的，解除的效力不及于主物。"},{"i":632,"n":"第六百三十二条","txt":"标的物为数物，其中一物不符合约定的，买受人可以就该物解除。但是，该物与他物分离使标的物的价值显受损害的，买受人可以就数物解除合同。"},{"i":633,"n":"第六百三十三条","txt":"出卖人分批交付标的物的，出卖人对其中一批标的物不交付或者交付不符合约定，致使该批标的物不能实现合同目的的，买受人可以就该批标的物解除。"},{"i":634,"n":"第六百三十四条","txt":"分期付款的买受人未支付到期价款的数额达到全部价款的五分之一，经催告后在合理期限内仍未支付到期价款的，出卖人可以请求买受人支付全部价款或者解除合同。"},{"i":635,"n":"第六百三十五条","txt":"凭样品买卖的当事人应当封存样品，并可以对样品质量予以说明。出卖人交付的标的物应当与样品及其说明的质量相同。"},{"i":636,"n":"第六百三十六条","txt":"凭样品买卖的买受人不知道样品有隐蔽瑕疵的，即使交付的标的物与样品相同，出卖人交付的标的物的质量仍然应当符合同种物的通常标准。"},{"i":637,"n":"第六百三十七条","txt":"试用买卖的当事人可以约定标的物的试用期限。对试用期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，由出卖人确定。"},{"i":638,"n":"第六百三十八条","txt":"试用买卖的买受人在试用期内可以购买标的物，也可以拒绝购买。试用期限届满，买受人对是否购买标的物未作表示的，视为购买。"},{"i":639,"n":"第六百三十九条","txt":"试用买卖的当事人对标的物使用费没有约定或者约定不明确的，出卖人无权请求买受人支付。"},{"i":640,"n":"第六百四十条","txt":"标的物在试用期内毁损、灭失的风险由出卖人承担。"},{"i":641,"n":"第六百四十一条","txt":"当事人可以在买卖合同中约定买受人未履行支付价款或者其他义务的，标的物的所有权属于出卖人。"},{"i":642,"n":"第六百四十二条","txt":"当事人约定出卖人保留合同标的物的所有权，在标的物所有权转移前，买受人有下列情形之一，造成出卖人损害的，除当事人另有约定外，出卖人有权取回标的物："},{"i":643,"n":"第六百四十三条","txt":"出卖人依据前条第一款的规定取回标的物后，买受人在双方约定或者出卖人指定的合理回赎期限内，消除出卖人取回标的物的事由的，可以请求回赎标的物。"},{"i":644,"n":"第六百四十四条","txt":"招标投标买卖的当事人的权利和义务以及招标投标程序等，依照有关法律、行政法规的规定。"},{"i":645,"n":"第六百四十五条","txt":"拍卖的当事人的权利和义务以及拍卖程序等，依照有关法律、行政法规的规定。"},{"i":646,"n":"第六百四十六条","txt":"法律对其他有偿合同有规定的，依照其规定；没有规定的，参照适用买卖合同的有关规定。"},{"i":647,"n":"第六百四十七条","txt":"当事人约定易货交易，转移标的物的所有权的，参照适用买卖合同的有关规定。"},{"i":648,"n":"第六百四十八条","txt":"供用电合同是供电人向用电人供电，用电人支付电费的合同。"},{"i":649,"n":"第六百四十九条","txt":"供用电合同的内容一般包括供电的方式、质量、时间，用电容量、地址、性质，计量方式，电价、电费的结算方式，供用电设施的维护责任等条款。"},{"i":650,"n":"第六百五十条","txt":"供用电合同的履行地点，按照当事人约定；当事人没有约定或者约定不明确的，供电设施的产权分界处为履行地点。"},{"i":651,"n":"第六百五十一条","txt":"供电人应当按照国家规定的供电质量标准和约定安全供电。供电人未按照国家规定的供电质量标准和约定安全供电，造成用电人损失的，应当承担赔偿责任。"},{"i":652,"n":"第六百五十二条","txt":"供电人因供电设施计划检修、临时检修、依法限电或者用电人违法用电等原因，需要中断供电时，应当按照国家有关规定事先通知用电人；未事先通知用电人中断供电，造成用电人损失的，应当承担赔偿责任。"},{"i":653,"n":"第六百五十三条","txt":"因自然灾害等原因断电，供电人应当按照国家有关规定及时抢修；未及时抢修，造成用电人损失的，应当承担赔偿责任。"},{"i":654,"n":"第六百五十四条","txt":"用电人应当按照国家有关规定和当事人的约定及时支付电费。用电人逾期不支付电费的，应当按照约定支付违约金。经催告用电人在合理期限内仍不支付电费和违约金的，供电人可以按照国家规定的程序中止供电。"},{"i":655,"n":"第六百五十五条","txt":"用电人应当按照国家有关规定和当事人的约定安全、节约和计划用电。用电人未按照国家有关规定和当事人的约定用电，造成供电人损失的，应当承担赔偿责任。"},{"i":656,"n":"第六百五十六条","txt":"供用水、供用气、供用热力合同，参照适用供用电合同的有关规定。"},{"i":657,"n":"第六百五十七条","txt":"赠与合同是赠与人将自己的财产无偿给予受赠人，受赠人表示接受赠与的合同。"},{"i":658,"n":"第六百五十八条","txt":"赠与人在赠与财产的权利转移之前可以撤销赠与。"},{"i":659,"n":"第六百五十九条","txt":"赠与的财产依法需要办理登记或者其他手续的，应当办理有关手续。"},{"i":660,"n":"第六百六十条","txt":"经过公证的赠与合同或者依法不得撤销的具有救灾、扶贫、助残等公益、道德义务性质的赠与合同，赠与人不交付赠与财产的，受赠人可以请求交付。"},{"i":661,"n":"第六百六十一条","txt":"赠与可以附义务。"},{"i":662,"n":"第六百六十二条","txt":"赠与的财产有瑕疵的，赠与人不承担责任。附义务的赠与，赠与的财产有瑕疵的，赠与人在附义务的限度内承担与出卖人相同的责任。"},{"i":663,"n":"第六百六十三条","txt":"受赠人有下列情形之一的，赠与人可以撤销赠与："},{"i":664,"n":"第六百六十四条","txt":"因受赠人的违法行为致使赠与人死亡或者丧失民事行为能力的，赠与人的继承人或者法定代理人可以撤销赠与。"},{"i":665,"n":"第六百六十五条","txt":"撤销权人撤销赠与的，可以向受赠人请求返还赠与的财产。"},{"i":666,"n":"第六百六十六条","txt":"赠与人的经济状况显著恶化，严重影响其生产经营或者家庭生活的，可以不再履行赠与义务。"},{"i":667,"n":"第六百六十七条","txt":"借款合同是借款人向贷款人借款，到期返还借款并支付利息的合同。"},{"i":668,"n":"第六百六十八条","txt":"借款合同应当采用书面形式，但是自然人之间借款另有约定的除外。"},{"i":669,"n":"第六百六十九条","txt":"订立借款合同，借款人应当按照贷款人的要求提供与借款有关的业务活动和财务状况的真实情况。"},{"i":670,"n":"第六百七十条","txt":"借款的利息不得预先在本金中扣除。利息预先在本金中扣除的，应当按照实际借款数额返还借款并计算利息。"},{"i":671,"n":"第六百七十一条","txt":"贷款人未按照约定的日期、数额提供借款，造成借款人损失的，应当赔偿损失。"},{"i":672,"n":"第六百七十二条","txt":"贷款人按照约定可以检查、监督借款的使用情况。借款人应当按照约定向贷款人定期提供有关财务会计报表或者其他资料。"},{"i":673,"n":"第六百七十三条","txt":"借款人未按照约定的借款用途使用借款的，贷款人可以停止发放借款、提前收回借款或者解除合同。"},{"i":674,"n":"第六百七十四条","txt":"借款人应当按照约定的期限支付利息。对支付利息的期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定，借款期间不满一年的，应当在返还借款时一并支付；借款期间一年以上的，应当在每届满一年时支付，剩余期间不满一年的，应当在返还借款时一并支付。"},{"i":675,"n":"第六百七十五条","txt":"借款人应当按照约定的期限返还借款。对借款期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，借款人可以随时返还；贷款人可以催告借款人在合理期限内返还。"},{"i":676,"n":"第六百七十六条","txt":"借款人未按照约定的期限返还借款的，应当按照约定或者国家有关规定支付逾期利息。"},{"i":677,"n":"第六百七十七条","txt":"借款人提前返还借款的，除当事人另有约定外，应当按照实际借款的期间计算利息。"},{"i":678,"n":"第六百七十八条","txt":"借款人可以在还款期限届满前向贷款人申请展期；贷款人同意的，可以展期。"},{"i":679,"n":"第六百七十九条","txt":"自然人之间的借款合同，自贷款人提供借款时成立。"},{"i":680,"n":"第六百八十条","txt":"禁止高利放贷，借款的利率不得违反国家有关规定。"},{"i":681,"n":"第六百八十一条","txt":"保证合同是为保障债权的实现，保证人和债权人约定，当债务人不履行到期债务或者发生当事人约定的情形时，保证人履行债务或者承担责任的合同。"},{"i":682,"n":"第六百八十二条","txt":"保证合同是主债权债务合同的从合同。主债权债务合同无效的，保证合同无效，但是法律另有规定的除外。"},{"i":683,"n":"第六百八十三条","txt":"机关法人不得为保证人，但是经国务院批准为使用外国政府或者国际经济组织贷款进行转贷的除外。"},{"i":684,"n":"第六百八十四条","txt":"保证合同的内容一般包括被保证的主债权的种类、数额，债务人履行债务的期限，保证的方式、范围和期间等条款。"},{"i":685,"n":"第六百八十五条","txt":"保证合同可以是单独订立的书面合同，也可以是主债权债务合同中的保证条款。"},{"i":686,"n":"第六百八十六条","txt":"保证的方式包括一般保证和连带责任保证。"},{"i":687,"n":"第六百八十七条","txt":"当事人在保证合同中约定，债务人不能履行债务时，由保证人承担保证责任的，为一般保证。"},{"i":688,"n":"第六百八十八条","txt":"当事人在保证合同中约定保证人和债务人对债务承担连带责任的，为连带责任保证。"},{"i":689,"n":"第六百八十九条","txt":"保证人可以要求债务人提供反担保。"},{"i":690,"n":"第六百九十条","txt":"保证人与债权人可以协商订立最高额保证的合同，约定在最高债权额限度内就一定期间连续发生的债权提供保证。"},{"i":691,"n":"第六百九十一条","txt":"保证的范围包括主债权及其利息、违约金、损害赔偿金和实现债权的费用。当事人另有约定的，按照其约定。"},{"i":692,"n":"第六百九十二条","txt":"保证期间是确定保证人承担保证责任的期间，不发生中止、中断和延长。"},{"i":693,"n":"第六百九十三条","txt":"一般保证的债权人未在保证期间对债务人提起诉讼或者申请仲裁的，保证人不再承担保证责任。"},{"i":694,"n":"第六百九十四条","txt":"一般保证的债权人在保证期间届满前对债务人提起诉讼或者申请仲裁的，从保证人拒绝承担保证责任的权利消灭之日起，开始计算保证债务的诉讼时效。"},{"i":695,"n":"第六百九十五条","txt":"债权人和债务人未经保证人书面同意，协商变更主债权债务合同内容，减轻债务的，保证人仍对变更后的债务承担保证责任；加重债务的，保证人对加重的部分不承担保证责任。"},{"i":696,"n":"第六百九十六条","txt":"债权人转让全部或者部分债权，未通知保证人的，该转让对保证人不发生效力。"},{"i":697,"n":"第六百九十七条","txt":"债权人未经保证人书面同意，允许债务人转移全部或者部分债务，保证人对未经其同意转移的债务不再承担保证责任，但是债权人和保证人另有约定的除外。"},{"i":698,"n":"第六百九十八条","txt":"一般保证的保证人在主债务履行期限届满后，向债权人提供债务人可供执行财产的真实情况，债权人放弃或者怠于行使权利致使该财产不能被执行的，保证人在其提供可供执行财产的价值范围内不再承担保证责任。"},{"i":699,"n":"第六百九十九条","txt":"同一债务有两个以上保证人的，保证人应当按照保证合同约定的保证份额，承担保证责任；没有约定保证份额的，债权人可以请求任何一个保证人在其保证范围内承担保证责任。"},{"i":700,"n":"第七百条","txt":"保证人承担保证责任后，除当事人另有约定外，有权在其承担保证责任的范围内向债务人追偿，享有债权人对债务人的权利，但是不得损害债权人的利益。"},{"i":701,"n":"第七百零一条","txt":"保证人可以主张债务人对债权人的抗辩。债务人放弃抗辩的，保证人仍有权向债权人主张抗辩。"},{"i":702,"n":"第七百零二条","txt":"债务人对债权人享有抵销权或者撤销权的，保证人可以在相应范围内拒绝承担保证责任。"},{"i":703,"n":"第七百零三条","txt":"租赁合同是出租人将租赁物交付承租人使用、收益，承租人支付租金的合同。"},{"i":704,"n":"第七百零四条","txt":"租赁合同的内容一般包括租赁物的名称、数量、用途、租赁期限、租金及其支付期限和方式、租赁物维修等条款。"},{"i":705,"n":"第七百零五条","txt":"租赁期限不得超过二十年。超过二十年的，超过部分无效。"},{"i":706,"n":"第七百零六条","txt":"当事人未依照法律、行政法规规定办理租赁合同登记备案手续的，不影响合同的效力。"},{"i":707,"n":"第七百零七条","txt":"租赁期限六个月以上的，应当采用书面形式。当事人未采用书面形式，无法确定租赁期限的，视为不定期租赁。"},{"i":708,"n":"第七百零八条","txt":"出租人应当按照约定将租赁物交付承租人，并在租赁期限内保持租赁物符合约定的用途。"},{"i":709,"n":"第七百零九条","txt":"承租人应当按照约定的方法使用租赁物。对租赁物的使用方法没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，应当根据租赁物的性质使用。"},{"i":710,"n":"第七百一十条","txt":"承租人按照约定的方法或者根据租赁物的性质使用租赁物，致使租赁物受到损耗的，不承担赔偿责任。"},{"i":711,"n":"第七百一十一条","txt":"承租人未按照约定的方法或者未根据租赁物的性质使用租赁物，致使租赁物受到损失的，出租人可以解除合同并请求赔偿损失。"},{"i":712,"n":"第七百一十二条","txt":"出租人应当履行租赁物的维修义务，但是当事人另有约定的除外。"},{"i":713,"n":"第七百一十三条","txt":"承租人在租赁物需要维修时可以请求出租人在合理期限内维修。出租人未履行维修义务的，承租人可以自行维修，维修费用由出租人负担。因维修租赁物影响承租人使用的，应当相应减少租金或者延长租期。"},{"i":714,"n":"第七百一十四条","txt":"承租人应当妥善保管租赁物，因保管不善造成租赁物毁损、灭失的，应当承担赔偿责任。"},{"i":715,"n":"第七百一十五条","txt":"承租人经出租人同意，可以对租赁物进行改善或者增设他物。"},{"i":716,"n":"第七百一十六条","txt":"承租人经出租人同意，可以将租赁物转租给第三人。承租人转租的，承租人与出租人之间的租赁合同继续有效；第三人造成租赁物损失的，承租人应当赔偿损失。"},{"i":717,"n":"第七百一十七条","txt":"承租人经出租人同意将租赁物转租给第三人，转租期限超过承租人剩余租赁期限的，超过部分的约定对出租人不具有法律约束力，但是出租人与承租人另有约定的除外。"},{"i":718,"n":"第七百一十八条","txt":"出租人知道或者应当知道承租人转租，但是在六个月内未提出异议的，视为出租人同意转租。"},{"i":719,"n":"第七百一十九条","txt":"承租人拖欠租金的，次承租人可以代承租人支付其欠付的租金和违约金，但是转租合同对出租人不具有法律约束力的除外。"},{"i":720,"n":"第七百二十条","txt":"在租赁期限内因占有、使用租赁物获得的收益，归承租人所有，但是当事人另有约定的除外。"},{"i":721,"n":"第七百二十一条","txt":"承租人应当按照约定的期限支付租金。对支付租金的期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定，租赁期限不满一年的，应当在租赁期限届满时支付；租赁期限一年以上的，应当在每届满一年时支付，剩余期限不满一年的，应当在租赁期限届满时支付。"},{"i":722,"n":"第七百二十二条","txt":"承租人无正当理由未支付或者迟延支付租金的，出租人可以请求承租人在合理期限内支付；承租人逾期不支付的，出租人可以解除合同。"},{"i":723,"n":"第七百二十三条","txt":"因第三人主张权利，致使承租人不能对租赁物使用、收益的，承租人可以请求减少租金或者不支付租金。"},{"i":724,"n":"第七百二十四条","txt":"有下列情形之一，非因承租人原因致使租赁物无法使用的，承租人可以解除合同："},{"i":725,"n":"第七百二十五条","txt":"租赁物在承租人按照租赁合同占有期限内发生所有权变动的，不影响租赁合同的效力。"},{"i":726,"n":"第七百二十六条","txt":"出租人出卖租赁房屋的，应当在出卖之前的合理期限内通知承租人，承租人享有以同等条件优先购买的权利；但是，房屋按份共有人行使优先购买权或者出租人将房屋出卖给近亲属的除外。"},{"i":727,"n":"第七百二十七条","txt":"出租人委托拍卖人拍卖租赁房屋的，应当在拍卖五日前通知承租人。承租人未参加拍卖的，视为放弃优先购买权。"},{"i":728,"n":"第七百二十八条","txt":"出租人未通知承租人或者有其他妨害承租人行使优先购买权情形的，承租人可以请求出租人承担赔偿责任。但是，出租人与第三人订立的房屋买卖合同的效力不受影响。"},{"i":729,"n":"第七百二十九条","txt":"因不可归责于承租人的事由，致使租赁物部分或者全部毁损、灭失的，承租人可以请求减少租金或者不支付租金；因租赁物部分或者全部毁损、灭失，致使不能实现合同目的的，承租人可以解除合同。"},{"i":730,"n":"第七百三十条","txt":"当事人对租赁期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，视为不定期租赁；当事人可以随时解除合同，但是应当在合理期限之前通知对方。"},{"i":731,"n":"第七百三十一条","txt":"租赁物危及承租人的安全或者健康的，即使承租人订立合同时明知该租赁物质量不合格，承租人仍然可以随时解除合同。"},{"i":732,"n":"第七百三十二条","txt":"承租人在房屋租赁期限内死亡的，与其生前共同居住的人或者共同经营人可以按照原租赁合同租赁该房屋。"},{"i":733,"n":"第七百三十三条","txt":"租赁期限届满，承租人应当返还租赁物。返还的租赁物应当符合按照约定或者根据租赁物的性质使用后的状态。"},{"i":734,"n":"第七百三十四条","txt":"租赁期限届满，承租人继续使用租赁物，出租人没有提出异议的，原租赁合同继续有效，但是租赁期限为不定期。"},{"i":735,"n":"第七百三十五条","txt":"融资租赁合同是出租人根据承租人对出卖人、租赁物的选择，向出卖人购买租赁物，提供给承租人使用，承租人支付租金的合同。"},{"i":736,"n":"第七百三十六条","txt":"融资租赁合同的内容一般包括租赁物的名称、数量、规格、技术性能、检验方法，租赁期限，租金构成及其支付期限和方式、币种，租赁期限届满租赁物的归属等条款。"},{"i":737,"n":"第七百三十七条","txt":"当事人以虚构租赁物方式订立的融资租赁合同无效。"},{"i":738,"n":"第七百三十八条","txt":"依照法律、行政法规的规定，对于租赁物的经营使用应当取得行政许可的，出租人未取得行政许可不影响融资租赁合同的效力。"},{"i":739,"n":"第七百三十九条","txt":"出租人根据承租人对出卖人、租赁物的选择订立的买卖合同，出卖人应当按照约定向承租人交付标的物，承租人享有与受领标的物有关的买受人的权利。"},{"i":740,"n":"第七百四十条","txt":"出卖人违反向承租人交付标的物的义务，有下列情形之一的，承租人可以拒绝受领出卖人向其交付的标的物："},{"i":741,"n":"第七百四十一条","txt":"出租人、出卖人、承租人可以约定，出卖人不履行买卖合同义务的，由承租人行使索赔的权利。承租人行使索赔权利的，出租人应当协助。"},{"i":742,"n":"第七百四十二条","txt":"承租人对出卖人行使索赔权利，不影响其履行支付租金的义务。但是，承租人依赖出租人的技能确定租赁物或者出租人干预选择租赁物的，承租人可以请求减免相应租金。"},{"i":743,"n":"第七百四十三条","txt":"出租人有下列情形之一，致使承租人对出卖人行使索赔权利失败的，承租人有权请求出租人承担相应的责任："},{"i":744,"n":"第七百四十四条","txt":"出租人根据承租人对出卖人、租赁物的选择订立的买卖合同，未经承租人同意，出租人不得变更与承租人有关的合同内容。"},{"i":745,"n":"第七百四十五条","txt":"出租人对租赁物享有的所有权，未经登记，不得对抗善意第三人。"},{"i":746,"n":"第七百四十六条","txt":"融资租赁合同的租金，除当事人另有约定外，应当根据购买租赁物的大部分或者全部成本以及出租人的合理利润确定。"},{"i":747,"n":"第七百四十七条","txt":"租赁物不符合约定或者不符合使用目的的，出租人不承担责任。但是，承租人依赖出租人的技能确定租赁物或者出租人干预选择租赁物的除外。"},{"i":748,"n":"第七百四十八条","txt":"出租人应当保证承租人对租赁物的占有和使用。"},{"i":749,"n":"第七百四十九条","txt":"承租人占有租赁物期间，租赁物造成第三人人身损害或者财产损失的，出租人不承担责任。"},{"i":750,"n":"第七百五十条","txt":"承租人应当妥善保管、使用租赁物。"},{"i":751,"n":"第七百五十一条","txt":"承租人占有租赁物期间，租赁物毁损、灭失的，出租人有权请求承租人继续支付租金，但是法律另有规定或者当事人另有约定的除外。"},{"i":752,"n":"第七百五十二条","txt":"承租人应当按照约定支付租金。承租人经催告后在合理期限内仍不支付租金的，出租人可以请求支付全部租金；也可以解除合同，收回租赁物。"},{"i":753,"n":"第七百五十三条","txt":"承租人未经出租人同意，将租赁物转让、抵押、质押、投资入股或者以其他方式处分的，出租人可以解除融资租赁合同。"},{"i":754,"n":"第七百五十四条","txt":"有下列情形之一的，出租人或者承租人可以解除融资租赁合同："},{"i":755,"n":"第七百五十五条","txt":"融资租赁合同因买卖合同解除、被确认无效或者被撤销而解除，出卖人、租赁物系由承租人选择的，出租人有权请求承租人赔偿相应损失；但是，因出租人原因致使买卖合同解除、被确认无效或者被撤销的除外。"},{"i":756,"n":"第七百五十六条","txt":"融资租赁合同因租赁物交付承租人后意外毁损、灭失等不可归责于当事人的原因解除的，出租人可以请求承租人按照租赁物折旧情况给予补偿。"},{"i":757,"n":"第七百五十七条","txt":"出租人和承租人可以约定租赁期限届满租赁物的归属；对租赁物的归属没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，租赁物的所有权归出租人。"},{"i":758,"n":"第七百五十八条","txt":"当事人约定租赁期限届满租赁物归承租人所有，承租人已经支付大部分租金，但是无力支付剩余租金，出租人因此解除合同收回租赁物，收回的租赁物的价值超过承租人欠付的租金以及其他费用的，承租人可以请求相应返还。"},{"i":759,"n":"第七百五十九条","txt":"当事人约定租赁期限届满，承租人仅需向出租人支付象征性价款的，视为约定的租金义务履行完毕后租赁物的所有权归承租人。"},{"i":760,"n":"第七百六十条","txt":"融资租赁合同无效，当事人就该情形下租赁物的归属有约定的，按照其约定；没有约定或者约定不明确的，租赁物应当返还出租人。但是，因承租人原因致使合同无效，出租人不请求返还或者返还后会显著降低租赁物效用的，租赁物的所有权归承租人，由承租人给予出租人合理补偿。"},{"i":761,"n":"第七百六十一条","txt":"保理合同是应收账款债权人将现有的或者将有的应收账款转让给保理人，保理人提供资金融通、应收账款管理或者催收、应收账款债务人付款担保等服务的合同。"},{"i":762,"n":"第七百六十二条","txt":"保理合同的内容一般包括业务类型、服务范围、服务期限、基础交易合同情况、应收账款信息、保理融资款或者服务报酬及其支付方式等条款。"},{"i":763,"n":"第七百六十三条","txt":"应收账款债权人与债务人虚构应收账款作为转让标的，与保理人订立保理合同的，应收账款债务人不得以应收账款不存在为由对抗保理人，但是保理人明知虚构的除外。"},{"i":764,"n":"第七百六十四条","txt":"保理人向应收账款债务人发出应收账款转让通知的，应当表明保理人身份并附有必要凭证。"},{"i":765,"n":"第七百六十五条","txt":"应收账款债务人接到应收账款转让通知后，应收账款债权人与债务人无正当理由协商变更或者终止基础交易合同，对保理人产生不利影响的，对保理人不发生效力。"},{"i":766,"n":"第七百六十六条","txt":"当事人约定有追索权保理的，保理人可以向应收账款债权人主张返还保理融资款本息或者回购应收账款债权，也可以向应收账款债务人主张应收账款债权。保理人向应收账款债务人主张应收账款债权，在扣除保理融资款本息和相关费用后有剩余的，剩余部分应当返还给应收账款债权人。"},{"i":767,"n":"第七百六十七条","txt":"当事人约定无追索权保理的，保理人应当向应收账款债务人主张应收账款债权，保理人取得超过保理融资款本息和相关费用的部分，无需向应收账款债权人返还。"},{"i":768,"n":"第七百六十八条","txt":"应收账款债权人就同一应收账款订立多个保理合同，致使多个保理人主张权利的，已经登记的先于未登记的取得应收账款；均已经登记的，按照登记时间的先后顺序取得应收账款；均未登记的，由最先到达应收账款债务人的转让通知中载明的保理人取得应收账款；既未登记也未通知的，按照保理融资款或者服务报酬的比例取得应收账款。"},{"i":769,"n":"第七百六十九条","txt":"本章没有规定的，适用本编第六章债权转让的有关规定。"},{"i":770,"n":"第七百七十条","txt":"承揽合同是承揽人按照定作人的要求完成工作，交付工作成果，定作人支付报酬的合同。"},{"i":771,"n":"第七百七十一条","txt":"承揽合同的内容一般包括承揽的标的、数量、质量、报酬，承揽方式，材料的提供，履行期限，验收标准和方法等条款。"},{"i":772,"n":"第七百七十二条","txt":"承揽人应当以自己的设备、技术和劳力，完成主要工作，但是当事人另有约定的除外。"},{"i":773,"n":"第七百七十三条","txt":"承揽人可以将其承揽的辅助工作交由第三人完成。承揽人将其承揽的辅助工作交由第三人完成的，应当就该第三人完成的工作成果向定作人负责。"},{"i":774,"n":"第七百七十四条","txt":"承揽人提供材料的，应当按照约定选用材料，并接受定作人检验。"},{"i":775,"n":"第七百七十五条","txt":"定作人提供材料的，应当按照约定提供材料。承揽人对定作人提供的材料应当及时检验，发现不符合约定时，应当及时通知定作人更换、补齐或者采取其他补救措施。"},{"i":776,"n":"第七百七十六条","txt":"承揽人发现定作人提供的图纸或者技术要求不合理的，应当及时通知定作人。因定作人怠于答复等原因造成承揽人损失的，应当赔偿损失。"},{"i":777,"n":"第七百七十七条","txt":"定作人中途变更承揽工作的要求，造成承揽人损失的，应当赔偿损失。"},{"i":778,"n":"第七百七十八条","txt":"承揽工作需要定作人协助的，定作人有协助的义务。定作人不履行协助义务致使承揽工作不能完成的，承揽人可以催告定作人在合理期限内履行义务，并可以顺延履行期限；定作人逾期不履行的，承揽人可以解除合同。"},{"i":779,"n":"第七百七十九条","txt":"承揽人在工作期间，应当接受定作人必要的监督检验。定作人不得因监督检验妨碍承揽人的正常工作。"},{"i":780,"n":"第七百八十条","txt":"承揽人完成工作的，应当向定作人交付工作成果，并提交必要的技术资料和有关质量证明。定作人应当验收该工作成果。"},{"i":781,"n":"第七百八十一条","txt":"承揽人交付的工作成果不符合质量要求的，定作人可以合理选择请求承揽人承担修理、重作、减少报酬、赔偿损失等违约责任。"},{"i":782,"n":"第七百八十二条","txt":"定作人应当按照约定的期限支付报酬。对支付报酬的期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，定作人应当在承揽人交付工作成果时支付；工作成果部分交付的，定作人应当相应支付。"},{"i":783,"n":"第七百八十三条","txt":"定作人未向承揽人支付报酬或者材料费等价款的，承揽人对完成的工作成果享有留置权或者有权拒绝交付，但是当事人另有约定的除外。"},{"i":784,"n":"第七百八十四条","txt":"承揽人应当妥善保管定作人提供的材料以及完成的工作成果，因保管不善造成毁损、灭失的，应当承担赔偿责任。"},{"i":785,"n":"第七百八十五条","txt":"承揽人应当按照定作人的要求保守秘密，未经定作人许可，不得留存复制品或者技术资料。"},{"i":786,"n":"第七百八十六条","txt":"共同承揽人对定作人承担连带责任，但是当事人另有约定的除外。"},{"i":787,"n":"第七百八十七条","txt":"定作人在承揽人完成工作前可以随时解除合同，造成承揽人损失的，应当赔偿损失。"},{"i":788,"n":"第七百八十八条","txt":"建设工程合同是承包人进行工程建设，发包人支付价款的合同。"},{"i":789,"n":"第七百八十九条","txt":"建设工程合同应当采用书面形式。"},{"i":790,"n":"第七百九十条","txt":"建设工程的招标投标活动，应当依照有关法律的规定公开、公平、公正进行。"},{"i":791,"n":"第七百九十一条","txt":"发包人可以与总承包人订立建设工程合同，也可以分别与勘察人、设计人、施工人订立勘察、设计、施工承包合同。发包人不得将应当由一个承包人完成的建设工程支解成若干部分发包给数个承包人。"},{"i":792,"n":"第七百九十二条","txt":"国家重大建设工程合同，应当按照国家规定的程序和国家批准的投资计划、可行性研究报告等文件订立。"},{"i":793,"n":"第七百九十三条","txt":"建设工程施工合同无效，但是建设工程经验收合格的，可以参照合同关于工程价款的约定折价补偿承包人。"},{"i":794,"n":"第七百九十四条","txt":"勘察、设计合同的内容一般包括提交有关基础资料和概预算等文件的期限、质量要求、费用以及其他协作条件等条款。"},{"i":795,"n":"第七百九十五条","txt":"施工合同的内容一般包括工程范围、建设工期、中间交工工程的开工和竣工时间、工程质量、工程造价、技术资料交付时间、材料和设备供应责任、拨款和结算、竣工验收、质量保修范围和质量保证期、相互协作等条款。"},{"i":796,"n":"第七百九十六条","txt":"建设工程实行监理的，发包人应当与监理人采用书面形式订立委托监理合同。发包人与监理人的权利和义务以及法律责任，应当依照本编委托合同以及其他有关法律、行政法规的规定。"},{"i":797,"n":"第七百九十七条","txt":"发包人在不妨碍承包人正常作业的情况下，可以随时对作业进度、质量进行检查。"},{"i":798,"n":"第七百九十八条","txt":"隐蔽工程在隐蔽以前，承包人应当通知发包人检查。发包人没有及时检查的，承包人可以顺延工程日期，并有权请求赔偿停工、窝工等损失。"},{"i":799,"n":"第七百九十九条","txt":"建设工程竣工后，发包人应当根据施工图纸及说明书、国家颁发的施工验收规范和质量检验标准及时进行验收。验收合格的，发包人应当按照约定支付价款，并接收该建设工程。"},{"i":800,"n":"第八百条","txt":"勘察、设计的质量不符合要求或者未按照期限提交勘察、设计文件拖延工期，造成发包人损失的，勘察人、设计人应当继续完善勘察、设计，减收或者免收勘察、设计费并赔偿损失。"},{"i":801,"n":"第八百零一条","txt":"因施工人的原因致使建设工程质量不符合约定的，发包人有权请求施工人在合理期限内无偿修理或者返工、改建。经过修理或者返工、改建后，造成逾期交付的，施工人应当承担违约责任。"},{"i":802,"n":"第八百零二条","txt":"因承包人的原因致使建设工程在合理使用期限内造成人身损害和财产损失的，承包人应当承担赔偿责任。"},{"i":803,"n":"第八百零三条","txt":"发包人未按照约定的时间和要求提供原材料、设备、场地、资金、技术资料的，承包人可以顺延工程日期，并有权请求赔偿停工、窝工等损失。"},{"i":804,"n":"第八百零四条","txt":"因发包人的原因致使工程中途停建、缓建的，发包人应当采取措施弥补或者减少损失，赔偿承包人因此造成的停工、窝工、倒运、机械设备调迁、材料和构件积压等损失和实际费用。"},{"i":805,"n":"第八百零五条","txt":"因发包人变更计划，提供的资料不准确，或者未按照期限提供必需的勘察、设计工作条件而造成勘察、设计的返工、停工或者修改设计，发包人应当按照勘察人、设计人实际消耗的工作量增付费用。"},{"i":806,"n":"第八百零六条","txt":"承包人将建设工程转包、违法分包的，发包人可以解除合同。"},{"i":807,"n":"第八百零七条","txt":"发包人未按照约定支付价款的，承包人可以催告发包人在合理期限内支付价款。发包人逾期不支付的，除根据建设工程的性质不宜折价、拍卖外，承包人可以与发包人协议将该工程折价，也可以请求人民法院将该工程依法拍卖。建设工程的价款就该工程折价或者拍卖的价款优先受偿。"},{"i":808,"n":"第八百零八条","txt":"本章没有规定的，适用承揽合同的有关规定。"},{"i":809,"n":"第八百零九条","txt":"运输合同是承运人将旅客或者货物从起运地点运输到约定地点，旅客、托运人或者收货人支付票款或者运输费用的合同。"},{"i":810,"n":"第八百一十条","txt":"从事公共运输的承运人不得拒绝旅客、托运人通常、合理的运输要求。"},{"i":811,"n":"第八百一十一条","txt":"承运人应当在约定期限或者合理期限内将旅客、货物安全运输到约定地点。"},{"i":812,"n":"第八百一十二条","txt":"承运人应当按照约定的或者通常的运输路线将旅客、货物运输到约定地点。"},{"i":813,"n":"第八百一十三条","txt":"旅客、托运人或者收货人应当支付票款或者运输费用。承运人未按照约定路线或者通常路线运输增加票款或者运输费用的，旅客、托运人或者收货人可以拒绝支付增加部分的票款或者运输费用。"},{"i":814,"n":"第八百一十四条","txt":"客运合同自承运人向旅客出具客票时成立，但是当事人另有约定或者另有交易习惯的除外。"},{"i":815,"n":"第八百一十五条","txt":"旅客应当按照有效客票记载的时间、班次和座位号乘坐。旅客无票乘坐、超程乘坐、越级乘坐或者持不符合减价条件的优惠客票乘坐的，应当补交票款，承运人可以按照规定加收票款；旅客不支付票款的，承运人可以拒绝运输。"},{"i":816,"n":"第八百一十六条","txt":"旅客因自己的原因不能按照客票记载的时间乘坐的，应当在约定的期限内办理退票或者变更手续；逾期办理的，承运人可以不退票款，并不再承担运输义务。"},{"i":817,"n":"第八百一十七条","txt":"旅客随身携带行李应当符合约定的限量和品类要求；超过限量或者违反品类要求携带行李的，应当办理托运手续。"},{"i":818,"n":"第八百一十八条","txt":"旅客不得随身携带或者在行李中夹带易燃、易爆、有毒、有腐蚀性、有放射性以及可能危及运输工具上人身和财产安全的危险物品或者违禁物品。"},{"i":819,"n":"第八百一十九条","txt":"承运人应当严格履行安全运输义务，及时告知旅客安全运输应当注意的事项。旅客对承运人为安全运输所作的合理安排应当积极协助和配合。"},{"i":820,"n":"第八百二十条","txt":"承运人应当按照有效客票记载的时间、班次和座位号运输旅客。承运人迟延运输或者有其他不能正常运输情形的，应当及时告知和提醒旅客，采取必要的安置措施，并根据旅客的要求安排改乘其他班次或者退票；由此造成旅客损失的，承运人应当承担赔偿责任，但是不可归责于承运人的除外。"},{"i":821,"n":"第八百二十一条","txt":"承运人擅自降低服务标准的，应当根据旅客的请求退票或者减收票款；提高服务标准的，不得加收票款。"},{"i":822,"n":"第八百二十二条","txt":"承运人在运输过程中，应当尽力救助患有急病、分娩、遇险的旅客。"},{"i":823,"n":"第八百二十三条","txt":"承运人应当对运输过程中旅客的伤亡承担赔偿责任；但是，伤亡是旅客自身健康原因造成的或者承运人证明伤亡是旅客故意、重大过失造成的除外。"},{"i":824,"n":"第八百二十四条","txt":"在运输过程中旅客随身携带物品毁损、灭失，承运人有过错的，应当承担赔偿责任。"},{"i":825,"n":"第八百二十五条","txt":"托运人办理货物运输，应当向承运人准确表明收货人的姓名、名称或者凭指示的收货人，货物的名称、性质、重量、数量，收货地点等有关货物运输的必要情况。"},{"i":826,"n":"第八百二十六条","txt":"货物运输需要办理审批、检验等手续的，托运人应当将办理完有关手续的文件提交承运人。"},{"i":827,"n":"第八百二十七条","txt":"托运人应当按照约定的方式包装货物。对包装方式没有约定或者约定不明确的，适用本法第六百一十九条的规定。"},{"i":828,"n":"第八百二十八条","txt":"托运人托运易燃、易爆、有毒、有腐蚀性、有放射性等危险物品的，应当按照国家有关危险物品运输的规定对危险物品妥善包装，做出危险物品标志和标签，并将有关危险物品的名称、性质和防范措施的书面材料提交承运人。"},{"i":829,"n":"第八百二十九条","txt":"在承运人将货物交付收货人之前，托运人可以要求承运人中止运输、返还货物、变更到达地或者将货物交给其他收货人，但是应当赔偿承运人因此受到的损失。"},{"i":830,"n":"第八百三十条","txt":"货物运输到达后，承运人知道收货人的，应当及时通知收货人，收货人应当及时提货。收货人逾期提货的，应当向承运人支付保管费等费用。"},{"i":831,"n":"第八百三十一条","txt":"收货人提货时应当按照约定的期限检验货物。对检验货物的期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，应当在合理期限内检验货物。收货人在约定的期限或者合理期限内对货物的数量、毁损等未提出异议的，视为承运人已经按照运输单证的记载交付的初步证据。"},{"i":832,"n":"第八百三十二条","txt":"承运人对运输过程中货物的毁损、灭失承担赔偿责任。但是，承运人证明货物的毁损、灭失是因不可抗力、货物本身的自然性质或者合理损耗以及托运人、收货人的过错造成的，不承担赔偿责任。"},{"i":833,"n":"第八百三十三条","txt":"货物的毁损、灭失的赔偿额，当事人有约定的，按照其约定；没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，按照交付或者应当交付时货物到达地的市场价格计算。法律、行政法规对赔偿额的计算方法和赔偿限额另有规定的，依照其规定。"},{"i":834,"n":"第八百三十四条","txt":"两个以上承运人以同一运输方式联运的，与托运人订立合同的承运人应当对全程运输承担责任；损失发生在某一运输区段的，与托运人订立合同的承运人和该区段的承运人承担连带责任。"},{"i":835,"n":"第八百三十五条","txt":"货物在运输过程中因不可抗力灭失，未收取运费的，承运人不得请求支付运费；已经收取运费的，托运人可以请求返还。法律另有规定的，依照其规定。"},{"i":836,"n":"第八百三十六条","txt":"托运人或者收货人不支付运费、保管费或者其他费用的，承运人对相应的运输货物享有留置权，但是当事人另有约定的除外。"},{"i":837,"n":"第八百三十七条","txt":"收货人不明或者收货人无正当理由拒绝受领货物的，承运人依法可以提存货物。"},{"i":838,"n":"第八百三十八条","txt":"多式联运经营人负责履行或者组织履行多式联运合同，对全程运输享有承运人的权利，承担承运人的义务。"},{"i":839,"n":"第八百三十九条","txt":"多式联运经营人可以与参加多式联运的各区段承运人就多式联运合同的各区段运输约定相互之间的责任；但是，该约定不影响多式联运经营人对全程运输承担的义务。"},{"i":840,"n":"第八百四十条","txt":"多式联运经营人收到托运人交付的货物时，应当签发多式联运单据。按照托运人的要求，多式联运单据可以是可转让单据，也可以是不可转让单据。"},{"i":841,"n":"第八百四十一条","txt":"因托运人托运货物时的过错造成多式联运经营人损失的，即使托运人已经转让多式联运单据，托运人仍然应当承担赔偿责任。"},{"i":842,"n":"第八百四十二条","txt":"货物的毁损、灭失发生于多式联运的某一运输区段的，多式联运经营人的赔偿责任和责任限额，适用调整该区段运输方式的有关法律规定；货物毁损、灭失发生的运输区段不能确定的，依照本章规定承担赔偿责任。"},{"i":843,"n":"第八百四十三条","txt":"技术合同是当事人就技术开发、转让、许可、咨询或者服务订立的确立相互之间权利和义务的合同。"},{"i":844,"n":"第八百四十四条","txt":"订立技术合同，应当有利于知识产权的保护和科学技术的进步，促进科学技术成果的研发、转化、应用和推广。"},{"i":845,"n":"第八百四十五条","txt":"技术合同的内容一般包括项目的名称，标的的内容、范围和要求，履行的计划、地点和方式，技术信息和资料的保密，技术成果的归属和收益的分配办法，验收标准和方法，名词和术语的解释等条款。"},{"i":846,"n":"第八百四十六条","txt":"技术合同价款、报酬或者使用费的支付方式由当事人约定，可以采取一次总算、一次总付或者一次总算、分期支付，也可以采取提成支付或者提成支付附加预付入门费的方式。"},{"i":847,"n":"第八百四十七条","txt":"职务技术成果的使用权、转让权属于法人或者非法人组织的，法人或者非法人组织可以就该项职务技术成果订立技术合同。法人或者非法人组织订立技术合同转让职务技术成果时，职务技术成果的完成人享有以同等条件优先受让的权利。"},{"i":848,"n":"第八百四十八条","txt":"非职务技术成果的使用权、转让权属于完成技术成果的个人，完成技术成果的个人可以就该项非职务技术成果订立技术合同。"},{"i":849,"n":"第八百四十九条","txt":"完成技术成果的个人享有在有关技术成果文件上写明自己是技术成果完成者的权利和取得荣誉证书、奖励的权利。"},{"i":850,"n":"第八百五十条","txt":"非法垄断技术或者侵害他人技术成果的技术合同无效。"},{"i":851,"n":"第八百五十一条","txt":"技术开发合同是当事人之间就新技术、新产品、新工艺、新品种或者新材料及其系统的研究开发所订立的合同。"},{"i":852,"n":"第八百五十二条","txt":"委托开发合同的委托人应当按照约定支付研究开发经费和报酬，提供技术资料，提出研究开发要求，完成协作事项，接受研究开发成果。"},{"i":853,"n":"第八百五十三条","txt":"委托开发合同的研究开发人应当按照约定制定和实施研究开发计划，合理使用研究开发经费，按期完成研究开发工作，交付研究开发成果，提供有关的技术资料和必要的技术指导，帮助委托人掌握研究开发成果。"},{"i":854,"n":"第八百五十四条","txt":"委托开发合同的当事人违反约定造成研究开发工作停滞、延误或者失败的，应当承担违约责任。"},{"i":855,"n":"第八百五十五条","txt":"合作开发合同的当事人应当按照约定进行投资，包括以技术进行投资，分工参与研究开发工作，协作配合研究开发工作。"},{"i":856,"n":"第八百五十六条","txt":"合作开发合同的当事人违反约定造成研究开发工作停滞、延误或者失败的，应当承担违约责任。"},{"i":857,"n":"第八百五十七条","txt":"作为技术开发合同标的的技术已经由他人公开，致使技术开发合同的履行没有意义的，当事人可以解除合同。"},{"i":858,"n":"第八百五十八条","txt":"技术开发合同履行过程中，因出现无法克服的技术困难，致使研究开发失败或者部分失败的，该风险由当事人约定；没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，风险由当事人合理分担。"},{"i":859,"n":"第八百五十九条","txt":"委托开发完成的发明创造，除法律另有规定或者当事人另有约定外，申请专利的权利属于研究开发人。研究开发人取得专利权的，委托人可以依法实施该专利。"},{"i":860,"n":"第八百六十条","txt":"合作开发完成的发明创造，申请专利的权利属于合作开发的当事人共有；当事人一方转让其共有的专利申请权的，其他各方享有以同等条件优先受让的权利。但是，当事人另有约定的除外。"},{"i":861,"n":"第八百六十一条","txt":"委托开发或者合作开发完成的技术秘密成果的使用权、转让权以及收益的分配办法，由当事人约定；没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，在没有相同技术方案被授予专利权前，当事人均有使用和转让的权利。但是，委托开发的研究开发人不得在向委托人交付研究开发成果之前，将研究开发成果转让给第三人。"},{"i":862,"n":"第八百六十二条","txt":"技术转让合同是合法拥有技术的权利人，将现有特定的专利、专利申请、技术秘密的相关权利让与他人所订立的合同。"},{"i":863,"n":"第八百六十三条","txt":"技术转让合同包括专利权转让、专利申请权转让、技术秘密转让等合同。"},{"i":864,"n":"第八百六十四条","txt":"技术转让合同和技术许可合同可以约定实施专利或者使用技术秘密的范围，但是不得限制技术竞争和技术发展。"},{"i":865,"n":"第八百六十五条","txt":"专利实施许可合同仅在该专利权的存续期限内有效。专利权有效期限届满或者专利权被宣告无效的，专利权人不得就该专利与他人订立专利实施许可合同。"},{"i":866,"n":"第八百六十六条","txt":"专利实施许可合同的许可人应当按照约定许可被许可人实施专利，交付实施专利有关的技术资料，提供必要的技术指导。"},{"i":867,"n":"第八百六十七条","txt":"专利实施许可合同的被许可人应当按照约定实施专利，不得许可约定以外的第三人实施该专利，并按照约定支付使用费。"},{"i":868,"n":"第八百六十八条","txt":"技术秘密转让合同的让与人和技术秘密使用许可合同的许可人应当按照约定提供技术资料，进行技术指导，保证技术的实用性、可靠性，承担保密义务。"},{"i":869,"n":"第八百六十九条","txt":"技术秘密转让合同的受让人和技术秘密使用许可合同的被许可人应当按照约定使用技术，支付转让费、使用费，承担保密义务。"},{"i":870,"n":"第八百七十条","txt":"技术转让合同的让与人和技术许可合同的许可人应当保证自己是所提供的技术的合法拥有者，并保证所提供的技术完整、无误、有效，能够达到约定的目标。"},{"i":871,"n":"第八百七十一条","txt":"技术转让合同的受让人和技术许可合同的被许可人应当按照约定的范围和期限，对让与人、许可人提供的技术中尚未公开的秘密部分，承担保密义务。"},{"i":872,"n":"第八百七十二条","txt":"许可人未按照约定许可技术的，应当返还部分或者全部使用费，并应当承担违约责任；实施专利或者使用技术秘密超越约定的范围的，违反约定擅自许可第三人实施该项专利或者使用该项技术秘密的，应当停止违约行为，承担违约责任；违反约定的保密义务的，应当承担违约责任。"},{"i":873,"n":"第八百七十三条","txt":"被许可人未按照约定支付使用费的，应当补交使用费并按照约定支付违约金；不补交使用费或者支付违约金的，应当停止实施专利或者使用技术秘密，交还技术资料，承担违约责任；实施专利或者使用技术秘密超越约定的范围的，未经许可人同意擅自许可第三人实施该专利或者使用该技术秘密的，应当停止违约行为，承担违约责任；违反约定的保密义务的，应当承担违约责任。"},{"i":874,"n":"第八百七十四条","txt":"受让人或者被许可人按照约定实施专利、使用技术秘密侵害他人合法权益的，由让与人或者许可人承担责任，但是当事人另有约定的除外。"},{"i":875,"n":"第八百七十五条","txt":"当事人可以按照互利的原则，在合同中约定实施专利、使用技术秘密后续改进的技术成果的分享办法；没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，一方后续改进的技术成果，其他各方无权分享。"},{"i":876,"n":"第八百七十六条","txt":"集成电路布图设计专有权、植物新品种权、计算机软件著作权等其他知识产权的转让和许可，参照适用本节的有关规定。"},{"i":877,"n":"第八百七十七条","txt":"法律、行政法规对技术进出口合同或者专利、专利申请合同另有规定的，依照其规定。"},{"i":878,"n":"第八百七十八条","txt":"技术咨询合同是当事人一方以技术知识为对方就特定技术项目提供可行性论证、技术预测、专题技术调查、分析评价报告等所订立的合同。"},{"i":879,"n":"第八百七十九条","txt":"技术咨询合同的委托人应当按照约定阐明咨询的问题，提供技术背景材料及有关技术资料，接受受托人的工作成果，支付报酬。"},{"i":880,"n":"第八百八十条","txt":"技术咨询合同的受托人应当按照约定的期限完成咨询报告或者解答问题，提出的咨询报告应当达到约定的要求。"},{"i":881,"n":"第八百八十一条","txt":"技术咨询合同的委托人未按照约定提供必要的资料，影响工作进度和质量，不接受或者逾期接受工作成果的，支付的报酬不得追回，未支付的报酬应当支付。"},{"i":882,"n":"第八百八十二条","txt":"技术服务合同的委托人应当按照约定提供工作条件，完成配合事项，接受工作成果并支付报酬。"},{"i":883,"n":"第八百八十三条","txt":"技术服务合同的受托人应当按照约定完成服务项目，解决技术问题，保证工作质量，并传授解决技术问题的知识。"},{"i":884,"n":"第八百八十四条","txt":"技术服务合同的委托人不履行合同义务或者履行合同义务不符合约定，影响工作进度和质量，不接受或者逾期接受工作成果的，支付的报酬不得追回，未支付的报酬应当支付。"},{"i":885,"n":"第八百八十五条","txt":"技术咨询合同、技术服务合同履行过程中，受托人利用委托人提供的技术资料和工作条件完成的新的技术成果，属于受托人。委托人利用受托人的工作成果完成的新的技术成果，属于委托人。当事人另有约定的，按照其约定。"},{"i":886,"n":"第八百八十六条","txt":"技术咨询合同和技术服务合同对受托人正常开展工作所需费用的负担没有约定或者约定不明确的，由受托人负担。"},{"i":887,"n":"第八百八十七条","txt":"法律、行政法规对技术中介合同、技术培训合同另有规定的，依照其规定。"},{"i":888,"n":"第八百八十八条","txt":"保管合同是保管人保管寄存人交付的保管物，并返还该物的合同。"},{"i":889,"n":"第八百八十九条","txt":"寄存人应当按照约定向保管人支付保管费。"},{"i":890,"n":"第八百九十条","txt":"保管合同自保管物交付时成立，但是当事人另有约定的除外。"},{"i":891,"n":"第八百九十一条","txt":"寄存人向保管人交付保管物的，保管人应当出具保管凭证，但是另有交易习惯的除外。"},{"i":892,"n":"第八百九十二条","txt":"保管人应当妥善保管保管物。"},{"i":893,"n":"第八百九十三条","txt":"寄存人交付的保管物有瑕疵或者根据保管物的性质需要采取特殊保管措施的，寄存人应当将有关情况告知保管人。寄存人未告知，致使保管物受损失的，保管人不承担赔偿责任；保管人因此受损失的，除保管人知道或者应当知道且未采取补救措施外，寄存人应当承担赔偿责任。"},{"i":894,"n":"第八百九十四条","txt":"保管人不得将保管物转交第三人保管，但是当事人另有约定的除外。"},{"i":895,"n":"第八百九十五条","txt":"保管人不得使用或者许可第三人使用保管物，但是当事人另有约定的除外。"},{"i":896,"n":"第八百九十六条","txt":"第三人对保管物主张权利的，除依法对保管物采取保全或者执行措施外，保管人应当履行向寄存人返还保管物的义务。"},{"i":897,"n":"第八百九十七条","txt":"保管期内，因保管人保管不善造成保管物毁损、灭失的，保管人应当承担赔偿责任。但是，无偿保管人证明自己没有故意或者重大过失的，不承担赔偿责任。"},{"i":898,"n":"第八百九十八条","txt":"寄存人寄存货币、有价证券或者其他贵重物品的，应当向保管人声明，由保管人验收或者封存；寄存人未声明的，该物品毁损、灭失后，保管人可以按照一般物品予以赔偿。"},{"i":899,"n":"第八百九十九条","txt":"寄存人可以随时领取保管物。"},{"i":900,"n":"第九百条","txt":"保管期限届满或者寄存人提前领取保管物的，保管人应当将原物及其孳息归还寄存人。"},{"i":901,"n":"第九百零一条","txt":"保管人保管货币的，可以返还相同种类、数量的货币；保管其他可替代物的，可以按照约定返还相同种类、品质、数量的物品。"},{"i":902,"n":"第九百零二条","txt":"有偿的保管合同，寄存人应当按照约定的期限向保管人支付保管费。"},{"i":903,"n":"第九百零三条","txt":"寄存人未按照约定支付保管费或者其他费用的，保管人对保管物享有留置权，但是当事人另有约定的除外。"},{"i":904,"n":"第九百零四条","txt":"仓储合同是保管人储存存货人交付的仓储物，存货人支付仓储费的合同。"},{"i":905,"n":"第九百零五条","txt":"仓储合同自保管人和存货人意思表示一致时成立。"},{"i":906,"n":"第九百零六条","txt":"储存易燃、易爆、有毒、有腐蚀性、有放射性等危险物品或者易变质物品的，存货人应当说明该物品的性质，提供有关资料。"},{"i":907,"n":"第九百零七条","txt":"保管人应当按照约定对入库仓储物进行验收。保管人验收时发现入库仓储物与约定不符合的，应当及时通知存货人。保管人验收后，发生仓储物的品种、数量、质量不符合约定的，保管人应当承担赔偿责任。"},{"i":908,"n":"第九百零八条","txt":"存货人交付仓储物的，保管人应当出具仓单、入库单等凭证。"},{"i":909,"n":"第九百零九条","txt":"保管人应当在仓单上签名或者盖章。仓单包括下列事项："},{"i":910,"n":"第九百一十条","txt":"仓单是提取仓储物的凭证。存货人或者仓单持有人在仓单上背书并经保管人签名或者盖章的，可以转让提取仓储物的权利。"},{"i":911,"n":"第九百一十一条","txt":"保管人根据存货人或者仓单持有人的要求，应当同意其检查仓储物或者提取样品。"},{"i":912,"n":"第九百一十二条","txt":"保管人发现入库仓储物有变质或者其他损坏的，应当及时通知存货人或者仓单持有人。"},{"i":913,"n":"第九百一十三条","txt":"保管人发现入库仓储物有变质或者其他损坏，危及其他仓储物的安全和正常保管的，应当催告存货人或者仓单持有人作出必要的处置。因情况紧急，保管人可以作出必要的处置；但是，事后应当将该情况及时通知存货人或者仓单持有人。"},{"i":914,"n":"第九百一十四条","txt":"当事人对储存期限没有约定或者约定不明确的，存货人或者仓单持有人可以随时提取仓储物，保管人也可以随时请求存货人或者仓单持有人提取仓储物，但是应当给予必要的准备时间。"},{"i":915,"n":"第九百一十五条","txt":"储存期限届满，存货人或者仓单持有人应当凭仓单、入库单等提取仓储物。存货人或者仓单持有人逾期提取的，应当加收仓储费；提前提取的，不减收仓储费。"},{"i":916,"n":"第九百一十六条","txt":"储存期限届满，存货人或者仓单持有人不提取仓储物的，保管人可以催告其在合理期限内提取；逾期不提取的，保管人可以提存仓储物。"},{"i":917,"n":"第九百一十七条","txt":"储存期内，因保管不善造成仓储物毁损、灭失的，保管人应当承担赔偿责任。因仓储物本身的自然性质、包装不符合约定或者超过有效储存期造成仓储物变质、损坏的，保管人不承担赔偿责任。"},{"i":918,"n":"第九百一十八条","txt":"本章没有规定的，适用保管合同的有关规定。"},{"i":919,"n":"第九百一十九条","txt":"委托合同是委托人和受托人约定，由受托人处理委托人事务的合同。"},{"i":920,"n":"第九百二十条","txt":"委托人可以特别委托受托人处理一项或者数项事务，也可以概括委托受托人处理一切事务。"},{"i":921,"n":"第九百二十一条","txt":"委托人应当预付处理委托事务的费用。受托人为处理委托事务垫付的必要费用，委托人应当偿还该费用并支付利息。"},{"i":922,"n":"第九百二十二条","txt":"受托人应当按照委托人的指示处理委托事务。需要变更委托人指示的，应当经委托人同意；因情况紧急，难以和委托人取得联系的，受托人应当妥善处理委托事务，但是事后应当将该情况及时报告委托人。"},{"i":923,"n":"第九百二十三条","txt":"受托人应当亲自处理委托事务。经委托人同意，受托人可以转委托。转委托经同意或者追认的，委托人可以就委托事务直接指示转委托的第三人，受托人仅就第三人的选任及其对第三人的指示承担责任。转委托未经同意或者追认的，受托人应当对转委托的第三人的行为承担责任；但是，在紧急情况下受托人为了维护委托人的利益需要转委托第三人的除外。"},{"i":924,"n":"第九百二十四条","txt":"受托人应当按照委托人的要求，报告委托事务的处理情况。委托合同终止时，受托人应当报告委托事务的结果。"},{"i":925,"n":"第九百二十五条","txt":"受托人以自己的名义，在委托人的授权范围内与第三人订立的合同，第三人在订立合同时知道受托人与委托人之间的代理关系的，该合同直接约束委托人和第三人；但是，有确切证据证明该合同只约束受托人和第三人的除外。"},{"i":926,"n":"第九百二十六条","txt":"受托人以自己的名义与第三人订立合同时，第三人不知道受托人与委托人之间的代理关系的，受托人因第三人的原因对委托人不履行义务，受托人应当向委托人披露第三人，委托人因此可以行使受托人对第三人的权利。但是，第三人与受托人订立合同时如果知道该委托人就不会订立合同的除外。"},{"i":927,"n":"第九百二十七条","txt":"受托人处理委托事务取得的财产，应当转交给委托人。"},{"i":928,"n":"第九百二十八条","txt":"受托人完成委托事务的，委托人应当按照约定向其支付报酬。"},{"i":929,"n":"第九百二十九条","txt":"有偿的委托合同，因受托人的过错造成委托人损失的，委托人可以请求赔偿损失。无偿的委托合同，因受托人的故意或者重大过失造成委托人损失的，委托人可以请求赔偿损失。"},{"i":930,"n":"第九百三十条","txt":"受托人处理委托事务时，因不可归责于自己的事由受到损失的，可以向委托人请求赔偿损失。"},{"i":931,"n":"第九百三十一条","txt":"委托人经受托人同意，可以在受托人之外委托第三人处理委托事务。因此造成受托人损失的，受托人可以向委托人请求赔偿损失。"},{"i":932,"n":"第九百三十二条","txt":"两个以上的受托人共同处理委托事务的，对委托人承担连带责任。"},{"i":933,"n":"第九百三十三条","txt":"委托人或者受托人可以随时解除委托合同。因解除合同造成对方损失的，除不可归责于该当事人的事由外，无偿委托合同的解除方应当赔偿因解除时间不当造成的直接损失，有偿委托合同的解除方应当赔偿对方的直接损失和合同履行后可以获得的利益。"},{"i":934,"n":"第九百三十四条","txt":"委托人死亡、终止或者受托人死亡、丧失民事行为能力、终止的，委托合同终止；但是，当事人另有约定或者根据委托事务的性质不宜终止的除外。"},{"i":935,"n":"第九百三十五条","txt":"因委托人死亡或者被宣告破产、解散，致使委托合同终止将损害委托人利益的，在委托人的继承人、遗产管理人或者清算人承受委托事务之前，受托人应当继续处理委托事务。"},{"i":936,"n":"第九百三十六条","txt":"因受托人死亡、丧失民事行为能力或者被宣告破产、解散，致使委托合同终止的，受托人的继承人、遗产管理人、法定代理人或者清算人应当及时通知委托人。因委托合同终止将损害委托人利益的，在委托人作出善后处理之前，受托人的继承人、遗产管理人、法定代理人或者清算人应当采取必要措施。"},{"i":937,"n":"第九百三十七条","txt":"物业服务合同是物业服务人在物业服务区域内，为业主提供建筑物及其附属设施的维修养护、环境卫生和相关秩序的管理维护等物业服务，业主支付物业费的合同。"},{"i":938,"n":"第九百三十八条","txt":"物业服务合同的内容一般包括服务事项、服务质量、服务费用的标准和收取办法、维修资金的使用、服务用房的管理和使用、服务期限、服务交接等条款。"},{"i":939,"n":"第九百三十九条","txt":"建设单位依法与物业服务人订立的前期物业服务合同，以及业主委员会与业主大会依法选聘的物业服务人订立的物业服务合同，对业主具有法律约束力。"},{"i":940,"n":"第九百四十条","txt":"建设单位依法与物业服务人订立的前期物业服务合同约定的服务期限届满前，业主委员会或者业主与新物业服务人订立的物业服务合同生效的，前期物业服务合同终止。"},{"i":941,"n":"第九百四十一条","txt":"物业服务人将物业服务区域内的部分专项服务事项委托给专业性服务组织或者其他第三人的，应当就该部分专项服务事项向业主负责。"},{"i":942,"n":"第九百四十二条","txt":"物业服务人应当按照约定和物业的使用性质，妥善维修、养护、清洁、绿化和经营管理物业服务区域内的业主共有部分，维护物业服务区域内的基本秩序，采取合理措施保护业主的人身、财产安全。"},{"i":943,"n":"第九百四十三条","txt":"物业服务人应当定期将服务的事项、负责人员、质量要求、收费项目、收费标准、履行情况，以及维修资金使用情况、业主共有部分的经营与收益情况等以合理方式向业主公开并向业主大会、业主委员会报告。"},{"i":944,"n":"第九百四十四条","txt":"业主应当按照约定向物业服务人支付物业费。物业服务人已经按照约定和有关规定提供服务的，业主不得以未接受或者无需接受相关物业服务为由拒绝支付物业费。"},{"i":945,"n":"第九百四十五条","txt":"业主装饰装修房屋的，应当事先告知物业服务人，遵守物业服务人提示的合理注意事项，并配合其进行必要的现场检查。"},{"i":946,"n":"第九百四十六条","txt":"业主依照法定程序共同决定解聘物业服务人的，可以解除物业服务合同。决定解聘的，应当提前六十日书面通知物业服务人，但是合同对通知期限另有约定的除外。"},{"i":947,"n":"第九百四十七条","txt":"物业服务期限届满前，业主依法共同决定续聘的，应当与原物业服务人在合同期限届满前续订物业服务合同。"},{"i":948,"n":"第九百四十八条","txt":"物业服务期限届满后，业主没有依法作出续聘或者另聘物业服务人的决定，物业服务人继续提供物业服务的，原物业服务合同继续有效，但是服务期限为不定期。"},{"i":949,"n":"第九百四十九条","txt":"物业服务合同终止的，原物业服务人应当在约定期限或者合理期限内退出物业服务区域，将物业服务用房、相关设施、物业服务所必需的相关资料等交还给业主委员会、决定自行管理的业主或者其指定的人，配合新物业服务人做好交接工作，并如实告知物业的使用和管理状况。"},{"i":950,"n":"第九百五十条","txt":"物业服务合同终止后，在业主或者业主大会选聘的新物业服务人或者决定自行管理的业主接管之前，原物业服务人应当继续处理物业服务事项，并可以请求业主支付该期间的物业费。"},{"i":951,"n":"第九百五十一条","txt":"行纪合同是行纪人以自己的名义为委托人从事贸易活动，委托人支付报酬的合同。"},{"i":952,"n":"第九百五十二条","txt":"行纪人处理委托事务支出的费用，由行纪人负担，但是当事人另有约定的除外。"},{"i":953,"n":"第九百五十三条","txt":"行纪人占有委托物的，应当妥善保管委托物。"},{"i":954,"n":"第九百五十四条","txt":"委托物交付给行纪人时有瑕疵或者容易腐烂、变质的，经委托人同意，行纪人可以处分该物；不能与委托人及时取得联系的，行纪人可以合理处分。"},{"i":955,"n":"第九百五十五条","txt":"行纪人低于委托人指定的价格卖出或者高于委托人指定的价格买入的，应当经委托人同意；未经委托人同意，行纪人补偿其差额的，该买卖对委托人发生效力。"},{"i":956,"n":"第九百五十六条","txt":"行纪人卖出或者买入具有市场定价的商品，除委托人有相反的意思表示外，行纪人自己可以作为买受人或者出卖人。"},{"i":957,"n":"第九百五十七条","txt":"行纪人按照约定买入委托物，委托人应当及时受领。经行纪人催告，委托人无正当理由拒绝受领的，行纪人依法可以提存委托物。"},{"i":958,"n":"第九百五十八条","txt":"行纪人与第三人订立合同的，行纪人对该合同直接享有权利、承担义务。"},{"i":959,"n":"第九百五十九条","txt":"行纪人完成或者部分完成委托事务的，委托人应当向其支付相应的报酬。委托人逾期不支付报酬的，行纪人对委托物享有留置权，但是当事人另有约定的除外。"},{"i":960,"n":"第九百六十条","txt":"本章没有规定的，参照适用委托合同的有关规定。"},{"i":961,"n":"第九百六十一条","txt":"中介合同是中介人向委托人报告订立合同的机会或者提供订立合同的媒介服务，委托人支付报酬的合同。"},{"i":962,"n":"第九百六十二条","txt":"中介人应当就有关订立合同的事项向委托人如实报告。"},{"i":963,"n":"第九百六十三条","txt":"中介人促成合同成立的，委托人应当按照约定支付报酬。对中介人的报酬没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，根据中介人的劳务合理确定。因中介人提供订立合同的媒介服务而促成合同成立的，由该合同的当事人平均负担中介人的报酬。"},{"i":964,"n":"第九百六十四条","txt":"中介人未促成合同成立的，不得请求支付报酬；但是，可以按照约定请求委托人支付从事中介活动支出的必要费用。"},{"i":965,"n":"第九百六十五条","txt":"委托人在接受中介人的服务后，利用中介人提供的交易机会或者媒介服务，绕开中介人直接订立合同的，应当向中介人支付报酬。"},{"i":966,"n":"第九百六十六条","txt":"本章没有规定的，参照适用委托合同的有关规定。"},{"i":967,"n":"第九百六十七条","txt":"合伙合同是两个以上合伙人为了共同的事业目的，订立的共享利益、共担风险的协议。"},{"i":968,"n":"第九百六十八条","txt":"合伙人应当按照约定的出资方式、数额和缴付期限，履行出资义务。"},{"i":969,"n":"第九百六十九条","txt":"合伙人的出资、因合伙事务依法取得的收益和其他财产，属于合伙财产。"},{"i":970,"n":"第九百七十条","txt":"合伙人就合伙事务作出决定的，除合伙合同另有约定外，应当经全体合伙人一致同意。"},{"i":971,"n":"第九百七十一条","txt":"合伙人不得因执行合伙事务而请求支付报酬，但是合伙合同另有约定的除外。"},{"i":972,"n":"第九百七十二条","txt":"合伙的利润分配和亏损分担，按照合伙合同的约定办理；合伙合同没有约定或者约定不明确的，由合伙人协商决定；协商不成的，由合伙人按照实缴出资比例分配、分担；无法确定出资比例的，由合伙人平均分配、分担。"},{"i":973,"n":"第九百七十三条","txt":"合伙人对合伙债务承担连带责任。清偿合伙债务超过自己应当承担份额的合伙人，有权向其他合伙人追偿。"},{"i":974,"n":"第九百七十四条","txt":"除合伙合同另有约定外，合伙人向合伙人以外的人转让其全部或者部分财产份额的，须经其他合伙人一致同意。"},{"i":975,"n":"第九百七十五条","txt":"合伙人的债权人不得代位行使合伙人依照本章规定和合伙合同享有的权利，但是合伙人享有的利益分配请求权除外。"},{"i":976,"n":"第九百七十六条","txt":"合伙人对合伙期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，视为不定期合伙。"},{"i":977,"n":"第九百七十七条","txt":"合伙人死亡、丧失民事行为能力或者终止的，合伙合同终止；但是，合伙合同另有约定或者根据合伙事务的性质不宜终止的除外。"},{"i":978,"n":"第九百七十八条","txt":"合伙合同终止后，合伙财产在支付因终止而产生的费用以及清偿合伙债务后有剩余的，依据本法第九百七十二条的规定进行分配。"},{"i":979,"n":"第九百七十九条","txt":"管理人没有法定的或者约定的义务，为避免他人利益受损失而管理他人事务的，可以请求受益人偿还因管理事务而支出的必要费用；管理人因管理事务受到损失的，可以请求受益人给予适当补偿。"},{"i":980,"n":"第九百八十条","txt":"管理人管理事务不属于前条规定的情形，但是受益人享有管理利益的，受益人应当在其获得的利益范围内向管理人承担前条第一款规定的义务。"},{"i":981,"n":"第九百八十一条","txt":"管理人管理他人事务，应当采取有利于受益人的方法。中断管理对受益人不利的，无正当理由不得中断。"},{"i":982,"n":"第九百八十二条","txt":"管理人管理他人事务，能够通知受益人的，应当及时通知受益人。管理的事务不需要紧急处理的，应当等待受益人的指示。"},{"i":983,"n":"第九百八十三条","txt":"管理结束后，管理人应当向受益人报告管理事务的情况。管理人管理事务取得的财产，应当及时转交给受益人。"},{"i":984,"n":"第九百八十四条","txt":"管理人管理事务经受益人事后追认的，从管理事务开始时起，适用委托合同的有关规定，但是管理人另有意思表示的除外。"},{"i":985,"n":"第九百八十五条","txt":"得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但是有下列情形之一的除外："},{"i":986,"n":"第九百八十六条","txt":"得利人不知道且不应当知道取得的利益没有法律根据，取得的利益已经不存在的，不承担返还该利益的义务。"},{"i":987,"n":"第九百八十七条","txt":"得利人知道或者应当知道取得的利益没有法律根据的，受损失的人可以请求得利人返还其取得的利益并依法赔偿损失。"},{"i":988,"n":"第九百八十八条","txt":"得利人已经将取得的利益无偿转让给第三人的，受损失的人可以请求第三人在相应范围内承担返还义务。"},{"i":989,"n":"第九百八十九条","txt":"本编调整因人格权的享有和保护产生的民事关系。"},{"i":990,"n":"第九百九十条","txt":"人格权是民事主体享有的生命权、身体权、健康权、姓名权、名称权、肖像权、名誉权、荣誉权、隐私权等权利。"},{"i":991,"n":"第九百九十一条","txt":"民事主体的人格权受法律保护，任何组织或者个人不得侵害。"},{"i":992,"n":"第九百九十二条","txt":"人格权不得放弃、转让或者继承。"},{"i":993,"n":"第九百九十三条","txt":"民事主体可以将自己的姓名、名称、肖像等许可他人使用，但是依照法律规定或者根据其性质不得许可的除外。"},{"i":994,"n":"第九百九十四条","txt":"死者的姓名、肖像、名誉、荣誉、隐私、遗体等受到侵害的，其配偶、子女、父母有权依法请求行为人承担民事责任；死者没有配偶、子女且父母已经死亡的，其他近亲属有权依法请求行为人承担民事责任。"},{"i":995,"n":"第九百九十五条","txt":"人格权受到侵害的，受害人有权依照本法和其他法律的规定请求行为人承担民事责任。受害人的停止侵害、排除妨碍、消除危险、消除影响、恢复名誉、赔礼道歉请求权，不适用诉讼时效的规定。"},{"i":996,"n":"第九百九十六条","txt":"因当事人一方的违约行为，损害对方人格权并造成严重精神损害，受损害方选择请求其承担违约责任的，不影响受损害方请求精神损害赔偿。"},{"i":997,"n":"第九百九十七条","txt":"民事主体有证据证明行为人正在实施或者即将实施侵害其人格权的违法行为，不及时制止将使其合法权益受到难以弥补的损害的，有权依法向人民法院申请采取责令行为人停止有关行为的措施。"},{"i":998,"n":"第九百九十八条","txt":"认定行为人承担侵害除生命权、身体权和健康权外的人格权的民事责任，应当考虑行为人和受害人的职业、影响范围、过错程度，以及行为的目的、方式、后果等因素。"},{"i":999,"n":"第九百九十九条","txt":"为公共利益实施新闻报道、舆论监督等行为的，可以合理使用民事主体的姓名、名称、肖像、个人信息等；使用不合理侵害民事主体人格权的，应当依法承担民事责任。"},{"i":1000,"n":"第一千条","txt":"行为人因侵害人格权承担消除影响、恢复名誉、赔礼道歉等民事责任的，应当与行为的具体方式和造成的影响范围相当。"},{"i":1001,"n":"第一千零一条","txt":"对自然人因婚姻家庭关系等产生的身份权利的保护，适用本法第一编、第五编和其他法律的相关规定；没有规定的，可以根据其性质参照适用本编人格权保护的有关规定。"},{"i":1002,"n":"第一千零二条","txt":"自然人享有生命权。自然人的生命安全和生命尊严受法律保护。任何组织或者个人不得侵害他人的生命权。"},{"i":1003,"n":"第一千零三条","txt":"自然人享有身体权。自然人的身体完整和行动自由受法律保护。任何组织或者个人不得侵害他人的身体权。"},{"i":1004,"n":"第一千零四条","txt":"自然人享有健康权。自然人的身心健康受法律保护。任何组织或者个人不得侵害他人的健康权。"},{"i":1005,"n":"第一千零五条","txt":"自然人的生命权、身体权、健康权受到侵害或者处于其他危难情形的，负有法定救助义务的组织或者个人应当及时施救。"},{"i":1006,"n":"第一千零六条","txt":"完全民事行为能力人有权依法自主决定无偿捐献其人体细胞、人体组织、人体器官、遗体。任何组织或者个人不得强迫、欺骗、利诱其捐献。"},{"i":1007,"n":"第一千零七条","txt":"禁止以任何形式买卖人体细胞、人体组织、人体器官、遗体。"},{"i":1008,"n":"第一千零八条","txt":"为研制新药、医疗器械或者发展新的预防和治疗方法，需要进行临床试验的，应当依法经相关主管部门批准并经伦理委员会审查同意，向受试者或者受试者的监护人告知试验目的、用途和可能产生的风险等详细情况，并经其书面同意。"},{"i":1009,"n":"第一千零九条","txt":"从事与人体基因、人体胚胎等有关的医学和科研活动，应当遵守法律、行政法规和国家有关规定，不得危害人体健康，不得违背伦理道德，不得损害公共利益。"},{"i":1010,"n":"第一千零一十条","txt":"违背他人意愿，以言语、文字、图像、肢体行为等方式对他人实施性骚扰的，受害人有权依法请求行为人承担民事责任。"},{"i":1011,"n":"第一千零一十一条","txt":"以非法拘禁等方式剥夺、限制他人的行动自由，或者非法搜查他人身体的，受害人有权依法请求行为人承担民事责任。"},{"i":1012,"n":"第一千零一十二条","txt":"自然人享有姓名权，有权依法决定、使用、变更或者许可他人使用自己的姓名，但是不得违背公序良俗。"},{"i":1013,"n":"第一千零一十三条","txt":"法人、非法人组织享有名称权，有权依法决定、使用、变更、转让或者许可他人使用自己的名称。"},{"i":1014,"n":"第一千零一十四条","txt":"任何组织或者个人不得以干涉、盗用、假冒等方式侵害他人的姓名权或者名称权。"},{"i":1015,"n":"第一千零一十五条","txt":"自然人应当随父姓或者母姓，但是有下列情形之一的，可以在父姓和母姓之外选取姓氏："},{"i":1016,"n":"第一千零一十六条","txt":"自然人决定、变更姓名，或者法人、非法人组织决定、变更、转让名称的，应当依法向有关机关办理登记手续，但是法律另有规定的除外。"},{"i":1017,"n":"第一千零一十七条","txt":"具有一定社会知名度，被他人使用足以造成公众混淆的笔名、艺名、网名、译名、字号、姓名和名称的简称等，参照适用姓名权和名称权保护的有关规定。"},{"i":1018,"n":"第一千零一十八条","txt":"自然人享有肖像权，有权依法制作、使用、公开或者许可他人使用自己的肖像。"},{"i":1019,"n":"第一千零一十九条","txt":"任何组织或者个人不得以丑化、污损，或者利用信息技术手段伪造等方式侵害他人的肖像权。未经肖像权人同意，不得制作、使用、公开肖像权人的肖像，但是法律另有规定的除外。"},{"i":1020,"n":"第一千零二十条","txt":"合理实施下列行为的，可以不经肖像权人同意："},{"i":1021,"n":"第一千零二十一条","txt":"当事人对肖像许可使用合同中关于肖像使用条款的理解有争议的，应当作出有利于肖像权人的解释。"},{"i":1022,"n":"第一千零二十二条","txt":"当事人对肖像许可使用期限没有约定或者约定不明确的，任何一方当事人可以随时解除肖像许可使用合同，但是应当在合理期限之前通知对方。"},{"i":1023,"n":"第一千零二十三条","txt":"对姓名等的许可使用，参照适用肖像许可使用的有关规定。"},{"i":1024,"n":"第一千零二十四条","txt":"民事主体享有名誉权。任何组织或者个人不得以侮辱、诽谤等方式侵害他人的名誉权。"},{"i":1025,"n":"第一千零二十五条","txt":"行为人为公共利益实施新闻报道、舆论监督等行为，影响他人名誉的，不承担民事责任，但是有下列情形之一的除外："},{"i":1026,"n":"第一千零二十六条","txt":"认定行为人是否尽到前条第二项规定的合理核实义务，应当考虑下列因素："},{"i":1027,"n":"第一千零二十七条","txt":"行为人发表的文学、艺术作品以真人真事或者特定人为描述对象，含有侮辱、诽谤内容，侵害他人名誉权的，受害人有权依法请求该行为人承担民事责任。"},{"i":1028,"n":"第一千零二十八条","txt":"民事主体有证据证明报刊、网络等媒体报道的内容失实，侵害其名誉权的，有权请求该媒体及时采取更正或者删除等必要措施。"},{"i":1029,"n":"第一千零二十九条","txt":"民事主体可以依法查询自己的信用评价；发现信用评价不当的，有权提出异议并请求采取更正、删除等必要措施。信用评价人应当及时核查，经核查属实的，应当及时采取必要措施。"},{"i":1030,"n":"第一千零三十条","txt":"民事主体与征信机构等信用信息处理者之间的关系，适用本编有关个人信息保护的规定和其他法律、行政法规的有关规定。"},{"i":1031,"n":"第一千零三十一条","txt":"民事主体享有荣誉权。任何组织或者个人不得非法剥夺他人的荣誉称号，不得诋毁、贬损他人的荣誉。"},{"i":1032,"n":"第一千零三十二条","txt":"自然人享有隐私权。任何组织或者个人不得以刺探、侵扰、泄露、公开等方式侵害他人的隐私权。"},{"i":1033,"n":"第一千零三十三条","txt":"除法律另有规定或者权利人明确同意外，任何组织或者个人不得实施下列行为："},{"i":1034,"n":"第一千零三十四条","txt":"自然人的个人信息受法律保护。"},{"i":1035,"n":"第一千零三十五条","txt":"处理个人信息的，应当遵循合法、正当、必要原则，不得过度处理，并符合下列条件："},{"i":1036,"n":"第一千零三十六条","txt":"处理个人信息，有下列情形之一的，行为人不承担民事责任："},{"i":1037,"n":"第一千零三十七条","txt":"自然人可以依法向信息处理者查阅或者复制其个人信息；发现信息有错误的，有权提出异议并请求及时采取更正等必要措施。"},{"i":1038,"n":"第一千零三十八条","txt":"信息处理者不得泄露或者篡改其收集、存储的个人信息；未经自然人同意，不得向他人非法提供其个人信息，但是经过加工无法识别特定个人且不能复原的除外。"},{"i":1039,"n":"第一千零三十九条","txt":"国家机关、承担行政职能的法定机构及其工作人员对于履行职责过程中知悉的自然人的隐私和个人信息，应当予以保密，不得泄露或者向他人非法提供。"},{"i":1040,"n":"第一千零四十条","txt":"本编调整因婚姻家庭产生的民事关系。"},{"i":1041,"n":"第一千零四十一条","txt":"婚姻家庭受国家保护。"},{"i":1042,"n":"第一千零四十二条","txt":"禁止包办、买卖婚姻和其他干涉婚姻自由的行为。禁止借婚姻索取财物。"},{"i":1043,"n":"第一千零四十三条","txt":"家庭应当树立优良家风，弘扬家庭美德，重视家庭文明建设。"},{"i":1044,"n":"第一千零四十四条","txt":"收养应当遵循最有利于被收养人的原则，保障被收养人和收养人的合法权益。"},{"i":1045,"n":"第一千零四十五条","txt":"亲属包括配偶、血亲和姻亲。"},{"i":1046,"n":"第一千零四十六条","txt":"结婚应当男女双方完全自愿，禁止任何一方对另一方加以强迫，禁止任何组织或者个人加以干涉。"},{"i":1047,"n":"第一千零四十七条","txt":"结婚年龄，男不得早于二十二周岁，女不得早于二十周岁。"},{"i":1048,"n":"第一千零四十八条","txt":"直系血亲或者三代以内的旁系血亲禁止结婚。"},{"i":1049,"n":"第一千零四十九条","txt":"要求结婚的男女双方应当亲自到婚姻登记机关申请结婚登记。符合本法规定的，予以登记，发给结婚证。完成结婚登记，即确立婚姻关系。未办理结婚登记的，应当补办登记。"},{"i":1050,"n":"第一千零五十条","txt":"登记结婚后，按照男女双方约定，女方可以成为男方家庭的成员，男方可以成为女方家庭的成员。"},{"i":1051,"n":"第一千零五十一条","txt":"有下列情形之一的，婚姻无效："},{"i":1052,"n":"第一千零五十二条","txt":"因胁迫结婚的，受胁迫的一方可以向人民法院请求撤销婚姻。"},{"i":1053,"n":"第一千零五十三条","txt":"一方患有重大疾病的，应当在结婚登记前如实告知另一方；不如实告知的，另一方可以向人民法院请求撤销婚姻。"},{"i":1054,"n":"第一千零五十四条","txt":"无效的或者被撤销的婚姻自始没有法律约束力，当事人不具有夫妻的权利和义务。同居期间所得的财产，由当事人协议处理；协议不成的，由人民法院根据照顾无过错方的原则判决。对重婚导致的无效婚姻的财产处理，不得侵害合法婚姻当事人的财产权益。当事人所生的子女，适用本法关于父母子女的规定。"},{"i":1055,"n":"第一千零五十五条","txt":"夫妻在婚姻家庭中地位平等。"},{"i":1056,"n":"第一千零五十六条","txt":"夫妻双方都有各自使用自己姓名的权利。"},{"i":1057,"n":"第一千零五十七条","txt":"夫妻双方都有参加生产、工作、学习和社会活动的自由，一方不得对另一方加以限制或者干涉。"},{"i":1058,"n":"第一千零五十八条","txt":"夫妻双方平等享有对未成年子女抚养、教育和保护的权利，共同承担对未成年子女抚养、教育和保护的义务。"},{"i":1059,"n":"第一千零五十九条","txt":"夫妻有相互扶养的义务。"},{"i":1060,"n":"第一千零六十条","txt":"夫妻一方因家庭日常生活需要而实施的民事法律行为，对夫妻双方发生效力，但是夫妻一方与相对人另有约定的除外。"},{"i":1061,"n":"第一千零六十一条","txt":"夫妻有相互继承遗产的权利。"},{"i":1062,"n":"第一千零六十二条","txt":"夫妻在婚姻关系存续期间所得的下列财产，为夫妻的共同财产，归夫妻共同所有："},{"i":1063,"n":"第一千零六十三条","txt":"下列财产为夫妻一方的个人财产："},{"i":1064,"n":"第一千零六十四条","txt":"夫妻双方共同签名或者夫妻一方事后追认等共同意思表示所负的债务，以及夫妻一方在婚姻关系存续期间以个人名义为家庭日常生活需要所负的债务，属于夫妻共同债务。"},{"i":1065,"n":"第一千零六十五条","txt":"男女双方可以约定婚姻关系存续期间所得的财产以及婚前财产归各自所有、共同所有或者部分各自所有、部分共同所有。约定应当采用书面形式。没有约定或者约定不明确的，适用本法第一千零六十二条、第一千零六十三条的规定。"},{"i":1066,"n":"第一千零六十六条","txt":"婚姻关系存续期间，有下列情形之一的，夫妻一方可以向人民法院请求分割共同财产："},{"i":1067,"n":"第一千零六十七条","txt":"父母不履行抚养义务的，未成年子女或者不能独立生活的成年子女，有要求父母给付抚养费的权利。"},{"i":1068,"n":"第一千零六十八条","txt":"父母有教育、保护未成年子女的权利和义务。未成年子女造成他人损害的，父母应当依法承担民事责任。"},{"i":1069,"n":"第一千零六十九条","txt":"子女应当尊重父母的婚姻权利，不得干涉父母离婚、再婚以及婚后的生活。子女对父母的赡养义务，不因父母的婚姻关系变化而终止。"},{"i":1070,"n":"第一千零七十条","txt":"父母和子女有相互继承遗产的权利。"},{"i":1071,"n":"第一千零七十一条","txt":"非婚生子女享有与婚生子女同等的权利，任何组织或者个人不得加以危害和歧视。"},{"i":1072,"n":"第一千零七十二条","txt":"继父母与继子女间，不得虐待或者歧视。"},{"i":1073,"n":"第一千零七十三条","txt":"对亲子关系有异议且有正当理由的，父或者母可以向人民法院提起诉讼，请求确认或者否认亲子关系。"},{"i":1074,"n":"第一千零七十四条","txt":"有负担能力的祖父母、外祖父母，对于父母已经死亡或者父母无力抚养的未成年孙子女、外孙子女，有抚养的义务。"},{"i":1075,"n":"第一千零七十五条","txt":"有负担能力的兄、姐，对于父母已经死亡或者父母无力抚养的未成年弟、妹，有扶养的义务。"},{"i":1076,"n":"第一千零七十六条","txt":"夫妻双方自愿离婚的，应当签订书面离婚协议，并亲自到婚姻登记机关申请离婚登记。"},{"i":1077,"n":"第一千零七十七条","txt":"自婚姻登记机关收到离婚登记申请之日起三十日内，任何一方不愿意离婚的，可以向婚姻登记机关撤回离婚登记申请。"},{"i":1078,"n":"第一千零七十八条","txt":"婚姻登记机关查明双方确实是自愿离婚，并已经对子女抚养、财产以及债务处理等事项协商一致的，予以登记，发给离婚证。"},{"i":1079,"n":"第一千零七十九条","txt":"夫妻一方要求离婚的，可以由有关组织进行调解或者直接向人民法院提起离婚诉讼。"},{"i":1080,"n":"第一千零八十条","txt":"完成离婚登记，或者离婚判决书、调解书生效，即解除婚姻关系。"},{"i":1081,"n":"第一千零八十一条","txt":"现役军人的配偶要求离婚，应当征得军人同意，但是军人一方有重大过错的除外。"},{"i":1082,"n":"第一千零八十二条","txt":"女方在怀孕期间、分娩后一年内或者终止妊娠后六个月内，男方不得提出离婚；但是，女方提出离婚或者人民法院认为确有必要受理男方离婚请求的除外。"},{"i":1083,"n":"第一千零八十三条","txt":"离婚后，男女双方自愿恢复婚姻关系的，应当到婚姻登记机关重新进行结婚登记。"},{"i":1084,"n":"第一千零八十四条","txt":"父母与子女间的关系，不因父母离婚而消除。离婚后，子女无论由父或者母直接抚养，仍是父母双方的子女。"},{"i":1085,"n":"第一千零八十五条","txt":"离婚后，子女由一方直接抚养的，另一方应当负担部分或者全部抚养费。负担费用的多少和期限的长短，由双方协议；协议不成的，由人民法院判决。"},{"i":1086,"n":"第一千零八十六条","txt":"离婚后，不直接抚养子女的父或者母，有探望子女的权利，另一方有协助的义务。"},{"i":1087,"n":"第一千零八十七条","txt":"离婚时，夫妻的共同财产由双方协议处理；协议不成的，由人民法院根据财产的具体情况，按照照顾子女、女方和无过错方权益的原则判决。"},{"i":1088,"n":"第一千零八十八条","txt":"夫妻一方因抚育子女、照料老年人、协助另一方工作等负担较多义务的，离婚时有权向另一方请求补偿，另一方应当给予补偿。具体办法由双方协议；协议不成的，由人民法院判决。"},{"i":1089,"n":"第一千零八十九条","txt":"离婚时，夫妻共同债务应当共同偿还。共同财产不足清偿或者财产归各自所有的，由双方协议清偿；协议不成的，由人民法院判决。"},{"i":1090,"n":"第一千零九十条","txt":"离婚时，如果一方生活困难，有负担能力的另一方应当给予适当帮助。具体办法由双方协议；协议不成的，由人民法院判决。"},{"i":1091,"n":"第一千零九十一条","txt":"有下列情形之一，导致离婚的，无过错方有权请求损害赔偿："},{"i":1092,"n":"第一千零九十二条","txt":"夫妻一方隐藏、转移、变卖、毁损、挥霍夫妻共同财产，或者伪造夫妻共同债务企图侵占另一方财产的，在离婚分割夫妻共同财产时，对该方可以少分或者不分。离婚后，另一方发现有上述行为的，可以向人民法院提起诉讼，请求再次分割夫妻共同财产。"},{"i":1093,"n":"第一千零九十三条","txt":"下列未成年人，可以被收养："},{"i":1094,"n":"第一千零九十四条","txt":"下列个人、组织可以作送养人："},{"i":1095,"n":"第一千零九十五条","txt":"未成年人的父母均不具备完全民事行为能力且可能严重危害该未成年人的，该未成年人的监护人可以将其送养。"},{"i":1096,"n":"第一千零九十六条","txt":"监护人送养孤儿的，应当征得有抚养义务的人同意。有抚养义务的人不同意送养、监护人不愿意继续履行监护职责的，应当依照本法第一编的规定另行确定监护人。"},{"i":1097,"n":"第一千零九十七条","txt":"生父母送养子女，应当双方共同送养。生父母一方不明或者查找不到的，可以单方送养。"},{"i":1098,"n":"第一千零九十八条","txt":"收养人应当同时具备下列条件："},{"i":1099,"n":"第一千零九十九条","txt":"收养三代以内旁系同辈血亲的子女，可以不受本法第一千零九十三条第三项、第一千零九十四条第三项和第一千一百零二条规定的限制。"},{"i":1100,"n":"第一千一百条","txt":"无子女的收养人可以收养两名子女；有子女的收养人只能收养一名子女。"},{"i":1101,"n":"第一千一百零一条","txt":"有配偶者收养子女，应当夫妻共同收养。"},{"i":1102,"n":"第一千一百零二条","txt":"无配偶者收养异性子女的，收养人与被收养人的年龄应当相差四十周岁以上。"},{"i":1103,"n":"第一千一百零三条","txt":"继父或者继母经继子女的生父母同意，可以收养继子女，并可以不受本法第一千零九十三条第三项、第一千零九十四条第三项、第一千零九十八条和第一千一百条第一款规定的限制。"},{"i":1104,"n":"第一千一百零四条","txt":"收养人收养与送养人送养，应当双方自愿。收养八周岁以上未成年人的，应当征得被收养人的同意。"},{"i":1105,"n":"第一千一百零五条","txt":"收养应当向县级以上人民政府民政部门登记。收养关系自登记之日起成立。"},{"i":1106,"n":"第一千一百零六条","txt":"收养关系成立后，公安机关应当按照国家有关规定为被收养人办理户口登记。"},{"i":1107,"n":"第一千一百零七条","txt":"孤儿或者生父母无力抚养的子女，可以由生父母的亲属、朋友抚养；抚养人与被抚养人的关系不适用本章规定。"},{"i":1108,"n":"第一千一百零八条","txt":"配偶一方死亡，另一方送养未成年子女的，死亡一方的父母有优先抚养的权利。"},{"i":1109,"n":"第一千一百零九条","txt":"外国人依法可以在中华人民共和国收养子女。"},{"i":1110,"n":"第一千一百一十条","txt":"收养人、送养人要求保守收养秘密的，其他人应当尊重其意愿，不得泄露。"},{"i":1111,"n":"第一千一百一十一条","txt":"自收养关系成立之日起，养父母与养子女间的权利义务关系，适用本法关于父母子女关系的规定；养子女与养父母的近亲属间的权利义务关系，适用本法关于子女与父母的近亲属关系的规定。"},{"i":1112,"n":"第一千一百一十二条","txt":"养子女可以随养父或者养母的姓氏，经当事人协商一致，也可以保留原姓氏。"},{"i":1113,"n":"第一千一百一十三条","txt":"有本法第一编关于民事法律行为无效规定情形或者违反本编规定的收养行为无效。"},{"i":1114,"n":"第一千一百一十四条","txt":"收养人在被收养人成年以前，不得解除收养关系，但是收养人、送养人双方协议解除的除外。养子女八周岁以上的，应当征得本人同意。"},{"i":1115,"n":"第一千一百一十五条","txt":"养父母与成年养子女关系恶化、无法共同生活的，可以协议解除收养关系。不能达成协议的，可以向人民法院提起诉讼。"},{"i":1116,"n":"第一千一百一十六条","txt":"当事人协议解除收养关系的，应当到民政部门办理解除收养关系登记。"},{"i":1117,"n":"第一千一百一十七条","txt":"收养关系解除后，养子女与养父母以及其他近亲属间的权利义务关系即行消除，与生父母以及其他近亲属间的权利义务关系自行恢复。但是，成年养子女与生父母以及其他近亲属间的权利义务关系是否恢复，可以协商确定。"},{"i":1118,"n":"第一千一百一十八条","txt":"收养关系解除后，经养父母抚养的成年养子女，对缺乏劳动能力又缺乏生活来源的养父母，应当给付生活费。因养子女成年后虐待、遗弃养父母而解除收养关系的，养父母可以要求养子女补偿收养期间支出的抚养费。"},{"i":1119,"n":"第一千一百一十九条","txt":"本编调整因继承产生的民事关系。"},{"i":1120,"n":"第一千一百二十条","txt":"国家保护自然人的继承权。"},{"i":1121,"n":"第一千一百二十一条","txt":"继承从被继承人死亡时开始。"},{"i":1122,"n":"第一千一百二十二条","txt":"遗产是自然人死亡时遗留的个人合法财产。"},{"i":1123,"n":"第一千一百二十三条","txt":"继承开始后，按照法定继承办理；有遗嘱的，按照遗嘱继承或者遗赠办理；有遗赠扶养协议的，按照协议办理。"},{"i":1124,"n":"第一千一百二十四条","txt":"继承开始后，继承人放弃继承的，应当在遗产处理前，以书面形式作出放弃继承的表示；没有表示的，视为接受继承。"},{"i":1125,"n":"第一千一百二十五条","txt":"继承人有下列行为之一的，丧失继承权："},{"i":1126,"n":"第一千一百二十六条","txt":"继承权男女平等。"},{"i":1127,"n":"第一千一百二十七条","txt":"遗产按照下列顺序继承："},{"i":1128,"n":"第一千一百二十八条","txt":"被继承人的子女先于被继承人死亡的，由被继承人的子女的直系晚辈血亲代位继承。"},{"i":1129,"n":"第一千一百二十九条","txt":"丧偶儿媳对公婆，丧偶女婿对岳父母，尽了主要赡养义务的，作为第一顺序继承人。"},{"i":1130,"n":"第一千一百三十条","txt":"同一顺序继承人继承遗产的份额，一般应当均等。"},{"i":1131,"n":"第一千一百三十一条","txt":"对继承人以外的依靠被继承人扶养的人，或者继承人以外的对被继承人扶养较多的人，可以分给适当的遗产。"},{"i":1132,"n":"第一千一百三十二条","txt":"继承人应当本着互谅互让、和睦团结的精神，协商处理继承问题。遗产分割的时间、办法和份额，由继承人协商确定；协商不成的，可以由人民调解委员会调解或者向人民法院提起诉讼。"},{"i":1133,"n":"第一千一百三十三条","txt":"自然人可以依照本法规定立遗嘱处分个人财产，并可以指定遗嘱执行人。"},{"i":1134,"n":"第一千一百三十四条","txt":"自书遗嘱由遗嘱人亲笔书写，签名，注明年、月、日。"},{"i":1135,"n":"第一千一百三十五条","txt":"代书遗嘱应当有两个以上见证人在场见证，由其中一人代书，并由遗嘱人、代书人和其他见证人签名，注明年、月、日。"},{"i":1136,"n":"第一千一百三十六条","txt":"打印遗嘱应当有两个以上见证人在场见证。遗嘱人和见证人应当在遗嘱每一页签名，注明年、月、日。"},{"i":1137,"n":"第一千一百三十七条","txt":"以录音录像形式立的遗嘱，应当有两个以上见证人在场见证。遗嘱人和见证人应当在录音录像中记录其姓名或者肖像，以及年、月、日。"},{"i":1138,"n":"第一千一百三十八条","txt":"遗嘱人在危急情况下，可以立口头遗嘱。口头遗嘱应当有两个以上见证人在场见证。危急情况消除后，遗嘱人能够以书面或者录音录像形式立遗嘱的，所立的口头遗嘱无效。"},{"i":1139,"n":"第一千一百三十九条","txt":"公证遗嘱由遗嘱人经公证机构办理。"},{"i":1140,"n":"第一千一百四十条","txt":"下列人员不能作为遗嘱见证人："},{"i":1141,"n":"第一千一百四十一条","txt":"遗嘱应当为缺乏劳动能力又没有生活来源的继承人保留必要的遗产份额。"},{"i":1142,"n":"第一千一百四十二条","txt":"遗嘱人可以撤回、变更自己所立的遗嘱。"},{"i":1143,"n":"第一千一百四十三条","txt":"无民事行为能力人或者限制民事行为能力人所立的遗嘱无效。"},{"i":1144,"n":"第一千一百四十四条","txt":"遗嘱继承或者遗赠附有义务的，继承人或者受遗赠人应当履行义务。没有正当理由不履行义务的，经利害关系人或者有关组织请求，人民法院可以取消其接受附义务部分遗产的权利。"},{"i":1145,"n":"第一千一百四十五条","txt":"继承开始后，遗嘱执行人为遗产管理人；没有遗嘱执行人的，继承人应当及时推选遗产管理人；继承人未推选的，由继承人共同担任遗产管理人；没有继承人或者继承人均放弃继承的，由被继承人生前住所地的民政部门或者村民委员会担任遗产管理人。"},{"i":1146,"n":"第一千一百四十六条","txt":"对遗产管理人的确定有争议的，利害关系人可以向人民法院申请指定遗产管理人。"},{"i":1147,"n":"第一千一百四十七条","txt":"遗产管理人应当履行下列职责："},{"i":1148,"n":"第一千一百四十八条","txt":"遗产管理人应当依法履行职责，因故意或者重大过失造成继承人、受遗赠人、债权人损害的，应当承担民事责任。"},{"i":1149,"n":"第一千一百四十九条","txt":"遗产管理人可以依照法律规定或者按照约定获得报酬。"},{"i":1150,"n":"第一千一百五十条","txt":"继承开始后，知道被继承人死亡的继承人应当及时通知其他继承人和遗嘱执行人。继承人中无人知道被继承人死亡或者知道被继承人死亡而不能通知的，由被继承人生前所在单位或者住所地的居民委员会、村民委员会负责通知。"},{"i":1151,"n":"第一千一百五十一条","txt":"存有遗产的人，应当妥善保管遗产，任何组织或者个人不得侵吞或者争抢。"},{"i":1152,"n":"第一千一百五十二条","txt":"继承开始后，继承人于遗产分割前死亡，并没有放弃继承的，该继承人应当继承的遗产转给其继承人，但是遗嘱另有安排的除外。"},{"i":1153,"n":"第一千一百五十三条","txt":"夫妻共同所有的财产，除有约定的外，遗产分割时，应当先将共同所有的财产的一半分出为配偶所有，其余的为被继承人的遗产。"},{"i":1154,"n":"第一千一百五十四条","txt":"有下列情形之一的，遗产中的有关部分按照法定继承办理："},{"i":1155,"n":"第一千一百五十五条","txt":"遗产分割时，应当保留胎儿的继承份额。胎儿娩出时是死体的，保留的份额按照法定继承办理。"},{"i":1156,"n":"第一千一百五十六条","txt":"遗产分割应当有利于生产和生活需要，不损害遗产的效用。"},{"i":1157,"n":"第一千一百五十七条","txt":"夫妻一方死亡后另一方再婚的，有权处分所继承的财产，任何组织或者个人不得干涉。"},{"i":1158,"n":"第一千一百五十八条","txt":"自然人可以与继承人以外的组织或者个人签订遗赠扶养协议。按照协议，该组织或者个人承担该自然人生养死葬的义务，享有受遗赠的权利。"},{"i":1159,"n":"第一千一百五十九条","txt":"分割遗产，应当清偿被继承人依法应当缴纳的税款和债务；但是，应当为缺乏劳动能力又没有生活来源的继承人保留必要的遗产。"},{"i":1160,"n":"第一千一百六十条","txt":"无人继承又无人受遗赠的遗产，归国家所有，用于公益事业；死者生前是集体所有制组织成员的，归所在集体所有制组织所有。"},{"i":1161,"n":"第一千一百六十一条","txt":"继承人以所得遗产实际价值为限清偿被继承人依法应当缴纳的税款和债务。超过遗产实际价值部分，继承人自愿偿还的不在此限。"},{"i":1162,"n":"第一千一百六十二条","txt":"执行遗赠不得妨碍清偿遗赠人依法应当缴纳的税款和债务。"},{"i":1163,"n":"第一千一百六十三条","txt":"既有法定继承又有遗嘱继承、遗赠的，由法定继承人清偿被继承人依法应当缴纳的税款和债务；超过法定继承遗产实际价值部分，由遗嘱继承人和受遗赠人按比例以所得遗产清偿。"},{"i":1164,"n":"第一千一百六十四条","txt":"本编调整因侵害民事权益产生的民事关系。"},{"i":1165,"n":"第一千一百六十五条","txt":"行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。"},{"i":1166,"n":"第一千一百六十六条","txt":"行为人造成他人民事权益损害，不论行为人有无过错，法律规定应当承担侵权责任的，依照其规定。"},{"i":1167,"n":"第一千一百六十七条","txt":"侵权行为危及他人人身、财产安全的，被侵权人有权请求侵权人承担停止侵害、排除妨碍、消除危险等侵权责任。"},{"i":1168,"n":"第一千一百六十八条","txt":"二人以上共同实施侵权行为，造成他人损害的，应当承担连带责任。"},{"i":1169,"n":"第一千一百六十九条","txt":"教唆、帮助他人实施侵权行为的，应当与行为人承担连带责任。"},{"i":1170,"n":"第一千一百七十条","txt":"二人以上实施危及他人人身、财产安全的行为，其中一人或者数人的行为造成他人损害，能够确定具体侵权人的，由侵权人承担责任；不能确定具体侵权人的，行为人承担连带责任。"},{"i":1171,"n":"第一千一百七十一条","txt":"二人以上分别实施侵权行为造成同一损害，每个人的侵权行为都足以造成全部损害的，行为人承担连带责任。"},{"i":1172,"n":"第一千一百七十二条","txt":"二人以上分别实施侵权行为造成同一损害，能够确定责任大小的，各自承担相应的责任；难以确定责任大小的，平均承担责任。"},{"i":1173,"n":"第一千一百七十三条","txt":"被侵权人对同一损害的发生或者扩大有过错的，可以减轻侵权人的责任。"},{"i":1174,"n":"第一千一百七十四条","txt":"损害是因受害人故意造成的，行为人不承担责任。"},{"i":1175,"n":"第一千一百七十五条","txt":"损害是因第三人造成的，第三人应当承担侵权责任。"},{"i":1176,"n":"第一千一百七十六条","txt":"自愿参加具有一定风险的文体活动，因其他参加者的行为受到损害的，受害人不得请求其他参加者承担侵权责任；但是，其他参加者对损害的发生有故意或者重大过失的除外。"},{"i":1177,"n":"第一千一百七十七条","txt":"合法权益受到侵害，情况紧迫且不能及时获得国家机关保护，不立即采取措施将使其合法权益受到难以弥补的损害的，受害人可以在保护自己合法权益的必要范围内采取扣留侵权人的财物等合理措施；但是，应当立即请求有关国家机关处理。"},{"i":1178,"n":"第一千一百七十八条","txt":"本法和其他法律对不承担责任或者减轻责任的情形另有规定的，依照其规定。"},{"i":1179,"n":"第一千一百七十九条","txt":"侵害他人造成人身损害的，应当赔偿医疗费、护理费、交通费、营养费、住院伙食补助费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿辅助器具费和残疾赔偿金；造成死亡的，还应当赔偿丧葬费和死亡赔偿金。"},{"i":1180,"n":"第一千一百八十条","txt":"因同一侵权行为造成多人死亡的，可以以相同数额确定死亡赔偿金。"},{"i":1181,"n":"第一千一百八十一条","txt":"被侵权人死亡的，其近亲属有权请求侵权人承担侵权责任。被侵权人为组织，该组织分立、合并的，承继权利的组织有权请求侵权人承担侵权责任。"},{"i":1182,"n":"第一千一百八十二条","txt":"侵害他人人身权益造成财产损失的，按照被侵权人因此受到的损失或者侵权人因此获得的利益赔偿；被侵权人因此受到的损失以及侵权人因此获得的利益难以确定，被侵权人和侵权人就赔偿数额协商不一致，向人民法院提起诉讼的，由人民法院根据实际情况确定赔偿数额。"},{"i":1183,"n":"第一千一百八十三条","txt":"侵害自然人人身权益造成严重精神损害的，被侵权人有权请求精神损害赔偿。"},{"i":1184,"n":"第一千一百八十四条","txt":"侵害他人财产的，财产损失按照损失发生时的市场价格或者其他合理方式计算。"},{"i":1185,"n":"第一千一百八十五条","txt":"故意侵害他人知识产权，情节严重的，被侵权人有权请求相应的惩罚性赔偿。"},{"i":1186,"n":"第一千一百八十六条","txt":"受害人和行为人对损害的发生都没有过错的，依照法律的规定由双方分担损失。"},{"i":1187,"n":"第一千一百八十七条","txt":"损害发生后，当事人可以协商赔偿费用的支付方式。协商不一致的，赔偿费用应当一次性支付；一次性支付确有困难的，可以分期支付，但是被侵权人有权请求提供相应的担保。"},{"i":1188,"n":"第一千一百八十八条","txt":"无民事行为能力人、限制民事行为能力人造成他人损害的，由监护人承担侵权责任。监护人尽到监护职责的，可以减轻其侵权责任。"},{"i":1189,"n":"第一千一百八十九条","txt":"无民事行为能力人、限制民事行为能力人造成他人损害，监护人将监护职责委托给他人的，监护人应当承担侵权责任；受托人有过错的，承担相应的责任。"},{"i":1190,"n":"第一千一百九十条","txt":"完全民事行为能力人对自己的行为暂时没有意识或者失去控制造成他人损害有过错的，应当承担侵权责任；没有过错的，根据行为人的经济状况对受害人适当补偿。"},{"i":1191,"n":"第一千一百九十一条","txt":"用人单位的工作人员因执行工作任务造成他人损害的，由用人单位承担侵权责任。用人单位承担侵权责任后，可以向有故意或者重大过失的工作人员追偿。"},{"i":1192,"n":"第一千一百九十二条","txt":"个人之间形成劳务关系，提供劳务一方因劳务造成他人损害的，由接受劳务一方承担侵权责任。接受劳务一方承担侵权责任后，可以向有故意或者重大过失的提供劳务一方追偿。提供劳务一方因劳务受到损害的，根据双方各自的过错承担相应的责任。"},{"i":1193,"n":"第一千一百九十三条","txt":"承揽人在完成工作过程中造成第三人损害或者自己损害的，定作人不承担侵权责任。但是，定作人对定作、指示或者选任有过错的，应当承担相应的责任。"},{"i":1194,"n":"第一千一百九十四条","txt":"网络用户、网络服务提供者利用网络侵害他人民事权益的，应当承担侵权责任。法律另有规定的，依照其规定。"},{"i":1195,"n":"第一千一百九十五条","txt":"网络用户利用网络服务实施侵权行为的，权利人有权通知网络服务提供者采取删除、屏蔽、断开链接等必要措施。通知应当包括构成侵权的初步证据及权利人的真实身份信息。"},{"i":1196,"n":"第一千一百九十六条","txt":"网络用户接到转送的通知后，可以向网络服务提供者提交不存在侵权行为的声明。声明应当包括不存在侵权行为的初步证据及网络用户的真实身份信息。"},{"i":1197,"n":"第一千一百九十七条","txt":"网络服务提供者知道或者应当知道网络用户利用其网络服务侵害他人民事权益，未采取必要措施的，与该网络用户承担连带责任。"},{"i":1198,"n":"第一千一百九十八条","txt":"宾馆、商场、银行、车站、机场、体育场馆、娱乐场所等经营场所、公共场所的经营者、管理者或者群众性活动的组织者，未尽到安全保障义务，造成他人损害的，应当承担侵权责任。"},{"i":1199,"n":"第一千一百九十九条","txt":"无民事行为能力人在幼儿园、学校或者其他教育机构学习、生活期间受到人身损害的，幼儿园、学校或者其他教育机构应当承担侵权责任；但是，能够证明尽到教育、管理职责的，不承担侵权责任。"},{"i":1200,"n":"第一千二百条","txt":"限制民事行为能力人在学校或者其他教育机构学习、生活期间受到人身损害，学校或者其他教育机构未尽到教育、管理职责的，应当承担侵权责任。"},{"i":1201,"n":"第一千二百零一条","txt":"无民事行为能力人或者限制民事行为能力人在幼儿园、学校或者其他教育机构学习、生活期间，受到幼儿园、学校或者其他教育机构以外的第三人人身损害的，由第三人承担侵权责任；幼儿园、学校或者其他教育机构未尽到管理职责的，承担相应的补充责任。幼儿园、学校或者其他教育机构承担补充责任后，可以向第三人追偿。"},{"i":1202,"n":"第一千二百零二条","txt":"因产品存在缺陷造成他人损害的，生产者应当承担侵权责任。"},{"i":1203,"n":"第一千二百零三条","txt":"因产品存在缺陷造成他人损害的，被侵权人可以向产品的生产者请求赔偿，也可以向产品的销售者请求赔偿。"},{"i":1204,"n":"第一千二百零四条","txt":"因运输者、仓储者等第三人的过错使产品存在缺陷，造成他人损害的，产品的生产者、销售者赔偿后，有权向第三人追偿。"},{"i":1205,"n":"第一千二百零五条","txt":"因产品缺陷危及他人人身、财产安全的，被侵权人有权请求生产者、销售者承担停止侵害、排除妨碍、消除危险等侵权责任。"},{"i":1206,"n":"第一千二百零六条","txt":"产品投入流通后发现存在缺陷的，生产者、销售者应当及时采取停止销售、警示、召回等补救措施；未及时采取补救措施或者补救措施不力造成损害扩大的，对扩大的损害也应当承担侵权责任。"},{"i":1207,"n":"第一千二百零七条","txt":"明知产品存在缺陷仍然生产、销售，或者没有依据前条规定采取有效补救措施，造成他人死亡或者健康严重损害的，被侵权人有权请求相应的惩罚性赔偿。"},{"i":1208,"n":"第一千二百零八条","txt":"机动车发生交通事故造成损害的，依照道路交通安全法律和本法的有关规定承担赔偿责任。"},{"i":1209,"n":"第一千二百零九条","txt":"因租赁、借用等情形机动车所有人、管理人与使用人不是同一人时，发生交通事故造成损害，属于该机动车一方责任的，由机动车使用人承担赔偿责任；机动车所有人、管理人对损害的发生有过错的，承担相应的赔偿责任。"},{"i":1210,"n":"第一千二百一十条","txt":"当事人之间已经以买卖或者其他方式转让并交付机动车但是未办理登记，发生交通事故造成损害，属于该机动车一方责任的，由受让人承担赔偿责任。"},{"i":1211,"n":"第一千二百一十一条","txt":"以挂靠形式从事道路运输经营活动的机动车，发生交通事故造成损害，属于该机动车一方责任的，由挂靠人和被挂靠人承担连带责任。"},{"i":1212,"n":"第一千二百一十二条","txt":"未经允许驾驶他人机动车，发生交通事故造成损害，属于该机动车一方责任的，由机动车使用人承担赔偿责任；机动车所有人、管理人对损害的发生有过错的，承担相应的赔偿责任，但是本章另有规定的除外。"},{"i":1213,"n":"第一千二百一十三条","txt":"机动车发生交通事故造成损害，属于该机动车一方责任的，先由承保机动车强制保险的保险人在强制保险责任限额范围内予以赔偿；不足部分，由承保机动车商业保险的保险人按照保险合同的约定予以赔偿；仍然不足或者没有投保机动车商业保险的，由侵权人赔偿。"},{"i":1214,"n":"第一千二百一十四条","txt":"以买卖或者其他方式转让拼装或者已经达到报废标准的机动车，发生交通事故造成损害的，由转让人和受让人承担连带责任。"},{"i":1215,"n":"第一千二百一十五条","txt":"盗窃、抢劫或者抢夺的机动车发生交通事故造成损害的，由盗窃人、抢劫人或者抢夺人承担赔偿责任。盗窃人、抢劫人或者抢夺人与机动车使用人不是同一人，发生交通事故造成损害，属于该机动车一方责任的，由盗窃人、抢劫人或者抢夺人与机动车使用人承担连带责任。"},{"i":1216,"n":"第一千二百一十六条","txt":"机动车驾驶人发生交通事故后逃逸，该机动车参加强制保险的，由保险人在机动车强制保险责任限额范围内予以赔偿；机动车不明、该机动车未参加强制保险或者抢救费用超过机动车强制保险责任限额，需要支付被侵权人人身伤亡的抢救、丧葬等费用的，由道路交通事故社会救助基金垫付。道路交通事故社会救助基金垫付后，其管理机构有权向交通事故责任人追偿。"},{"i":1217,"n":"第一千二百一十七条","txt":"非营运机动车发生交通事故造成无偿搭乘人损害，属于该机动车一方责任的，应当减轻其赔偿责任，但是机动车使用人有故意或者重大过失的除外。"},{"i":1218,"n":"第一千二百一十八条","txt":"患者在诊疗活动中受到损害，医疗机构或者其医务人员有过错的，由医疗机构承担赔偿责任。"},{"i":1219,"n":"第一千二百一十九条","txt":"医务人员在诊疗活动中应当向患者说明病情和医疗措施。需要实施手术、特殊检查、特殊治疗的，医务人员应当及时向患者具体说明医疗风险、替代医疗方案等情况，并取得其明确同意；不能或者不宜向患者说明的，应当向患者的近亲属说明，并取得其明确同意。"},{"i":1220,"n":"第一千二百二十条","txt":"因抢救生命垂危的患者等紧急情况，不能取得患者或者其近亲属意见的，经医疗机构负责人或者授权的负责人批准，可以立即实施相应的医疗措施。"},{"i":1221,"n":"第一千二百二十一条","txt":"医务人员在诊疗活动中未尽到与当时的医疗水平相应的诊疗义务，造成患者损害的，医疗机构应当承担赔偿责任。"},{"i":1222,"n":"第一千二百二十二条","txt":"患者在诊疗活动中受到损害，有下列情形之一的，推定医疗机构有过错："},{"i":1223,"n":"第一千二百二十三条","txt":"因药品、消毒产品、医疗器械的缺陷，或者输入不合格的血液造成患者损害的，患者可以向药品上市许可持有人、生产者、血液提供机构请求赔偿，也可以向医疗机构请求赔偿。患者向医疗机构请求赔偿的，医疗机构赔偿后，有权向负有责任的药品上市许可持有人、生产者、血液提供机构追偿。"},{"i":1224,"n":"第一千二百二十四条","txt":"患者在诊疗活动中受到损害，有下列情形之一的，医疗机构不承担赔偿责任："},{"i":1225,"n":"第一千二百二十五条","txt":"医疗机构及其医务人员应当按照规定填写并妥善保管住院志、医嘱单、检验报告、手术及麻醉记录、病理资料、护理记录等病历资料。"},{"i":1226,"n":"第一千二百二十六条","txt":"医疗机构及其医务人员应当对患者的隐私和个人信息保密。泄露患者的隐私和个人信息，或者未经患者同意公开其病历资料的，应当承担侵权责任。"},{"i":1227,"n":"第一千二百二十七条","txt":"医疗机构及其医务人员不得违反诊疗规范实施不必要的检查。"},{"i":1228,"n":"第一千二百二十八条","txt":"医疗机构及其医务人员的合法权益受法律保护。"},{"i":1229,"n":"第一千二百二十九条","txt":"因污染环境、破坏生态造成他人损害的，侵权人应当承担侵权责任。"},{"i":1230,"n":"第一千二百三十条","txt":"因污染环境、破坏生态发生纠纷，行为人应当就法律规定的不承担责任或者减轻责任的情形及其行为与损害之间不存在因果关系承担举证责任。"},{"i":1231,"n":"第一千二百三十一条","txt":"两个以上侵权人污染环境、破坏生态的，承担责任的大小，根据污染物的种类、浓度、排放量，破坏生态的方式、范围、程度，以及行为对损害后果所起的作用等因素确定。"},{"i":1232,"n":"第一千二百三十二条","txt":"侵权人违反法律规定故意污染环境、破坏生态造成严重后果的，被侵权人有权请求相应的惩罚性赔偿。"},{"i":1233,"n":"第一千二百三十三条","txt":"因第三人的过错污染环境、破坏生态的，被侵权人可以向侵权人请求赔偿，也可以向第三人请求赔偿。侵权人赔偿后，有权向第三人追偿。"},{"i":1234,"n":"第一千二百三十四条","txt":"违反国家规定造成生态环境损害，生态环境能够修复的，国家规定的机关或者法律规定的组织有权请求侵权人在合理期限内承担修复责任。侵权人在期限内未修复的，国家规定的机关或者法律规定的组织可以自行或者委托他人进行修复，所需费用由侵权人负担。"},{"i":1235,"n":"第一千二百三十五条","txt":"违反国家规定造成生态环境损害的，国家规定的机关或者法律规定的组织有权请求侵权人赔偿下列损失和费用："},{"i":1236,"n":"第一千二百三十六条","txt":"从事高度危险作业造成他人损害的，应当承担侵权责任。"},{"i":1237,"n":"第一千二百三十七条","txt":"民用核设施或者运入运出核设施的核材料发生核事故造成他人损害的，民用核设施的营运单位应当承担侵权责任；但是，能够证明损害是因战争、武装冲突、暴乱等情形或者受害人故意造成的，不承担责任。"},{"i":1238,"n":"第一千二百三十八条","txt":"民用航空器造成他人损害的，民用航空器的经营者应当承担侵权责任；但是，能够证明损害是因受害人故意造成的，不承担责任。"},{"i":1239,"n":"第一千二百三十九条","txt":"占有或者使用易燃、易爆、剧毒、高放射性、强腐蚀性、高致病性等高度危险物造成他人损害的，占有人或者使用人应当承担侵权责任；但是，能够证明损害是因受害人故意或者不可抗力造成的，不承担责任。被侵权人对损害的发生有重大过失的，可以减轻占有人或者使用人的责任。"},{"i":1240,"n":"第一千二百四十条","txt":"从事高空、高压、地下挖掘活动或者使用高速轨道运输工具造成他人损害的，经营者应当承担侵权责任；但是，能够证明损害是因受害人故意或者不可抗力造成的，不承担责任。被侵权人对损害的发生有重大过失的，可以减轻经营者的责任。"},{"i":1241,"n":"第一千二百四十一条","txt":"遗失、抛弃高度危险物造成他人损害的，由所有人承担侵权责任。所有人将高度危险物交由他人管理的，由管理人承担侵权责任；所有人有过错的，与管理人承担连带责任。"},{"i":1242,"n":"第一千二百四十二条","txt":"非法占有高度危险物造成他人损害的，由非法占有人承担侵权责任。所有人、管理人不能证明对防止非法占有尽到高度注意义务的，与非法占有人承担连带责任。"},{"i":1243,"n":"第一千二百四十三条","txt":"未经许可进入高度危险活动区域或者高度危险物存放区域受到损害，管理人能够证明已经采取足够安全措施并尽到充分警示义务的，可以减轻或者不承担责任。"},{"i":1244,"n":"第一千二百四十四条","txt":"承担高度危险责任，法律规定赔偿限额的，依照其规定，但是行为人有故意或者重大过失的除外。"},{"i":1245,"n":"第一千二百四十五条","txt":"饲养的动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任；但是，能够证明损害是因被侵权人故意或者重大过失造成的，可以不承担或者减轻责任。"},{"i":1246,"n":"第一千二百四十六条","txt":"违反管理规定，未对动物采取安全措施造成他人损害的，动物饲养人或者管理人应当承担侵权责任；但是，能够证明损害是因被侵权人故意造成的，可以减轻责任。"},{"i":1247,"n":"第一千二百四十七条","txt":"禁止饲养的烈性犬等危险动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任。"},{"i":1248,"n":"第一千二百四十八条","txt":"动物园的动物造成他人损害的，动物园应当承担侵权责任；但是，能够证明尽到管理职责的，不承担侵权责任。"},{"i":1249,"n":"第一千二百四十九条","txt":"遗弃、逃逸的动物在遗弃、逃逸期间造成他人损害的，由动物原饲养人或者管理人承担侵权责任。"},{"i":1250,"n":"第一千二百五十条","txt":"因第三人的过错致使动物造成他人损害的，被侵权人可以向动物饲养人或者管理人请求赔偿，也可以向第三人请求赔偿。动物饲养人或者管理人赔偿后，有权向第三人追偿。"},{"i":1251,"n":"第一千二百五十一条","txt":"饲养动物应当遵守法律法规，尊重社会公德，不得妨碍他人生活。"},{"i":1252,"n":"第一千二百五十二条","txt":"建筑物、构筑物或者其他设施倒塌、塌陷造成他人损害的，由建设单位与施工单位承担连带责任，但是建设单位与施工单位能够证明不存在质量缺陷的除外。建设单位、施工单位赔偿后，有其他责任人的，有权向其他责任人追偿。"},{"i":1253,"n":"第一千二百五十三条","txt":"建筑物、构筑物或者其他设施及其搁置物、悬挂物发生脱落、坠落造成他人损害，所有人、管理人或者使用人不能证明自己没有过错的，应当承担侵权责任。所有人、管理人或者使用人赔偿后，有其他责任人的，有权向其他责任人追偿。"},{"i":1254,"n":"第一千二百五十四条","txt":"禁止从建筑物中抛掷物品。从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害的，由侵权人依法承担侵权责任；经调查难以确定具体侵权人的，除能够证明自己不是侵权人的外，由可能加害的建筑物使用人给予补偿。可能加害的建筑物使用人补偿后，有权向侵权人追偿。"},{"i":1255,"n":"第一千二百五十五条","txt":"堆放物倒塌、滚落或者滑落造成他人损害，堆放人不能证明自己没有过错的，应当承担侵权责任。"},{"i":1256,"n":"第一千二百五十六条","txt":"在公共道路上堆放、倾倒、遗撒妨碍通行的物品造成他人损害的，由行为人承担侵权责任。公共道路管理人不能证明已经尽到清理、防护、警示等义务的，应当承担相应的责任。"},{"i":1257,"n":"第一千二百五十七条","txt":"因林木折断、倾倒或者果实坠落等造成他人损害，林木的所有人或者管理人不能证明自己没有过错的，应当承担侵权责任。"},{"i":1258,"n":"第一千二百五十八条","txt":"在公共场所或者道路上挖掘、修缮安装地下设施等造成他人损害，施工人不能证明已经设置明显标志和采取安全措施的，应当承担侵权责任。"},{"i":1259,"n":"第一千二百五十九条","txt":"民法所称的“以上”、“以下”、“以内”、“届满”，包括本数；所称的“不满”、“超过”、“以外”，不包括本数。"},{"i":1260,"n":"第一千二百六十条","txt":"本法自2021年1月1日起施行。《中华人民共和国婚姻法》、《中华人民共和国继承法》、《中华人民共和国民法通则》、《中华人民共和国收养法》、《中华人民共和国担保法》、《中华人民共和国合同法》、《中华人民共和国物权法》、《中华人民共和国侵权责任法》、《中华人民共和国民法总则》同时废止。"}],"haishangfa":[{"i":1,"n":"第一条","txt":"为了调整海上运输关系、船舶关系，保护当事人各方的合法权益，加强海洋生态环境保护，促进海上运输和经济贸易高质量发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称海上运输，是指海上货物运输和海上旅客运输，包括海江之间、江海之间的直达运输。"},{"i":3,"n":"第三条","txt":"本法所称船舶，是指海船和其他海上移动式装置，但是用于军事的、政府公务的船舶和20总吨以下的小型船艇除外。船舶包括船舶属具。"},{"i":4,"n":"第四条","txt":"船舶经依法登记取得中华人民共和国国籍，有权悬挂中华人民共和国国旗航行。"},{"i":5,"n":"第五条","txt":"中华人民共和国港口之间的海上运输和拖航，由依法取得中华人民共和国国籍的船舶经营。但是，法律、行政法规另有规定的除外。"},{"i":6,"n":"第六条","txt":"国务院交通运输主管部门、有关地方人民政府及其交通运输主管部门依法对海上运输活动实施监督管理。"},{"i":7,"n":"第七条","txt":"船舶所有权，是指船舶所有人依法对其船舶享有占有、使用、收益和处分的权利。"},{"i":8,"n":"第八条","txt":"船舶所有权的设立、变更、转让和消灭，应当向船舶登记机关登记；未经登记，不得对抗善意第三人。"},{"i":9,"n":"第九条","txt":"船舶由两个以上的法人、非法人组织或者自然人共有的，应当向船舶登记机关登记；未经登记，不得对抗善意第三人。"},{"i":10,"n":"第十条","txt":"建造中的船舶的所有权，当事人对其归属有约定的，按照约定；没有约定或者约定不明确的，归造船人所有。"},{"i":11,"n":"第十一条","txt":"船舶抵押权，是指抵押权人对于抵押人提供的作为债务担保的船舶，在债务人不履行到期债务或者发生当事人约定的实现抵押权情形时，依法享有的就该船舶优先受偿的权利。"},{"i":12,"n":"第十二条","txt":"船舶所有人或者船舶所有人授权的人可以设立船舶抵押权。"},{"i":13,"n":"第十三条","txt":"船舶抵押权的设立、变更、转让和消灭，应当向船舶登记机关登记；未经登记，不得对抗善意第三人。"},{"i":14,"n":"第十四条","txt":"建造中的船舶可以设立船舶抵押权。"},{"i":15,"n":"第十五条","txt":"除合同另有约定外，抵押人应当对抵押船舶进行保险；未保险的，抵押权人有权对该船舶进行保险，保险费由抵押人负担。"},{"i":16,"n":"第十六条","txt":"除船舶共有人另有约定外，以共有船舶设立抵押权的，按照下列情形处理："},{"i":17,"n":"第十七条","txt":"船舶抵押权设立后，抵押人可以转让抵押船舶。当事人另有约定的，按照其约定。抵押船舶转让的，船舶抵押权不受影响。"},{"i":18,"n":"第十八条","txt":"船舶抵押担保的债权转让的，抵押权一并转让，但是法律另有规定或者当事人另有约定的除外。"},{"i":19,"n":"第十九条","txt":"同一船舶设立两个以上船舶抵押权的，其清偿顺序按照以下情形确定："},{"i":20,"n":"第二十条","txt":"抵押船舶毁损、灭失或者被征收的，抵押权人可以就获得的保险金、赔偿金、补偿金等优先受偿。"},{"i":21,"n":"第二十一条","txt":"船舶优先权，是指海事请求人依照本法规定，向船舶所有人、光船承租人、船舶管理人或者船舶经营人提出海事请求，对产生该海事请求的船舶具有优先受偿的权利。"},{"i":22,"n":"第二十二条","txt":"下列各项海事请求具有船舶优先权："},{"i":23,"n":"第二十三条","txt":"本法第二十二条第一款所列各项海事请求，按照顺序受偿。但是，第四项海事请求，后于第一项至第三项发生的，应当先于第一项至第三项受偿。"},{"i":24,"n":"第二十四条","txt":"因行使船舶优先权产生的诉讼费用，保存、拍卖或者变卖船舶和分配船舶价款产生的费用，以及为海事请求人的共同利益而支付的其他费用，应当从船舶拍卖或者变卖所得价款中先行拨付。"},{"i":25,"n":"第二十五条","txt":"船舶优先权不因船舶所有权的转让而消灭。但是，船舶转让时，船舶优先权自法院应受让人申请予以公告之日起满六十日不行使的除外。"},{"i":26,"n":"第二十六条","txt":"本法第二十二条规定的具有船舶优先权的海事请求发生转让或者代位的，该项船舶优先权随之转移。"},{"i":27,"n":"第二十七条","txt":"船舶优先权应当通过法院扣押产生优先权的船舶行使。"},{"i":28,"n":"第二十八条","txt":"除本法第二十五条规定的情形外，船舶优先权因下列原因之一而消灭："},{"i":29,"n":"第二十九条","txt":"本节规定不影响本法第十一章关于海事赔偿责任限制规定的实施。"},{"i":30,"n":"第三十条","txt":"船舶留置权，是指造船人、修船人在合同另一方未按照约定支付船舶建造或者修理费用时，留置已经合法占有的船舶，并就该船舶优先受偿的权利。"},{"i":31,"n":"第三十一条","txt":"除另有约定外，造船人、修船人留置船舶满六十日后，债务人仍不履行债务的，可以与债务人协议以留置船舶折价，也可以就拍卖、变卖留置船舶所得的价款优先受偿。"},{"i":32,"n":"第三十二条","txt":"在留置期间，船舶被法院扣押并拍卖、变卖的，不影响船舶留置权人优先受偿的权利。"},{"i":33,"n":"第三十三条","txt":"船员，是指包括船长在内的船上一切任职人员。"},{"i":34,"n":"第三十四条","txt":"中国籍船员应当依照有关船员管理的法律、行政法规的规定取得相应的船员适任证书和健康证明。"},{"i":35,"n":"第三十五条","txt":"从事国际航行船舶的中国籍船员，应当依法持有中华人民共和国海事管理机构颁发的海员证和有关证书。"},{"i":36,"n":"第三十六条","txt":"船员用人单位应当依照有关法律、行政法规和中华人民共和国缔结或者参加的有关船员劳动与社会保障国际条约的规定，与船员订立劳动合同。"},{"i":37,"n":"第三十七条","txt":"船长负责管理和指挥船舶。"},{"i":38,"n":"第三十八条","txt":"为保障在船人员和船舶的安全，船长有权对在船上涉嫌进行违法犯罪活动的人员采取禁闭或者其他必要措施，并防止其隐匿、毁灭、伪造证据。"},{"i":39,"n":"第三十九条","txt":"船长应当将船上发生的出生或者死亡事件记入航海日志，并在两名证人的参加下制作证明书。死亡证明书应当附有死者遗物清单。死者有遗嘱的，船长应当予以证明。死亡证明书和遗嘱由船长负责保管，并送交家属或者有关方面。"},{"i":40,"n":"第四十条","txt":"船舶发生海上事故，危及在船人员和财产安全时，船长应当组织船员和其他在船人员尽力施救。在船舶沉没、毁灭不可避免的情况下，船长有权作出弃船决定。"},{"i":41,"n":"第四十一条","txt":"船长管理船舶和指挥船舶的责任，不因引航员引领船舶而解除。"},{"i":42,"n":"第四十二条","txt":"船长在航行中死亡或者因故不能执行职务时，应当由驾驶员中职务最高的人代理船长职务；在下一个港口开航前，船舶所有人、船舶经营人或者船舶管理人应当指派新船长接任。"},{"i":43,"n":"第四十三条","txt":"海上货物运输合同，是指承运人收取运费，负责将托运人托运的货物经海路由一港运至另一港的合同，包括国际海上货物运输合同和中华人民共和国港口之间的国内海上货物运输合同。"},{"i":44,"n":"第四十四条","txt":"本章下列用语的含义："},{"i":45,"n":"第四十五条","txt":"违反本章规定的海上货物运输合同和作为合同证明的提单或者其他运输单证中的条款，以及将货物的保险利益转让给承运人的条款或者类似条款无效。此类条款的无效，不影响该合同和提单或者其他运输单证中其他条款的效力。"},{"i":46,"n":"第四十六条","txt":"本法第四十五条的规定不影响承运人在本章规定的承运人责任和义务之外，增加其责任和义务。"},{"i":47,"n":"第四十七条","txt":"承运人对集装箱装运的货物的责任期间，是指从装货港接收货物时起至卸货港交付货物时止，货物处于承运人掌管之下的全部期间。承运人对非集装箱装运的货物的责任期间，是指从货物装上船时起至卸下船时止，货物处于承运人掌管之下的全部期间。在承运人的责任期间，货物发生灭失或者损坏，除本节另有规定外，承运人应当承担赔偿责任。"},{"i":48,"n":"第四十八条","txt":"承运人在船舶开航前和开航当时，应当谨慎处理，使船舶处于适航状态，妥善配备船员、装备船舶和配备供应品，并使货舱、船舶其他载货处所以及承运人提供的载货集装箱适于并能安全收受、载运和保管货物。"},{"i":49,"n":"第四十九条","txt":"承运人应当妥善、谨慎地接收、装载、搬移、积载、运输、保管、照料、卸载和交付所运货物。"},{"i":50,"n":"第五十条","txt":"承运人应当按照约定的或者习惯的或者地理上的航线，将货物运往卸货港。"},{"i":51,"n":"第五十一条","txt":"货物未能在明确约定的期限内，在约定的卸货港交付的，构成迟延交付；国内海上货物运输中，货物未能在合理期限内交付的，也构成迟延交付。"},{"i":52,"n":"第五十二条","txt":"在责任期间货物发生的灭失、损坏，或者迟延交付是由于下列原因之一造成的，承运人不承担赔偿责任："},{"i":53,"n":"第五十三条","txt":"因运输活动物固有的特殊风险造成活动物灭失、损害或者迟延交付的，承运人不承担赔偿责任。但是，承运人应当证明其已经履行托运人关于运输活动物的特别要求，并证明根据实际情况，灭失、损害或者迟延交付是由于运输活动物固有的特殊风险造成的。"},{"i":54,"n":"第五十四条","txt":"承运人在舱面上载运货物，应当与托运人达成协议，或者符合航运惯例，或者符合有关法律、行政法规的规定。"},{"i":55,"n":"第五十五条","txt":"货物的灭失、损坏或者迟延交付是由于承运人或者承运人的受雇人、代理人不能免除赔偿责任的原因和其他原因共同造成的，承运人仅在其不能免除赔偿责任的范围内承担赔偿责任；但是，承运人对其他原因造成的灭失、损坏或者迟延交付应当承担举证责任。"},{"i":56,"n":"第五十六条","txt":"货物灭失的赔偿额，按照货物的实际价值计算；货物损坏的赔偿额，按照货物受损前后实际价值的差额或者货物的修复费用计算。"},{"i":57,"n":"第五十七条","txt":"承运人对货物灭失或者损坏的赔偿限额，按照货物件数或者其他货运单位数计算，每件或者每个其他货运单位为666.67计算单位，或者按照货物毛重计算，每千克为2计算单位，以其中赔偿限额较高的为准。但是，托运人在货物装运前已经申报其性质和价值并在提单中载明，或者承运人与托运人已经另行约定高于本条规定的赔偿限额的除外。"},{"i":58,"n":"第五十八条","txt":"承运人对于货物因迟延交付造成经济损失的赔偿限额，为所迟延交付的货物的运费数额。货物的灭失、损坏和迟延交付同时发生的，承运人的赔偿责任限额适用本法第五十七条第一款规定的限额。"},{"i":59,"n":"第五十九条","txt":"就海上货物运输合同所涉及的货物灭失、损坏或者迟延交付通过诉讼、仲裁等方式对承运人提起的任何赔偿请求，无论海事请求人是否为合同的一方，也无论是根据合同或者侵权行为提出请求，均适用本章关于承运人的抗辩理由和限制赔偿责任的规定。"},{"i":60,"n":"第六十条","txt":"经证明，货物的灭失、损坏或者迟延交付是由于承运人的故意或者明知可能造成损失而轻率地作为或者不作为造成的，承运人不得援用本法第五十七条或者第五十八条限制赔偿责任的规定。"},{"i":61,"n":"第六十一条","txt":"承运人将货物运输或者部分运输委托给实际承运人履行的，承运人仍然应当依照本章规定对全部运输负责。对实际承运人承担的运输，承运人应当对实际承运人的行为或者实际承运人的受雇人、代理人在受雇或者受委托的范围内的行为负责。"},{"i":62,"n":"第六十二条","txt":"本章关于承运人责任的规定，适用于实际承运人。对实际承运人的受雇人、代理人提起赔偿请求的，适用本法第五十九条第二款和第六十条第二款的规定。"},{"i":63,"n":"第六十三条","txt":"承运人承担本章未规定的义务或者放弃本章赋予的权利的任何特别协议，经实际承运人书面明确同意的，对实际承运人发生效力；实际承运人是否同意，不影响此项特别协议对承运人的效力。"},{"i":64,"n":"第六十四条","txt":"承运人与实际承运人均负有赔偿责任的，应当在此项责任范围内承担连带责任。"},{"i":65,"n":"第六十五条","txt":"就货物的灭失、损坏或者迟延交付分别向承运人、实际承运人以及他们的受雇人、代理人提出赔偿请求的，赔偿总额不得超过本法第五十七条或者第五十八条规定的限额。"},{"i":66,"n":"第六十六条","txt":"本法第六十一条至第六十五条的规定，不影响承运人和实际承运人之间相互追偿。"},{"i":67,"n":"第六十七条","txt":"托运人应当按照海上货物运输合同的约定将货物交付承运人运输，并保证交付运输的货物适于约定的运输。"},{"i":68,"n":"第六十八条","txt":"托运人托运货物，应当妥善包装，并向承运人保证货物装船时所提供货物的品名、标志、包数或者件数、重量或者体积的正确性；由于包装不当或者上述资料不正确，对承运人造成损失的，托运人应当承担赔偿责任。"},{"i":69,"n":"第六十九条","txt":"托运人应当及时向港口、海关和其他主管机关办理货物运输所需要的各项手续，并将已办理各项手续的单证送交承运人；因办理各项手续不及时、不完备或者不正确，使承运人的利益受到损害的，托运人应当承担赔偿责任。"},{"i":70,"n":"第七十条","txt":"托运人托运危险货物，应当按照有关海上危险货物运输的规定妥善包装，作出危险品标志和标签，并将货物正式名称和性质以及应当采取的预防危害措施、应急处置措施书面通知承运人；托运人未通知或者通知有误的，承运人可以在任何时间、任何地点根据情况需要将货物卸下、销毁或者消除危险性，而不承担赔偿责任。托运人对承运人因运输此类货物所受到的损害，应当承担赔偿责任。"},{"i":71,"n":"第七十一条","txt":"托运人应当按照约定向承运人支付运费。"},{"i":72,"n":"第七十二条","txt":"托运人对承运人、实际承运人所遭受的损失或者船舶所遭受的损坏，不承担赔偿责任；但是，此种损失或者损坏是由于托运人或者托运人的受雇人、代理人的过错造成的除外。"},{"i":73,"n":"第七十三条","txt":"货物由承运人接收或者装船后，应托运人的要求，承运人应当签发提单。提单可以由承运人授权的人签发；由载货船舶的船长签发的，视为代表承运人签发。"},{"i":74,"n":"第七十四条","txt":"提单内容包括下列各项："},{"i":75,"n":"第七十五条","txt":"货物装船前，承运人已经应托运人的要求签发收货待运提单或者其他单证的，货物装船完毕，托运人可以将收货待运提单或者其他单证退还承运人，换取已装船提单；承运人也可以在收货待运提单上加注承运船舶的船名和装船日期，加注后的收货待运提单视为已装船提单。"},{"i":76,"n":"第七十六条","txt":"承运人或者代其签发提单的人知道或者有合理的根据怀疑提单记载的货物的品名、标志、包数或者件数、重量或者体积与实际接收的货物不符，在签发已装船提单的情况下怀疑与已装船的货物不符，或者没有适当的方法核对提单记载的，可以在提单上批注，说明不符之处、怀疑的根据或者说明无法核对。"},{"i":77,"n":"第七十七条","txt":"承运人或者代其签发提单的人未在提单上批注货物表面状况的，视为货物的表面状况良好。"},{"i":78,"n":"第七十八条","txt":"除依据本法第七十六条的规定作出批注外，承运人或者代其签发提单的人签发的提单，是承运人已经按照提单所载状况收到货物或者货物已经装船的初步证据；承运人向包括收货人在内的善意第三人提出的货物状况与提单记载不同的证据，不予承认。"},{"i":79,"n":"第七十九条","txt":"承运人与收货人、提单持有人之间的权利义务关系，按照提单确定。未签发提单的，承运人与收货人之间的权利义务关系适用本章有关规定。"},{"i":80,"n":"第八十条","txt":"记名提单不得转让。"},{"i":81,"n":"第八十一条","txt":"承运人签发提单以外的单证用以证明收到待运货物的，此项单证即为订立海上货物运输合同和承运人接收该单证中所列货物的初步证据。"},{"i":82,"n":"第八十二条","txt":"电子运输记录，是指承运人根据海上货物运输合同，以电子通信方式发出，证明海上货物运输合同和货物已经由承运人接收或者装船的信息，包括可转让电子运输记录和不可转让电子运输记录。"},{"i":83,"n":"第八十三条","txt":"承运人和托运人协商一致，可以签发、使用电子运输记录。"},{"i":84,"n":"第八十四条","txt":"电子运输记录应当符合下列要求："},{"i":85,"n":"第八十五条","txt":"可转让电子运输记录除符合本法第八十四条规定外，还应当包括可转让性信息和转让程序。"},{"i":86,"n":"第八十六条","txt":"经承运人和托运人、运输单证持有人协商一致，电子运输记录与运输单证之间可以互相转换。"},{"i":87,"n":"第八十七条","txt":"承运人交付货物，按照下列规定执行："},{"i":88,"n":"第八十八条","txt":"承运人向收货人交付货物时，收货人应当将货物灭失或者损坏的情况书面通知承运人；未通知的，此项交付视为承运人已经按照运输单证的记载交付以及货物状况良好的初步证据。"},{"i":89,"n":"第八十九条","txt":"承运人自向收货人交付货物的次日起连续六十日内，未收到收货人就货物因迟延交付造成经济损失而提交的书面通知的，不承担赔偿责任。"},{"i":90,"n":"第九十条","txt":"收货人在目的港提取货物前或者承运人在目的港交付货物前，可以要求检验机构对货物状况进行检验；要求检验的一方应当支付检验费用，但是有权向造成货物损失的责任方追偿。"},{"i":91,"n":"第九十一条","txt":"承运人和收货人对本法第八十八条和第九十条规定的检验，应当相互提供合理的便利条件。"},{"i":92,"n":"第九十二条","txt":"货物由实际承运人交付的，收货人依据本法第八十八条的规定向实际承运人提交的书面通知，与向承运人提交书面通知具有同等效力；向承运人提交的书面通知，与向实际承运人提交书面通知具有同等效力。"},{"i":93,"n":"第九十三条","txt":"在卸货港无人提取货物的，船长可以将货物卸在仓库或者其他适当场所，由此产生的费用和风险由托运人承担，但是应当及时通知托运人。"},{"i":94,"n":"第九十四条","txt":"应当向承运人支付的运费、共同海损分摊、滞期费和承运人为货物垫付的必要费用以及应当向承运人支付的其他费用没有付清，又没有提供适当担保的，承运人可以留置相应的货物。"},{"i":95,"n":"第九十五条","txt":"承运人依据本法第九十四条规定留置的货物，自船舶抵达卸货港的次日起满六十日无人提取的，承运人可以申请法院拍卖；货物易腐烂变质或者货物的保管费用加上应当向承运人支付的费用可能超过货物价值的，承运人可以申请提前拍卖。"},{"i":96,"n":"第九十六条","txt":"在承运人责任期间内，托运人可以书面通知承运人中止运输、返还货物、变更卸货港或者将货物交给其他收货人，但是应当赔偿承运人因此遭受的损失。"},{"i":97,"n":"第九十七条","txt":"船舶在装货港开航前，托运人可以要求解除合同。但是，除合同另有约定外，托运人应当向承运人支付约定运费的一半；货物已经装船的，并应当负担装货、卸货和其他与此有关的费用。"},{"i":98,"n":"第九十八条","txt":"船舶在装货港开航前，因不可抗力或者其他不能归责于承运人和托运人的原因致使合同不能履行的，双方均可以解除合同，并互相不承担赔偿责任。除合同另有约定外，运费已经支付的，承运人应当将运费退还给托运人；货物已经装船的，托运人应当承担装卸费用；已经签发运输单证的，托运人应当将运输单证退还承运人。"},{"i":99,"n":"第九十九条","txt":"因不可抗力或者其他不能归责于承运人和托运人的原因致使船舶不能在合同约定的目的港卸货的，除合同另有约定外，船长有权将货物在目的港邻近的安全港口或者地点卸载，视为已经履行合同。"},{"i":100,"n":"第一百条","txt":"本法所称多式联运合同，是指多式联运经营人以包括海上运输方式在内的两种以上的不同运输方式，负责将货物从接收地运至目的地交付收货人，并收取全程运费的合同。"},{"i":101,"n":"第一百零一条","txt":"多式联运经营人对多式联运货物的责任期间，自接收货物时起至交付货物时止。"},{"i":102,"n":"第一百零二条","txt":"多式联运经营人负责履行或者组织履行多式联运合同，并对全程运输负责。"},{"i":103,"n":"第一百零三条","txt":"货物的灭失、损坏或者迟延交付发生于多式联运的某一运输区段的，多式联运经营人的赔偿责任、责任限额和时效，依照调整该区段运输方式的有关法律确定。"},{"i":104,"n":"第一百零四条","txt":"货物的灭失、损坏或者迟延交付发生的运输区段不能确定的，多式联运经营人应当依照本章关于承运人赔偿责任、责任限额和本法关于时效的规定承担赔偿责任。"},{"i":105,"n":"第一百零五条","txt":"海上旅客运输合同，是指承运人以客轮、邮轮等适合的船舶经海路运输旅客及其行李，由旅客支付票款的合同。"},{"i":106,"n":"第一百零六条","txt":"本章下列用语的含义："},{"i":107,"n":"第一百零七条","txt":"旅客客票是海上旅客运输合同成立的凭证。"},{"i":108,"n":"第一百零八条","txt":"海上旅客运输合同中含有下列内容之一的条款无效："},{"i":109,"n":"第一百零九条","txt":"海上旅客运输的运输期间，自旅客登船时起至旅客离船时止。客票票价含接送费用的，运输期间包括承运人经水路将旅客从岸上接到船上和从船上送到岸上的时间，但是不包括旅客在港站内、码头上或者在港口其他设施内的时间。"},{"i":110,"n":"第一百一十条","txt":"旅客无票乘船、越级乘船、超程乘船或者持不符合减价条件的优惠客票乘船的，应当按照规定补足票款，承运人可以按照规定加收票款；拒不支付票款的，船长有权在适当地点令其离船，承运人有权要求其支付。"},{"i":111,"n":"第一百一十一条","txt":"旅客不得随身携带或者在行李中夹带违禁品或者易燃、易爆、有毒、有腐蚀性、有放射性以及其他有可能危及船上人身和财产安全的危险品。"},{"i":112,"n":"第一百一十二条","txt":"在本法第一百零九条规定的旅客及其行李的运输期间，因承运人或者承运人的受雇人、代理人在受雇或者受委托的范围内的过错引起事故，造成旅客人身伤亡或者行李灭失、损坏的，承运人应当承担赔偿责任。"},{"i":113,"n":"第一百一十三条","txt":"经承运人证明，旅客的人身伤亡或者行李的灭失、损坏是因旅客本人的过失或者旅客和承运人的共同过失造成的，可以免除或者相应减轻承运人的赔偿责任。"},{"i":114,"n":"第一百一十四条","txt":"承运人对旅客的货币、金银、珠宝、有价证券或者其他贵重物品所发生的灭失、损坏，不承担赔偿责任。"},{"i":115,"n":"第一百一十五条","txt":"承运人在每次海上旅客运输中的赔偿责任限额，按照下列规定执行："},{"i":116,"n":"第一百一十六条","txt":"经证明，旅客的人身伤亡或者行李的灭失、损坏是因承运人的故意或者明知可能造成损害而轻率地作为或者不作为造成的，承运人不得援用本法第一百一十四条和第一百一十五条限制赔偿责任的规定。"},{"i":117,"n":"第一百一十七条","txt":"行李发生明显损坏的，旅客应当按照下列规定向承运人或者承运人的受雇人、代理人提交书面通知："},{"i":118,"n":"第一百一十八条","txt":"就旅客人身伤亡或者行李灭失、损坏通过诉讼、仲裁等方式对承运人提起的任何赔偿请求，无论请求人是否为合同的一方，也无论是根据合同或者侵权行为提出请求，均适用本章关于承运人的抗辩理由和限制赔偿责任的规定。"},{"i":119,"n":"第一百一十九条","txt":"承运人将旅客及其行李全部运输或者部分运输委托给实际承运人履行的，仍然应当依照本章规定，对全部运输负责。实际承运人履行运输的，承运人应当对实际承运人的行为或者实际承运人的受雇人、代理人在受雇或者受委托的范围内的行为负责。"},{"i":120,"n":"第一百二十条","txt":"本章关于承运人责任的规定，适用于实际承运人。本章关于承运人的受雇人、代理人责任的规定，适用于实际承运人的受雇人、代理人。"},{"i":121,"n":"第一百二十一条","txt":"承运人承担本章未规定的义务或者放弃本章赋予的权利的任何特别协议，经实际承运人书面明确同意的，对实际承运人发生效力；实际承运人是否同意，不影响此项特别协议对承运人的效力。"},{"i":122,"n":"第一百二十二条","txt":"承运人与实际承运人均负有赔偿责任的，应当在此项责任范围内承担连带责任。"},{"i":123,"n":"第一百二十三条","txt":"就旅客的人身伤亡或者行李的灭失、损坏，分别向承运人、实际承运人以及他们的受雇人、代理人提出赔偿请求的，赔偿总额不得超过本法第一百一十五条规定的限额。"},{"i":124,"n":"第一百二十四条","txt":"本法第一百一十九条至第一百二十三条的规定，不影响承运人和实际承运人之间相互追偿。"},{"i":125,"n":"第一百二十五条","txt":"承运人或者实际承运人应当对旅客人身伤亡赔偿责任进行责任保险或者取得相应的财务保证。"},{"i":126,"n":"第一百二十六条","txt":"旅客人身伤亡损害赔偿请求可以直接向责任保险人或者财务保证人提出。承运人或者实际承运人丧失本章规定的限制赔偿责任权利的，不影响其责任保险人或者财务保证人援用本章规定限制赔偿责任。"},{"i":127,"n":"第一百二十七条","txt":"本法规定的租船合同，包括航次租船合同、定期租船合同和光船租赁合同。租船合同应当采用书面形式订立。"},{"i":128,"n":"第一百二十八条","txt":"本章关于出租人和承租人之间权利义务的规定，仅在租船合同没有约定或者没有不同约定时适用。"},{"i":129,"n":"第一百二十九条","txt":"航次租船合同，是指船舶出租人向承租人提供船舶或者船舶的部分舱位，装运约定的货物，从一港运至另一港，由承租人支付约定运费的合同。"},{"i":130,"n":"第一百三十条","txt":"航次租船合同的内容，主要包括出租人和承租人的名称、船名、船籍、载货重量、容积、货名、装货港和目的港、受载期限、装卸期限、运费、滞期费、速遣费以及其他有关事项。"},{"i":131,"n":"第一百三十一条","txt":"对于按照航次租船合同运输的货物签发的提单，提单持有人不是承租人的，承运人与该提单持有人之间的权利义务关系适用提单的约定。但是，提单中载明适用航次租船合同条款的，适用该航次租船合同的条款。"},{"i":132,"n":"第一百三十二条","txt":"出租人应当提供约定的船舶；经承租人同意，可以更换船舶。出租人提供或者更换的船舶不符合合同约定的，承租人有权拒绝或者解除合同。"},{"i":133,"n":"第一百三十三条","txt":"出租人在约定的受载期限内未能提供船舶的，承租人有权解除合同。但是，出租人将船舶延误情况和船舶预期抵达装货港的日期通知承租人的，承租人应当自收到通知时起四十八小时内，将是否解除合同的决定通知出租人。"},{"i":134,"n":"第一百三十四条","txt":"航次租船合同的装货、卸货期限及其计算办法，超过装货、卸货期限后的滞期费和提前完成装货、卸货的速遣费，由双方约定。"},{"i":135,"n":"第一百三十五条","txt":"承租人可以将其租用的船舶转租；转租后，原合同约定的权利和义务不受影响。"},{"i":136,"n":"第一百三十六条","txt":"承租人应当提供约定的货物；经出租人同意，可以更换货物。但是，更换的货物对出租人不利的，出租人有权拒绝或者解除合同。"},{"i":137,"n":"第一百三十七条","txt":"出租人应当在合同约定的卸货港卸货。合同订有承租人选择卸货港条款的，在承租人未按照合同约定及时通知确定的卸货港时，船长可以从约定的选卸港中自行选定一港卸货。承租人未按照合同约定及时通知确定的卸货港，致使出租人遭受损失的，应当承担赔偿责任。出租人未按照合同约定，擅自选定港口卸货致使承租人遭受损失的，应当承担赔偿责任。"},{"i":138,"n":"第一百三十八条","txt":"定期租船合同，是指船舶出租人向承租人提供约定的由出租人配备船员的船舶，由承租人在约定的期间内按照约定的用途使用，并支付租金的合同。"},{"i":139,"n":"第一百三十九条","txt":"定期租船合同的内容，主要包括出租人和承租人的名称、船名、船籍、船级、吨位、容积、船速、燃料消耗、航区、用途、租船期间、交船和还船的时间和地点以及条件、租金及其支付，以及其他有关事项。"},{"i":140,"n":"第一百四十条","txt":"出租人应当按照合同约定的时间交付船舶。"},{"i":141,"n":"第一百四十一条","txt":"出租人交付船舶时，应当做到谨慎处理，使船舶处于适航状态。交付的船舶应当适于约定的用途。"},{"i":142,"n":"第一百四十二条","txt":"船舶在租期内不符合约定的适航状态或者其他状态，出租人应当采取可能采取的合理措施，使船舶状态尽快恢复。"},{"i":143,"n":"第一百四十三条","txt":"承租人应当保证船舶在约定航区内的安全港口或者地点之间从事约定的海上运输。"},{"i":144,"n":"第一百四十四条","txt":"承租人应当保证船舶用于运输约定的合法货物。"},{"i":145,"n":"第一百四十五条","txt":"承租人有权就船舶的营运向船长发出指示，但是不得违反定期租船合同的约定。"},{"i":146,"n":"第一百四十六条","txt":"承租人可以将租用的船舶转租，但是应当将转租的情况及时通知出租人。租用的船舶转租后，原租船合同约定的权利和义务不受影响。"},{"i":147,"n":"第一百四十七条","txt":"船舶所有人转让已经租出的船舶的所有权，定期租船合同约定的当事人的权利和义务不受影响，但是应当及时通知承租人。船舶所有权转让后，原租船合同由受让人和承租人继续履行。"},{"i":148,"n":"第一百四十八条","txt":"在合同期间，船舶进行海难救助的，承租人有权获得扣除救助费用、损失赔偿、船员应得部分以及其他费用后的救助款项的百分之五十。"},{"i":149,"n":"第一百四十九条","txt":"承租人应当按照合同约定支付租金；未按照合同约定支付租金的，出租人有权解除合同，并有权要求赔偿因此遭受的损失。"},{"i":150,"n":"第一百五十条","txt":"承租人未向出租人支付租金或者合同约定的其他款项的，出租人对船上属于承租人的货物和财产以及转租船舶的收入享有留置权。"},{"i":151,"n":"第一百五十一条","txt":"承租人向出租人交还船舶时，该船舶应当具有与出租人交船时相同的良好状态，但是船舶本身的自然磨损除外。"},{"i":152,"n":"第一百五十二条","txt":"经合理计算，完成最后航次的日期约为合同约定的还船日期，但是可能超过合同约定的还船日期的，承租人有权超期用船以完成该航次。超期期间，承租人应当按照合同约定的租金率支付租金；市场租金率高于合同约定的租金率的，承租人应当按照市场租金率支付租金。"},{"i":153,"n":"第一百五十三条","txt":"光船租赁合同，是指船舶出租人向承租人提供不配备船员的船舶，在约定的期间内由承租人占有、使用和营运，并向出租人支付租金的合同。"},{"i":154,"n":"第一百五十四条","txt":"光船租赁合同的内容，主要包括出租人和承租人的名称、船名、船籍、船级、吨位、容积、航区、用途、租船期间、交船和还船的时间和地点以及条件、船舶检验、船舶的保养维修、租金及其支付、船舶保险、合同解除的时间和条件，以及其他有关事项。"},{"i":155,"n":"第一百五十五条","txt":"出租人应当在合同约定的港口或者地点，按照合同约定的时间，向承租人交付船舶以及船舶证书。交付船舶时，出租人应当做到谨慎处理，使船舶处于适航状态。交付的船舶应当适于合同约定的用途。"},{"i":156,"n":"第一百五十六条","txt":"在光船租赁期间，承租人负责船舶的保养、维修。"},{"i":157,"n":"第一百五十七条","txt":"在光船租赁期间，承租人应当按照合同约定的船舶价值，以出租人同意的保险方式为船舶进行保险，并负担保险费用。"},{"i":158,"n":"第一百五十八条","txt":"在光船租赁期间，因承租人对船舶占有、使用和营运的原因使出租人的利益受到影响或者遭受损失的，承租人应当负责消除影响或者赔偿损失。"},{"i":159,"n":"第一百五十九条","txt":"在光船租赁期间，未经出租人书面同意，承租人不得转让合同的权利和义务或者以光船租赁的方式将船舶进行转租。"},{"i":160,"n":"第一百六十条","txt":"未经承租人事先书面同意，出租人不得在光船租赁期间对船舶设立抵押权。"},{"i":161,"n":"第一百六十一条","txt":"承租人应当按照合同约定支付租金。承租人未按照合同约定的时间支付租金连续超过七日的，出租人有权解除合同，并有权要求赔偿因此遭受的损失。"},{"i":162,"n":"第一百六十二条","txt":"本法第一百四十三条、第一百四十四条第一款、第一百五十一条和第一百五十二条的规定，适用于光船租赁合同。"},{"i":163,"n":"第一百六十三条","txt":"订有租购条款的光船租赁合同，承租人按照合同约定向出租人付清租购费时，船舶所有权即归于承租人。"},{"i":164,"n":"第一百六十四条","txt":"海上拖航合同，是指承拖方用拖轮将被拖物经海路从一地拖至另一地，而由被拖方支付拖航费的合同。"},{"i":165,"n":"第一百六十五条","txt":"海上拖航合同应当采用书面形式订立。海上拖航合同的内容，主要包括承拖方和被拖方的名称和住所、拖轮和被拖物的名称和主要尺度、拖轮马力、起拖地和目的地、起拖日期、拖航费及其支付方式，以及其他有关事项。"},{"i":166,"n":"第一百六十六条","txt":"承拖方在起拖前和起拖当时，应当谨慎处理，使拖轮处于适航、适拖状态，妥善配备船员，配置拖航索具和配备供应品以及该航次必备的其他装置、设备。"},{"i":167,"n":"第一百六十七条","txt":"起拖前，因不可抗力或者其他不能归责于双方的原因致使合同不能履行的，双方均可以解除合同，并互相不承担赔偿责任。除合同另有约定外，拖航费已经支付的，承拖方应当退还给被拖方。"},{"i":168,"n":"第一百六十八条","txt":"起拖后，因不可抗力或者其他不能归责于双方的原因致使合同不能继续履行的，双方均可以解除合同，并互相不承担赔偿责任。除合同另有约定外，拖航费按照实际完成的拖航部分确定。"},{"i":169,"n":"第一百六十九条","txt":"因不可抗力或者其他不能归责于双方的原因致使被拖物不能拖至目的地的，除合同另有约定外，承拖方可以在目的地的邻近地点或者拖轮船长选定的安全的港口或者锚泊地，将被拖物移交给被拖方或者其代理人，视为已经履行合同。"},{"i":170,"n":"第一百七十条","txt":"被拖方未按照约定支付拖航费和其他合理费用的，承拖方对被拖物享有留置权。"},{"i":171,"n":"第一百七十一条","txt":"在海上拖航过程中，承拖方或者被拖方遭受的损失，由一方的过错造成的，有过错的一方应当承担赔偿责任；由双方过错造成的，各方按照过错程度的比例承担赔偿责任。"},{"i":172,"n":"第一百七十二条","txt":"在海上拖航过程中，由于承拖方或者被拖方的过错，造成第三人人身伤亡或者财产损失的，承拖方和被拖方对第三人承担连带赔偿责任。除合同另有约定外，一方支付的赔偿超过其应当承担的比例的，对另一方有追偿权。"},{"i":173,"n":"第一百七十三条","txt":"拖轮所有人拖带其所有的或者经营的驳船载运货物，经海路由一港运至另一港的，视为海上货物运输。"},{"i":174,"n":"第一百七十四条","txt":"船舶碰撞，是指船舶在海上或者与海相通的可航水域发生接触造成损害的事故。"},{"i":175,"n":"第一百七十五条","txt":"船舶发生碰撞，当事船舶的船长在不严重危及本船和船上人员安全的情况下，对于相碰的船舶和船上人员应当尽力施救。"},{"i":176,"n":"第一百七十六条","txt":"船舶发生碰撞，是由于不可抗力或者其他不能归责于任何一方的原因或者无法查明的原因造成的，碰撞各方互相不承担赔偿责任。"},{"i":177,"n":"第一百七十七条","txt":"船舶发生碰撞，是由于一船的过错造成的，由有过错的船舶承担赔偿责任。"},{"i":178,"n":"第一百七十八条","txt":"船舶发生碰撞，碰撞的船舶互有过错的，各船按照过错程度的比例承担赔偿责任；过错程度相当或者过错程度的比例无法判定的，平均承担赔偿责任。"},{"i":179,"n":"第一百七十九条","txt":"船舶因操纵不当或者不遵守航行规章，虽然实际上没有与其他船舶发生碰撞，但是使其他船舶以及船上的人员、货物或者其他财产遭受损失的，适用本章的规定。"},{"i":180,"n":"第一百八十条","txt":"本章规定适用于对海上或者与海相通的可航水域内遇险的船舶或者其他财产进行的救助。"},{"i":181,"n":"第一百八十一条","txt":"本章下列用语的含义："},{"i":182,"n":"第一百八十二条","txt":"本章规定不适用于海上已经就位的从事海底矿物资源的勘探、开发或者生产的固定式、浮动式平台和移动式近海钻井装置。"},{"i":183,"n":"第一百八十三条","txt":"船长在不严重危及本船和船上人员安全的情况下，有义务尽力救助海上人命。"},{"i":184,"n":"第一百八十四条","txt":"救助方与被救助方就海难救助达成协议，救助合同成立。"},{"i":185,"n":"第一百八十五条","txt":"有下列情形之一，一方当事人起诉或者双方当事人协议仲裁的，受理争议的法院或者仲裁机构可以撤销、变更救助合同："},{"i":186,"n":"第一百八十六条","txt":"在救助作业过程中，救助方对被救助方负有下列义务："},{"i":187,"n":"第一百八十七条","txt":"在救助作业过程中，被救助方对救助方负有下列义务："},{"i":188,"n":"第一百八十八条","txt":"救助方对遇险的船舶和其他财产的救助，取得效果的，有权获得救助报酬；未取得效果的，除本法第一百九十一条或者其他法律另有规定外，无权获得救助款项。"},{"i":189,"n":"第一百八十九条","txt":"确定救助报酬，应当体现对救助作业的鼓励，并综合考虑下列各项因素："},{"i":190,"n":"第一百九十条","txt":"船舶和其他财产的获救价值，是指船舶和其他财产获救后的估计价值或者实际出卖的收入，扣除有关税款和海关、检疫、检验费用以及进行卸载、保管、估价、出卖而产生的费用后的价值。"},{"i":191,"n":"第一百九十一条","txt":"对构成生态环境损害危险的船舶或者船上货物进行的救助，救助方依据本法第一百八十九条规定获得的救助报酬，少于依据本条规定可以得到的特别补偿的，救助方有权从船舶所有人处获得相当于救助费用的特别补偿。"},{"i":192,"n":"第一百九十二条","txt":"救助报酬的金额，应当由获救的船舶和其他财产的各所有人，按照船舶和其他各项财产各自的获救价值占全部获救价值的比例承担。"},{"i":193,"n":"第一百九十三条","txt":"参加同一救助作业的各救助方的救助报酬，依据本法第一百八十九条的规定标准，由各方协商确定；协商不成的，可以向法院起诉或者经各方协议申请仲裁。"},{"i":194,"n":"第一百九十四条","txt":"在救助作业中救助人命的救助方，对获救人员不得请求酬金，但是有权从救助船舶或者其他财产、防止或者减少生态环境损害的救助方获得的救助款项中，获得合理的份额。"},{"i":195,"n":"第一百九十五条","txt":"下列救助行为无权获得救助款项："},{"i":196,"n":"第一百九十六条","txt":"因救助方的过失致使救助作业成为必需或者更加困难的，或者救助方有欺诈或者其他不诚实行为的，应当取消或者减少向救助方支付的救助款项。"},{"i":197,"n":"第一百九十七条","txt":"被救助方在救助作业结束后，应当根据救助方的要求，对救助款项提供满意的担保。"},{"i":198,"n":"第一百九十八条","txt":"受理救助款项请求的法院或者仲裁机构根据具体情况，在合理的条件下，可以裁定或者裁决被救助方向救助方先行支付适当的金额。"},{"i":199,"n":"第一百九十九条","txt":"对于获救满九十日的船舶和其他财产，被救助方不支付救助款项也不提供满意的担保的，救助方可以申请法院裁定强制拍卖；对于无法保管、不易保管或者保管费用可能超过其价值的获救的船舶和其他财产，可以申请提前拍卖。"},{"i":200,"n":"第二百条","txt":"同一船舶所有人的船舶之间进行的救助，救助方获得救助款项的权利适用本章规定。"},{"i":201,"n":"第二百零一条","txt":"国家有关主管机关从事或者控制的救助作业，救助方有权享受本章规定的关于救助作业的权利和补偿。"},{"i":202,"n":"第二百零二条","txt":"共同海损，是指在同一海上航程中，船舶、货物和其他财产遭遇共同危险，为了共同安全，有意合理地采取措施所直接造成的特殊牺牲、支付的特殊费用。"},{"i":203,"n":"第二百零三条","txt":"船舶因发生意外、牺牲或者其他特殊情况而损坏时，为了安全完成本航程，驶入避难港口、避难地点或者驶回装货港口、装货地点进行必要的修理，在该港口或者地点额外停留期间所支付的港口费，船员工资、给养，船舶所消耗的燃料、物料，为修理而卸载、储存、重装或者搬移船上货物、燃料、物料以及其他财产所造成的损失、支付的费用，应当列入共同海损。"},{"i":204,"n":"第二百零四条","txt":"为代替可以列为共同海损的特殊费用而支付的额外费用，可以作为代替费用列入共同海损；但是，列入共同海损的代替费用的金额，不得超过被代替的共同海损的特殊费用。"},{"i":205,"n":"第二百零五条","txt":"提出共同海损分摊请求的一方应当承担举证责任，证明其损失应当列入共同海损。"},{"i":206,"n":"第二百零六条","txt":"引起共同海损特殊牺牲、特殊费用的事故，可能是由航程中一方的过错造成的，不影响该方要求分摊共同海损的权利；但是，非过错方或者过错方可以就此项过错提出赔偿请求或者进行抗辩。"},{"i":207,"n":"第二百零七条","txt":"船舶、货物和运费的共同海损牺牲的金额，按照下列规定确定："},{"i":208,"n":"第二百零八条","txt":"共同海损应当由受益方按照各自的分摊价值的比例分摊。"},{"i":209,"n":"第二百零九条","txt":"未申报的货物或者谎报的货物，应当参加共同海损分摊；其遭受的特殊牺牲，不得列入共同海损。"},{"i":210,"n":"第二百一十条","txt":"对共同海损特殊牺牲和垫付的共同海损特殊费用，应当计算利息。"},{"i":211,"n":"第二百一十一条","txt":"经利害关系人要求，各分摊方应当提供共同海损担保。"},{"i":212,"n":"第二百一十二条","txt":"共同海损理算，适用合同约定的理算规则；合同未约定的，适用本章的规定。"},{"i":213,"n":"第二百一十三条","txt":"船舶所有人、海难救助方，对本法第二百一十六条规定的海事赔偿请求，可以依照本章规定限制赔偿责任。"},{"i":214,"n":"第二百一十四条","txt":"本法第二百一十六条规定的海事赔偿请求向船舶所有人、海难救助方之外的人员提出，船舶所有人、海难救助方对该人员的行为、过错负有责任的，该人员可以依照本章规定限制赔偿责任。"},{"i":215,"n":"第二百一十五条","txt":"被保险人依照本章规定可以限制赔偿责任的，对该海事赔偿请求承担责任的保险人，有权依照本章规定享受相同的赔偿责任限制。"},{"i":216,"n":"第二百一十六条","txt":"下列海事赔偿请求，除本法第二百一十七条和第二百一十八条另有规定外，无论赔偿责任的基础有何不同，责任人均可以依照本章规定限制赔偿责任："},{"i":217,"n":"第二百一十七条","txt":"本章规定不适用于下列各项："},{"i":218,"n":"第二百一十八条","txt":"经证明，引起赔偿请求的损失是因责任人的故意或者明知可能造成损失而轻率地作为或者不作为造成的，该责任人无权依照本章规定限制赔偿责任。"},{"i":219,"n":"第二百一十九条","txt":"除本法第二百二十条另有规定外，海事赔偿责任限制，依照下列规定计算赔偿责任限额："},{"i":220,"n":"第二百二十条","txt":"海上旅客运输的旅客人身伤亡赔偿责任限制，按照175000计算单位乘以船舶证书规定的载客定额计算赔偿责任限额。"},{"i":221,"n":"第二百二十一条","txt":"本法第二百一十九条和第二百二十条规定的赔偿责任限额，适用于同一特定事故引起的，向船舶所有人、海难救助方本人和他们对其行为、过错负有责任的人员提出的请求的总额。"},{"i":222,"n":"第二百二十二条","txt":"责任人要求依照本法规定限制赔偿责任的，可以在有管辖权的法院设立责任限制基金。基金数额分别为本法第二百一十九条、第二百二十条规定的限额，加上自事故发生之日起至基金设立之日止的相应利息。"},{"i":223,"n":"第二百二十三条","txt":"责任人设立责任限制基金后，有权依据本法第二百一十六条规定提出请求的任何人，不得对责任人的任何财产行使任何权利；已设立责任限制基金的责任人的船舶或者其他财产已经被采取保全措施，或者基金设立人已经提交担保的，法院应当及时解除保全措施或者退还担保。"},{"i":224,"n":"第二百二十四条","txt":"享受本章规定的责任限制的人，就同一事故向请求人提出反请求的，双方的请求金额应当相互抵销，本章规定的赔偿责任限额仅适用于两个请求金额之间的差额。"},{"i":225,"n":"第二百二十五条","txt":"在中华人民共和国管辖海域和与海相通的可航水域的船舶油污损害赔偿，适用本章规定。"},{"i":226,"n":"第二百二十六条","txt":"漏油船舶的船舶所有人承担船舶油污损害赔偿责任。"},{"i":227,"n":"第二百二十七条","txt":"船舶所有人可以依照本章规定限制赔偿责任。但是，船舶油污损害是因船舶所有人故意或者明知可能造成损害而轻率地作为或者不作为造成的，船舶所有人不得依照本章规定限制其赔偿责任。"},{"i":228,"n":"第二百二十八条","txt":"两艘及以上船舶造成油污损害的，各船舶所有人应当对无法合理分开的损害承担连带责任。"},{"i":229,"n":"第二百二十九条","txt":"国家建立船舶油污损害责任保险制度。船舶所有人应当按照国家有关规定投保船舶油污损害民事责任保险或者取得相应的财务保证。"},{"i":230,"n":"第二百三十条","txt":"本章规定不影响船舶所有人向第三人追偿的权利。"},{"i":231,"n":"第二百三十一条","txt":"船舶载运散装油类造成的油污损害责任适用本节规定。"},{"i":232,"n":"第二百三十二条","txt":"下列人员对船舶油类污染损害不承担赔偿责任，但是损害是因其本人故意或者明知可能造成损害而轻率地作为或者不作为造成的除外："},{"i":233,"n":"第二百三十三条","txt":"船舶载运油类造成油污损害的，船舶所有人对每一次事故按照下列规定计算赔偿责任限额："},{"i":234,"n":"第二百三十四条","txt":"船舶所有人或者其责任保险人、财务保证人援用本节赔偿责任限制的规定的，应当在有管辖权的法院设立责任限制基金。"},{"i":235,"n":"第二百三十五条","txt":"责任限制基金已经设立且船舶所有人有权限制其赔偿责任的，油污损害赔偿请求人不得申请法院对船舶所有人的财产行使保全措施；已经采取的财产保全措施应当解除，船舶所有人为避免或者解除保全措施已经提供的保证金或者其他担保应当退还。"},{"i":236,"n":"第二百三十六条","txt":"油污损害赔偿请求人应当按照损害赔偿额的比例分配责任限制基金。"},{"i":237,"n":"第二百三十七条","txt":"本章第二节规定的船舶装载的非持久性燃油以及除第二节规定的船舶之外的其他船舶装载的燃油造成的油污损害责任适用本节规定。"},{"i":238,"n":"第二百三十八条","txt":"下列人员对本节规定的燃油污染损害不承担赔偿责任，但是损害是因其本人故意或者明知可能造成损害而轻率地作为或者不作为造成的除外："},{"i":239,"n":"第二百三十九条","txt":"本节规定的燃油污染损害赔偿责任限额适用本法第十一章的规定。"},{"i":240,"n":"第二百四十条","txt":"海上保险合同，是指保险人按照约定，对被保险人遭受海上保险事故造成保险标的的损失和产生的责任负责赔偿，而由被保险人支付保险费的合同。"},{"i":241,"n":"第二百四十一条","txt":"海上保险合同的内容，主要包括下列各项："},{"i":242,"n":"第二百四十二条","txt":"下列各项可以作为保险标的："},{"i":243,"n":"第二百四十三条","txt":"保险标的的保险价值由保险人与被保险人书面约定；保险标的发生损失时，以约定的保险价值为赔偿计算标准。"},{"i":244,"n":"第二百四十四条","txt":"保险金额由保险人与被保险人约定。保险金额不得超过保险价值；超过保险价值的，超过部分无效。"},{"i":245,"n":"第二百四十五条","txt":"建造中的船舶保险合同适用本章有关规定。"},{"i":246,"n":"第二百四十六条","txt":"被保险人提出保险要求，经保险人同意承保，并就海上保险合同的条款达成协议后，合同成立。保险人应当及时向被保险人签发保险单或者其他保险单证，并在保险单或者其他保险单证中载明当事人双方约定的合同内容。"},{"i":247,"n":"第二百四十七条","txt":"合同订立前，被保险人应当将其知道的或者在通常业务中应当知道的有关影响保险人据以确定保险费率或者确定是否同意承保的重要情况，如实告知保险人。"},{"i":248,"n":"第二百四十八条","txt":"因被保险人的故意，未将本法第二百四十七条第一款规定的重要情况如实告知保险人的，保险人有权解除合同，并不退还保险费。合同解除前发生海上保险事故造成损失的，保险人不承担赔偿责任。"},{"i":249,"n":"第二百四十九条","txt":"海上保险合同采用保险人提供的格式条款的，对于保险合同中免除或者减轻保险人责任等与被保险人有重大利害关系的条款，保险人在订立合同时应当作出足以引起被保险人注意的提示。被保险人要求说明的，保险人对该条款应当予以明确说明。"},{"i":250,"n":"第二百五十条","txt":"订立合同时，被保险人已经知道或者应当知道保险标的已经因发生海上保险事故而遭受损失的，保险人不承担赔偿责任，但是有权收取保险费；保险人已经知道或者应当知道保险标的已经不可能因发生海上保险事故而遭受损失的，被保险人有权收回已经支付的保险费。"},{"i":251,"n":"第二百五十一条","txt":"被保险人对同一保险标的、同一保险利益就同一海上保险事故向两个以上保险人重复订立合同，致使该保险标的的保险金额总和超过保险价值的，除合同另有约定外，被保险人可以向任何保险人提出赔偿请求，但是被保险人获得的赔偿金额总和不得超过保险标的的受损价值。"},{"i":252,"n":"第二百五十二条","txt":"保险责任开始前，被保险人可以要求解除合同，但是应当向保险人支付手续费，保险人应当退还保险费。"},{"i":253,"n":"第二百五十三条","txt":"除法律另有规定或者合同另有约定外，保险责任开始后，被保险人和保险人均不得解除合同。"},{"i":254,"n":"第二百五十四条","txt":"海上货物运输和船舶的航次保险，保险责任开始后，被保险人不得要求解除合同。"},{"i":255,"n":"第二百五十五条","txt":"海上货物运输保险合同可以由被保险人背书或者以其他方式转让，合同的权利义务随之转移。合同转让时尚未支付保险费的，被保险人和合同受让人承担连带支付责任。"},{"i":256,"n":"第二百五十六条","txt":"因船舶转让而转让船舶保险合同的，应当取得保险人同意。未经保险人同意，船舶保险合同从船舶转让时起解除；船舶转让发生在航次之中的，船舶保险合同至航次终了时解除。"},{"i":257,"n":"第二百五十七条","txt":"预约保险合同是指保险人按照约定对于被保险人将来一定期间内分批运输的货物承担保险责任，而由被保险人支付保险费的合同。"},{"i":258,"n":"第二百五十八条","txt":"应被保险人要求，保险人应当对按照预约保险合同分批运输的货物分别签发保险单证。"},{"i":259,"n":"第二百五十九条","txt":"预约保险合同下分批运输货物的名称、数量，装运货物的船名、航线，保险价值和保险金额等具体事项，被保险人应当在每一次运输前向保险人如实申报。"},{"i":260,"n":"第二百六十条","txt":"除合同另有约定外，被保险人应当在合同订立后立即支付保险费；被保险人支付保险费前，保险人可以拒绝签发保险单证。"},{"i":261,"n":"第二百六十一条","txt":"被保险人违反合同约定的保证条款的，保险人有权解除合同或者要求修改承保条件、增加保险费。保险人解除合同的，应当书面通知被保险人，合同自通知到达被保险人时解除。"},{"i":262,"n":"第二百六十二条","txt":"发生海上保险事故，被保险人应当立即通知保险人，并采取必要的合理措施，防止或者减少损失。被保险人收到保险人发出的有关采取防止或者减少损失的合理措施的特别通知的，应当按照保险人通知的要求处理。"},{"i":263,"n":"第二百六十三条","txt":"发生海上保险事故造成损失后，保险人应当及时向被保险人支付保险赔偿。"},{"i":264,"n":"第二百六十四条","txt":"保险人赔偿海上保险事故造成的损失，以保险金额为限。保险金额低于保险价值的，在保险标的发生部分损失时，保险人按照保险金额与保险价值的比例承担赔偿责任。"},{"i":265,"n":"第二百六十五条","txt":"保险标的在保险期间发生几次海上保险事故所造成的损失，即使损失金额的总和超过保险金额，保险人也应当赔偿。但是，对发生部分损失后未经修复又发生全部损失的，保险人按照全部损失赔偿。"},{"i":266,"n":"第二百六十六条","txt":"被保险人为防止或者减少根据合同可以得到赔偿的损失而支出的必要的合理费用，为确定海上保险事故的性质、程度而支出的检验、估价等合理费用，以及为执行保险人的特别通知而支出的费用，应当由保险人在保险标的损失赔偿之外另行支付。"},{"i":267,"n":"第二百六十七条","txt":"保险金额低于共同海损分摊价值的，保险人按照保险金额同分摊价值的比例赔偿共同海损分摊。"},{"i":268,"n":"第二百六十八条","txt":"对于被保险人故意造成的损失，保险人不承担赔偿责任。"},{"i":269,"n":"第二百六十九条","txt":"除合同另有约定外，因下列原因之一造成货物损失的，保险人不承担赔偿责任："},{"i":270,"n":"第二百七十条","txt":"除合同另有约定外，因下列原因之一造成保险船舶损失的，保险人不承担赔偿责任："},{"i":271,"n":"第二百七十一条","txt":"保险标的发生海上保险事故后灭失，或者受到严重损坏完全失去原有形体、效用，或者不能再归被保险人所拥有的，为实际全损。"},{"i":272,"n":"第二百七十二条","txt":"船舶发生海上保险事故后，认为实际全损已经不可避免，或者为避免发生实际全损所需支付的费用超过保险价值的，为推定全损。"},{"i":273,"n":"第二百七十三条","txt":"不属于实际全损和推定全损的损失，为部分损失。"},{"i":274,"n":"第二百七十四条","txt":"船舶在合理时间内未从被获知最后消息的地点抵达目的地，除合同另有约定外，满六十日后仍没有获知其消息的，为船舶失踪。船舶失踪视为实际全损。"},{"i":275,"n":"第二百七十五条","txt":"保险标的发生推定全损，被保险人要求保险人按照全部损失赔偿的，应当在合理的时间内向保险人委付保险标的。保险人可以接受委付，也可以不接受委付，但是应当在合理的时间内将接受委付或者不接受委付的决定通知被保险人。保险人未在合理的时间内通知被保险人是否接受委付的，视为不接受委付。"},{"i":276,"n":"第二百七十六条","txt":"保险人接受委付的，被保险人对委付财产的全部权利和义务转移给保险人。"},{"i":277,"n":"第二百七十七条","txt":"海上保险事故发生后，保险人向被保险人支付保险赔偿前，可以要求被保险人提供与确认海上保险事故性质和损失程度有关的证明和资料。"},{"i":278,"n":"第二百七十八条","txt":"保险标的发生保险责任范围内的损失是由第三人造成的，被保险人向第三人要求赔偿的权利，自保险人支付赔偿之日起，相应转移给保险人。"},{"i":279,"n":"第二百七十九条","txt":"被保险人未经保险人同意放弃向第三人要求赔偿的权利，或者因过错致使保险人不能行使追偿权利的，保险人可以相应扣减保险赔偿。"},{"i":280,"n":"第二百八十条","txt":"保险人支付保险赔偿时，可以从应支付的赔偿额中相应扣减被保险人已经从第三人取得的赔偿。"},{"i":281,"n":"第二百八十一条","txt":"发生海上保险事故后，保险人有权放弃对保险标的的权利，全额支付合同约定的保险赔偿，以解除对保险标的的义务。"},{"i":282,"n":"第二百八十二条","txt":"除本法第二百八十一条规定外，保险标的发生全损，保险人支付全部保险金额的，取得对保险标的的全部权利；但是，在不足额保险的情况下，保险人按照保险金额与保险价值的比例取得对保险标的的部分权利。"},{"i":283,"n":"第二百八十三条","txt":"发生海事纠纷的，当事人可以依法提起诉讼或者申请仲裁。"},{"i":284,"n":"第二百八十四条","txt":"海上货物运输请求赔偿的请求权，时效期间为一年。其中，请求承运人、实际承运人赔偿的，时效自货物交付或者应当交付之日起计算；请求托运人、收货人或者运输单证持有人赔偿的，时效自权利人知道或者应当知道权利被侵害之日起计算。"},{"i":285,"n":"第二百八十五条","txt":"海上旅客运输请求赔偿的请求权，时效期间为二年，分别按照下列规定计算："},{"i":286,"n":"第二百八十六条","txt":"有关租船合同的请求权，时效期间为二年，自知道或者应当知道权利被侵害之日起计算。"},{"i":287,"n":"第二百八十七条","txt":"有关海上拖航合同的请求权，时效期间为一年，自知道或者应当知道权利被侵害之日起计算。"},{"i":288,"n":"第二百八十八条","txt":"有关船舶碰撞的请求权，时效期间为二年，自碰撞事故发生之日起计算。"},{"i":289,"n":"第二百八十九条","txt":"有关海难救助的请求权，时效期间为二年，自救助作业终止之日起计算。"},{"i":290,"n":"第二百九十条","txt":"有关共同海损分摊的请求权，时效期间为一年，自共同海损理算结束之日起计算，但是不得超过从共同航程终止之日起六年。"},{"i":291,"n":"第二百九十一条","txt":"根据海上保险合同向保险人请求保险赔偿的请求权，时效期间为二年，自知道或者应当知道海上保险事故发生之日起计算。"},{"i":292,"n":"第二百九十二条","txt":"有关船舶油污损害的请求权，时效期间为三年，自损害发生之日起计算，但是不得超过从造成损害的事故发生之日起六年。"},{"i":293,"n":"第二百九十三条","txt":"在时效期间的最后六个月内，因不可抗力或者其他障碍不能行使请求权的，时效中止。自中止时效的原因消除之日起满六个月，时效期间届满。"},{"i":294,"n":"第二百九十四条","txt":"时效因请求人提出履行请求、提起诉讼、申请仲裁或者被请求人同意履行义务而中断。"},{"i":295,"n":"第二百九十五条","txt":"合同当事人可以选择合同适用的法律，但是法律另有规定的除外。合同当事人没有选择的，适用与合同有最密切联系的国家的法律。"},{"i":296,"n":"第二百九十六条","txt":"船舶所有权，适用船旗国法律。"},{"i":297,"n":"第二百九十七条","txt":"船舶抵押权，适用船旗国法律。"},{"i":298,"n":"第二百九十八条","txt":"船舶优先权，适用法院地法律。"},{"i":299,"n":"第二百九十九条","txt":"船舶留置权，适用船舶被留置地法律。"},{"i":300,"n":"第三百条","txt":"船舶优先权、船舶留置权和船舶抵押权相互之间的受偿顺序，适用法院地法律。"},{"i":301,"n":"第三百零一条","txt":"船舶碰撞责任，适用侵权行为地法律。船舶碰撞发生在公海的，适用法院地法律。同一国籍船舶发生碰撞的，碰撞船舶之间的责任，适用船旗国法律。"},{"i":302,"n":"第三百零二条","txt":"共同海损理算，适用理算地法律。"},{"i":303,"n":"第三百零三条","txt":"海事赔偿责任限制，适用法院地法律。"},{"i":304,"n":"第三百零四条","txt":"船舶油污损害责任，适用油污损害结果发生地法律。"},{"i":305,"n":"第三百零五条","txt":"依照本章规定适用外国法律，不得损害中华人民共和国的公共利益。"},{"i":306,"n":"第三百零六条","txt":"本法所称计算单位，是指国际货币基金组织规定的特别提款权；其人民币数额为法院判决之日、仲裁机构裁决之日或者当事人协议之日，按照国际货币基金组织发布的特别提款权对人民币的汇率计算得出的人民币数额。"},{"i":307,"n":"第三百零七条","txt":"中华人民共和国缔结或者参加的国际条约与本法有不同规定的，适用国际条约的规定；但是，中华人民共和国声明保留的条款除外。"},{"i":308,"n":"第三百零八条","txt":"国家支持开展国际海运事务合作，推动海运业健康发展。"},{"i":309,"n":"第三百零九条","txt":"船舶所有人、船舶经营人、船舶管理人或者船舶承租人等作为会员自愿组成互保组织，按照章程收取会费，对会员在船舶营运中发生的损失、产生的责任或者支付的费用承担赔偿责任。"},{"i":310,"n":"第三百一十条","txt":"本法自2026年5月1日起施行。"}],"xiaofeizhequanyibaohufa":[{"i":1,"n":"第一条","txt":"为保护消费者的合法权益，维护社会经济秩序，促进社会主义市场经济健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"消费者为生活消费需要购买、使用商品或者接受服务，其权益受本法保护；本法未作规定的，受其他有关法律、法规保护。"},{"i":3,"n":"第三条","txt":"经营者为消费者提供其生产、销售的商品或者提供服务，应当遵守本法；本法未作规定的，应当遵守其他有关法律、法规。"},{"i":4,"n":"第四条","txt":"经营者与消费者进行交易，应当遵循自愿、平等、公平、诚实信用的原则。"},{"i":5,"n":"第五条","txt":"国家保护消费者的合法权益不受侵害。"},{"i":6,"n":"第六条","txt":"保护消费者的合法权益是全社会的共同责任。"},{"i":7,"n":"第七条","txt":"消费者在购买、使用商品和接受服务时享有人身、财产安全不受损害的权利。"},{"i":8,"n":"第八条","txt":"消费者享有知悉其购买、使用的商品或者接受的服务的真实情况的权利。"},{"i":9,"n":"第九条","txt":"消费者享有自主选择商品或者服务的权利。"},{"i":10,"n":"第十条","txt":"消费者享有公平交易的权利。"},{"i":11,"n":"第十一条","txt":"消费者因购买、使用商品或者接受服务受到人身、财产损害的，享有依法获得赔偿的权利。"},{"i":12,"n":"第十二条","txt":"消费者享有依法成立维护自身合法权益的社会组织的权利。"},{"i":13,"n":"第十三条","txt":"消费者享有获得有关消费和消费者权益保护方面的知识的权利。"},{"i":14,"n":"第十四条","txt":"消费者在购买、使用商品和接受服务时，享有人格尊严、民族风俗习惯得到尊重的权利，享有个人信息依法得到保护的权利。"},{"i":15,"n":"第十五条","txt":"消费者享有对商品和服务以及保护消费者权益工作进行监督的权利。"},{"i":16,"n":"第十六条","txt":"经营者向消费者提供商品或者服务，应当依照本法和其他有关法律、法规的规定履行义务。"},{"i":17,"n":"第十七条","txt":"经营者应当听取消费者对其提供的商品或者服务的意见，接受消费者的监督。"},{"i":18,"n":"第十八条","txt":"经营者应当保证其提供的商品或者服务符合保障人身、财产安全的要求。对可能危及人身、财产安全的商品和服务，应当向消费者作出真实的说明和明确的警示，并说明和标明正确使用商品或者接受服务的方法以及防止危害发生的方法。"},{"i":19,"n":"第十九条","txt":"经营者发现其提供的商品或者服务存在缺陷，有危及人身、财产安全危险的，应当立即向有关行政部门报告和告知消费者，并采取停止销售、警示、召回、无害化处理、销毁、停止生产或者服务等措施。采取召回措施的，经营者应当承担消费者因商品被召回支出的必要费用。"},{"i":20,"n":"第二十条","txt":"经营者向消费者提供有关商品或者服务的质量、性能、用途、有效期限等信息，应当真实、全面，不得作虚假或者引人误解的宣传。"},{"i":21,"n":"第二十一条","txt":"经营者应当标明其真实名称和标记。"},{"i":22,"n":"第二十二条","txt":"经营者提供商品或者服务，应当按照国家有关规定或者商业惯例向消费者出具发票等购货凭证或者服务单据；消费者索要发票等购货凭证或者服务单据的，经营者必须出具。"},{"i":23,"n":"第二十三条","txt":"经营者应当保证在正常使用商品或者接受服务的情况下其提供的商品或者服务应当具有的质量、性能、用途和有效期限；但消费者在购买该商品或者接受该服务前已经知道其存在瑕疵，且存在该瑕疵不违反法律强制性规定的除外。"},{"i":24,"n":"第二十四条","txt":"经营者提供的商品或者服务不符合质量要求的，消费者可以依照国家规定、当事人约定退货，或者要求经营者履行更换、修理等义务。没有国家规定和当事人约定的，消费者可以自收到商品之日起七日内退货；七日后符合法定解除合同条件的，消费者可以及时退货，不符合法定解除合同条件的，可以要求经营者履行更换、修理等义务。"},{"i":25,"n":"第二十五条","txt":"经营者采用网络、电视、电话、邮购等方式销售商品，消费者有权自收到商品之日起七日内退货，且无需说明理由，但下列商品除外："},{"i":26,"n":"第二十六条","txt":"经营者在经营活动中使用格式条款的，应当以显著方式提请消费者注意商品或者服务的数量和质量、价款或者费用、履行期限和方式、安全注意事项和风险警示、售后服务、民事责任等与消费者有重大利害关系的内容，并按照消费者的要求予以说明。"},{"i":27,"n":"第二十七条","txt":"经营者不得对消费者进行侮辱、诽谤，不得搜查消费者的身体及其携带的物品，不得侵犯消费者的人身自由。"},{"i":28,"n":"第二十八条","txt":"采用网络、电视、电话、邮购等方式提供商品或者服务的经营者，以及提供证券、保险、银行等金融服务的经营者，应当向消费者提供经营地址、联系方式、商品或者服务的数量和质量、价款或者费用、履行期限和方式、安全注意事项和风险警示、售后服务、民事责任等信息。"},{"i":29,"n":"第二十九条","txt":"经营者收集、使用消费者个人信息，应当遵循合法、正当、必要的原则，明示收集、使用信息的目的、方式和范围，并经消费者同意。经营者收集、使用消费者个人信息，应当公开其收集、使用规则，不得违反法律、法规的规定和双方的约定收集、使用信息。"},{"i":30,"n":"第三十条","txt":"国家制定有关消费者权益的法律、法规、规章和强制性标准，应当听取消费者和消费者协会等组织的意见。"},{"i":31,"n":"第三十一条","txt":"各级人民政府应当加强领导，组织、协调、督促有关行政部门做好保护消费者合法权益的工作，落实保护消费者合法权益的职责。"},{"i":32,"n":"第三十二条","txt":"各级人民政府工商行政管理部门和其他有关行政部门应当依照法律、法规的规定，在各自的职责范围内，采取措施，保护消费者的合法权益。"},{"i":33,"n":"第三十三条","txt":"有关行政部门在各自的职责范围内，应当定期或者不定期对经营者提供的商品和服务进行抽查检验，并及时向社会公布抽查检验结果。"},{"i":34,"n":"第三十四条","txt":"有关国家机关应当依照法律、法规的规定，惩处经营者在提供商品和服务中侵害消费者合法权益的违法犯罪行为。"},{"i":35,"n":"第三十五条","txt":"人民法院应当采取措施，方便消费者提起诉讼。对符合《中华人民共和国民事诉讼法》起诉条件的消费者权益争议，必须受理，及时审理。"},{"i":36,"n":"第三十六条","txt":"消费者协会和其他消费者组织是依法成立的对商品和服务进行社会监督的保护消费者合法权益的社会组织。"},{"i":37,"n":"第三十七条","txt":"消费者协会履行下列公益性职责："},{"i":38,"n":"第三十八条","txt":"消费者组织不得从事商品经营和营利性服务，不得以收取费用或者其他牟取利益的方式向消费者推荐商品和服务。"},{"i":39,"n":"第三十九条","txt":"消费者和经营者发生消费者权益争议的，可以通过下列途径解决："},{"i":40,"n":"第四十条","txt":"消费者在购买、使用商品时，其合法权益受到损害的，可以向销售者要求赔偿。销售者赔偿后，属于生产者的责任或者属于向销售者提供商品的其他销售者的责任的，销售者有权向生产者或者其他销售者追偿。"},{"i":41,"n":"第四十一条","txt":"消费者在购买、使用商品或者接受服务时，其合法权益受到损害，因原企业分立、合并的，可以向变更后承受其权利义务的企业要求赔偿。"},{"i":42,"n":"第四十二条","txt":"使用他人营业执照的违法经营者提供商品或者服务，损害消费者合法权益的，消费者可以向其要求赔偿，也可以向营业执照的持有人要求赔偿。"},{"i":43,"n":"第四十三条","txt":"消费者在展销会、租赁柜台购买商品或者接受服务，其合法权益受到损害的，可以向销售者或者服务者要求赔偿。展销会结束或者柜台租赁期满后，也可以向展销会的举办者、柜台的出租者要求赔偿。展销会的举办者、柜台的出租者赔偿后，有权向销售者或者服务者追偿。"},{"i":44,"n":"第四十四条","txt":"消费者通过网络交易平台购买商品或者接受服务，其合法权益受到损害的，可以向销售者或者服务者要求赔偿。网络交易平台提供者不能提供销售者或者服务者的真实名称、地址和有效联系方式的，消费者也可以向网络交易平台提供者要求赔偿；网络交易平台提供者作出更有利于消费者的承诺的，应当履行承诺。网络交易平台提供者赔偿后，有权向销售者或者服务者追偿。"},{"i":45,"n":"第四十五条","txt":"消费者因经营者利用虚假广告或者其他虚假宣传方式提供商品或者服务，其合法权益受到损害的，可以向经营者要求赔偿。广告经营者、发布者发布虚假广告的，消费者可以请求行政主管部门予以惩处。广告经营者、发布者不能提供经营者的真实名称、地址和有效联系方式的，应当承担赔偿责任。"},{"i":46,"n":"第四十六条","txt":"消费者向有关行政部门投诉的，该部门应当自收到投诉之日起七个工作日内，予以处理并告知消费者。"},{"i":47,"n":"第四十七条","txt":"对侵害众多消费者合法权益的行为，中国消费者协会以及在省、自治区、直辖市设立的消费者协会，可以向人民法院提起诉讼。"},{"i":48,"n":"第四十八条","txt":"经营者提供商品或者服务有下列情形之一的，除本法另有规定外，应当依照其他有关法律、法规的规定，承担民事责任："},{"i":49,"n":"第四十九条","txt":"经营者提供商品或者服务，造成消费者或者其他受害人人身伤害的，应当赔偿医疗费、护理费、交通费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿残疾生活辅助具费和残疾赔偿金。造成死亡的，还应当赔偿丧葬费和死亡赔偿金。"},{"i":50,"n":"第五十条","txt":"经营者侵害消费者的人格尊严、侵犯消费者人身自由或者侵害消费者个人信息依法得到保护的权利的，应当停止侵害、恢复名誉、消除影响、赔礼道歉，并赔偿损失。"},{"i":51,"n":"第五十一条","txt":"经营者有侮辱诽谤、搜查身体、侵犯人身自由等侵害消费者或者其他受害人人身权益的行为，造成严重精神损害的，受害人可以要求精神损害赔偿。"},{"i":52,"n":"第五十二条","txt":"经营者提供商品或者服务，造成消费者财产损害的，应当依照法律规定或者当事人约定承担修理、重作、更换、退货、补足商品数量、退还货款和服务费用或者赔偿损失等民事责任。"},{"i":53,"n":"第五十三条","txt":"经营者以预收款方式提供商品或者服务的，应当按照约定提供。未按照约定提供的，应当按照消费者的要求履行约定或者退回预付款；并应当承担预付款的利息、消费者必须支付的合理费用。"},{"i":54,"n":"第五十四条","txt":"依法经有关行政部门认定为不合格的商品，消费者要求退货的，经营者应当负责退货。"},{"i":55,"n":"第五十五条","txt":"经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。"},{"i":56,"n":"第五十六条","txt":"经营者有下列情形之一，除承担相应的民事责任外，其他有关法律、法规对处罚机关和处罚方式有规定的，依照法律、法规的规定执行；法律、法规未作规定的，由工商行政管理部门或者其他有关行政部门责令改正，可以根据情节单处或者并处警告、没收违法所得、处以违法所得一倍以上十倍以下的罚款，没有违法所得的，处以五十万元以下的罚款；情节严重的，责令停业整顿、吊销营业执照："},{"i":57,"n":"第五十七条","txt":"经营者违反本法规定提供商品或者服务，侵害消费者合法权益，构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"经营者违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金，其财产不足以同时支付的，先承担民事赔偿责任。"},{"i":59,"n":"第五十九条","txt":"经营者对行政处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":60,"n":"第六十条","txt":"以暴力、威胁等方法阻碍有关行政部门工作人员依法执行职务的，依法追究刑事责任；拒绝、阻碍有关行政部门工作人员依法执行职务，未使用暴力、威胁方法的，由公安机关依照《中华人民共和国治安管理处罚法》的规定处罚。"},{"i":61,"n":"第六十一条","txt":"国家机关工作人员玩忽职守或者包庇经营者侵害消费者合法权益的行为的，由其所在单位或者上级机关给予行政处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":62,"n":"第六十二条","txt":"农民购买、使用直接用于农业生产的生产资料，参照本法执行。"},{"i":63,"n":"第六十三条","txt":"本法自1994年1月1日起施行。"}],"shewaiminshiguanxifalvshiyongfa":[{"i":1,"n":"第一条","txt":"为了明确涉外民事关系的法律适用，合理解决涉外民事争议，维护当事人的合法权益，制定本法。"},{"i":2,"n":"第二条","txt":"涉外民事关系适用的法律，依照本法确定。其他法律对涉外民事关系法律适用另有特别规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"当事人依照法律规定可以明示选择涉外民事关系适用的法律。"},{"i":4,"n":"第四条","txt":"中华人民共和国法律对涉外民事关系有强制性规定的，直接适用该强制性规定。"},{"i":5,"n":"第五条","txt":"外国法律的适用将损害中华人民共和国社会公共利益的，适用中华人民共和国法律。"},{"i":6,"n":"第六条","txt":"涉外民事关系适用外国法律，该国不同区域实施不同法律的，适用与该涉外民事关系有最密切联系区域的法律。"},{"i":7,"n":"第七条","txt":"诉讼时效，适用相关涉外民事关系应当适用的法律。"},{"i":8,"n":"第八条","txt":"涉外民事关系的定性，适用法院地法律。"},{"i":9,"n":"第九条","txt":"涉外民事关系适用的外国法律，不包括该国的法律适用法。"},{"i":10,"n":"第十条","txt":"涉外民事关系适用的外国法律，由人民法院、仲裁机构或者行政机关查明。当事人选择适用外国法律的，应当提供该国法律。"},{"i":11,"n":"第十一条","txt":"自然人的民事权利能力，适用经常居所地法律。"},{"i":12,"n":"第十二条","txt":"自然人的民事行为能力，适用经常居所地法律。"},{"i":13,"n":"第十三条","txt":"宣告失踪或者宣告死亡，适用自然人经常居所地法律。"},{"i":14,"n":"第十四条","txt":"法人及其分支机构的民事权利能力、民事行为能力、组织机构、股东权利义务等事项，适用登记地法律。"},{"i":15,"n":"第十五条","txt":"人格权的内容，适用权利人经常居所地法律。"},{"i":16,"n":"第十六条","txt":"代理适用代理行为地法律，但被代理人与代理人的民事关系，适用代理关系发生地法律。"},{"i":17,"n":"第十七条","txt":"当事人可以协议选择信托适用的法律。当事人没有选择的，适用信托财产所在地法律或者信托关系发生地法律。"},{"i":18,"n":"第十八条","txt":"当事人可以协议选择仲裁协议适用的法律。当事人没有选择的，适用仲裁机构所在地法律或者仲裁地法律。"},{"i":19,"n":"第十九条","txt":"依照本法适用国籍国法律，自然人具有两个以上国籍的，适用有经常居所的国籍国法律；在所有国籍国均无经常居所的，适用与其有最密切联系的国籍国法律。自然人无国籍或者国籍不明的，适用其经常居所地法律。"},{"i":20,"n":"第二十条","txt":"依照本法适用经常居所地法律，自然人经常居所地不明的，适用其现在居所地法律。"},{"i":21,"n":"第二十一条","txt":"结婚条件，适用当事人共同经常居所地法律；没有共同经常居所地的，适用共同国籍国法律；没有共同国籍，在一方当事人经常居所地或者国籍国缔结婚姻的，适用婚姻缔结地法律。"},{"i":22,"n":"第二十二条","txt":"结婚手续，符合婚姻缔结地法律、一方当事人经常居所地法律或者国籍国法律的，均为有效。"},{"i":23,"n":"第二十三条","txt":"夫妻人身关系，适用共同经常居所地法律；没有共同经常居所地的，适用共同国籍国法律。"},{"i":24,"n":"第二十四条","txt":"夫妻财产关系，当事人可以协议选择适用一方当事人经常居所地法律、国籍国法律或者主要财产所在地法律。当事人没有选择的，适用共同经常居所地法律；没有共同经常居所地的，适用共同国籍国法律。"},{"i":25,"n":"第二十五条","txt":"父母子女人身、财产关系，适用共同经常居所地法律；没有共同经常居所地的，适用一方当事人经常居所地法律或者国籍国法律中有利于保护弱者权益的法律。"},{"i":26,"n":"第二十六条","txt":"协议离婚，当事人可以协议选择适用一方当事人经常居所地法律或者国籍国法律。当事人没有选择的，适用共同经常居所地法律；没有共同经常居所地的，适用共同国籍国法律；没有共同国籍的，适用办理离婚手续机构所在地法律。"},{"i":27,"n":"第二十七条","txt":"诉讼离婚，适用法院地法律。"},{"i":28,"n":"第二十八条","txt":"收养的条件和手续，适用收养人和被收养人经常居所地法律。收养的效力，适用收养时收养人经常居所地法律。收养关系的解除，适用收养时被收养人经常居所地法律或者法院地法律。"},{"i":29,"n":"第二十九条","txt":"扶养，适用一方当事人经常居所地法律、国籍国法律或者主要财产所在地法律中有利于保护被扶养人权益的法律。"},{"i":30,"n":"第三十条","txt":"监护，适用一方当事人经常居所地法律或者国籍国法律中有利于保护被监护人权益的法律。"},{"i":31,"n":"第三十一条","txt":"法定继承，适用被继承人死亡时经常居所地法律，但不动产法定继承，适用不动产所在地法律。"},{"i":32,"n":"第三十二条","txt":"遗嘱方式，符合遗嘱人立遗嘱时或者死亡时经常居所地法律、国籍国法律或者遗嘱行为地法律的，遗嘱均为成立。"},{"i":33,"n":"第三十三条","txt":"遗嘱效力，适用遗嘱人立遗嘱时或者死亡时经常居所地法律或者国籍国法律。"},{"i":34,"n":"第三十四条","txt":"遗产管理等事项，适用遗产所在地法律。"},{"i":35,"n":"第三十五条","txt":"无人继承遗产的归属，适用被继承人死亡时遗产所在地法律。"},{"i":36,"n":"第三十六条","txt":"不动产物权，适用不动产所在地法律。"},{"i":37,"n":"第三十七条","txt":"当事人可以协议选择动产物权适用的法律。当事人没有选择的，适用法律事实发生时动产所在地法律。"},{"i":38,"n":"第三十八条","txt":"当事人可以协议选择运输中动产物权发生变更适用的法律。当事人没有选择的，适用运输目的地法律。"},{"i":39,"n":"第三十九条","txt":"有价证券，适用有价证券权利实现地法律或者其他与该有价证券有最密切联系的法律。"},{"i":40,"n":"第四十条","txt":"权利质权，适用质权设立地法律。"},{"i":41,"n":"第四十一条","txt":"当事人可以协议选择合同适用的法律。当事人没有选择的，适用履行义务最能体现该合同特征的一方当事人经常居所地法律或者其他与该合同有最密切联系的法律。"},{"i":42,"n":"第四十二条","txt":"消费者合同，适用消费者经常居所地法律；消费者选择适用商品、服务提供地法律或者经营者在消费者经常居所地没有从事相关经营活动的，适用商品、服务提供地法律。"},{"i":43,"n":"第四十三条","txt":"劳动合同，适用劳动者工作地法律；难以确定劳动者工作地的，适用用人单位主营业地法律。劳务派遣，可以适用劳务派出地法律。"},{"i":44,"n":"第四十四条","txt":"侵权责任，适用侵权行为地法律，但当事人有共同经常居所地的，适用共同经常居所地法律。侵权行为发生后，当事人协议选择适用法律的，按照其协议。"},{"i":45,"n":"第四十五条","txt":"产品责任，适用被侵权人经常居所地法律；被侵权人选择适用侵权人主营业地法律、损害发生地法律的，或者侵权人在被侵权人经常居所地没有从事相关经营活动的，适用侵权人主营业地法律或者损害发生地法律。"},{"i":46,"n":"第四十六条","txt":"通过网络或者采用其他方式侵害姓名权、肖像权、名誉权、隐私权等人格权的，适用被侵权人经常居所地法律。"},{"i":47,"n":"第四十七条","txt":"不当得利、无因管理，适用当事人协议选择适用的法律。当事人没有选择的，适用当事人共同经常居所地法律；没有共同经常居所地的，适用不当得利、无因管理发生地法律。"},{"i":48,"n":"第四十八条","txt":"知识产权的归属和内容，适用被请求保护地法律。"},{"i":49,"n":"第四十九条","txt":"当事人可以协议选择知识产权转让和许可使用适用的法律。当事人没有选择的，适用本法对合同的有关规定。"},{"i":50,"n":"第五十条","txt":"知识产权的侵权责任，适用被请求保护地法律，当事人也可以在侵权行为发生后协议选择适用法院地法律。"},{"i":51,"n":"第五十一条","txt":"《中华人民共和国民法通则》第一百四十六条、第一百四十七条，《中华人民共和国继承法》第三十六条，与本法的规定不一致的，适用本法。"},{"i":52,"n":"第五十二条","txt":"本法自2011年4月1日起施行。"}],"dianziqianmingfa":[{"i":1,"n":"第一条","txt":"为了规范电子签名行为，确立电子签名的法律效力，维护有关各方的合法权益，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称电子签名，是指数据电文中以电子形式所含、所附用于识别签名人身份并表明签名人认可其中内容的数据。"},{"i":3,"n":"第三条","txt":"民事活动中的合同或者其他文件、单证等文书，当事人可以约定使用或者不使用电子签名、数据电文。"},{"i":4,"n":"第四条","txt":"能够有形地表现所载内容，并可以随时调取查用的数据电文，视为符合法律、法规要求的书面形式。"},{"i":5,"n":"第五条","txt":"符合下列条件的数据电文，视为满足法律、法规规定的原件形式要求："},{"i":6,"n":"第六条","txt":"符合下列条件的数据电文，视为满足法律、法规规定的文件保存要求："},{"i":7,"n":"第七条","txt":"数据电文不得仅因为其是以电子、光学、磁或者类似手段生成、发送、接收或者储存的而被拒绝作为证据使用。"},{"i":8,"n":"第八条","txt":"审查数据电文作为证据的真实性，应当考虑以下因素："},{"i":9,"n":"第九条","txt":"数据电文有下列情形之一的，视为发件人发送："},{"i":10,"n":"第十条","txt":"法律、行政法规规定或者当事人约定数据电文需要确认收讫的，应当确认收讫。发件人收到收件人的收讫确认时，数据电文视为已经收到。"},{"i":11,"n":"第十一条","txt":"数据电文进入发件人控制之外的某个信息系统的时间，视为该数据电文的发送时间。"},{"i":12,"n":"第十二条","txt":"发件人的主营业地为数据电文的发送地点，收件人的主营业地为数据电文的接收地点。没有主营业地的，其经常居住地为发送或者接收地点。"},{"i":13,"n":"第十三条","txt":"电子签名同时符合下列条件的，视为可靠的电子签名："},{"i":14,"n":"第十四条","txt":"可靠的电子签名与手写签名或者盖章具有同等的法律效力。"},{"i":15,"n":"第十五条","txt":"电子签名人应当妥善保管电子签名制作数据。电子签名人知悉电子签名制作数据已经失密或者可能已经失密时，应当及时告知有关各方，并终止使用该电子签名制作数据。"},{"i":16,"n":"第十六条","txt":"电子签名需要第三方认证的，由依法设立的电子认证服务提供者提供认证服务。"},{"i":17,"n":"第十七条","txt":"提供电子认证服务，应当具备下列条件："},{"i":18,"n":"第十八条","txt":"从事电子认证服务，应当向国务院信息产业主管部门提出申请，并提交符合本法第十七条规定条件的相关材料。国务院信息产业主管部门接到申请后经依法审查，征求国务院商务主管部门等有关部门的意见后，自接到申请之日起四十五日内作出许可或者不予许可的决定。予以许可的，颁发电子认证许可证书；不予许可的，应当书面通知申请人并告知理由。"},{"i":19,"n":"第十九条","txt":"电子认证服务提供者应当制定、公布符合国家有关规定的电子认证业务规则，并向国务院信息产业主管部门备案。"},{"i":20,"n":"第二十条","txt":"电子签名人向电子认证服务提供者申请电子签名认证证书，应当提供真实、完整和准确的信息。"},{"i":21,"n":"第二十一条","txt":"电子认证服务提供者签发的电子签名认证证书应当准确无误，并应当载明下列内容："},{"i":22,"n":"第二十二条","txt":"电子认证服务提供者应当保证电子签名认证证书内容在有效期内完整、准确，并保证电子签名依赖方能够证实或者了解电子签名认证证书所载内容及其他有关事项。"},{"i":23,"n":"第二十三条","txt":"电子认证服务提供者拟暂停或者终止电子认证服务的，应当在暂停或者终止服务九十日前，就业务承接及其他有关事项通知有关各方。"},{"i":24,"n":"第二十四条","txt":"电子认证服务提供者应当妥善保存与认证相关的信息，信息保存期限至少为电子签名认证证书失效后五年。"},{"i":25,"n":"第二十五条","txt":"国务院信息产业主管部门依照本法制定电子认证服务业的具体管理办法，对电子认证服务提供者依法实施监督管理。"},{"i":26,"n":"第二十六条","txt":"经国务院信息产业主管部门根据有关协议或者对等原则核准后，中华人民共和国境外的电子认证服务提供者在境外签发的电子签名认证证书与依照本法设立的电子认证服务提供者签发的电子签名认证证书具有同等的法律效力。"},{"i":27,"n":"第二十七条","txt":"电子签名人知悉电子签名制作数据已经失密或者可能已经失密未及时告知有关各方、并终止使用电子签名制作数据，未向电子认证服务提供者提供真实、完整和准确的信息，或者有其他过错，给电子签名依赖方、电子认证服务提供者造成损失的，承担赔偿责任。"},{"i":28,"n":"第二十八条","txt":"电子签名人或者电子签名依赖方因依据电子认证服务提供者提供的电子签名认证服务从事民事活动遭受损失，电子认证服务提供者不能证明自己无过错的，承担赔偿责任。"},{"i":29,"n":"第二十九条","txt":"未经许可提供电子认证服务的，由国务院信息产业主管部门责令停止违法行为；有违法所得的，没收违法所得；违法所得三十万元以上的，处违法所得一倍以上三倍以下的罚款；没有违法所得或者违法所得不足三十万元的，处十万元以上三十万元以下的罚款。"},{"i":30,"n":"第三十条","txt":"电子认证服务提供者暂停或者终止电子认证服务，未在暂停或者终止服务六十日前向国务院信息产业主管部门报告的，由国务院信息产业主管部门对其直接负责的主管人员处一万元以上五万元以下的罚款。"},{"i":31,"n":"第三十一条","txt":"电子认证服务提供者不遵守认证业务规则、未妥善保存与认证相关的信息，或者有其他违法行为的，由国务院信息产业主管部门责令限期改正；逾期未改正的，吊销电子认证许可证书，其直接负责的主管人员和其他直接责任人员十年内不得从事电子认证服务。吊销电子认证许可证书的，应当予以公告并通知工商行政管理部门。"},{"i":32,"n":"第三十二条","txt":"伪造、冒用、盗用他人的电子签名，构成犯罪的，依法追究刑事责任；给他人造成损失的，依法承担民事责任。"},{"i":33,"n":"第三十三条","txt":"依照本法负责电子认证服务业监督管理工作的部门的工作人员，不依法履行行政许可、监督管理职责的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"本法中下列用语的含义："},{"i":35,"n":"第三十五条","txt":"国务院或者国务院规定的部门可以依据本法制定政务活动和其他社会活动中使用电子签名、数据电文的具体办法。"},{"i":36,"n":"第三十六条","txt":"本法自2005年4月1日起施行。"}],"piaojufa":[{"i":1,"n":"第一条","txt":"为了规范票据行为，保障票据活动中当事人的合法权益，维护社会经济秩序，促进社会主义市场经济的发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内的票据活动，适用本法。"},{"i":3,"n":"第三条","txt":"票据活动应当遵守法律、行政法规，不得损害社会公共利益。"},{"i":4,"n":"第四条","txt":"票据出票人制作票据，应当按照法定条件在票据上签章，并按照所记载的事项承担票据责任。"},{"i":5,"n":"第五条","txt":"票据当事人可以委托其代理人在票据上签章，并应当在票据上表明其代理关系。"},{"i":6,"n":"第六条","txt":"无民事行为能力人或者限制民事行为能力人在票据上签章的，其签章无效，但是不影响其他签章的效力。"},{"i":7,"n":"第七条","txt":"票据上的签章，为签名、盖章或者签名加盖章。"},{"i":8,"n":"第八条","txt":"票据金额以中文大写和数码同时记载，二者必须一致，二者不一致的，票据无效。"},{"i":9,"n":"第九条","txt":"票据上的记载事项必须符合本法的规定。"},{"i":10,"n":"第十条","txt":"票据的签发、取得和转让，应当遵循诚实信用的原则，具有真实的交易关系和债权债务关系。"},{"i":11,"n":"第十一条","txt":"因税收、继承、赠与可以依法无偿取得票据的，不受给付对价的限制。但是，所享有的票据权利不得优于其前手的权利。"},{"i":12,"n":"第十二条","txt":"以欺诈、偷盗或者胁迫等手段取得票据的，或者明知有前列情形，出于恶意取得票据的，不得享有票据权利。"},{"i":13,"n":"第十三条","txt":"票据债务人不得以自己与出票人或者与持票人的前手之间的抗辩事由，对抗持票人。但是，持票人明知存在抗辩事由而取得票据的除外。"},{"i":14,"n":"第十四条","txt":"票据上的记载事项应当真实，不得伪造、变造。伪造、变造票据上的签章和其他记载事项的，应当承担法律责任。"},{"i":15,"n":"第十五条","txt":"票据丧失，失票人可以及时通知票据的付款人挂失止付，但是，未记载付款人或者无法确定付款人及其代理付款人的票据除外。"},{"i":16,"n":"第十六条","txt":"持票人对票据债务人行使票据权利，或者保全票据权利，应当在票据当事人的营业场所和营业时间内进行，票据当事人无营业场所的，应当在其住所进行。"},{"i":17,"n":"第十七条","txt":"票据权利在下列期限内不行使而消灭："},{"i":18,"n":"第十八条","txt":"持票人因超过票据权利时效或者因票据记载事项欠缺而丧失票据权利的，仍享有民事权利，可以请求出票人或者承兑人返还其与未支付的票据金额相当的利益。"},{"i":19,"n":"第十九条","txt":"汇票是出票人签发的，委托付款人在见票时或者在指定日期无条件支付确定的金额给收款人或者持票人的票据。"},{"i":20,"n":"第二十条","txt":"出票是指出票人签发票据并将其交付给收款人的票据行为。"},{"i":21,"n":"第二十一条","txt":"汇票的出票人必须与付款人具有真实的委托付款关系，并且具有支付汇票金额的可靠资金来源。"},{"i":22,"n":"第二十二条","txt":"汇票必须记载下列事项："},{"i":23,"n":"第二十三条","txt":"汇票上记载付款日期、付款地、出票地等事项的，应当清楚、明确。"},{"i":24,"n":"第二十四条","txt":"汇票上可以记载本法规定事项以外的其他出票事项，但是该记载事项不具有汇票上的效力。"},{"i":25,"n":"第二十五条","txt":"付款日期可以按照下列形式之一记载："},{"i":26,"n":"第二十六条","txt":"出票人签发汇票后，即承担保证该汇票承兑和付款的责任。出票人在汇票得不到承兑或者付款时，应当向持票人清偿本法第七十条、第七十一条规定的金额和费用。"},{"i":27,"n":"第二十七条","txt":"持票人可以将汇票权利转让给他人或者将一定的汇票权利授予他人行使。"},{"i":28,"n":"第二十八条","txt":"票据凭证不能满足背书人记载事项的需要，可以加附粘单，粘附于票据凭证上。"},{"i":29,"n":"第二十九条","txt":"背书由背书人签章并记载背书日期。"},{"i":30,"n":"第三十条","txt":"汇票以背书转让或者以背书将一定的汇票权利授予他人行使时，必须记载被背书人名称。"},{"i":31,"n":"第三十一条","txt":"以背书转让的汇票，背书应当连续。持票人以背书的连续，证明其汇票权利；非经背书转让，而以其他合法方式取得汇票的，依法举证，证明其汇票权利。"},{"i":32,"n":"第三十二条","txt":"以背书转让的汇票，后手应当对其直接前手背书的真实性负责。"},{"i":33,"n":"第三十三条","txt":"背书不得附有条件。背书时附有条件的，所附条件不具有汇票上的效力。"},{"i":34,"n":"第三十四条","txt":"背书人在汇票上记载“不得转让”字样，其后手再背书转让的，原背书人对后手的被背书人不承担保证责任。"},{"i":35,"n":"第三十五条","txt":"背书记载“委托收款”字样的，被背书人有权代背书人行使被委托的汇票权利。但是，被背书人不得再以背书转让汇票权利。"},{"i":36,"n":"第三十六条","txt":"汇票被拒绝承兑、被拒绝付款或者超过付款提示期限的，不得背书转让；背书转让的，背书人应当承担汇票责任。"},{"i":37,"n":"第三十七条","txt":"背书人以背书转让汇票后，即承担保证其后手所持汇票承兑和付款的责任。背书人在汇票得不到承兑或者付款时，应当向持票人清偿本法第七十条、第七十一条规定的金额和费用。"},{"i":38,"n":"第三十八条","txt":"承兑是指汇票付款人承诺在汇票到期日支付汇票金额的票据行为。"},{"i":39,"n":"第三十九条","txt":"定日付款或者出票后定期付款的汇票，持票人应当在汇票到期日前向付款人提示承兑。"},{"i":40,"n":"第四十条","txt":"见票后定期付款的汇票，持票人应当自出票日起一个月内向付款人提示承兑。"},{"i":41,"n":"第四十一条","txt":"付款人对向其提示承兑的汇票，应当自收到提示承兑的汇票之日起三日内承兑或者拒绝承兑。"},{"i":42,"n":"第四十二条","txt":"付款人承兑汇票的，应当在汇票正面记载“承兑”字样和承兑日期并签章；见票后定期付款的汇票，应当在承兑时记载付款日期。"},{"i":43,"n":"第四十三条","txt":"付款人承兑汇票，不得附有条件；承兑附有条件的，视为拒绝承兑。"},{"i":44,"n":"第四十四条","txt":"付款人承兑汇票后，应当承担到期付款的责任。"},{"i":45,"n":"第四十五条","txt":"汇票的债务可以由保证人承担保证责任。"},{"i":46,"n":"第四十六条","txt":"保证人必须在汇票或者粘单上记载下列事项："},{"i":47,"n":"第四十七条","txt":"保证人在汇票或者粘单上未记载前条第（三）项的，已承兑的汇票，承兑人为被保证人；未承兑的汇票，出票人为被保证人。"},{"i":48,"n":"第四十八条","txt":"保证不得附有条件；附有条件的，不影响对汇票的保证责任。"},{"i":49,"n":"第四十九条","txt":"保证人对合法取得汇票的持票人所享有的汇票权利，承担保证责任。但是，被保证人的债务因汇票记载事项欠缺而无效的除外。"},{"i":50,"n":"第五十条","txt":"被保证的汇票，保证人应当与被保证人对持票人承担连带责任。汇票到期后得不到付款的，持票人有权向保证人请求付款，保证人应当足额付款。"},{"i":51,"n":"第五十一条","txt":"保证人为二人以上的，保证人之间承担连带责任。"},{"i":52,"n":"第五十二条","txt":"保证人清偿汇票债务后，可以行使持票人对被保证人及其前手的追索权。"},{"i":53,"n":"第五十三条","txt":"持票人应当按照下列期限提示付款："},{"i":54,"n":"第五十四条","txt":"持票人依照前条规定提示付款的，付款人必须在当日足额付款。"},{"i":55,"n":"第五十五条","txt":"持票人获得付款的，应当在汇票上签收，并将汇票交给付款人。持票人委托银行收款的，受委托的银行将代收的汇票金额转账收入持票人账户，视同签收。"},{"i":56,"n":"第五十六条","txt":"持票人委托的收款银行的责任，限于按照汇票上记载事项将汇票金额转入持票人账户。"},{"i":57,"n":"第五十七条","txt":"付款人及其代理付款人付款时，应当审查汇票背书的连续，并审查提示付款人的合法身份证明或者有效证件。"},{"i":58,"n":"第五十八条","txt":"对定日付款、出票后定期付款或者见票后定期付款的汇票，付款人在到期日前付款的，由付款人自行承担所产生的责任。"},{"i":59,"n":"第五十九条","txt":"汇票金额为外币的，按照付款日的市场汇价，以人民币支付。"},{"i":60,"n":"第六十条","txt":"付款人依法足额付款后，全体汇票债务人的责任解除。"},{"i":61,"n":"第六十一条","txt":"汇票到期被拒绝付款的，持票人可以对背书人、出票人以及汇票的其他债务人行使追索权。"},{"i":62,"n":"第六十二条","txt":"持票人行使追索权时，应当提供被拒绝承兑或者被拒绝付款的有关证明。"},{"i":63,"n":"第六十三条","txt":"持票人因承兑人或者付款人死亡、逃匿或者其他原因，不能取得拒绝证明的，可以依法取得其他有关证明。"},{"i":64,"n":"第六十四条","txt":"承兑人或者付款人被人民法院依法宣告破产的，人民法院的有关司法文书具有拒绝证明的效力。"},{"i":65,"n":"第六十五条","txt":"持票人不能出示拒绝证明、退票理由书或者未按照规定期限提供其他合法证明的，丧失对其前手的追索权。但是，承兑人或者付款人仍应当对持票人承担责任。"},{"i":66,"n":"第六十六条","txt":"持票人应当自收到被拒绝承兑或者被拒绝付款的有关证明之日起三日内，将被拒绝事由书面通知其前手；其前手应当自收到通知之日起三日内书面通知其再前手。持票人也可以同时向各汇票债务人发出书面通知。"},{"i":67,"n":"第六十七条","txt":"依照前条第一款所作的书面通知，应当记明汇票的主要记载事项，并说明该汇票已被退票。"},{"i":68,"n":"第六十八条","txt":"汇票的出票人、背书人、承兑人和保证人对持票人承担连带责任。"},{"i":69,"n":"第六十九条","txt":"持票人为出票人的，对其前手无追索权。持票人为背书人的，对其后手无追索权。"},{"i":70,"n":"第七十条","txt":"持票人行使追索权，可以请求被追索人支付下列金额和费用："},{"i":71,"n":"第七十一条","txt":"被追索人依照前条规定清偿后，可以向其他汇票债务人行使再追索权，请求其他汇票债务人支付下列金额和费用："},{"i":72,"n":"第七十二条","txt":"被追索人依照前二条规定清偿债务后，其责任解除。"},{"i":73,"n":"第七十三条","txt":"本票是出票人签发的，承诺自己在见票时无条件支付确定的金额给收款人或者持票人的票据。"},{"i":74,"n":"第七十四条","txt":"本票的出票人必须具有支付本票金额的可靠资金来源，并保证支付。"},{"i":75,"n":"第七十五条","txt":"本票必须记载下列事项："},{"i":76,"n":"第七十六条","txt":"本票上记载付款地、出票地等事项的，应当清楚、明确。"},{"i":77,"n":"第七十七条","txt":"本票的出票人在持票人提示见票时，必须承担付款的责任。"},{"i":78,"n":"第七十八条","txt":"本票自出票日起，付款期限最长不得超过二个月。"},{"i":79,"n":"第七十九条","txt":"本票的持票人未按照规定期限提示见票的，丧失对出票人以外的前手的追索权。"},{"i":80,"n":"第八十条","txt":"本票的背书、保证、付款行为和追索权的行使，除本章规定外，适用本法第二章有关汇票的规定。"},{"i":81,"n":"第八十一条","txt":"支票是出票人签发的，委托办理支票存款业务的银行或者其他金融机构在见票时无条件支付确定的金额给收款人或者持票人的票据。"},{"i":82,"n":"第八十二条","txt":"开立支票存款账户，申请人必须使用其本名，并提交证明其身份的合法证件。"},{"i":83,"n":"第八十三条","txt":"支票可以支取现金，也可以转账，用于转账时，应当在支票正面注明。"},{"i":84,"n":"第八十四条","txt":"支票必须记载下列事项："},{"i":85,"n":"第八十五条","txt":"支票上的金额可以由出票人授权补记，未补记前的支票，不得使用。"},{"i":86,"n":"第八十六条","txt":"支票上未记载收款人名称的，经出票人授权，可以补记。"},{"i":87,"n":"第八十七条","txt":"支票的出票人所签发的支票金额不得超过其付款时在付款人处实有的存款金额。"},{"i":88,"n":"第八十八条","txt":"支票的出票人不得签发与其预留本名的签名式样或者印鉴不符的支票。"},{"i":89,"n":"第八十九条","txt":"出票人必须按照签发的支票金额承担保证向该持票人付款的责任。"},{"i":90,"n":"第九十条","txt":"支票限于见票即付，不得另行记载付款日期。另行记载付款日期的，该记载无效。"},{"i":91,"n":"第九十一条","txt":"支票的持票人应当自出票日起十日内提示付款；异地使用的支票，其提示付款的期限由中国人民银行另行规定。"},{"i":92,"n":"第九十二条","txt":"付款人依法支付支票金额的，对出票人不再承担受委托付款的责任，对持票人不再承担付款的责任。但是，付款人以恶意或者有重大过失付款的除外。"},{"i":93,"n":"第九十三条","txt":"支票的背书、付款行为和追索权的行使，除本章规定外，适用本法第二章有关汇票的规定。"},{"i":94,"n":"第九十四条","txt":"涉外票据的法律适用，依照本章的规定确定。"},{"i":95,"n":"第九十五条","txt":"中华人民共和国缔结或者参加的国际条约同本法有不同规定的，适用国际条约的规定。但是，中华人民共和国声明保留的条款除外。"},{"i":96,"n":"第九十六条","txt":"票据债务人的民事行为能力，适用其本国法律。"},{"i":97,"n":"第九十七条","txt":"汇票、本票出票时的记载事项，适用出票地法律。"},{"i":98,"n":"第九十八条","txt":"票据的背书、承兑、付款和保证行为，适用行为地法律。"},{"i":99,"n":"第九十九条","txt":"票据追索权的行使期限，适用出票地法律。"},{"i":100,"n":"第一百条","txt":"票据的提示期限、有关拒绝证明的方式、出具拒绝证明的期限，适用付款地法律。"},{"i":101,"n":"第一百零一条","txt":"票据丧失时，失票人请求保全票据权利的程序，适用付款地法律。"},{"i":102,"n":"第一百零二条","txt":"有下列票据欺诈行为之一的，依法追究刑事责任："},{"i":103,"n":"第一百零三条","txt":"有前条所列行为之一，情节轻微，不构成犯罪的，依照国家有关规定给予行政处罚。"},{"i":104,"n":"第一百零四条","txt":"金融机构工作人员在票据业务中玩忽职守，对违反本法规定的票据予以承兑、付款或者保证的，给予处分；造成重大损失，构成犯罪的，依法追究刑事责任。"},{"i":105,"n":"第一百零五条","txt":"票据的付款人对见票即付或者到期的票据，故意压票，拖延支付的，由金融行政管理部门处以罚款，对直接责任人员给予处分。"},{"i":106,"n":"第一百零六条","txt":"依照本法规定承担赔偿责任以外的其他违反本法规定的行为，给他人造成损失的，应当依法承担民事责任。"},{"i":107,"n":"第一百零七条","txt":"本法规定的各项期限的计算，适用民法通则关于计算期间的规定。"},{"i":108,"n":"第一百零八条","txt":"汇票、本票、支票的格式应当统一。"},{"i":109,"n":"第一百零九条","txt":"票据管理的具体实施办法，由中国人民银行依照本法制定，报国务院批准后施行。"},{"i":110,"n":"第一百一十条","txt":"本法自1996年1月1日起施行。"}],"zhuzuoquanfa":[{"i":1,"n":"第一条","txt":"为保护文学、艺术和科学作品作者的著作权，以及与著作权有关的权益，鼓励有益于社会主义精神文明、物质文明建设的作品的创作和传播，促进社会主义文化和科学事业的发展与繁荣，根据宪法制定本法。"},{"i":2,"n":"第二条","txt":"中国公民、法人或者非法人组织的作品，不论是否发表，依照本法享有著作权。"},{"i":3,"n":"第三条","txt":"本法所称的作品，是指文学、艺术和科学领域内具有独创性并能以一定形式表现的智力成果，包括："},{"i":4,"n":"第四条","txt":"著作权人和与著作权有关的权利人行使权利，不得违反宪法和法律，不得损害公共利益。国家对作品的出版、传播依法进行监督管理。"},{"i":5,"n":"第五条","txt":"本法不适用于："},{"i":6,"n":"第六条","txt":"民间文学艺术作品的著作权保护办法由国务院另行规定。"},{"i":7,"n":"第七条","txt":"国家著作权主管部门负责全国的著作权管理工作；县级以上地方主管著作权的部门负责本行政区域的著作权管理工作。"},{"i":8,"n":"第八条","txt":"著作权人和与著作权有关的权利人可以授权著作权集体管理组织行使著作权或者与著作权有关的权利。依法设立的著作权集体管理组织是非营利法人，被授权后可以以自己的名义为著作权人和与著作权有关的权利人主张权利，并可以作为当事人进行涉及著作权或者与著作权有关的权利的诉讼、仲裁、调解活动。"},{"i":9,"n":"第九条","txt":"著作权人包括："},{"i":10,"n":"第十条","txt":"著作权包括下列人身权和财产权："},{"i":11,"n":"第十一条","txt":"著作权属于作者，本法另有规定的除外。"},{"i":12,"n":"第十二条","txt":"在作品上署名的自然人、法人或者非法人组织为作者，且该作品上存在相应权利，但有相反证明的除外。"},{"i":13,"n":"第十三条","txt":"改编、翻译、注释、整理已有作品而产生的作品，其著作权由改编、翻译、注释、整理人享有，但行使著作权时不得侵犯原作品的著作权。"},{"i":14,"n":"第十四条","txt":"两人以上合作创作的作品，著作权由合作作者共同享有。没有参加创作的人，不能成为合作作者。"},{"i":15,"n":"第十五条","txt":"汇编若干作品、作品的片段或者不构成作品的数据或者其他材料，对其内容的选择或者编排体现独创性的作品，为汇编作品，其著作权由汇编人享有，但行使著作权时，不得侵犯原作品的著作权。"},{"i":16,"n":"第十六条","txt":"使用改编、翻译、注释、整理、汇编已有作品而产生的作品进行出版、演出和制作录音录像制品，应当取得该作品的著作权人和原作品的著作权人许可，并支付报酬。"},{"i":17,"n":"第十七条","txt":"视听作品中的电影作品、电视剧作品的著作权由制作者享有，但编剧、导演、摄影、作词、作曲等作者享有署名权，并有权按照与制作者签订的合同获得报酬。"},{"i":18,"n":"第十八条","txt":"自然人为完成法人或者非法人组织工作任务所创作的作品是职务作品，除本条第二款的规定以外，著作权由作者享有，但法人或者非法人组织有权在其业务范围内优先使用。作品完成两年内，未经单位同意，作者不得许可第三人以与单位使用的相同方式使用该作品。"},{"i":19,"n":"第十九条","txt":"受委托创作的作品，著作权的归属由委托人和受托人通过合同约定。合同未作明确约定或者没有订立合同的，著作权属于受托人。"},{"i":20,"n":"第二十条","txt":"作品原件所有权的转移，不改变作品著作权的归属，但美术、摄影作品原件的展览权由原件所有人享有。"},{"i":21,"n":"第二十一条","txt":"著作权属于自然人的，自然人死亡后，其本法第十条第一款第五项至第十七项规定的权利在本法规定的保护期内，依法转移。"},{"i":22,"n":"第二十二条","txt":"作者的署名权、修改权、保护作品完整权的保护期不受限制。"},{"i":23,"n":"第二十三条","txt":"自然人的作品，其发表权、本法第十条第一款第五项至第十七项规定的权利的保护期为作者终生及其死亡后五十年，截止于作者死亡后第五十年的12月31日；如果是合作作品，截止于最后死亡的作者死亡后第五十年的12月31日。"},{"i":24,"n":"第二十四条","txt":"在下列情况下使用作品，可以不经著作权人许可，不向其支付报酬，但应当指明作者姓名或者名称、作品名称，并且不得影响该作品的正常使用，也不得不合理地损害著作权人的合法权益："},{"i":25,"n":"第二十五条","txt":"为实施义务教育和国家教育规划而编写出版教科书，可以不经著作权人许可，在教科书中汇编已经发表的作品片段或者短小的文字作品、音乐作品或者单幅的美术作品、摄影作品、图形作品，但应当按照规定向著作权人支付报酬，指明作者姓名或者名称、作品名称，并且不得侵犯著作权人依照本法享有的其他权利。"},{"i":26,"n":"第二十六条","txt":"使用他人作品应当同著作权人订立许可使用合同，本法规定可以不经许可的除外。"},{"i":27,"n":"第二十七条","txt":"转让本法第十条第一款第五项至第十七项规定的权利，应当订立书面合同。"},{"i":28,"n":"第二十八条","txt":"以著作权中的财产权出质的，由出质人和质权人依法办理出质登记。"},{"i":29,"n":"第二十九条","txt":"许可使用合同和转让合同中著作权人未明确许可、转让的权利，未经著作权人同意，另一方当事人不得行使。"},{"i":30,"n":"第三十条","txt":"使用作品的付酬标准可以由当事人约定，也可以按照国家著作权主管部门会同有关部门制定的付酬标准支付报酬。当事人约定不明确的，按照国家著作权主管部门会同有关部门制定的付酬标准支付报酬。"},{"i":31,"n":"第三十一条","txt":"出版者、表演者、录音录像制作者、广播电台、电视台等依照本法有关规定使用他人作品的，不得侵犯作者的署名权、修改权、保护作品完整权和获得报酬的权利。"},{"i":32,"n":"第三十二条","txt":"图书出版者出版图书应当和著作权人订立出版合同，并支付报酬。"},{"i":33,"n":"第三十三条","txt":"图书出版者对著作权人交付出版的作品，按照合同约定享有的专有出版权受法律保护，他人不得出版该作品。"},{"i":34,"n":"第三十四条","txt":"著作权人应当按照合同约定期限交付作品。图书出版者应当按照合同约定的出版质量、期限出版图书。"},{"i":35,"n":"第三十五条","txt":"著作权人向报社、期刊社投稿的，自稿件发出之日起十五日内未收到报社通知决定刊登的，或者自稿件发出之日起三十日内未收到期刊社通知决定刊登的，可以将同一作品向其他报社、期刊社投稿。双方另有约定的除外。"},{"i":36,"n":"第三十六条","txt":"图书出版者经作者许可，可以对作品修改、删节。"},{"i":37,"n":"第三十七条","txt":"出版者有权许可或者禁止他人使用其出版的图书、期刊的版式设计。"},{"i":38,"n":"第三十八条","txt":"使用他人作品演出，表演者应当取得著作权人许可，并支付报酬。演出组织者组织演出，由该组织者取得著作权人许可，并支付报酬。"},{"i":39,"n":"第三十九条","txt":"表演者对其表演享有下列权利："},{"i":40,"n":"第四十条","txt":"演员为完成本演出单位的演出任务进行的表演为职务表演，演员享有表明身份和保护表演形象不受歪曲的权利，其他权利归属由当事人约定。当事人没有约定或者约定不明确的，职务表演的权利由演出单位享有。"},{"i":41,"n":"第四十一条","txt":"本法第三十九条第一款第一项、第二项规定的权利的保护期不受限制。"},{"i":42,"n":"第四十二条","txt":"录音录像制作者使用他人作品制作录音录像制品，应当取得著作权人许可，并支付报酬。"},{"i":43,"n":"第四十三条","txt":"录音录像制作者制作录音录像制品，应当同表演者订立合同，并支付报酬。"},{"i":44,"n":"第四十四条","txt":"录音录像制作者对其制作的录音录像制品，享有许可他人复制、发行、出租、通过信息网络向公众传播并获得报酬的权利；权利的保护期为五十年，截止于该制品首次制作完成后第五十年的12月31日。"},{"i":45,"n":"第四十五条","txt":"将录音制品用于有线或者无线公开传播，或者通过传送声音的技术设备向公众公开播送的，应当向录音制作者支付报酬。"},{"i":46,"n":"第四十六条","txt":"广播电台、电视台播放他人未发表的作品，应当取得著作权人许可，并支付报酬。"},{"i":47,"n":"第四十七条","txt":"广播电台、电视台有权禁止未经其许可的下列行为："},{"i":48,"n":"第四十八条","txt":"电视台播放他人的视听作品、录像制品，应当取得视听作品著作权人或者录像制作者许可，并支付报酬；播放他人的录像制品，还应当取得著作权人许可，并支付报酬。"},{"i":49,"n":"第四十九条","txt":"为保护著作权和与著作权有关的权利，权利人可以采取技术措施。"},{"i":50,"n":"第五十条","txt":"下列情形可以避开技术措施，但不得向他人提供避开技术措施的技术、装置或者部件，不得侵犯权利人依法享有的其他权利："},{"i":51,"n":"第五十一条","txt":"未经权利人许可，不得进行下列行为："},{"i":52,"n":"第五十二条","txt":"有下列侵权行为的，应当根据情况，承担停止侵害、消除影响、赔礼道歉、赔偿损失等民事责任："},{"i":53,"n":"第五十三条","txt":"有下列侵权行为的，应当根据情况，承担本法第五十二条规定的民事责任；侵权行为同时损害公共利益的，由主管著作权的部门责令停止侵权行为，予以警告，没收违法所得，没收、无害化销毁处理侵权复制品以及主要用于制作侵权复制品的材料、工具、设备等，违法经营额五万元以上的，可以并处违法经营额一倍以上五倍以下的罚款；没有违法经营额、违法经营额难以计算或者不足五万元的，可以并处二十五万元以下的罚款；构成犯罪的，依法追究刑事责任："},{"i":54,"n":"第五十四条","txt":"侵犯著作权或者与著作权有关的权利的，侵权人应当按照权利人因此受到的实际损失或者侵权人的违法所得给予赔偿；权利人的实际损失或者侵权人的违法所得难以计算的，可以参照该权利使用费给予赔偿。对故意侵犯著作权或者与著作权有关的权利，情节严重的，可以在按照上述方法确定数额的一倍以上五倍以下给予赔偿。"},{"i":55,"n":"第五十五条","txt":"主管著作权的部门对涉嫌侵犯著作权和与著作权有关的权利的行为进行查处时，可以询问有关当事人，调查与涉嫌违法行为有关的情况；对当事人涉嫌违法行为的场所和物品实施现场检查；查阅、复制与涉嫌违法行为有关的合同、发票、账簿以及其他有关资料；对于涉嫌违法行为的场所和物品，可以查封或者扣押。"},{"i":56,"n":"第五十六条","txt":"著作权人或者与著作权有关的权利人有证据证明他人正在实施或者即将实施侵犯其权利、妨碍其实现权利的行为，如不及时制止将会使其合法权益受到难以弥补的损害的，可以在起诉前依法向人民法院申请采取财产保全、责令作出一定行为或者禁止作出一定行为等措施。"},{"i":57,"n":"第五十七条","txt":"为制止侵权行为，在证据可能灭失或者以后难以取得的情况下，著作权人或者与著作权有关的权利人可以在起诉前依法向人民法院申请保全证据。"},{"i":58,"n":"第五十八条","txt":"人民法院审理案件，对于侵犯著作权或者与著作权有关的权利的，可以没收违法所得、侵权复制品以及进行违法活动的财物。"},{"i":59,"n":"第五十九条","txt":"复制品的出版者、制作者不能证明其出版、制作有合法授权的，复制品的发行者或者视听作品、计算机软件、录音录像制品的复制品的出租者不能证明其发行、出租的复制品有合法来源的，应当承担法律责任。"},{"i":60,"n":"第六十条","txt":"著作权纠纷可以调解，也可以根据当事人达成的书面仲裁协议或者著作权合同中的仲裁条款，向仲裁机构申请仲裁。"},{"i":61,"n":"第六十一条","txt":"当事人因不履行合同义务或者履行合同义务不符合约定而承担民事责任，以及当事人行使诉讼权利、申请保全等，适用有关法律的规定。"},{"i":62,"n":"第六十二条","txt":"本法所称的著作权即版权。"},{"i":63,"n":"第六十三条","txt":"本法第二条所称的出版，指作品的复制、发行。"},{"i":64,"n":"第六十四条","txt":"计算机软件、信息网络传播权的保护办法由国务院另行规定。"},{"i":65,"n":"第六十五条","txt":"摄影作品，其发表权、本法第十条第一款第五项至第十七项规定的权利的保护期在2021年6月1日前已经届满，但依据本法第二十三条第一款的规定仍在保护期内的，不再保护。"},{"i":66,"n":"第六十六条","txt":"本法规定的著作权人和出版者、表演者、录音录像制作者、广播电台、电视台的权利，在本法施行之日尚未超过本法规定的保护期的，依照本法予以保护。"},{"i":67,"n":"第六十七条","txt":"本法自1991年6月1日起施行。"}],"zhengquantouzijijinfa":[{"i":1,"n":"第一条","txt":"为了规范证券投资基金活动，保护投资人及相关当事人的合法权益，促进证券投资基金和资本市场的健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，公开或者非公开募集资金设立证券投资基金（以下简称基金），由基金管理人管理，基金托管人托管，为基金份额持有人的利益，进行证券投资活动，适用本法；本法未规定的，适用《中华人民共和国信托法》、《中华人民共和国证券法》和其他有关法律、行政法规的规定。"},{"i":3,"n":"第三条","txt":"基金管理人、基金托管人和基金份额持有人的权利、义务，依照本法在基金合同中约定。"},{"i":4,"n":"第四条","txt":"从事证券投资基金活动，应当遵循自愿、公平、诚实信用的原则，不得损害国家利益和社会公共利益。"},{"i":5,"n":"第五条","txt":"基金财产的债务由基金财产本身承担，基金份额持有人以其出资为限对基金财产的债务承担责任。但基金合同依照本法另有约定的，从其约定。"},{"i":6,"n":"第六条","txt":"基金财产的债权，不得与基金管理人、基金托管人固有财产的债务相抵销；不同基金财产的债权债务，不得相互抵销。"},{"i":7,"n":"第七条","txt":"非因基金财产本身承担的债务，不得对基金财产强制执行。"},{"i":8,"n":"第八条","txt":"基金财产投资的相关税收，由基金份额持有人承担，基金管理人或者其他扣缴义务人按照国家有关税收征收的规定代扣代缴。"},{"i":9,"n":"第九条","txt":"基金管理人、基金托管人管理、运用基金财产，基金服务机构从事基金服务活动，应当恪尽职守，履行诚实信用、谨慎勤勉的义务。"},{"i":10,"n":"第十条","txt":"基金管理人、基金托管人和基金服务机构，应当依照本法成立证券投资基金行业协会（以下简称基金行业协会），进行行业自律，协调行业关系，提供行业服务，促进行业发展。"},{"i":11,"n":"第十一条","txt":"国务院证券监督管理机构依法对证券投资基金活动实施监督管理；其派出机构依照授权履行职责。"},{"i":12,"n":"第十二条","txt":"基金管理人由依法设立的公司或者合伙企业担任。"},{"i":13,"n":"第十三条","txt":"设立管理公开募集基金的基金管理公司，应当具备下列条件，并经国务院证券监督管理机构批准："},{"i":14,"n":"第十四条","txt":"国务院证券监督管理机构应当自受理基金管理公司设立申请之日起六个月内依照本法第十三条规定的条件和审慎监管原则进行审查，作出批准或者不予批准的决定，并通知申请人；不予批准的，应当说明理由。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，不得担任公开募集基金的基金管理人的董事、监事、高级管理人员和其他从业人员："},{"i":16,"n":"第十六条","txt":"公开募集基金的基金管理人的董事、监事和高级管理人员，应当熟悉证券投资方面的法律、行政法规，具有三年以上与其所任职务相关的工作经历；高级管理人员还应当具备基金从业资格。"},{"i":17,"n":"第十七条","txt":"公开募集基金的基金管理人的董事、监事、高级管理人员和其他从业人员，其本人、配偶、利害关系人进行证券投资，应当事先向基金管理人申报，并不得与基金份额持有人发生利益冲突。"},{"i":18,"n":"第十八条","txt":"公开募集基金的基金管理人的董事、监事、高级管理人员和其他从业人员，不得担任基金托管人或者其他基金管理人的任何职务，不得从事损害基金财产和基金份额持有人利益的证券交易及其他活动。"},{"i":19,"n":"第十九条","txt":"公开募集基金的基金管理人应当履行下列职责："},{"i":20,"n":"第二十条","txt":"公开募集基金的基金管理人及其董事、监事、高级管理人员和其他从业人员不得有下列行为："},{"i":21,"n":"第二十一条","txt":"公开募集基金的基金管理人应当建立良好的内部治理结构，明确股东会、董事会、监事会和高级管理人员的职责权限，确保基金管理人独立运作。"},{"i":22,"n":"第二十二条","txt":"公开募集基金的基金管理人应当从管理基金的报酬中计提风险准备金。"},{"i":23,"n":"第二十三条","txt":"公开募集基金的基金管理人的股东、实际控制人应当按照国务院证券监督管理机构的规定及时履行重大事项报告义务，并不得有下列行为："},{"i":24,"n":"第二十四条","txt":"公开募集基金的基金管理人违法违规，或者其内部治理结构、稽核监控和风险控制管理不符合规定的，国务院证券监督管理机构应当责令其限期改正；逾期未改正，或者其行为严重危及该基金管理人的稳健运行、损害基金份额持有人合法权益的，国务院证券监督管理机构可以区别情形，对其采取下列措施："},{"i":25,"n":"第二十五条","txt":"公开募集基金的基金管理人的董事、监事、高级管理人员未能勤勉尽责，致使基金管理人存在重大违法违规行为或者重大风险的，国务院证券监督管理机构可以责令更换。"},{"i":26,"n":"第二十六条","txt":"公开募集基金的基金管理人违法经营或者出现重大风险，严重危害证券市场秩序、损害基金份额持有人利益的，国务院证券监督管理机构可以对该基金管理人采取责令停业整顿、指定其他机构托管、接管、取消基金管理资格或者撤销等监管措施。"},{"i":27,"n":"第二十七条","txt":"在公开募集基金的基金管理人被责令停业整顿、被依法指定托管、接管或者清算期间，或者出现重大风险时，经国务院证券监督管理机构批准，可以对该基金管理人直接负责的董事、监事、高级管理人员和其他直接责任人员采取下列措施："},{"i":28,"n":"第二十八条","txt":"有下列情形之一的，公开募集基金的基金管理人职责终止："},{"i":29,"n":"第二十九条","txt":"公开募集基金的基金管理人职责终止的，基金份额持有人大会应当在六个月内选任新基金管理人；新基金管理人产生前，由国务院证券监督管理机构指定临时基金管理人。"},{"i":30,"n":"第三十条","txt":"公开募集基金的基金管理人职责终止的，应当按照规定聘请会计师事务所对基金财产进行审计，并将审计结果予以公告，同时报国务院证券监督管理机构备案。"},{"i":31,"n":"第三十一条","txt":"对非公开募集基金的基金管理人进行规范的具体办法，由国务院金融监督管理机构依照本章的原则制定。"},{"i":32,"n":"第三十二条","txt":"基金托管人由依法设立的商业银行或者其他金融机构担任。"},{"i":33,"n":"第三十三条","txt":"担任基金托管人，应当具备下列条件："},{"i":34,"n":"第三十四条","txt":"本法第十五条、第十七条、第十八条的规定，适用于基金托管人的专门基金托管部门的高级管理人员和其他从业人员。"},{"i":35,"n":"第三十五条","txt":"基金托管人与基金管理人不得为同一机构，不得相互出资或者持有股份。"},{"i":36,"n":"第三十六条","txt":"基金托管人应当履行下列职责："},{"i":37,"n":"第三十七条","txt":"基金托管人发现基金管理人的投资指令违反法律、行政法规和其他有关规定，或者违反基金合同约定的，应当拒绝执行，立即通知基金管理人，并及时向国务院证券监督管理机构报告。"},{"i":38,"n":"第三十八条","txt":"本法第二十条、第二十二条的规定，适用于基金托管人。"},{"i":39,"n":"第三十九条","txt":"基金托管人不再具备本法规定的条件，或者未能勤勉尽责，在履行本法规定的职责时存在重大失误的，国务院证券监督管理机构、国务院银行业监督管理机构应当责令其改正；逾期未改正，或者其行为严重影响所托管基金的稳健运行、损害基金份额持有人利益的，国务院证券监督管理机构、国务院银行业监督管理机构可以区别情形，对其采取下列措施："},{"i":40,"n":"第四十条","txt":"国务院证券监督管理机构、国务院银行业监督管理机构对有下列情形之一的基金托管人，可以取消其基金托管资格："},{"i":41,"n":"第四十一条","txt":"有下列情形之一的，基金托管人职责终止："},{"i":42,"n":"第四十二条","txt":"基金托管人职责终止的，基金份额持有人大会应当在六个月内选任新基金托管人；新基金托管人产生前，由国务院证券监督管理机构指定临时基金托管人。"},{"i":43,"n":"第四十三条","txt":"基金托管人职责终止的，应当按照规定聘请会计师事务所对基金财产进行审计，并将审计结果予以公告，同时报国务院证券监督管理机构备案。"},{"i":44,"n":"第四十四条","txt":"基金合同应当约定基金的运作方式。"},{"i":45,"n":"第四十五条","txt":"基金的运作方式可以采用封闭式、开放式或者其他方式。"},{"i":46,"n":"第四十六条","txt":"基金份额持有人享有下列权利："},{"i":47,"n":"第四十七条","txt":"基金份额持有人大会由全体基金份额持有人组成，行使下列职权："},{"i":48,"n":"第四十八条","txt":"按照基金合同约定，基金份额持有人大会可以设立日常机构，行使下列职权："},{"i":49,"n":"第四十九条","txt":"基金份额持有人大会及其日常机构不得直接参与或者干涉基金的投资管理活动。"},{"i":50,"n":"第五十条","txt":"公开募集基金，应当经国务院证券监督管理机构注册。未经注册，不得公开或者变相公开募集基金。"},{"i":51,"n":"第五十一条","txt":"注册公开募集基金，由拟任基金管理人向国务院证券监督管理机构提交下列文件："},{"i":52,"n":"第五十二条","txt":"公开募集基金的基金合同应当包括下列内容："},{"i":53,"n":"第五十三条","txt":"公开募集基金的基金招募说明书应当包括下列内容："},{"i":54,"n":"第五十四条","txt":"国务院证券监督管理机构应当自受理公开募集基金的募集注册申请之日起六个月内依照法律、行政法规及国务院证券监督管理机构的规定进行审查，作出注册或者不予注册的决定，并通知申请人；不予注册的，应当说明理由。"},{"i":55,"n":"第五十五条","txt":"基金募集申请经注册后，方可发售基金份额。"},{"i":56,"n":"第五十六条","txt":"基金管理人应当在基金份额发售的三日前公布招募说明书、基金合同及其他有关文件。"},{"i":57,"n":"第五十七条","txt":"基金管理人应当自收到准予注册文件之日起六个月内进行基金募集。超过六个月开始募集，原注册的事项未发生实质性变化的，应当报国务院证券监督管理机构备案；发生实质性变化的，应当向国务院证券监督管理机构重新提交注册申请。"},{"i":58,"n":"第五十八条","txt":"基金募集期限届满，封闭式基金募集的基金份额总额达到准予注册规模的百分之八十以上，开放式基金募集的基金份额总额超过准予注册的最低募集份额总额，并且基金份额持有人人数符合国务院证券监督管理机构规定的，基金管理人应当自募集期限届满之日起十日内聘请法定验资机构验资，自收到验资报告之日起十日内，向国务院证券监督管理机构提交验资报告，办理基金备案手续，并予以公告。"},{"i":59,"n":"第五十九条","txt":"基金募集期间募集的资金应当存入专门账户，在基金募集行为结束前，任何人不得动用。"},{"i":60,"n":"第六十条","txt":"投资人交纳认购的基金份额的款项时，基金合同成立；基金管理人依照本法第五十八条的规定向国务院证券监督管理机构办理基金备案手续，基金合同生效。"},{"i":61,"n":"第六十一条","txt":"申请基金份额上市交易，基金管理人应当向证券交易所提出申请，证券交易所依法审核同意的，双方应当签订上市协议。"},{"i":62,"n":"第六十二条","txt":"基金份额上市交易，应当符合下列条件："},{"i":63,"n":"第六十三条","txt":"基金份额上市交易规则由证券交易所制定，报国务院证券监督管理机构批准。"},{"i":64,"n":"第六十四条","txt":"基金份额上市交易后，有下列情形之一的，由证券交易所终止其上市交易，并报国务院证券监督管理机构备案："},{"i":65,"n":"第六十五条","txt":"开放式基金的基金份额的申购、赎回、登记，由基金管理人或者其委托的基金服务机构办理。"},{"i":66,"n":"第六十六条","txt":"基金管理人应当在每个工作日办理基金份额的申购、赎回业务；基金合同另有约定的，从其约定。"},{"i":67,"n":"第六十七条","txt":"基金管理人应当按时支付赎回款项，但是下列情形除外："},{"i":68,"n":"第六十八条","txt":"开放式基金应当保持足够的现金或者政府债券，以备支付基金份额持有人的赎回款项。基金财产中应当保持的现金或者政府债券的具体比例，由国务院证券监督管理机构规定。"},{"i":69,"n":"第六十九条","txt":"基金份额的申购、赎回价格，依据申购、赎回日基金份额净值加、减有关费用计算。"},{"i":70,"n":"第七十条","txt":"基金份额净值计价出现错误时，基金管理人应当立即纠正，并采取合理的措施防止损失进一步扩大。计价错误达到基金份额净值百分之零点五时，基金管理人应当公告，并报国务院证券监督管理机构备案。"},{"i":71,"n":"第七十一条","txt":"基金管理人运用基金财产进行证券投资，除国务院证券监督管理机构另有规定外，应当采用资产组合的方式。"},{"i":72,"n":"第七十二条","txt":"基金财产应当用于下列投资："},{"i":73,"n":"第七十三条","txt":"基金财产不得用于下列投资或者活动："},{"i":74,"n":"第七十四条","txt":"基金管理人、基金托管人和其他基金信息披露义务人应当依法披露基金信息，并保证所披露信息的真实性、准确性和完整性。"},{"i":75,"n":"第七十五条","txt":"基金信息披露义务人应当确保应予披露的基金信息在国务院证券监督管理机构规定时间内披露，并保证投资人能够按照基金合同约定的时间和方式查阅或者复制公开披露的信息资料。"},{"i":76,"n":"第七十六条","txt":"公开披露的基金信息包括："},{"i":77,"n":"第七十七条","txt":"公开披露基金信息，不得有下列行为："},{"i":78,"n":"第七十八条","txt":"按照基金合同的约定或者基金份额持有人大会的决议，基金可以转换运作方式或者与其他基金合并。"},{"i":79,"n":"第七十九条","txt":"封闭式基金扩募或者延长基金合同期限，应当符合下列条件，并报国务院证券监督管理机构备案："},{"i":80,"n":"第八十条","txt":"有下列情形之一的，基金合同终止："},{"i":81,"n":"第八十一条","txt":"基金合同终止时，基金管理人应当组织清算组对基金财产进行清算。"},{"i":82,"n":"第八十二条","txt":"清算后的剩余基金财产，应当按照基金份额持有人所持份额比例进行分配。"},{"i":83,"n":"第八十三条","txt":"基金份额持有人大会由基金管理人召集。基金份额持有人大会设立日常机构的，由该日常机构召集；该日常机构未召集的，由基金管理人召集。基金管理人未按规定召集或者不能召集的，由基金托管人召集。"},{"i":84,"n":"第八十四条","txt":"召开基金份额持有人大会，召集人应当至少提前三十日公告基金份额持有人大会的召开时间、会议形式、审议事项、议事程序和表决方式等事项。"},{"i":85,"n":"第八十五条","txt":"基金份额持有人大会可以采取现场方式召开，也可以采取通讯等方式召开。"},{"i":86,"n":"第八十六条","txt":"基金份额持有人大会应当有代表二分之一以上基金份额的持有人参加，方可召开。"},{"i":87,"n":"第八十七条","txt":"非公开募集基金应当向合格投资者募集，合格投资者累计不得超过二百人。"},{"i":88,"n":"第八十八条","txt":"除基金合同另有约定外，非公开募集基金应当由基金托管人托管。"},{"i":89,"n":"第八十九条","txt":"担任非公开募集基金的基金管理人，应当按照规定向基金行业协会履行登记手续，报送基本情况。"},{"i":90,"n":"第九十条","txt":"未经登记，任何单位或者个人不得使用“基金”或者“基金管理”字样或者近似名称进行证券投资活动；但是，法律、行政法规另有规定的除外。"},{"i":91,"n":"第九十一条","txt":"非公开募集基金，不得向合格投资者之外的单位和个人募集资金，不得通过报刊、电台、电视台、互联网等公众传播媒体或者讲座、报告会、分析会等方式向不特定对象宣传推介。"},{"i":92,"n":"第九十二条","txt":"非公开募集基金，应当制定并签订基金合同。基金合同应当包括下列内容："},{"i":93,"n":"第九十三条","txt":"按照基金合同约定，非公开募集基金可以由部分基金份额持有人作为基金管理人负责基金的投资管理活动，并在基金财产不足以清偿其债务时对基金财产的债务承担无限连带责任。"},{"i":94,"n":"第九十四条","txt":"非公开募集基金募集完毕，基金管理人应当向基金行业协会备案。对募集的资金总额或者基金份额持有人的人数达到规定标准的基金，基金行业协会应当向国务院证券监督管理机构报告。"},{"i":95,"n":"第九十五条","txt":"基金管理人、基金托管人应当按照基金合同的约定，向基金份额持有人提供基金信息。"},{"i":96,"n":"第九十六条","txt":"专门从事非公开募集基金管理业务的基金管理人，其股东、高级管理人员、经营期限、管理的基金资产规模等符合规定条件的，经国务院证券监督管理机构核准，可以从事公开募集基金管理业务。"},{"i":97,"n":"第九十七条","txt":"从事公开募集基金的销售、销售支付、份额登记、估值、投资顾问、评价、信息技术系统服务等基金服务业务的机构，应当按照国务院证券监督管理机构的规定进行注册或者备案。"},{"i":98,"n":"第九十八条","txt":"基金销售机构应当向投资人充分揭示投资风险，并根据投资人的风险承担能力销售不同风险等级的基金产品。"},{"i":99,"n":"第九十九条","txt":"基金销售支付机构应当按照规定办理基金销售结算资金的划付，确保基金销售结算资金安全、及时划付。"},{"i":100,"n":"第一百条","txt":"基金销售结算资金、基金份额独立于基金销售机构、基金销售支付机构或者基金份额登记机构的自有财产。基金销售机构、基金销售支付机构或者基金份额登记机构破产或者清算时，基金销售结算资金、基金份额不属于其破产财产或者清算财产。非因投资人本身的债务或者法律规定的其他情形，不得查封、冻结、扣划或者强制执行基金销售结算资金、基金份额。"},{"i":101,"n":"第一百零一条","txt":"基金管理人可以委托基金服务机构代为办理基金的份额登记、核算、估值、投资顾问等事项，基金托管人可以委托基金服务机构代为办理基金的核算、估值、复核等事项，但基金管理人、基金托管人依法应当承担的责任不因委托而免除。"},{"i":102,"n":"第一百零二条","txt":"基金份额登记机构以电子介质登记的数据，是基金份额持有人权利归属的根据。基金份额持有人以基金份额出质的，质权自基金份额登记机构办理出质登记时设立。"},{"i":103,"n":"第一百零三条","txt":"基金投资顾问机构及其从业人员提供基金投资顾问服务，应当具有合理的依据，对其服务能力和经营业绩进行如实陈述，不得以任何方式承诺或者保证投资收益，不得损害服务对象的合法权益。"},{"i":104,"n":"第一百零四条","txt":"基金评价机构及其从业人员应当客观公正，按照依法制定的业务规则开展基金评价业务，禁止误导投资人，防范可能发生的利益冲突。"},{"i":105,"n":"第一百零五条","txt":"基金管理人、基金托管人、基金服务机构的信息技术系统，应当符合规定的要求。国务院证券监督管理机构可以要求信息技术系统服务机构提供该信息技术系统的相关资料。"},{"i":106,"n":"第一百零六条","txt":"律师事务所、会计师事务所接受基金管理人、基金托管人的委托，为有关基金业务活动出具法律意见书、审计报告、内部控制评价报告等文件，应当勤勉尽责，对所依据的文件资料内容的真实性、准确性、完整性进行核查和验证。其制作、出具的文件有虚假记载、误导性陈述或者重大遗漏，给他人财产造成损失的，应当与委托人承担连带赔偿责任。"},{"i":107,"n":"第一百零七条","txt":"基金服务机构应当勤勉尽责、恪尽职守，建立应急等风险管理制度和灾难备份系统，不得泄露与基金份额持有人、基金投资运作相关的非公开信息。"},{"i":108,"n":"第一百零八条","txt":"基金行业协会是证券投资基金行业的自律性组织，是社会团体法人。"},{"i":109,"n":"第一百零九条","txt":"基金行业协会的权力机构为全体会员组成的会员大会。"},{"i":110,"n":"第一百一十条","txt":"基金行业协会章程由会员大会制定，并报国务院证券监督管理机构备案。"},{"i":111,"n":"第一百一十一条","txt":"基金行业协会履行下列职责："},{"i":112,"n":"第一百一十二条","txt":"国务院证券监督管理机构依法履行下列职责："},{"i":113,"n":"第一百一十三条","txt":"国务院证券监督管理机构依法履行职责，有权采取下列措施："},{"i":114,"n":"第一百一十四条","txt":"国务院证券监督管理机构工作人员依法履行职责，进行调查或者检查时，不得少于二人，并应当出示合法证件；对调查或者检查中知悉的商业秘密负有保密的义务。"},{"i":115,"n":"第一百一十五条","txt":"国务院证券监督管理机构工作人员应当忠于职守，依法办事，公正廉洁，接受监督，不得利用职务牟取私利。"},{"i":116,"n":"第一百一十六条","txt":"国务院证券监督管理机构依法履行职责时，被调查、检查的单位和个人应当配合，如实提供有关文件和资料，不得拒绝、阻碍和隐瞒。"},{"i":117,"n":"第一百一十七条","txt":"国务院证券监督管理机构依法履行职责，发现违法行为涉嫌犯罪的，应当将案件移送司法机关处理。"},{"i":118,"n":"第一百一十八条","txt":"国务院证券监督管理机构工作人员在任职期间，或者离职后在《中华人民共和国公务员法》规定的期限内，不得在被监管的机构中担任职务。"},{"i":119,"n":"第一百一十九条","txt":"违反本法规定，未经批准擅自设立基金管理公司或者未经核准从事公开募集基金管理业务的，由证券监督管理机构予以取缔或者责令改正，没收违法所得，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处三万元以上三十万元以下罚款。"},{"i":120,"n":"第一百二十条","txt":"基金管理人的董事、监事、高级管理人员和其他从业人员，基金托管人的专门基金托管部门的高级管理人员和其他从业人员，未按照本法第十七条第一款规定申报的，责令改正，处三万元以上十万元以下罚款。"},{"i":121,"n":"第一百二十一条","txt":"基金管理人的董事、监事、高级管理人员和其他从业人员，基金托管人的专门基金托管部门的高级管理人员和其他从业人员违反本法第十八条规定的，责令改正，没收违法所得，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款；情节严重的，撤销基金从业资格。"},{"i":122,"n":"第一百二十二条","txt":"基金管理人、基金托管人违反本法规定，未对基金财产实行分别管理或者分账保管，责令改正，处五万元以上五十万元以下罚款；对直接负责的主管人员和其他直接责任人员给予警告，暂停或者撤销基金从业资格，并处三万元以上三十万元以下罚款。"},{"i":123,"n":"第一百二十三条","txt":"基金管理人、基金托管人及其董事、监事、高级管理人员和其他从业人员有本法第二十条所列行为之一的，责令改正，没收违法所得，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款；基金管理人、基金托管人有上述行为的，还应当对其直接负责的主管人员和其他直接责任人员给予警告，暂停或者撤销基金从业资格，并处三万元以上三十万元以下罚款。"},{"i":124,"n":"第一百二十四条","txt":"基金管理人的股东、实际控制人违反本法第二十三条规定的，责令改正，没收违法所得，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款；对直接负责的主管人员和其他直接责任人员给予警告，暂停或者撤销基金或证券从业资格，并处三万元以上三十万元以下罚款。"},{"i":125,"n":"第一百二十五条","txt":"未经核准，擅自从事基金托管业务的，责令停止，没收违法所得，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款；对直接负责的主管人员和其他直接责任人员给予警告，并处三万元以上三十万元以下罚款。"},{"i":126,"n":"第一百二十六条","txt":"基金管理人、基金托管人违反本法规定，相互出资或者持有股份的，责令改正，可以处十万元以下罚款。"},{"i":127,"n":"第一百二十七条","txt":"违反本法规定，擅自公开或者变相公开募集基金的，责令停止，返还所募资金和加计的银行同期存款利息，没收违法所得，并处所募资金金额百分之一以上百分之五以下罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处五万元以上五十万元以下罚款。"},{"i":128,"n":"第一百二十八条","txt":"违反本法第五十九条规定，动用募集的资金的，责令返还，没收违法所得，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足五十万元的，并处五万元以上五十万元以下罚款；对直接负责的主管人员和其他直接责任人员给予警告，并处三万元以上三十万元以下罚款。"},{"i":129,"n":"第一百二十九条","txt":"基金管理人、基金托管人有本法第七十三条第一款第一项至第五项和第七项所列行为之一，或者违反本法第七十三条第二款规定的，责令改正，处十万元以上一百万元以下罚款；对直接负责的主管人员和其他直接责任人员给予警告，暂停或者撤销基金从业资格，并处三万元以上三十万元以下罚款。"},{"i":130,"n":"第一百三十条","txt":"基金管理人、基金托管人有本法第七十三条第一款第六项规定行为的，除依照《中华人民共和国证券法》的有关规定处罚外，对直接负责的主管人员和其他直接责任人员暂停或者撤销基金从业资格。"},{"i":131,"n":"第一百三十一条","txt":"基金信息披露义务人不依法披露基金信息或者披露的信息有虚假记载、误导性陈述或者重大遗漏的，责令改正，没收违法所得，并处十万元以上一百万元以下罚款；对直接负责的主管人员和其他直接责任人员给予警告，暂停或者撤销基金从业资格，并处三万元以上三十万元以下罚款。"},{"i":132,"n":"第一百三十二条","txt":"基金管理人或者基金托管人不按照规定召集基金份额持有人大会的，责令改正，可以处五万元以下罚款；对直接负责的主管人员和其他直接责任人员给予警告，暂停或者撤销基金从业资格。"},{"i":133,"n":"第一百三十三条","txt":"违反本法规定，未经登记，使用“基金”或者“基金管理”字样或者近似名称进行证券投资活动的，没收违法所得，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处三万元以上三十万元以下罚款。"},{"i":134,"n":"第一百三十四条","txt":"违反本法规定，非公开募集基金募集完毕，基金管理人未备案的，处十万元以上三十万元以下罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处三万元以上十万元以下罚款。"},{"i":135,"n":"第一百三十五条","txt":"违反本法规定，向合格投资者之外的单位或者个人非公开募集资金或者转让基金份额的，没收违法所得，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处三万元以上三十万元以下罚款。"},{"i":136,"n":"第一百三十六条","txt":"违反本法规定，擅自从事公开募集基金的基金服务业务的，责令改正，没收违法所得，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足三十万元的，并处十万元以上三十万元以下罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处三万元以上十万元以下罚款。"},{"i":137,"n":"第一百三十七条","txt":"基金销售机构未向投资人充分揭示投资风险并误导其购买与其风险承担能力不相当的基金产品的，处十万元以上三十万元以下罚款；情节严重的，责令其停止基金服务业务。对直接负责的主管人员和其他直接责任人员给予警告，撤销基金从业资格，并处三万元以上十万元以下罚款。"},{"i":138,"n":"第一百三十八条","txt":"基金销售支付机构未按照规定划付基金销售结算资金的，处十万元以上三十万元以下罚款；情节严重的，责令其停止基金服务业务。对直接负责的主管人员和其他直接责任人员给予警告，撤销基金从业资格，并处三万元以上十万元以下罚款。"},{"i":139,"n":"第一百三十九条","txt":"挪用基金销售结算资金或者基金份额的，责令改正，没收违法所得，并处违法所得一倍以上五倍以下罚款；没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处三万元以上三十万元以下罚款。"},{"i":140,"n":"第一百四十条","txt":"基金份额登记机构未妥善保存或者备份基金份额登记数据的，责令改正，给予警告，并处十万元以上三十万元以下罚款；情节严重的，责令其停止基金服务业务。对直接负责的主管人员和其他直接责任人员给予警告，撤销基金从业资格，并处三万元以上十万元以下罚款。"},{"i":141,"n":"第一百四十一条","txt":"基金投资顾问机构、基金评价机构及其从业人员违反本法规定开展投资顾问、基金评价服务的，处十万元以上三十万元以下罚款；情节严重的，责令其停止基金服务业务。对直接负责的主管人员和其他直接责任人员给予警告，撤销基金从业资格，并处三万元以上十万元以下罚款。"},{"i":142,"n":"第一百四十二条","txt":"信息技术系统服务机构未按照规定向国务院证券监督管理机构提供相关信息技术系统资料，或者提供的信息技术系统资料虚假、有重大遗漏的，责令改正，处三万元以上十万元以下罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处一万元以上三万元以下罚款。"},{"i":143,"n":"第一百四十三条","txt":"会计师事务所、律师事务所未勤勉尽责，所出具的文件有虚假记载、误导性陈述或者重大遗漏的，责令改正，没收业务收入，暂停或者撤销相关业务许可，并处业务收入一倍以上五倍以下罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处三万元以上十万元以下罚款。"},{"i":144,"n":"第一百四十四条","txt":"基金服务机构未建立应急等风险管理制度和灾难备份系统，或者泄露与基金份额持有人、基金投资运作相关的非公开信息的，处十万元以上三十万元以下罚款；情节严重的，责令其停止基金服务业务。对直接负责的主管人员和其他直接责任人员给予警告，撤销基金从业资格，并处三万元以上十万元以下罚款。"},{"i":145,"n":"第一百四十五条","txt":"违反本法规定，给基金财产、基金份额持有人或者投资人造成损害的，依法承担赔偿责任。"},{"i":146,"n":"第一百四十六条","txt":"证券监督管理机构工作人员玩忽职守、滥用职权、徇私舞弊或者利用职务上的便利索取或者收受他人财物的，依法给予行政处分。"},{"i":147,"n":"第一百四十七条","txt":"拒绝、阻碍证券监督管理机构及其工作人员依法行使监督检查、调查职权未使用暴力、威胁方法的，依法给予治安管理处罚。"},{"i":148,"n":"第一百四十八条","txt":"违反法律、行政法规或者国务院证券监督管理机构的有关规定，情节严重的，国务院证券监督管理机构可以对有关责任人员采取证券市场禁入的措施。"},{"i":149,"n":"第一百四十九条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":150,"n":"第一百五十条","txt":"违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金，其财产不足以同时支付时，先承担民事赔偿责任。"},{"i":151,"n":"第一百五十一条","txt":"依照本法规定，基金管理人、基金托管人、基金服务机构应当承担的民事赔偿责任和缴纳的罚款、罚金，由基金管理人、基金托管人、基金服务机构以其固有财产承担。"},{"i":152,"n":"第一百五十二条","txt":"在中华人民共和国境内募集投资境外证券的基金，以及合格境外投资者在境内进行证券投资，应当经国务院证券监督管理机构批准，具体办法由国务院证券监督管理机构会同国务院有关部门规定，报国务院批准。"},{"i":153,"n":"第一百五十三条","txt":"公开或者非公开募集资金，以进行证券投资活动为目的设立的公司或者合伙企业，资产由基金管理人或者普通合伙人管理的，其证券投资活动适用本法。"},{"i":154,"n":"第一百五十四条","txt":"本法自2013年6月1日起施行。"}],"zhengquanfa":[{"i":1,"n":"第一条","txt":"为了规范证券发行和交易行为，保护投资者的合法权益，维护社会经济秩序和社会公共利益，促进社会主义市场经济的发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，股票、公司债券、存托凭证和国务院依法认定的其他证券的发行和交易，适用本法；本法未规定的，适用《中华人民共和国公司法》和其他法律、行政法规的规定。"},{"i":3,"n":"第三条","txt":"证券的发行、交易活动，必须遵循公开、公平、公正的原则。"},{"i":4,"n":"第四条","txt":"证券发行、交易活动的当事人具有平等的法律地位，应当遵守自愿、有偿、诚实信用的原则。"},{"i":5,"n":"第五条","txt":"证券的发行、交易活动，必须遵守法律、行政法规；禁止欺诈、内幕交易和操纵证券市场的行为。"},{"i":6,"n":"第六条","txt":"证券业和银行业、信托业、保险业实行分业经营、分业管理，证券公司与银行、信托、保险业务机构分别设立。国家另有规定的除外。"},{"i":7,"n":"第七条","txt":"国务院证券监督管理机构依法对全国证券市场实行集中统一监督管理。"},{"i":8,"n":"第八条","txt":"国家审计机关依法对证券交易场所、证券公司、证券登记结算机构、证券监督管理机构进行审计监督。"},{"i":9,"n":"第九条","txt":"公开发行证券，必须符合法律、行政法规规定的条件，并依法报经国务院证券监督管理机构或者国务院授权的部门注册。未经依法注册，任何单位和个人不得公开发行证券。证券发行注册制的具体范围、实施步骤，由国务院规定。"},{"i":10,"n":"第十条","txt":"发行人申请公开发行股票、可转换为股票的公司债券，依法采取承销方式的，或者公开发行法律、行政法规规定实行保荐制度的其他证券的，应当聘请证券公司担任保荐人。"},{"i":11,"n":"第十一条","txt":"设立股份有限公司公开发行股票，应当符合《中华人民共和国公司法》规定的条件和经国务院批准的国务院证券监督管理机构规定的其他条件，向国务院证券监督管理机构报送募股申请和下列文件："},{"i":12,"n":"第十二条","txt":"公司首次公开发行新股，应当符合下列条件："},{"i":13,"n":"第十三条","txt":"公司公开发行新股，应当报送募股申请和下列文件："},{"i":14,"n":"第十四条","txt":"公司对公开发行股票所募集资金，必须按照招股说明书或者其他公开发行募集文件所列资金用途使用；改变资金用途，必须经股东大会作出决议。擅自改变用途，未作纠正的，或者未经股东大会认可的，不得公开发行新股。"},{"i":15,"n":"第十五条","txt":"公开发行公司债券，应当符合下列条件："},{"i":16,"n":"第十六条","txt":"申请公开发行公司债券，应当向国务院授权的部门或者国务院证券监督管理机构报送下列文件："},{"i":17,"n":"第十七条","txt":"有下列情形之一的，不得再次公开发行公司债券："},{"i":18,"n":"第十八条","txt":"发行人依法申请公开发行证券所报送的申请文件的格式、报送方式，由依法负责注册的机构或者部门规定。"},{"i":19,"n":"第十九条","txt":"发行人报送的证券发行申请文件，应当充分披露投资者作出价值判断和投资决策所必需的信息，内容应当真实、准确、完整。"},{"i":20,"n":"第二十条","txt":"发行人申请首次公开发行股票的，在提交申请文件后，应当按照国务院证券监督管理机构的规定预先披露有关申请文件。"},{"i":21,"n":"第二十一条","txt":"国务院证券监督管理机构或者国务院授权的部门依照法定条件负责证券发行申请的注册。证券公开发行注册的具体办法由国务院规定。"},{"i":22,"n":"第二十二条","txt":"国务院证券监督管理机构或者国务院授权的部门应当自受理证券发行申请文件之日起三个月内，依照法定条件和法定程序作出予以注册或者不予注册的决定，发行人根据要求补充、修改发行申请文件的时间不计算在内。不予注册的，应当说明理由。"},{"i":23,"n":"第二十三条","txt":"证券发行申请经注册后，发行人应当依照法律、行政法规的规定，在证券公开发行前公告公开发行募集文件，并将该文件置备于指定场所供公众查阅。"},{"i":24,"n":"第二十四条","txt":"国务院证券监督管理机构或者国务院授权的部门对已作出的证券发行注册的决定，发现不符合法定条件或者法定程序，尚未发行证券的，应当予以撤销，停止发行。已经发行尚未上市的，撤销发行注册决定，发行人应当按照发行价并加算银行同期存款利息返还证券持有人；发行人的控股股东、实际控制人以及保荐人，应当与发行人承担连带责任，但是能够证明自己没有过错的除外。"},{"i":25,"n":"第二十五条","txt":"股票依法发行后，发行人经营与收益的变化，由发行人自行负责；由此变化引致的投资风险，由投资者自行负责。"},{"i":26,"n":"第二十六条","txt":"发行人向不特定对象发行的证券，法律、行政法规规定应当由证券公司承销的，发行人应当同证券公司签订承销协议。证券承销业务采取代销或者包销方式。"},{"i":27,"n":"第二十七条","txt":"公开发行证券的发行人有权依法自主选择承销的证券公司。"},{"i":28,"n":"第二十八条","txt":"证券公司承销证券，应当同发行人签订代销或者包销协议，载明下列事项："},{"i":29,"n":"第二十九条","txt":"证券公司承销证券，应当对公开发行募集文件的真实性、准确性、完整性进行核查。发现有虚假记载、误导性陈述或者重大遗漏的，不得进行销售活动；已经销售的，必须立即停止销售活动，并采取纠正措施。"},{"i":30,"n":"第三十条","txt":"向不特定对象发行证券聘请承销团承销的，承销团应当由主承销和参与承销的证券公司组成。"},{"i":31,"n":"第三十一条","txt":"证券的代销、包销期限最长不得超过九十日。"},{"i":32,"n":"第三十二条","txt":"股票发行采取溢价发行的，其发行价格由发行人与承销的证券公司协商确定。"},{"i":33,"n":"第三十三条","txt":"股票发行采用代销方式，代销期限届满，向投资者出售的股票数量未达到拟公开发行股票数量百分之七十的，为发行失败。发行人应当按照发行价并加算银行同期存款利息返还股票认购人。"},{"i":34,"n":"第三十四条","txt":"公开发行股票，代销、包销期限届满，发行人应当在规定的期限内将股票发行情况报国务院证券监督管理机构备案。"},{"i":35,"n":"第三十五条","txt":"证券交易当事人依法买卖的证券，必须是依法发行并交付的证券。"},{"i":36,"n":"第三十六条","txt":"依法发行的证券，《中华人民共和国公司法》和其他法律对其转让期限有限制性规定的，在限定的期限内不得转让。"},{"i":37,"n":"第三十七条","txt":"公开发行的证券，应当在依法设立的证券交易所上市交易或者在国务院批准的其他全国性证券交易场所交易。"},{"i":38,"n":"第三十八条","txt":"证券在证券交易所上市交易，应当采用公开的集中交易方式或者国务院证券监督管理机构批准的其他方式。"},{"i":39,"n":"第三十九条","txt":"证券交易当事人买卖的证券可以采用纸面形式或者国务院证券监督管理机构规定的其他形式。"},{"i":40,"n":"第四十条","txt":"证券交易场所、证券公司和证券登记结算机构的从业人员，证券监督管理机构的工作人员以及法律、行政法规规定禁止参与股票交易的其他人员，在任期或者法定限期内，不得直接或者以化名、借他人名义持有、买卖股票或者其他具有股权性质的证券，也不得收受他人赠送的股票或者其他具有股权性质的证券。"},{"i":41,"n":"第四十一条","txt":"证券交易场所、证券公司、证券登记结算机构、证券服务机构及其工作人员应当依法为投资者的信息保密，不得非法买卖、提供或者公开投资者的信息。"},{"i":42,"n":"第四十二条","txt":"为证券发行出具审计报告或者法律意见书等文件的证券服务机构和人员，在该证券承销期内和期满后六个月内，不得买卖该证券。"},{"i":43,"n":"第四十三条","txt":"证券交易的收费必须合理，并公开收费项目、收费标准和管理办法。"},{"i":44,"n":"第四十四条","txt":"上市公司、股票在国务院批准的其他全国性证券交易场所交易的公司持有百分之五以上股份的股东、董事、监事、高级管理人员，将其持有的该公司的股票或者其他具有股权性质的证券在买入后六个月内卖出，或者在卖出后六个月内又买入，由此所得收益归该公司所有，公司董事会应当收回其所得收益。但是，证券公司因购入包销售后剩余股票而持有百分之五以上股份，以及有国务院证券监督管理机构规定的其他情形的除外。"},{"i":45,"n":"第四十五条","txt":"通过计算机程序自动生成或者下达交易指令进行程序化交易的，应当符合国务院证券监督管理机构的规定，并向证券交易所报告，不得影响证券交易所系统安全或者正常交易秩序。"},{"i":46,"n":"第四十六条","txt":"申请证券上市交易，应当向证券交易所提出申请，由证券交易所依法审核同意，并由双方签订上市协议。"},{"i":47,"n":"第四十七条","txt":"申请证券上市交易，应当符合证券交易所上市规则规定的上市条件。"},{"i":48,"n":"第四十八条","txt":"上市交易的证券，有证券交易所规定的终止上市情形的，由证券交易所按照业务规则终止其上市交易。"},{"i":49,"n":"第四十九条","txt":"对证券交易所作出的不予上市交易、终止上市交易决定不服的，可以向证券交易所设立的复核机构申请复核。"},{"i":50,"n":"第五十条","txt":"禁止证券交易内幕信息的知情人和非法获取内幕信息的人利用内幕信息从事证券交易活动。"},{"i":51,"n":"第五十一条","txt":"证券交易内幕信息的知情人包括："},{"i":52,"n":"第五十二条","txt":"证券交易活动中，涉及发行人的经营、财务或者对该发行人证券的市场价格有重大影响的尚未公开的信息，为内幕信息。"},{"i":53,"n":"第五十三条","txt":"证券交易内幕信息的知情人和非法获取内幕信息的人，在内幕信息公开前，不得买卖该公司的证券，或者泄露该信息，或者建议他人买卖该证券。"},{"i":54,"n":"第五十四条","txt":"禁止证券交易场所、证券公司、证券登记结算机构、证券服务机构和其他金融机构的从业人员、有关监管部门或者行业协会的工作人员，利用因职务便利获取的内幕信息以外的其他未公开的信息，违反规定，从事与该信息相关的证券交易活动，或者明示、暗示他人从事相关交易活动。"},{"i":55,"n":"第五十五条","txt":"禁止任何人以下列手段操纵证券市场，影响或者意图影响证券交易价格或者证券交易量："},{"i":56,"n":"第五十六条","txt":"禁止任何单位和个人编造、传播虚假信息或者误导性信息，扰乱证券市场。"},{"i":57,"n":"第五十七条","txt":"禁止证券公司及其从业人员从事下列损害客户利益的行为："},{"i":58,"n":"第五十八条","txt":"任何单位和个人不得违反规定，出借自己的证券账户或者借用他人的证券账户从事证券交易。"},{"i":59,"n":"第五十九条","txt":"依法拓宽资金入市渠道，禁止资金违规流入股市。"},{"i":60,"n":"第六十条","txt":"国有独资企业、国有独资公司、国有资本控股公司买卖上市交易的股票，必须遵守国家有关规定。"},{"i":61,"n":"第六十一条","txt":"证券交易场所、证券公司、证券登记结算机构、证券服务机构及其从业人员对证券交易中发现的禁止的交易行为，应当及时向证券监督管理机构报告。"},{"i":62,"n":"第六十二条","txt":"投资者可以采取要约收购、协议收购及其他合法方式收购上市公司。"},{"i":63,"n":"第六十三条","txt":"通过证券交易所的证券交易，投资者持有或者通过协议、其他安排与他人共同持有一个上市公司已发行的有表决权股份达到百分之五时，应当在该事实发生之日起三日内，向国务院证券监督管理机构、证券交易所作出书面报告，通知该上市公司，并予公告，在上述期限内不得再行买卖该上市公司的股票，但国务院证券监督管理机构规定的情形除外。"},{"i":64,"n":"第六十四条","txt":"依照前条规定所作的公告，应当包括下列内容："},{"i":65,"n":"第六十五条","txt":"通过证券交易所的证券交易，投资者持有或者通过协议、其他安排与他人共同持有一个上市公司已发行的有表决权股份达到百分之三十时，继续进行收购的，应当依法向该上市公司所有股东发出收购上市公司全部或者部分股份的要约。"},{"i":66,"n":"第六十六条","txt":"依照前条规定发出收购要约，收购人必须公告上市公司收购报告书，并载明下列事项："},{"i":67,"n":"第六十七条","txt":"收购要约约定的收购期限不得少于三十日，并不得超过六十日。"},{"i":68,"n":"第六十八条","txt":"在收购要约确定的承诺期限内，收购人不得撤销其收购要约。收购人需要变更收购要约的，应当及时公告，载明具体变更事项，且不得存在下列情形："},{"i":69,"n":"第六十九条","txt":"收购要约提出的各项收购条件，适用于被收购公司的所有股东。"},{"i":70,"n":"第七十条","txt":"采取要约收购方式的，收购人在收购期限内，不得卖出被收购公司的股票，也不得采取要约规定以外的形式和超出要约的条件买入被收购公司的股票。"},{"i":71,"n":"第七十一条","txt":"采取协议收购方式的，收购人可以依照法律、行政法规的规定同被收购公司的股东以协议方式进行股份转让。"},{"i":72,"n":"第七十二条","txt":"采取协议收购方式的，协议双方可以临时委托证券登记结算机构保管协议转让的股票，并将资金存放于指定的银行。"},{"i":73,"n":"第七十三条","txt":"采取协议收购方式的，收购人收购或者通过协议、其他安排与他人共同收购一个上市公司已发行的有表决权股份达到百分之三十时，继续进行收购的，应当依法向该上市公司所有股东发出收购上市公司全部或者部分股份的要约。但是，按照国务院证券监督管理机构的规定免除发出要约的除外。"},{"i":74,"n":"第七十四条","txt":"收购期限届满，被收购公司股权分布不符合证券交易所规定的上市交易要求的，该上市公司的股票应当由证券交易所依法终止上市交易；其余仍持有被收购公司股票的股东，有权向收购人以收购要约的同等条件出售其股票，收购人应当收购。"},{"i":75,"n":"第七十五条","txt":"在上市公司收购中，收购人持有的被收购的上市公司的股票，在收购行为完成后的十八个月内不得转让。"},{"i":76,"n":"第七十六条","txt":"收购行为完成后，收购人与被收购公司合并，并将该公司解散的，被解散公司的原有股票由收购人依法更换。"},{"i":77,"n":"第七十七条","txt":"国务院证券监督管理机构依照本法制定上市公司收购的具体办法。"},{"i":78,"n":"第七十八条","txt":"发行人及法律、行政法规和国务院证券监督管理机构规定的其他信息披露义务人，应当及时依法履行信息披露义务。"},{"i":79,"n":"第七十九条","txt":"上市公司、公司债券上市交易的公司、股票在国务院批准的其他全国性证券交易场所交易的公司，应当按照国务院证券监督管理机构和证券交易场所规定的内容和格式编制定期报告，并按照以下规定报送和公告："},{"i":80,"n":"第八十条","txt":"发生可能对上市公司、股票在国务院批准的其他全国性证券交易场所交易的公司的股票交易价格产生较大影响的重大事件，投资者尚未得知时，公司应当立即将有关该重大事件的情况向国务院证券监督管理机构和证券交易场所报送临时报告，并予公告，说明事件的起因、目前的状态和可能产生的法律后果。"},{"i":81,"n":"第八十一条","txt":"发生可能对上市交易公司债券的交易价格产生较大影响的重大事件，投资者尚未得知时，公司应当立即将有关该重大事件的情况向国务院证券监督管理机构和证券交易场所报送临时报告，并予公告，说明事件的起因、目前的状态和可能产生的法律后果。"},{"i":82,"n":"第八十二条","txt":"发行人的董事、高级管理人员应当对证券发行文件和定期报告签署书面确认意见。"},{"i":83,"n":"第八十三条","txt":"信息披露义务人披露的信息应当同时向所有投资者披露，不得提前向任何单位和个人泄露。但是，法律、行政法规另有规定的除外。"},{"i":84,"n":"第八十四条","txt":"除依法需要披露的信息之外，信息披露义务人可以自愿披露与投资者作出价值判断和投资决策有关的信息，但不得与依法披露的信息相冲突，不得误导投资者。"},{"i":85,"n":"第八十五条","txt":"信息披露义务人未按照规定披露信息，或者公告的证券发行文件、定期报告、临时报告及其他信息披露资料存在虚假记载、误导性陈述或者重大遗漏，致使投资者在证券交易中遭受损失的，信息披露义务人应当承担赔偿责任；发行人的控股股东、实际控制人、董事、监事、高级管理人员和其他直接责任人员以及保荐人、承销的证券公司及其直接责任人员，应当与发行人承担连带赔偿责任，但是能够证明自己没有过错的除外。"},{"i":86,"n":"第八十六条","txt":"依法披露的信息，应当在证券交易场所的网站和符合国务院证券监督管理机构规定条件的媒体发布，同时将其置备于公司住所、证券交易场所，供社会公众查阅。"},{"i":87,"n":"第八十七条","txt":"国务院证券监督管理机构对信息披露义务人的信息披露行为进行监督管理。"},{"i":88,"n":"第八十八条","txt":"证券公司向投资者销售证券、提供服务时，应当按照规定充分了解投资者的基本情况、财产状况、金融资产状况、投资知识和经验、专业能力等相关信息；如实说明证券、服务的重要内容，充分揭示投资风险；销售、提供与投资者上述状况相匹配的证券、服务。"},{"i":89,"n":"第八十九条","txt":"根据财产状况、金融资产状况、投资知识和经验、专业能力等因素，投资者可以分为普通投资者和专业投资者。专业投资者的标准由国务院证券监督管理机构规定。"},{"i":90,"n":"第九十条","txt":"上市公司董事会、独立董事、持有百分之一以上有表决权股份的股东或者依照法律、行政法规或者国务院证券监督管理机构的规定设立的投资者保护机构（以下简称投资者保护机构），可以作为征集人，自行或者委托证券公司、证券服务机构，公开请求上市公司股东委托其代为出席股东大会，并代为行使提案权、表决权等股东权利。"},{"i":91,"n":"第九十一条","txt":"上市公司应当在章程中明确分配现金股利的具体安排和决策程序，依法保障股东的资产收益权。"},{"i":92,"n":"第九十二条","txt":"公开发行公司债券的，应当设立债券持有人会议，并应当在募集说明书中说明债券持有人会议的召集程序、会议规则和其他重要事项。"},{"i":93,"n":"第九十三条","txt":"发行人因欺诈发行、虚假陈述或者其他重大违法行为给投资者造成损失的，发行人的控股股东、实际控制人、相关的证券公司可以委托投资者保护机构，就赔偿事宜与受到损失的投资者达成协议，予以先行赔付。先行赔付后，可以依法向发行人以及其他连带责任人追偿。"},{"i":94,"n":"第九十四条","txt":"投资者与发行人、证券公司等发生纠纷的，双方可以向投资者保护机构申请调解。普通投资者与证券公司发生证券业务纠纷，普通投资者提出调解请求的，证券公司不得拒绝。"},{"i":95,"n":"第九十五条","txt":"投资者提起虚假陈述等证券民事赔偿诉讼时，诉讼标的是同一种类，且当事人一方人数众多的，可以依法推选代表人进行诉讼。"},{"i":96,"n":"第九十六条","txt":"证券交易所、国务院批准的其他全国性证券交易场所为证券集中交易提供场所和设施，组织和监督证券交易，实行自律管理，依法登记，取得法人资格。"},{"i":97,"n":"第九十七条","txt":"证券交易所、国务院批准的其他全国性证券交易场所可以根据证券品种、行业特点、公司规模等因素设立不同的市场层次。"},{"i":98,"n":"第九十八条","txt":"按照国务院规定设立的区域性股权市场为非公开发行证券的发行、转让提供场所和设施，具体管理办法由国务院规定。"},{"i":99,"n":"第九十九条","txt":"证券交易所履行自律管理职能，应当遵守社会公共利益优先原则，维护市场的公平、有序、透明。"},{"i":100,"n":"第一百条","txt":"证券交易所必须在其名称中标明证券交易所字样。其他任何单位或者个人不得使用证券交易所或者近似的名称。"},{"i":101,"n":"第一百零一条","txt":"证券交易所可以自行支配的各项费用收入，应当首先用于保证其证券交易场所和设施的正常运行并逐步改善。"},{"i":102,"n":"第一百零二条","txt":"实行会员制的证券交易所设理事会、监事会。"},{"i":103,"n":"第一百零三条","txt":"有《中华人民共和国公司法》第一百四十六条规定的情形或者下列情形之一的，不得担任证券交易所的负责人："},{"i":104,"n":"第一百零四条","txt":"因违法行为或者违纪行为被开除的证券交易场所、证券公司、证券登记结算机构、证券服务机构的从业人员和被开除的国家机关工作人员，不得招聘为证券交易所的从业人员。"},{"i":105,"n":"第一百零五条","txt":"进入实行会员制的证券交易所参与集中交易的，必须是证券交易所的会员。证券交易所不得允许非会员直接参与股票的集中交易。"},{"i":106,"n":"第一百零六条","txt":"投资者应当与证券公司签订证券交易委托协议，并在证券公司实名开立账户，以书面、电话、自助终端、网络等方式，委托该证券公司代其买卖证券。"},{"i":107,"n":"第一百零七条","txt":"证券公司为投资者开立账户，应当按照规定对投资者提供的身份信息进行核对。"},{"i":108,"n":"第一百零八条","txt":"证券公司根据投资者的委托，按照证券交易规则提出交易申报，参与证券交易所场内的集中交易，并根据成交结果承担相应的清算交收责任。证券登记结算机构根据成交结果，按照清算交收规则，与证券公司进行证券和资金的清算交收，并为证券公司客户办理证券的登记过户手续。"},{"i":109,"n":"第一百零九条","txt":"证券交易所应当为组织公平的集中交易提供保障，实时公布证券交易即时行情，并按交易日制作证券市场行情表，予以公布。"},{"i":110,"n":"第一百一十条","txt":"上市公司可以向证券交易所申请其上市交易股票的停牌或者复牌，但不得滥用停牌或者复牌损害投资者的合法权益。"},{"i":111,"n":"第一百一十一条","txt":"因不可抗力、意外事件、重大技术故障、重大人为差错等突发性事件而影响证券交易正常进行时，为维护证券交易正常秩序和市场公平，证券交易所可以按照业务规则采取技术性停牌、临时停市等处置措施，并应当及时向国务院证券监督管理机构报告。"},{"i":112,"n":"第一百一十二条","txt":"证券交易所对证券交易实行实时监控，并按照国务院证券监督管理机构的要求，对异常的交易情况提出报告。"},{"i":113,"n":"第一百一十三条","txt":"证券交易所应当加强对证券交易的风险监测，出现重大异常波动的，证券交易所可以按照业务规则采取限制交易、强制停牌等处置措施，并向国务院证券监督管理机构报告；严重影响证券市场稳定的，证券交易所可以按照业务规则采取临时停市等处置措施并公告。"},{"i":114,"n":"第一百一十四条","txt":"证券交易所应当从其收取的交易费用和会员费、席位费中提取一定比例的金额设立风险基金。风险基金由证券交易所理事会管理。"},{"i":115,"n":"第一百一十五条","txt":"证券交易所依照法律、行政法规和国务院证券监督管理机构的规定，制定上市规则、交易规则、会员管理规则和其他有关业务规则，并报国务院证券监督管理机构批准。"},{"i":116,"n":"第一百一十六条","txt":"证券交易所的负责人和其他从业人员执行与证券交易有关的职务时，与其本人或者其亲属有利害关系的，应当回避。"},{"i":117,"n":"第一百一十七条","txt":"按照依法制定的交易规则进行的交易，不得改变其交易结果，但本法第一百一十一条第二款规定的除外。对交易中违规交易者应负的民事责任不得免除；在违规交易中所获利益，依照有关规定处理。"},{"i":118,"n":"第一百一十八条","txt":"设立证券公司，应当具备下列条件，并经国务院证券监督管理机构批准："},{"i":119,"n":"第一百一十九条","txt":"国务院证券监督管理机构应当自受理证券公司设立申请之日起六个月内，依照法定条件和法定程序并根据审慎监管原则进行审查，作出批准或者不予批准的决定，并通知申请人；不予批准的，应当说明理由。"},{"i":120,"n":"第一百二十条","txt":"经国务院证券监督管理机构核准，取得经营证券业务许可证，证券公司可以经营下列部分或者全部证券业务："},{"i":121,"n":"第一百二十一条","txt":"证券公司经营本法第一百二十条第一款第（一）项至第（三）项业务的，注册资本最低限额为人民币五千万元；经营第（四）项至第（八）项业务之一的，注册资本最低限额为人民币一亿元；经营第（四）项至第（八）项业务中两项以上的，注册资本最低限额为人民币五亿元。证券公司的注册资本应当是实缴资本。"},{"i":122,"n":"第一百二十二条","txt":"证券公司变更证券业务范围，变更主要股东或者公司的实际控制人，合并、分立、停业、解散、破产，应当经国务院证券监督管理机构核准。"},{"i":123,"n":"第一百二十三条","txt":"国务院证券监督管理机构应当对证券公司净资本和其他风险控制指标作出规定。"},{"i":124,"n":"第一百二十四条","txt":"证券公司的董事、监事、高级管理人员，应当正直诚实、品行良好，熟悉证券法律、行政法规，具有履行职责所需的经营管理能力。证券公司任免董事、监事、高级管理人员，应当报国务院证券监督管理机构备案。"},{"i":125,"n":"第一百二十五条","txt":"证券公司从事证券业务的人员应当品行良好，具备从事证券业务所需的专业能力。"},{"i":126,"n":"第一百二十六条","txt":"国家设立证券投资者保护基金。证券投资者保护基金由证券公司缴纳的资金及其他依法筹集的资金组成，其规模以及筹集、管理和使用的具体办法由国务院规定。"},{"i":127,"n":"第一百二十七条","txt":"证券公司从每年的业务收入中提取交易风险准备金，用于弥补证券经营的损失，其提取的具体比例由国务院证券监督管理机构会同国务院财政部门规定。"},{"i":128,"n":"第一百二十八条","txt":"证券公司应当建立健全内部控制制度，采取有效隔离措施，防范公司与客户之间、不同客户之间的利益冲突。"},{"i":129,"n":"第一百二十九条","txt":"证券公司的自营业务必须以自己的名义进行，不得假借他人名义或者以个人名义进行。"},{"i":130,"n":"第一百三十条","txt":"证券公司应当依法审慎经营，勤勉尽责，诚实守信。"},{"i":131,"n":"第一百三十一条","txt":"证券公司客户的交易结算资金应当存放在商业银行，以每个客户的名义单独立户管理。"},{"i":132,"n":"第一百三十二条","txt":"证券公司办理经纪业务，应当置备统一制定的证券买卖委托书，供委托人使用。采取其他委托方式的，必须作出委托记录。"},{"i":133,"n":"第一百三十三条","txt":"证券公司接受证券买卖的委托，应当根据委托书载明的证券名称、买卖数量、出价方式、价格幅度等，按照交易规则代理买卖证券，如实进行交易记录；买卖成交后，应当按照规定制作买卖成交报告单交付客户。"},{"i":134,"n":"第一百三十四条","txt":"证券公司办理经纪业务，不得接受客户的全权委托而决定证券买卖、选择证券种类、决定买卖数量或者买卖价格。"},{"i":135,"n":"第一百三十五条","txt":"证券公司不得对客户证券买卖的收益或者赔偿证券买卖的损失作出承诺。"},{"i":136,"n":"第一百三十六条","txt":"证券公司的从业人员在证券交易活动中，执行所属的证券公司的指令或者利用职务违反交易规则的，由所属的证券公司承担全部责任。"},{"i":137,"n":"第一百三十七条","txt":"证券公司应当建立客户信息查询制度，确保客户能够查询其账户信息、委托记录、交易记录以及其他与接受服务或者购买产品有关的重要信息。"},{"i":138,"n":"第一百三十八条","txt":"证券公司应当按照规定向国务院证券监督管理机构报送业务、财务等经营管理信息和资料。国务院证券监督管理机构有权要求证券公司及其主要股东、实际控制人在指定的期限内提供有关信息、资料。"},{"i":139,"n":"第一百三十九条","txt":"国务院证券监督管理机构认为有必要时，可以委托会计师事务所、资产评估机构对证券公司的财务状况、内部控制状况、资产价值进行审计或者评估。具体办法由国务院证券监督管理机构会同有关主管部门制定。"},{"i":140,"n":"第一百四十条","txt":"证券公司的治理结构、合规管理、风险控制指标不符合规定的，国务院证券监督管理机构应当责令其限期改正；逾期未改正，或者其行为严重危及该证券公司的稳健运行、损害客户合法权益的，国务院证券监督管理机构可以区别情形，对其采取下列措施："},{"i":141,"n":"第一百四十一条","txt":"证券公司的股东有虚假出资、抽逃出资行为的，国务院证券监督管理机构应当责令其限期改正，并可责令其转让所持证券公司的股权。"},{"i":142,"n":"第一百四十二条","txt":"证券公司的董事、监事、高级管理人员未能勤勉尽责，致使证券公司存在重大违法违规行为或者重大风险的，国务院证券监督管理机构可以责令证券公司予以更换。"},{"i":143,"n":"第一百四十三条","txt":"证券公司违法经营或者出现重大风险，严重危害证券市场秩序、损害投资者利益的，国务院证券监督管理机构可以对该证券公司采取责令停业整顿、指定其他机构托管、接管或者撤销等监管措施。"},{"i":144,"n":"第一百四十四条","txt":"在证券公司被责令停业整顿、被依法指定托管、接管或者清算期间，或者出现重大风险时，经国务院证券监督管理机构批准，可以对该证券公司直接负责的董事、监事、高级管理人员和其他直接责任人员采取以下措施："},{"i":145,"n":"第一百四十五条","txt":"证券登记结算机构为证券交易提供集中登记、存管与结算服务，不以营利为目的，依法登记，取得法人资格。"},{"i":146,"n":"第一百四十六条","txt":"设立证券登记结算机构，应当具备下列条件："},{"i":147,"n":"第一百四十七条","txt":"证券登记结算机构履行下列职能："},{"i":148,"n":"第一百四十八条","txt":"在证券交易所和国务院批准的其他全国性证券交易场所交易的证券的登记结算，应当采取全国集中统一的运营方式。"},{"i":149,"n":"第一百四十九条","txt":"证券登记结算机构应当依法制定章程和业务规则，并经国务院证券监督管理机构批准。证券登记结算业务参与人应当遵守证券登记结算机构制定的业务规则。"},{"i":150,"n":"第一百五十条","txt":"在证券交易所或者国务院批准的其他全国性证券交易场所交易的证券，应当全部存管在证券登记结算机构。"},{"i":151,"n":"第一百五十一条","txt":"证券登记结算机构应当向证券发行人提供证券持有人名册及有关资料。"},{"i":152,"n":"第一百五十二条","txt":"证券登记结算机构应当采取下列措施保证业务的正常进行："},{"i":153,"n":"第一百五十三条","txt":"证券登记结算机构应当妥善保存登记、存管和结算的原始凭证及有关文件和资料。其保存期限不得少于二十年。"},{"i":154,"n":"第一百五十四条","txt":"证券登记结算机构应当设立证券结算风险基金，用于垫付或者弥补因违约交收、技术故障、操作失误、不可抗力造成的证券登记结算机构的损失。"},{"i":155,"n":"第一百五十五条","txt":"证券结算风险基金应当存入指定银行的专门账户，实行专项管理。"},{"i":156,"n":"第一百五十六条","txt":"证券登记结算机构申请解散，应当经国务院证券监督管理机构批准。"},{"i":157,"n":"第一百五十七条","txt":"投资者委托证券公司进行证券交易，应当通过证券公司申请在证券登记结算机构开立证券账户。证券登记结算机构应当按照规定为投资者开立证券账户。"},{"i":158,"n":"第一百五十八条","txt":"证券登记结算机构作为中央对手方提供证券结算服务的，是结算参与人共同的清算交收对手，进行净额结算，为证券交易提供集中履约保障。"},{"i":159,"n":"第一百五十九条","txt":"证券登记结算机构按照业务规则收取的各类结算资金和证券，必须存放于专门的清算交收账户，只能按业务规则用于已成交的证券交易的清算交收，不得被强制执行。"},{"i":160,"n":"第一百六十条","txt":"会计师事务所、律师事务所以及从事证券投资咨询、资产评估、资信评级、财务顾问、信息技术系统服务的证券服务机构，应当勤勉尽责、恪尽职守，按照相关业务规则为证券的交易及相关活动提供服务。"},{"i":161,"n":"第一百六十一条","txt":"证券投资咨询机构及其从业人员从事证券服务业务不得有下列行为："},{"i":162,"n":"第一百六十二条","txt":"证券服务机构应当妥善保存客户委托文件、核查和验证资料、工作底稿以及与质量控制、内部管理、业务经营有关的信息和资料，任何人不得泄露、隐匿、伪造、篡改或者毁损。上述信息和资料的保存期限不得少于十年，自业务委托结束之日起算。"},{"i":163,"n":"第一百六十三条","txt":"证券服务机构为证券的发行、上市、交易等证券业务活动制作、出具审计报告及其他鉴证报告、资产评估报告、财务顾问报告、资信评级报告或者法律意见书等文件，应当勤勉尽责，对所依据的文件资料内容的真实性、准确性、完整性进行核查和验证。其制作、出具的文件有虚假记载、误导性陈述或者重大遗漏，给他人造成损失的，应当与委托人承担连带赔偿责任，但是能够证明自己没有过错的除外。"},{"i":164,"n":"第一百六十四条","txt":"证券业协会是证券业的自律性组织，是社会团体法人。"},{"i":165,"n":"第一百六十五条","txt":"证券业协会章程由会员大会制定，并报国务院证券监督管理机构备案。"},{"i":166,"n":"第一百六十六条","txt":"证券业协会履行下列职责："},{"i":167,"n":"第一百六十七条","txt":"证券业协会设理事会。理事会成员依章程的规定由选举产生。"},{"i":168,"n":"第一百六十八条","txt":"国务院证券监督管理机构依法对证券市场实行监督管理，维护证券市场公开、公平、公正，防范系统性风险，维护投资者合法权益，促进证券市场健康发展。"},{"i":169,"n":"第一百六十九条","txt":"国务院证券监督管理机构在对证券市场实施监督管理中履行下列职责："},{"i":170,"n":"第一百七十条","txt":"国务院证券监督管理机构依法履行职责，有权采取下列措施："},{"i":171,"n":"第一百七十一条","txt":"国务院证券监督管理机构对涉嫌证券违法的单位或者个人进行调查期间，被调查的当事人书面申请，承诺在国务院证券监督管理机构认可的期限内纠正涉嫌违法行为，赔偿有关投资者损失，消除损害或者不良影响的，国务院证券监督管理机构可以决定中止调查。被调查的当事人履行承诺的，国务院证券监督管理机构可以决定终止调查；被调查的当事人未履行承诺或者有国务院规定的其他情形的，应当恢复调查。具体办法由国务院规定。"},{"i":172,"n":"第一百七十二条","txt":"国务院证券监督管理机构依法履行职责，进行监督检查或者调查，其监督检查、调查的人员不得少于二人，并应当出示合法证件和监督检查、调查通知书或者其他执法文书。监督检查、调查的人员少于二人或者未出示合法证件和监督检查、调查通知书或者其他执法文书的，被检查、调查的单位和个人有权拒绝。"},{"i":173,"n":"第一百七十三条","txt":"国务院证券监督管理机构依法履行职责，被检查、调查的单位和个人应当配合，如实提供有关文件和资料，不得拒绝、阻碍和隐瞒。"},{"i":174,"n":"第一百七十四条","txt":"国务院证券监督管理机构制定的规章、规则和监督管理工作制度应当依法公开。"},{"i":175,"n":"第一百七十五条","txt":"国务院证券监督管理机构应当与国务院其他金融监督管理机构建立监督管理信息共享机制。"},{"i":176,"n":"第一百七十六条","txt":"对涉嫌证券违法、违规行为，任何单位和个人有权向国务院证券监督管理机构举报。"},{"i":177,"n":"第一百七十七条","txt":"国务院证券监督管理机构可以和其他国家或者地区的证券监督管理机构建立监督管理合作机制，实施跨境监督管理。"},{"i":178,"n":"第一百七十八条","txt":"国务院证券监督管理机构依法履行职责，发现证券违法行为涉嫌犯罪的，应当依法将案件移送司法机关处理；发现公职人员涉嫌职务违法或者职务犯罪的，应当依法移送监察机关处理。"},{"i":179,"n":"第一百七十九条","txt":"国务院证券监督管理机构工作人员必须忠于职守、依法办事、公正廉洁，不得利用职务便利牟取不正当利益，不得泄露所知悉的有关单位和个人的商业秘密。"},{"i":180,"n":"第一百八十条","txt":"违反本法第九条的规定，擅自公开或者变相公开发行证券的，责令停止发行，退还所募资金并加算银行同期存款利息，处以非法所募资金金额百分之五以上百分之五十以下的罚款；对擅自公开或者变相公开发行证券设立的公司，由依法履行监督管理职责的机构或者部门会同县级以上地方人民政府予以取缔。对直接负责的主管人员和其他直接责任人员给予警告，并处以五十万元以上五百万元以下的罚款。"},{"i":181,"n":"第一百八十一条","txt":"发行人在其公告的证券发行文件中隐瞒重要事实或者编造重大虚假内容，尚未发行证券的，处以二百万元以上二千万元以下的罚款；已经发行证券的，处以非法所募资金金额百分之十以上一倍以下的罚款。对直接负责的主管人员和其他直接责任人员，处以一百万元以上一千万元以下的罚款。"},{"i":182,"n":"第一百八十二条","txt":"保荐人出具有虚假记载、误导性陈述或者重大遗漏的保荐书，或者不履行其他法定职责的，责令改正，给予警告，没收业务收入，并处以业务收入一倍以上十倍以下的罚款；没有业务收入或者业务收入不足一百万元的，处以一百万元以上一千万元以下的罚款；情节严重的，并处暂停或者撤销保荐业务许可。对直接负责的主管人员和其他直接责任人员给予警告，并处以五十万元以上五百万元以下的罚款。"},{"i":183,"n":"第一百八十三条","txt":"证券公司承销或者销售擅自公开发行或者变相公开发行的证券的，责令停止承销或者销售，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足一百万元的，处以一百万元以上一千万元以下的罚款；情节严重的，并处暂停或者撤销相关业务许可。给投资者造成损失的，应当与发行人承担连带赔偿责任。对直接负责的主管人员和其他直接责任人员给予警告，并处以五十万元以上五百万元以下的罚款。"},{"i":184,"n":"第一百八十四条","txt":"证券公司承销证券违反本法第二十九条规定的，责令改正，给予警告，没收违法所得，可以并处五十万元以上五百万元以下的罚款；情节严重的，暂停或者撤销相关业务许可。对直接负责的主管人员和其他直接责任人员给予警告，可以并处二十万元以上二百万元以下的罚款；情节严重的，并处以五十万元以上五百万元以下的罚款。"},{"i":185,"n":"第一百八十五条","txt":"发行人违反本法第十四条、第十五条的规定擅自改变公开发行证券所募集资金的用途的，责令改正，处以五十万元以上五百万元以下的罚款；对直接负责的主管人员和其他直接责任人员给予警告，并处以十万元以上一百万元以下的罚款。"},{"i":186,"n":"第一百八十六条","txt":"违反本法第三十六条的规定，在限制转让期内转让证券，或者转让股票不符合法律、行政法规和国务院证券监督管理机构规定的，责令改正，给予警告，没收违法所得，并处以买卖证券等值以下的罚款。"},{"i":187,"n":"第一百八十七条","txt":"法律、行政法规规定禁止参与股票交易的人员，违反本法第四十条的规定，直接或者以化名、借他人名义持有、买卖股票或者其他具有股权性质的证券的，责令依法处理非法持有的股票、其他具有股权性质的证券，没收违法所得，并处以买卖证券等值以下的罚款；属于国家工作人员的，还应当依法给予处分。"},{"i":188,"n":"第一百八十八条","txt":"证券服务机构及其从业人员，违反本法第四十二条的规定买卖证券的，责令依法处理非法持有的证券，没收违法所得，并处以买卖证券等值以下的罚款。"},{"i":189,"n":"第一百八十九条","txt":"上市公司、股票在国务院批准的其他全国性证券交易场所交易的公司的董事、监事、高级管理人员、持有该公司百分之五以上股份的股东，违反本法第四十四条的规定，买卖该公司股票或者其他具有股权性质的证券的，给予警告，并处以十万元以上一百万元以下的罚款。"},{"i":190,"n":"第一百九十条","txt":"违反本法第四十五条的规定，采取程序化交易影响证券交易所系统安全或者正常交易秩序的，责令改正，并处以五十万元以上五百万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以十万元以上一百万元以下的罚款。"},{"i":191,"n":"第一百九十一条","txt":"证券交易内幕信息的知情人或者非法获取内幕信息的人违反本法第五十三条的规定从事内幕交易的，责令依法处理非法持有的证券，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款。单位从事内幕交易的，还应当对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。国务院证券监督管理机构工作人员从事内幕交易的，从重处罚。"},{"i":192,"n":"第一百九十二条","txt":"违反本法第五十五条的规定，操纵证券市场的，责令依法处理其非法持有的证券，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足一百万元的，处以一百万元以上一千万元以下的罚款。单位操纵证券市场的，还应当对直接负责的主管人员和其他直接责任人员给予警告，并处以五十万元以上五百万元以下的罚款。"},{"i":193,"n":"第一百九十三条","txt":"违反本法第五十六条第一款、第三款的规定，编造、传播虚假信息或者误导性信息，扰乱证券市场的，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足二十万元的，处以二十万元以上二百万元以下的罚款。"},{"i":194,"n":"第一百九十四条","txt":"证券公司及其从业人员违反本法第五十七条的规定，有损害客户利益的行为的，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足十万元的，处以十万元以上一百万元以下的罚款；情节严重的，暂停或者撤销相关业务许可。"},{"i":195,"n":"第一百九十五条","txt":"违反本法第五十八条的规定，出借自己的证券账户或者借用他人的证券账户从事证券交易的，责令改正，给予警告，可以处五十万元以下的罚款。"},{"i":196,"n":"第一百九十六条","txt":"收购人未按照本法规定履行上市公司收购的公告、发出收购要约义务的，责令改正，给予警告，并处以五十万元以上五百万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":197,"n":"第一百九十七条","txt":"信息披露义务人未按照本法规定报送有关报告或者履行信息披露义务的，责令改正，给予警告，并处以五十万元以上五百万元以下的罚款；对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。发行人的控股股东、实际控制人组织、指使从事上述违法行为，或者隐瞒相关事项导致发生上述情形的，处以五十万元以上五百万元以下的罚款；对直接负责的主管人员和其他直接责任人员，处以二十万元以上二百万元以下的罚款。"},{"i":198,"n":"第一百九十八条","txt":"证券公司违反本法第八十八条的规定未履行或者未按照规定履行投资者适当性管理义务的，责令改正，给予警告，并处以十万元以上一百万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以下的罚款。"},{"i":199,"n":"第一百九十九条","txt":"违反本法第九十条的规定征集股东权利的，责令改正，给予警告，可以处五十万元以下的罚款。"},{"i":200,"n":"第二百条","txt":"非法开设证券交易场所的，由县级以上人民政府予以取缔，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足一百万元的，处以一百万元以上一千万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":201,"n":"第二百零一条","txt":"证券公司违反本法第一百零七条第一款的规定，未对投资者开立账户提供的身份信息进行核对的，责令改正，给予警告，并处以五万元以上五十万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以十万元以下的罚款。"},{"i":202,"n":"第二百零二条","txt":"违反本法第一百一十八条、第一百二十条第一款、第四款的规定，擅自设立证券公司、非法经营证券业务或者未经批准以证券公司名义开展证券业务活动的，责令改正，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足一百万元的，处以一百万元以上一千万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。对擅自设立的证券公司，由国务院证券监督管理机构予以取缔。"},{"i":203,"n":"第二百零三条","txt":"提交虚假证明文件或者采取其他欺诈手段骗取证券公司设立许可、业务许可或者重大事项变更核准的，撤销相关许可，并处以一百万元以上一千万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":204,"n":"第二百零四条","txt":"证券公司违反本法第一百二十二条的规定，未经核准变更证券业务范围，变更主要股东或者公司的实际控制人，合并、分立、停业、解散、破产的，责令改正，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款；情节严重的，并处撤销相关业务许可。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":205,"n":"第二百零五条","txt":"证券公司违反本法第一百二十三条第二款的规定，为其股东或者股东的关联人提供融资或者担保的，责令改正，给予警告，并处以五十万元以上五百万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以十万元以上一百万元以下的罚款。股东有过错的，在按照要求改正前，国务院证券监督管理机构可以限制其股东权利；拒不改正的，可以责令其转让所持证券公司股权。"},{"i":206,"n":"第二百零六条","txt":"证券公司违反本法第一百二十八条的规定，未采取有效隔离措施防范利益冲突，或者未分开办理相关业务、混合操作的，责令改正，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款；情节严重的，并处撤销相关业务许可。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":207,"n":"第二百零七条","txt":"证券公司违反本法第一百二十九条的规定从事证券自营业务的，责令改正，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款；情节严重的，并处撤销相关业务许可或者责令关闭。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":208,"n":"第二百零八条","txt":"违反本法第一百三十一条的规定，将客户的资金和证券归入自有财产，或者挪用客户的资金和证券的，责令改正，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足一百万元的，处以一百万元以上一千万元以下的罚款；情节严重的，并处撤销相关业务许可或者责令关闭。对直接负责的主管人员和其他直接责任人员给予警告，并处以五十万元以上五百万元以下的罚款。"},{"i":209,"n":"第二百零九条","txt":"证券公司违反本法第一百三十四条第一款的规定接受客户的全权委托买卖证券的，或者违反本法第一百三十五条的规定对客户的收益或者赔偿客户的损失作出承诺的，责令改正，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款；情节严重的，并处撤销相关业务许可。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":210,"n":"第二百一十条","txt":"证券公司的从业人员违反本法第一百三十六条的规定，私下接受客户委托买卖证券的，责令改正，给予警告，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得的，处以五十万元以下的罚款。"},{"i":211,"n":"第二百一十一条","txt":"证券公司及其主要股东、实际控制人违反本法第一百三十八条的规定，未报送、提供信息和资料，或者报送、提供的信息和资料有虚假记载、误导性陈述或者重大遗漏的，责令改正，给予警告，并处以一百万元以下的罚款；情节严重的，并处撤销相关业务许可。对直接负责的主管人员和其他直接责任人员，给予警告，并处以五十万元以下的罚款。"},{"i":212,"n":"第二百一十二条","txt":"违反本法第一百四十五条的规定，擅自设立证券登记结算机构的，由国务院证券监督管理机构予以取缔，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":213,"n":"第二百一十三条","txt":"证券投资咨询机构违反本法第一百六十条第二款的规定擅自从事证券服务业务，或者从事证券服务业务有本法第一百六十一条规定行为的，责令改正，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款。对直接负责的主管人员和其他直接责任人员，给予警告，并处以二十万元以上二百万元以下的罚款。"},{"i":214,"n":"第二百一十四条","txt":"发行人、证券登记结算机构、证券公司、证券服务机构未按照规定保存有关文件和资料的，责令改正，给予警告，并处以十万元以上一百万元以下的罚款；泄露、隐匿、伪造、篡改或者毁损有关文件和资料的，给予警告，并处以二十万元以上二百万元以下的罚款；情节严重的，处以五十万元以上五百万元以下的罚款，并处暂停、撤销相关业务许可或者禁止从事相关业务。对直接负责的主管人员和其他直接责任人员给予警告，并处以十万元以上一百万元以下的罚款。"},{"i":215,"n":"第二百一十五条","txt":"国务院证券监督管理机构依法将有关市场主体遵守本法的情况纳入证券市场诚信档案。"},{"i":216,"n":"第二百一十六条","txt":"国务院证券监督管理机构或者国务院授权的部门有下列情形之一的，对直接负责的主管人员和其他直接责任人员，依法给予处分："},{"i":217,"n":"第二百一十七条","txt":"国务院证券监督管理机构或者国务院授权的部门的工作人员，不履行本法规定的职责，滥用职权、玩忽职守，利用职务便利牟取不正当利益，或者泄露所知悉的有关单位和个人的商业秘密的，依法追究法律责任。"},{"i":218,"n":"第二百一十八条","txt":"拒绝、阻碍证券监督管理机构及其工作人员依法行使监督检查、调查职权，由证券监督管理机构责令改正，处以十万元以上一百万元以下的罚款，并由公安机关依法给予治安管理处罚。"},{"i":219,"n":"第二百一十九条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":220,"n":"第二百二十条","txt":"违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金、违法所得，违法行为人的财产不足以支付的，优先用于承担民事赔偿责任。"},{"i":221,"n":"第二百二十一条","txt":"违反法律、行政法规或者国务院证券监督管理机构的有关规定，情节严重的，国务院证券监督管理机构可以对有关责任人员采取证券市场禁入的措施。"},{"i":222,"n":"第二百二十二条","txt":"依照本法收缴的罚款和没收的违法所得，全部上缴国库。"},{"i":223,"n":"第二百二十三条","txt":"当事人对证券监督管理机构或者国务院授权的部门的处罚决定不服的，可以依法申请行政复议，或者依法直接向人民法院提起诉讼。"},{"i":224,"n":"第二百二十四条","txt":"境内企业直接或者间接到境外发行证券或者将其证券在境外上市交易，应当符合国务院的有关规定。"},{"i":225,"n":"第二百二十五条","txt":"境内公司股票以外币认购和交易的，具体办法由国务院另行规定。"},{"i":226,"n":"第二百二十六条","txt":"本法自2020年3月1日起施行。"}]};
